fn terminal_status_should_close(status: &zz_terminal::SessionStatus) -> bool {
    matches!(
        status,
        zz_terminal::SessionStatus::Exited(_) | zz_terminal::SessionStatus::Failed(_)
    )
}

fn daemon_color_scheme() -> TerminalColorScheme {
    match std::env::var("ZZ_COLOR_SCHEME").as_deref() {
        Ok("light") => TerminalColorScheme::Light,
        _ => TerminalColorScheme::Dark,
    }
}

fn mode_keys_from_environment(visual: Option<&OsStr>, editor: Option<&OsStr>) -> &'static str {
    let Some(editor) = visual.or(editor) else {
        return "emacs";
    };
    let editor = editor.to_string_lossy();
    let basename = editor.rsplit('/').next().unwrap_or(&editor);
    if basename.contains("vi") {
        "vi"
    } else {
        "emacs"
    }
}

fn editor_from_environment(visual: Option<&OsStr>, editor: Option<&OsStr>) -> String {
    visual.or(editor).map_or_else(
        || "/usr/bin/vi".to_owned(),
        |value| value.to_string_lossy().into_owned(),
    )
}

#[cfg(unix)]
fn shell_is_valid_for_program(shell: &Path, program: &OsStr) -> bool {
    use std::os::unix::ffi::OsStrExt as _;

    if !shell.is_absolute() {
        return false;
    }
    let Some(shell_name) = shell.file_name() else {
        return false;
    };
    let program = Path::new(program).file_name().unwrap_or(program).as_bytes();
    let program = program.strip_prefix(b"-").unwrap_or(program);
    if shell_name.as_bytes() == program {
        return false;
    }
    rustix::fs::access(shell, rustix::fs::Access::EXEC_OK).is_ok()
}

#[cfg(unix)]
fn shell_is_valid(shell: &Path) -> bool {
    let program = std::env::args_os().next().unwrap_or_default();
    shell_is_valid_for_program(shell, &program)
}

#[cfg(not(unix))]
fn shell_is_valid(shell: &Path) -> bool {
    !shell.as_os_str().is_empty()
}

#[cfg(unix)]
#[allow(unsafe_code, clippy::undocumented_unsafe_blocks)]
fn passwd_shell() -> Option<PathBuf> {
    use std::{ffi::CStr, mem::MaybeUninit, os::unix::ffi::OsStrExt as _};

    let mut passwd = MaybeUninit::<libc::passwd>::uninit();
    let mut result = std::ptr::null_mut();
    let mut buffer = vec![0_u8; 16 * 1024];
    let status = unsafe {
        libc::getpwuid_r(
            libc::getuid(),
            passwd.as_mut_ptr(),
            buffer.as_mut_ptr().cast(),
            buffer.len(),
            &raw mut result,
        )
    };
    if status != 0 || result.is_null() {
        return None;
    }
    let passwd = unsafe { passwd.assume_init() };
    if passwd.pw_shell.is_null() {
        return None;
    }
    let shell = unsafe { CStr::from_ptr(passwd.pw_shell) };
    Some(PathBuf::from(OsStr::from_bytes(shell.to_bytes())))
}

#[cfg(unix)]
fn resolve_runtime_default_shell(environment_shell: Option<&OsStr>) -> String {
    if let Some(shell) = environment_shell {
        let shell = Path::new(shell);
        if shell_is_valid(shell) {
            return shell.to_string_lossy().into_owned();
        }
    }
    if let Some(shell) = passwd_shell()
        && shell_is_valid(&shell)
    {
        return shell.to_string_lossy().into_owned();
    }
    "/bin/sh".to_owned()
}

#[cfg(not(unix))]
fn resolve_runtime_default_shell(environment_shell: Option<&OsStr>) -> String {
    environment_shell
        .and_then(OsStr::to_str)
        .unwrap_or("cmd.exe")
        .to_owned()
}

#[cfg(unix)]
fn terminal_shell_for_session(
    engine: &MuxEngine,
    session: SessionId,
) -> Result<String, ServerError> {
    let shell = engine.default_shell_for_session(session)?;
    if shell_is_valid(Path::new(shell)) {
        Ok(shell.to_owned())
    } else {
        Ok("/bin/sh".to_owned())
    }
}

#[cfg(not(unix))]
fn terminal_shell_for_session(
    engine: &MuxEngine,
    session: SessionId,
) -> Result<String, ServerError> {
    engine.default_shell_for_session(session).map(str::to_owned)
}

fn daemon_environment() -> Vec<(String, String)> {
    let mut environment = std::env::vars_os()
        .map(|(name, value)| {
            (
                name.to_string_lossy().into_owned(),
                value.to_string_lossy().into_owned(),
            )
        })
        .collect::<BTreeMap<_, _>>();
    if let Ok(cwd) = std::env::current_dir() {
        let cwd = environment
            .get("PWD")
            .filter(|pwd| !pwd.is_empty())
            .filter(|pwd| {
                fs::canonicalize(pwd)
                    .ok()
                    .zip(fs::canonicalize(&cwd).ok())
                    .is_some_and(|(pwd, cwd)| pwd == cwd)
            })
            .cloned()
            .unwrap_or_else(|| cwd.to_string_lossy().into_owned());
        environment.insert("PWD".to_owned(), cwd);
    }
    environment.into_iter().collect()
}

fn terminal_environment_for_session(
    engine: &MuxEngine,
    session: SessionId,
) -> Result<Vec<(String, Option<String>)>, ServerError> {
    let mut environment = engine.environment_for_session(session)?;
    environment.retain(|(name, _)| name != "TERM");
    Ok(environment)
}

fn tmux_environment(socket_path: &Path, session: Option<SessionId>) -> String {
    let session = session.map_or_else(|| "-1".to_owned(), |session| session.0.to_string());
    format!("{},{},{session}", socket_path.display(), std::process::id())
}

#[cfg(any(target_os = "linux", target_os = "macos"))]
fn terminal_working_directory(terminal: &TerminalSession) -> Option<PathBuf> {
    let process_id = terminal.foreground_process_id().filter(|pid| *pid != 0)?;
    let process_id = Pid::from_u32(process_id);
    let mut system = System::new();
    system.refresh_processes_specifics(
        ProcessesToUpdate::Some(&[process_id]),
        ProcessRefreshKind::new().with_cwd(sysinfo::UpdateKind::Always),
    );
    system
        .process(process_id)
        .and_then(|process| process.cwd())
        .map(Path::to_path_buf)
}

#[cfg(not(any(target_os = "linux", target_os = "macos")))]
fn terminal_working_directory(_terminal: &TerminalSession) -> Option<PathBuf> {
    None
}

fn terminal_current_command(terminal: &TerminalSession) -> String {
    let Some(process_id) = terminal
        .foreground_process_id()
        .filter(|pid| *pid != 0)
        .map(Pid::from_u32)
    else {
        return String::new();
    };
    let mut system = System::new();
    system.refresh_processes_specifics(
        ProcessesToUpdate::Some(&[process_id]),
        ProcessRefreshKind::new(),
    );
    system
        .process(process_id)
        .map(|process| process.name().to_string_lossy().into_owned())
        .unwrap_or_default()
}

fn unix_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn command_log_line(command: &CommandInvocation) -> String {
    let mut line = canonical_command(&command.name).to_owned();
    for argument in &command.args {
        line.push(' ');
        line.push_str(argument);
    }
    line
}

fn push_server_message(inner: &mut ServerState, text: String) -> u64 {
    let number = inner.next_message_number;
    inner.next_message_number = inner.next_message_number.wrapping_add(1);
    inner.message_log.push_back(ServerMessage {
        number,
        time: SystemTime::now(),
        text,
    });
    let limit = inner.engine.message_limit();
    while inner.message_log.len() > limit {
        inner.message_log.pop_front();
    }
    number
}

