const CURSOR_STYLE_OVERRIDES: [(&str, Option<(CursorStyle, CursorBlinkPolicy)>); 7] = [
    ("default", None),
    (
        "blinking-block",
        Some((CursorStyle::Block, CursorBlinkPolicy::On)),
    ),
    ("block", Some((CursorStyle::Block, CursorBlinkPolicy::Off))),
    (
        "blinking-underline",
        Some((CursorStyle::Underline, CursorBlinkPolicy::On)),
    ),
    (
        "underline",
        Some((CursorStyle::Underline, CursorBlinkPolicy::Off)),
    ),
    (
        "blinking-bar",
        Some((CursorStyle::Bar, CursorBlinkPolicy::On)),
    ),
    ("bar", Some((CursorStyle::Bar, CursorBlinkPolicy::Off))),
];

struct ResolvedTerminalWorkerOptions {
    appearance: Arc<TerminalAppearance>,
    allow_passthrough: bool,
    wrap_search: bool,
}

fn terminal_worker_options(
    engine: &MuxEngine,
    base_appearance: &Arc<TerminalAppearance>,
    pane: PaneId,
) -> Result<ResolvedTerminalWorkerOptions, ServerError> {
    let options = engine.terminal_worker_options_for_pane(pane)?;
    Ok(ResolvedTerminalWorkerOptions {
        appearance: pane_terminal_appearance(
            base_appearance,
            options.cursor_style,
            &options.cursor_colour,
        ),
        allow_passthrough: options.allow_passthrough,
        wrap_search: options.wrap_search,
    })
}

fn pane_terminal_appearance(
    base: &Arc<TerminalAppearance>,
    cursor_style: &str,
    cursor_colour: &str,
) -> Arc<TerminalAppearance> {
    let cursor_style = CURSOR_STYLE_OVERRIDES
        .iter()
        .find_map(|(candidate, mapped)| (*candidate == cursor_style).then_some(*mapped))
        .flatten();
    let resolved_color = pane_cursor_color(base, cursor_colour);
    if cursor_style.is_none() && resolved_color.is_none() {
        return Arc::clone(base);
    }
    let mut appearance = (**base).clone();
    if let Some((style, blink)) = cursor_style {
        appearance.cursor_style = style;
        appearance.cursor_blink_policy = blink;
    }
    if let Some(color) = resolved_color {
        appearance.cursor_color = color;
    }
    Arc::new(appearance)
}

fn pane_cursor_color(appearance: &TerminalAppearance, value: &str) -> Option<Color> {
    if let Some(color) = parse_x11_color(value)
        && value.chars().any(char::is_whitespace)
    {
        return Some(color);
    }
    let colour = parse_tmux_colour(value)?;
    match colour {
        TmuxColour::Basic(index) | TmuxColour::Indexed(index) => appearance
            .palette
            .as_array()
            .get(usize::from(index))
            .copied(),
        TmuxColour::Rgb(value) => Some(Color::rgb(
            u8::try_from((value >> 16) & 0xff).expect("red component is one byte"),
            u8::try_from((value >> 8) & 0xff).expect("green component is one byte"),
            u8::try_from(value & 0xff).expect("blue component is one byte"),
        )),
        TmuxColour::Theme(index) => [0, 7, 7, 0, 2, 3, 1, 4, 6, 5]
            .get(usize::from(index))
            .and_then(|index| appearance.palette.as_array().get(*index))
            .copied(),
        TmuxColour::Default | TmuxColour::Terminal => None,
    }
}

fn terminal_appearance_updates(
    inner: &ServerState,
) -> Vec<(Arc<TerminalSession>, Arc<TerminalAppearance>)> {
    let mut updates = Vec::with_capacity(inner.terminals.len() + inner.command_outputs.len());
    for (pane, terminal) in &inner.terminals {
        let appearance = terminal_worker_options(&inner.engine, &inner.appearance, *pane)
            .map_or_else(
                |_| Arc::clone(&inner.appearance),
                |options| options.appearance,
            );
        updates.push((Arc::clone(terminal), appearance));
    }
    for output in inner.command_outputs.values() {
        let appearance = terminal_worker_options(&inner.engine, &inner.appearance, output.pane)
            .map_or_else(
                |_| Arc::clone(&inner.appearance),
                |options| options.appearance,
            );
        updates.push((Arc::clone(&output.terminal), appearance));
    }
    updates
}

fn log_appearance_load(reason: &str, load: &AppearanceLoad) {
    log::info!(
        target: "zz_daemon::diagnostics::appearance",
        "loaded appearance reason={reason} root={:?} scheme={} supported={} unsupported={} invalid={} diagnostics_dropped={} bytes={} hash={} appearance={:?}",
        load.root,
        load.appearance.color_scheme.as_str(),
        load.supported,
        load.unsupported,
        load.invalid,
        load.diagnostics_dropped,
        load.bytes_read,
        load.appearance.stable_hash(),
        load.appearance,
    );
    for diagnostic in &load.diagnostics {
        match diagnostic.disposition {
            AppearanceConfigDisposition::Invalid => log::warn!(
                target: "zz_daemon::diagnostics::appearance",
                "config reason={reason} path={} line={} key={:?} disposition={:?} message={}",
                diagnostic.path.display(),
                diagnostic.line,
                diagnostic.key,
                diagnostic.disposition,
                diagnostic.message,
            ),
            _ => log::debug!(
                target: "zz_daemon::diagnostics::appearance",
                "config reason={reason} path={} line={} key={:?} disposition={:?} message={}",
                diagnostic.path.display(),
                diagnostic.line,
                diagnostic.key,
                diagnostic.disposition,
                diagnostic.message,
            ),
        }
    }
}

#[derive(Debug, Default, PartialEq, Eq)]
struct MuxOverrideApplyReport {
    applied: usize,
    diagnostics: Vec<String>,
}

fn partition_config_overrides(
    entries: &[ConfigOverrideEntry],
) -> (Vec<ConfigOverrideEntry>, Vec<ConfigOverrideEntry>) {
    let mut appearance_entries = Vec::new();
    let mut mux_entries = Vec::new();
    for entry in entries {
        if zz_terminal::AppearanceConfigKey::from_config_key(&entry.0).is_some() {
            appearance_entries.push(entry.clone());
        } else if MuxOptionKey::from_config_key(&entry.0).is_some() {
            mux_entries.push(entry.clone());
        } else {
            log::warn!(
                target: "zz_daemon::diagnostics::mux_config",
                "ignored unsupported configuration override key={:?}",
                entry.0,
            );
        }
    }
    (appearance_entries, mux_entries)
}

#[derive(Clone, Debug)]
pub struct Daemon {
    socket_path: PathBuf,
    load_user_config: bool,
    mux_config_files: Option<Vec<PathBuf>>,
}

impl Daemon {
    #[must_use]
    pub fn new(socket_path: impl Into<PathBuf>) -> Self {
        Self {
            socket_path: socket_path.into(),
            load_user_config: true,
            mux_config_files: None,
        }
    }

    #[must_use]
    pub fn with_mux_config_files(mut self, files: impl IntoIterator<Item = PathBuf>) -> Self {
        let files = files.into_iter().collect::<Vec<_>>();
        self.mux_config_files = (!files.is_empty()).then_some(files);
        self
    }

    /// Skip the user's `zz/mux.conf`, for hermetic embedding and tests.
    #[must_use]
    pub fn without_user_config(mut self) -> Self {
        self.load_user_config = false;
        self
    }

    /// Run the persistent listener on the current thread until shutdown.
    pub fn run_foreground(&self) -> Result<(), DaemonError> {
        prepare_socket(&self.socket_path)?;
        let listener = LocalTransport::bind(&self.socket_path).map_err(|error| {
            if error.kind() == ErrorKind::AddrInUse {
                DaemonError::AlreadyRunning(self.socket_path.clone())
            } else {
                DaemonError::Io(error)
            }
        })?;
        restrict_socket_permissions(&self.socket_path)?;
        listener.set_nonblocking(true)?;
        let socket_guard = SocketGuard::new(self.socket_path.clone());
        let identity_guard = DaemonIdentityGuard::install(&self.socket_path)?;

        self.run_foreground_listener::<LocalTransport>(
            listener,
            (socket_guard, identity_guard),
            self.socket_path.display(),
        )
    }

    fn run_foreground_listener<T: Transport>(
        &self,
        listener: T::Listener,
        socket_guards: (SocketGuard, DaemonIdentityGuard),
        endpoint: impl std::fmt::Display,
    ) -> Result<(), DaemonError>
    where
        T::Listener: Send + 'static,
    {
        let color_scheme = daemon_color_scheme();
        let load = AppearanceLoad::defaults_for(color_scheme);
        log_appearance_load("startup", &load);
        let (appearance, provenance) = (Arc::new(load.appearance), load.provenance);
        let shared = Arc::new(Shared::configured(
            server_id(),
            appearance,
            provenance,
            self.load_user_config,
            paste_upload_directory(&self.socket_path),
            self.socket_path.clone(),
        ));
        #[cfg(unix)]
        shared.install_tmux_shim()?;
        shared.begin_startup();
        #[cfg(unix)]
        let _signal_guard = DaemonSignalGuard::install(&shared)?;
        let accept_shared = Arc::clone(&shared);
        let accept_thread = thread::Builder::new()
            .name("zz-daemon-accept".to_owned())
            .spawn(move || {
                let result = accept_connections::<T>(&listener, &accept_shared);
                drop(listener);
                if result.is_err() {
                    accept_shared.request_shutdown();
                }
                result
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        let startup_result = (|| {
            shared.initialize_with_mux_config_files(
                self.load_user_config,
                self.mux_config_files.as_deref(),
            )?;
            shared.start_diagnostic_sampler()?;
            shared.start_status_sampler()?;
            shared.log_diagnostic_snapshot("startup");
            log::info!("zz daemon listening at {endpoint}");
            Ok::<(), DaemonError>(())
        })();
        if startup_result.is_ok() {
            shared.finish_startup();
        } else {
            shared.request_shutdown();
        }
        let accept_result = accept_thread
            .join()
            .map_err(|_| DaemonError::Thread("daemon accept thread panicked".to_owned()))?;
        drop(socket_guards);
        startup_result?;
        if accept_result.is_err() {
            shared.request_shutdown();
        }
        accept_result?;
        shared.request_shutdown();
        shared.publish(EventPayload::ServerStopping);
        shared.drain_subscribers_for_shutdown(Duration::from_secs(2));
        // The adapter children are told to close and joined before the socket
        // goes; what refuses to settle is the acp crate's problem, not ours.
        #[cfg(feature = "agent")]
        shared.shutdown_agents();
        shared.log_diagnostic_snapshot("shutdown");
        log::info!("zz daemon stopped");
        log::logger().flush();
        Ok(())
    }
}

#[cfg(unix)]
struct DaemonSignalGuard {
    stop: async_channel::Sender<()>,
    thread: Option<thread::JoinHandle<()>>,
}

#[cfg(unix)]
impl DaemonSignalGuard {
    fn install(shared: &Arc<Shared>) -> Result<Self, DaemonError> {
        use async_signal::Signal;

        let mut signals = async_signal::Signals::new([Signal::Term, Signal::Int])?;
        let (stop, stopped) = async_channel::bounded(1);
        let shared = Arc::downgrade(shared);
        let thread = thread::Builder::new()
            .name("zz-daemon-signals".to_owned())
            .spawn(move || {
                use futures_lite::{StreamExt as _, future};

                let signalled = future::block_on(future::race(
                    async {
                        let _ = signals.next().await;
                        true
                    },
                    async {
                        let _ = stopped.recv().await;
                        false
                    },
                ));
                if signalled && let Some(shared) = shared.upgrade() {
                    shared.request_shutdown();
                }
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        Ok(Self {
            stop,
            thread: Some(thread),
        })
    }
}

#[cfg(unix)]
impl Drop for DaemonSignalGuard {
    fn drop(&mut self) {
        let _ = self.stop.send_blocking(());
        if let Some(thread) = self.thread.take() {
            let _ = thread.join();
        }
    }
}

fn accept_connections<T: Transport>(
    listener: &T::Listener,
    shared: &Arc<Shared>,
) -> Result<(), DaemonError> {
    while !shared.stopping.load(Ordering::Acquire) {
        match listener.accept() {
            Ok(stream) => {
                let shared = Arc::clone(shared);
                thread::Builder::new()
                    .name("zz-client".to_owned())
                    .spawn(move || {
                        if let Err(error) = handle_connection(stream, &shared) {
                            log::debug!("client disconnected: {error}");
                        }
                    })
                    .map_err(|error| DaemonError::Thread(error.to_string()))?;
            }
            Err(error) if error.kind() == ErrorKind::WouldBlock => {
                listener.wait_for_incoming(ACCEPT_WAIT_TIMEOUT)?;
            }
            Err(error) => return Err(error.into()),
        }
    }
    Ok(())
}

#[cfg(unix)]
struct SocketGuard(PathBuf);

#[cfg(windows)]
struct SocketGuard;

impl SocketGuard {
    fn new(path: PathBuf) -> Self {
        #[cfg(unix)]
        {
            Self(path)
        }
        #[cfg(windows)]
        {
            let _ = path;
            Self
        }
    }
}

#[cfg(unix)]
impl Drop for SocketGuard {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.0);
    }
}

#[cfg(unix)]
struct TmuxShimGuard {
    directory: PathBuf,
    executable: PathBuf,
}

#[cfg(unix)]
impl TmuxShimGuard {
    fn install(executable: PathBuf) -> std::io::Result<Self> {
        use std::os::unix::fs::{DirBuilderExt as _, OpenOptionsExt as _};

        let directory = loop {
            let sequence = TMUX_SHIM_SEQUENCE.fetch_add(1, Ordering::Relaxed);
            let directory = std::env::temp_dir()
                .join(format!("zz-tmux-shim-{}-{sequence}", std::process::id()));
            let mut builder = fs::DirBuilder::new();
            builder.mode(0o700);
            match builder.create(&directory) {
                Ok(()) => break directory,
                Err(error) if error.kind() == ErrorKind::AlreadyExists => {}
                Err(error) => return Err(error),
            }
        };
        let path = directory.join("tmux");
        let result = (|| {
            let mut options = fs::OpenOptions::new();
            options.create_new(true).write(true).mode(0o700);
            let mut file = options.open(&path)?;
            file.write_all(b"#!/bin/sh\nexec \"$ZZ_TMUX_EXECUTABLE\" \"$@\"\n")?;
            file.flush()
        })();
        if let Err(error) = result {
            let _ = fs::remove_file(path);
            let _ = fs::remove_dir(&directory);
            return Err(error);
        }
        Ok(Self {
            directory,
            executable,
        })
    }
}

#[cfg(unix)]
impl Drop for TmuxShimGuard {
    fn drop(&mut self) {
        let _ = fs::remove_file(self.directory.join("tmux"));
        let _ = fs::remove_dir(&self.directory);
    }
}

#[cfg(unix)]
fn paste_upload_directory(socket_path: &Path) -> PathBuf {
    socket_path
        .parent()
        .map_or_else(|| PathBuf::from("paste"), |parent| parent.join("paste"))
}

#[cfg(not(unix))]
fn paste_upload_directory(_socket_path: &Path) -> PathBuf {
    std::env::temp_dir().join("zz").join("paste")
}

fn write_paste_upload(
    directory: &Path,
    file_name: &str,
    bytes: &[u8],
) -> Result<PathBuf, std::io::Error> {
    fs::create_dir_all(directory)?;
    #[cfg(unix)]
    fs::set_permissions(
        directory,
        <fs::Permissions as std::os::unix::fs::PermissionsExt>::from_mode(0o700),
    )?;
    let path = directory.join(file_name);
    let mut options = fs::OpenOptions::new();
    options.write(true).create(true).truncate(true);
    #[cfg(unix)]
    std::os::unix::fs::OpenOptionsExt::mode(&mut options, 0o600);
    let mut file = options.open(&path)?;
    file.write_all(bytes)?;
    file.flush()?;
    Ok(path)
}

fn prune_paste_uploads(directory: &Path, keep: usize) {
    let Ok(entries) = fs::read_dir(directory) else {
        return;
    };
    let mut uploads = Vec::new();
    for entry in entries.flatten() {
        let Ok(metadata) = entry.metadata() else {
            continue;
        };
        if !metadata.is_file() {
            continue;
        }
        uploads.push((metadata.modified().unwrap_or(UNIX_EPOCH), entry.path()));
    }
    if uploads.len() <= keep {
        return;
    }
    uploads.sort_unstable_by_key(|(modified, _)| Reverse(*modified));
    for (_, path) in uploads.into_iter().skip(keep) {
        let _ = fs::remove_file(path);
    }
}

struct OutboundMailbox {
    state: Mutex<OutboundState>,
    ready: Condvar,
}

#[derive(Default)]
struct OutboundState {
    reliable: VecDeque<Vec<u8>>,
    command_output: Option<Vec<u8>>,
    agent: BTreeMap<PaneId, PendingAgent>,
    agent_order: VecDeque<PaneId>,
    terminals: BTreeMap<PaneId, PendingTerminal>,
    delivered_terminals: BTreeMap<PaneId, TerminalGeneration>,
    delivered_images: BTreeMap<PaneId, BTreeMap<u32, u64>>,
    delivered_pasted_images: BTreeMap<PaneId, BTreeMap<u32, u64>>,
    terminal_order: VecDeque<PaneId>,
    recycled_frames: Vec<Vec<u8>>,
    recycled_capacity: usize,
    queued_bytes: usize,
    closed: bool,
    writer_finished: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TerminalEnqueue {
    Queued,
    NeedsFull,
    Closed,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum KittyImageEnqueue {
    Queued,
    AlreadyDelivered,
    Closed,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PastedImageEnqueue {
    Queued,
    AlreadyDelivered,
    Closed,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct TerminalGeneration {
    content: u64,
    view: u64,
    dictionary: u32,
    columns: u16,
    rows: u16,
}

struct PendingTerminal {
    encoded: Vec<u8>,
    current: TerminalGeneration,
}

/// One pane's undelivered agent frames. Unlike a terminal viewport an agent
/// batch cannot be coalesced away — every item is transcript — so the lane
/// queues them and drops the whole pane when it outgrows its share.
#[derive(Default)]
struct PendingAgent {
    /// Encoded frames, each tagged with the first sequence it carries: what a
    /// lagged client must replay from.
    frames: VecDeque<(u64, Vec<u8>)>,
    bytes: usize,
}

#[derive(Clone, Copy)]
struct TerminalTransition {
    base: Option<TerminalGeneration>,
    current: TerminalGeneration,
}

enum TerminalFanout {
    Full,
    Patch(zz_terminal::TerminalViewportPatch),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct TerminalGeometry {
    columns: u16,
    rows: u16,
    cell_width_px: u32,
    cell_height_px: u32,
}

fn viewport_generation(viewport: &TerminalViewport) -> TerminalGeneration {
    TerminalGeneration {
        content: viewport.generation,
        view: viewport.view_generation,
        dictionary: viewport.dictionary_generation,
        columns: viewport.columns,
        rows: viewport.rows,
    }
}

fn terminal_transition(pane: PaneId, message: &ProtocolMessage) -> Option<TerminalTransition> {
    let ProtocolMessage::Event(Event { payload, .. }) = message else {
        return None;
    };
    match payload {
        EventPayload::TerminalViewport {
            pane: target,
            viewport,
        } if *target == pane => Some(TerminalTransition {
            base: None,
            current: viewport_generation(viewport),
        }),
        EventPayload::TerminalPatch {
            pane: target,
            patch,
        } if *target == pane => Some(TerminalTransition {
            base: Some(TerminalGeneration {
                content: patch.base_generation,
                view: patch.base_view_generation,
                dictionary: patch.dictionary_generation,
                columns: patch.columns,
                rows: patch.rows,
            }),
            current: TerminalGeneration {
                content: patch.generation,
                view: patch.view_generation,
                dictionary: patch.dictionary_generation,
                columns: patch.columns,
                rows: patch.rows,
            },
        }),
        _ => None,
    }
}

impl OutboundMailbox {
    fn new() -> Arc<Self> {
        Arc::new(Self {
            state: Mutex::new(OutboundState::default()),
            ready: Condvar::new(),
        })
    }

    fn encode_message(&self, message: &ProtocolMessage) -> Result<Vec<u8>, ProtocolError> {
        self.encode_with(|frame| encode_protocol_message_into(message, frame))
    }

    fn encode_with(
        &self,
        encode: impl FnOnce(&mut Vec<u8>) -> Result<(), ProtocolError>,
    ) -> Result<Vec<u8>, ProtocolError> {
        let mut frame = {
            let mut state = self.state.lock();
            take_recycled_frame(&mut state)
        };
        if let Err(error) = encode(&mut frame) {
            self.recycle_frame(frame);
            return Err(error);
        }
        Ok(frame)
    }

    fn recycle_frame(&self, frame: Vec<u8>) {
        let mut state = self.state.lock();
        recycle_outbound_frame(&mut state, frame);
    }

    #[must_use]
    fn enqueue_reliable(&self, message: &ProtocolMessage) -> bool {
        let removed_pane = match message {
            ProtocolMessage::Event(Event {
                payload: EventPayload::PaneRemoved(pane),
                ..
            }) => Some(*pane),
            _ => None,
        };
        let removed_images = match message {
            ProtocolMessage::Event(Event {
                payload: EventPayload::KittyImagesRemoved { pane, image_ids },
                ..
            }) => Some((*pane, image_ids.as_slice())),
            _ => None,
        };
        let clears_command_output = matches!(
            message,
            ProtocolMessage::Event(Event {
                payload: EventPayload::CommandOutput { viewport: None, .. },
                ..
            })
        );
        let Ok(encoded) = self.encode_message(message) else {
            log::error!("failed to encode outbound control message");
            return false;
        };
        let mut state = self.state.lock();
        if state.closed {
            return false;
        }
        if let Some(pane) = removed_pane {
            remove_pending_terminal(&mut state, pane);
            clear_pending_agent(&mut state, pane);
            state.delivered_terminals.remove(&pane);
            state.delivered_images.remove(&pane);
            state.delivered_pasted_images.remove(&pane);
        }
        if let Some((pane, image_ids)) = removed_images
            && let Some(delivered) = state.delivered_images.get_mut(&pane)
        {
            for image_id in image_ids {
                delivered.remove(image_id);
            }
            if delivered.is_empty() {
                state.delivered_images.remove(&pane);
            }
        }
        if clears_command_output && let Some(frame) = state.command_output.take() {
            state.queued_bytes = state.queued_bytes.saturating_sub(frame.len());
            recycle_outbound_frame(&mut state, frame);
        }
        if state.reliable.len() >= MAX_RELIABLE_MESSAGES
            || !reserve_outbound_bytes(&mut state, encoded.len(), 0)
        {
            close_outbound_too_far_behind(&mut state);
            self.ready.notify_all();
            return false;
        }
        state.queued_bytes += encoded.len();
        state.reliable.push_back(encoded);
        drop(state);
        self.ready.notify_one();
        true
    }

    fn enqueue_kitty_image(
        &self,
        pane: PaneId,
        image_id: u32,
        generation: u64,
        frames: &[Vec<u8>],
    ) -> KittyImageEnqueue {
        let mut state = self.state.lock();
        if state.closed {
            return KittyImageEnqueue::Closed;
        }
        if state
            .delivered_images
            .get(&pane)
            .and_then(|images| images.get(&image_id))
            == Some(&generation)
        {
            return KittyImageEnqueue::AlreadyDelivered;
        }
        let Some(frame_bytes) = frames
            .iter()
            .try_fold(0_usize, |total, frame| total.checked_add(frame.len()))
        else {
            close_outbound(&mut state);
            self.ready.notify_all();
            return KittyImageEnqueue::Closed;
        };
        if state.reliable.len().saturating_add(frames.len()) > MAX_RELIABLE_MESSAGES
            || !reserve_outbound_bytes(&mut state, frame_bytes, 0)
        {
            close_outbound(&mut state);
            self.ready.notify_all();
            return KittyImageEnqueue::Closed;
        }
        for frame in frames {
            state.queued_bytes += frame.len();
            state.reliable.push_back(frame.clone());
        }
        state
            .delivered_images
            .entry(pane)
            .or_default()
            .insert(image_id, generation);
        drop(state);
        self.ready.notify_one();
        KittyImageEnqueue::Queued
    }

    fn enqueue_kitty_images_removed(&self, pane: PaneId, image_ids: &[u32]) {
        let image_ids = {
            let state = self.state.lock();
            let Some(delivered) = state.delivered_images.get(&pane) else {
                return;
            };
            image_ids
                .iter()
                .copied()
                .filter(|image_id| delivered.contains_key(image_id))
                .collect::<Vec<_>>()
        };
        if image_ids.is_empty() {
            return;
        }
        let message = ProtocolMessage::Event(Event {
            sequence: Shared::next_sequence(),
            payload: EventPayload::KittyImagesRemoved { pane, image_ids },
        });
        let _ = self.enqueue_reliable(&message);
    }

    fn enqueue_pasted_image(
        &self,
        pane: PaneId,
        number: u32,
        token: u64,
        frames: &[Vec<u8>],
    ) -> PastedImageEnqueue {
        let mut state = self.state.lock();
        if state.closed {
            return PastedImageEnqueue::Closed;
        }
        if state
            .delivered_pasted_images
            .get(&pane)
            .and_then(|images| images.get(&number))
            == Some(&token)
        {
            return PastedImageEnqueue::AlreadyDelivered;
        }
        let Some(frame_bytes) = frames
            .iter()
            .try_fold(0_usize, |total, frame| total.checked_add(frame.len()))
        else {
            close_outbound(&mut state);
            self.ready.notify_all();
            return PastedImageEnqueue::Closed;
        };
        if state.reliable.len().saturating_add(frames.len()) > MAX_RELIABLE_MESSAGES
            || !reserve_outbound_bytes(&mut state, frame_bytes, 0)
        {
            close_outbound(&mut state);
            self.ready.notify_all();
            return PastedImageEnqueue::Closed;
        }
        for frame in frames {
            state.queued_bytes += frame.len();
            state.reliable.push_back(frame.clone());
        }
        state
            .delivered_pasted_images
            .entry(pane)
            .or_default()
            .insert(number, token);
        drop(state);
        self.ready.notify_one();
        PastedImageEnqueue::Queued
    }

    /// Queue one encoded `AgentUpdates` frame. Overflow clears the pane's lane
    /// and answers with a lag marker on the reliable lane instead of closing
    /// the connection: the journal makes the stream recoverable.
    #[cfg(feature = "agent")]
    fn enqueue_agent(&self, pane: PaneId, first_seq: u64, encoded: Vec<u8>) -> bool {
        let lagged_from = {
            let mut state = self.state.lock();
            if state.closed {
                return false;
            }
            let (queued_bytes, queued_first) =
                state.agent.get(&pane).map_or((0, first_seq), |queued| {
                    (
                        queued.bytes,
                        queued.frames.front().map_or(first_seq, |(seq, _)| *seq),
                    )
                });
            if queued_bytes.saturating_add(encoded.len()) > MAX_PENDING_AGENT_BYTES
                || !reserve_outbound_bytes(&mut state, encoded.len(), 0)
            {
                clear_pending_agent(&mut state, pane);
                Some(queued_first)
            } else {
                let fresh = queued_bytes == 0;
                state.queued_bytes += encoded.len();
                let queued = state.agent.entry(pane).or_default();
                queued.bytes = queued.bytes.saturating_add(encoded.len());
                queued.frames.push_back((first_seq, encoded));
                if fresh {
                    state.agent_order.push_back(pane);
                }
                None
            }
        };
        let Some(next_seq) = lagged_from else {
            self.ready.notify_one();
            return true;
        };
        log::warn!(
            target: "zz_daemon::diagnostics::outbound",
            "agent lane for {pane} overflowed; asking for a replay from {next_seq}",
        );
        self.enqueue_reliable(&Shared::event(EventPayload::AgentLagged { pane, next_seq }))
    }

    #[cfg(feature = "agent")]
    fn enqueue_agent_replay(&self, pane: PaneId, frames: Vec<(u64, Vec<u8>)>) -> bool {
        let Some(bytes) = frames
            .iter()
            .try_fold(0_usize, |total, (_, frame)| total.checked_add(frame.len()))
        else {
            return false;
        };
        let mut state = self.state.lock();
        if state.closed {
            return false;
        }
        let replaced = state.agent.get(&pane).map_or(0, |queued| queued.bytes);
        if bytes > MAX_PENDING_AGENT_REPLAY_BYTES
            || !reserve_outbound_bytes(&mut state, bytes, replaced)
        {
            close_outbound(&mut state);
            drop(state);
            self.ready.notify_all();
            return false;
        }
        clear_pending_agent(&mut state, pane);
        if frames.is_empty() {
            return true;
        }
        state.queued_bytes = state.queued_bytes.saturating_add(bytes);
        let queued = state.agent.entry(pane).or_default();
        queued.bytes = bytes;
        queued.frames.extend(frames);
        state.agent_order.push_back(pane);
        drop(state);
        self.ready.notify_one();
        true
    }

    #[cfg(feature = "agent")]
    fn cancel_agent(&self, pane: PaneId) {
        let mut state = self.state.lock();
        clear_pending_agent(&mut state, pane);
    }

    fn enqueue_terminal(&self, pane: PaneId, message: &ProtocolMessage) -> TerminalEnqueue {
        let Some(transition) = terminal_transition(pane, message) else {
            log::error!("refusing a non-terminal update in the terminal mailbox for {pane}");
            return TerminalEnqueue::Closed;
        };
        self.enqueue_terminal_with(pane, transition, |frame| {
            encode_protocol_message_into(message, frame)
        })
    }

    fn enqueue_terminal_viewport(
        &self,
        pane: PaneId,
        sequence: u64,
        viewport: &TerminalViewport,
    ) -> TerminalEnqueue {
        self.enqueue_terminal_with(
            pane,
            TerminalTransition {
                base: None,
                current: viewport_generation(viewport),
            },
            |frame| encode_terminal_viewport_event_into(pane, sequence, viewport, frame),
        )
    }

    fn enqueue_terminal_with(
        &self,
        pane: PaneId,
        transition: TerminalTransition,
        encode: impl FnOnce(&mut Vec<u8>) -> Result<(), ProtocolError>,
    ) -> TerminalEnqueue {
        {
            let state = self.state.lock();
            if state.closed {
                return TerminalEnqueue::Closed;
            }
            if state.terminals.contains_key(&pane) {
                return TerminalEnqueue::NeedsFull;
            }
            if transition.base.is_some()
                && transition.base != state.delivered_terminals.get(&pane).copied()
            {
                return TerminalEnqueue::NeedsFull;
            }
        }
        let Ok(encoded) = self.encode_with(encode) else {
            log::error!("failed to encode terminal update for {pane}");
            return TerminalEnqueue::Closed;
        };
        let mut state = self.state.lock();
        if state.closed {
            return TerminalEnqueue::Closed;
        }
        if state.terminals.contains_key(&pane) {
            recycle_outbound_frame(&mut state, encoded);
            return TerminalEnqueue::NeedsFull;
        }
        if transition.base.is_some()
            && transition.base != state.delivered_terminals.get(&pane).copied()
        {
            recycle_outbound_frame(&mut state, encoded);
            return TerminalEnqueue::NeedsFull;
        }
        if state.terminals.len() >= MAX_PENDING_TERMINALS
            || !reserve_outbound_bytes(&mut state, encoded.len(), 0)
        {
            close_outbound(&mut state);
            self.ready.notify_all();
            return TerminalEnqueue::Closed;
        }
        state.queued_bytes += encoded.len();
        state.terminals.insert(
            pane,
            PendingTerminal {
                encoded,
                current: transition.current,
            },
        );
        state.terminal_order.push_back(pane);
        drop(state);
        self.ready.notify_one();
        TerminalEnqueue::Queued
    }

    fn replace_terminal(&self, pane: PaneId, message: &ProtocolMessage) -> bool {
        let Some(transition) = terminal_transition(pane, message) else {
            log::error!("refusing a non-terminal update in the terminal mailbox for {pane}");
            return false;
        };
        self.replace_terminal_with(pane, transition, |frame| {
            encode_protocol_message_into(message, frame)
        })
    }

    fn replace_terminal_viewport(
        &self,
        pane: PaneId,
        sequence: u64,
        viewport: &TerminalViewport,
    ) -> bool {
        self.replace_terminal_with(
            pane,
            TerminalTransition {
                base: None,
                current: viewport_generation(viewport),
            },
            |frame| encode_terminal_viewport_event_into(pane, sequence, viewport, frame),
        )
    }

    fn replace_terminal_with(
        &self,
        pane: PaneId,
        transition: TerminalTransition,
        encode: impl FnOnce(&mut Vec<u8>) -> Result<(), ProtocolError>,
    ) -> bool {
        let Ok(encoded) = self.encode_with(encode) else {
            log::error!("failed to encode coalesced terminal update for {pane}");
            return false;
        };
        let mut state = self.state.lock();
        if state.closed {
            return false;
        }
        let replaced_len = state
            .terminals
            .get(&pane)
            .map_or(0, |pending| pending.encoded.len());
        if replaced_len == 0 && state.terminals.len() >= MAX_PENDING_TERMINALS
            || !reserve_outbound_bytes(&mut state, encoded.len(), replaced_len)
        {
            close_outbound(&mut state);
            self.ready.notify_all();
            return false;
        }
        state.queued_bytes = state
            .queued_bytes
            .saturating_sub(replaced_len)
            .saturating_add(encoded.len());
        let replaced = state.terminals.insert(
            pane,
            PendingTerminal {
                encoded,
                current: transition.current,
            },
        );
        if let Some(replaced) = replaced {
            recycle_outbound_frame(&mut state, replaced.encoded);
        } else {
            state.terminal_order.push_back(pane);
        }
        drop(state);
        self.ready.notify_one();
        true
    }

    fn replace_command_output(&self, message: &ProtocolMessage) -> bool {
        let Ok(encoded) = self.encode_message(message) else {
            log::error!("failed to encode command-output viewport");
            return false;
        };
        self.replace_encoded_command_output(encoded)
    }

    fn replace_encoded_command_output(&self, encoded: Vec<u8>) -> bool {
        let mut state = self.state.lock();
        if state.closed {
            return false;
        }
        let replaced_len = state.command_output.as_ref().map_or(0, Vec::len);
        if !reserve_outbound_bytes(&mut state, encoded.len(), replaced_len) {
            close_outbound(&mut state);
            self.ready.notify_all();
            return false;
        }
        state.queued_bytes = state
            .queued_bytes
            .saturating_sub(replaced_len)
            .saturating_add(encoded.len());
        let replaced = state.command_output.replace(encoded);
        if let Some(replaced) = replaced {
            recycle_outbound_frame(&mut state, replaced);
        }
        drop(state);
        self.ready.notify_one();
        true
    }

    fn recv(&self) -> Option<Vec<u8>> {
        let mut state = self.state.lock();
        loop {
            if let Some(frame) = state.reliable.pop_front() {
                state.queued_bytes = state.queued_bytes.saturating_sub(frame.len());
                return Some(frame);
            }
            if let Some(frame) = state.command_output.take() {
                state.queued_bytes = state.queued_bytes.saturating_sub(frame.len());
                return Some(frame);
            }
            // One frame per pane per turn: a chatty agent never starves the
            // pane beside it, and terminals still drain behind both.
            while let Some(pane) = state.agent_order.pop_front() {
                let Some(queued) = state.agent.get_mut(&pane) else {
                    continue;
                };
                let Some((_, frame)) = queued.frames.pop_front() else {
                    state.agent.remove(&pane);
                    continue;
                };
                queued.bytes = queued.bytes.saturating_sub(frame.len());
                if queued.frames.is_empty() {
                    state.agent.remove(&pane);
                } else {
                    state.agent_order.push_back(pane);
                }
                state.queued_bytes = state.queued_bytes.saturating_sub(frame.len());
                return Some(frame);
            }
            while let Some(pane) = state.terminal_order.pop_front() {
                if let Some(pending) = state.terminals.remove(&pane) {
                    state.queued_bytes = state.queued_bytes.saturating_sub(pending.encoded.len());
                    state.delivered_terminals.insert(pane, pending.current);
                    return Some(pending.encoded);
                }
            }
            if state.closed {
                return None;
            }
            self.ready.wait(&mut state);
        }
    }

    fn close(&self) {
        let mut state = self.state.lock();
        close_outbound(&mut state);
        drop(state);
        self.ready.notify_all();
    }

    fn close_after_flush(&self) {
        let mut state = self.state.lock();
        state.closed = true;
        drop(state);
        self.ready.notify_all();
    }

    fn mark_writer_finished(&self) {
        let mut state = self.state.lock();
        state.writer_finished = true;
        drop(state);
        self.ready.notify_all();
    }

    fn wait_writer_finished(&self, deadline: Instant) -> bool {
        let mut state = self.state.lock();
        while !state.writer_finished {
            if self.ready.wait_until(&mut state, deadline).timed_out() {
                return state.writer_finished;
            }
        }
        true
    }

    fn queued_reliable(&self) -> Option<(usize, usize)> {
        let state = self.state.lock();
        (!state.closed).then_some((state.queued_bytes, state.reliable.len()))
    }

    fn close_too_far_behind(&self) {
        let mut state = self.state.lock();
        close_outbound_too_far_behind(&mut state);
        drop(state);
        self.ready.notify_all();
    }

    #[cfg(test)]
    fn cancel_terminal(&self, pane: PaneId) {
        let mut state = self.state.lock();
        remove_pending_terminal(&mut state, pane);
        state.delivered_terminals.remove(&pane);
        state.delivered_images.remove(&pane);
        state.delivered_pasted_images.remove(&pane);
    }

    fn suspend_terminal(&self, pane: PaneId) {
        let mut state = self.state.lock();
        remove_pending_terminal(&mut state, pane);
        state.delivered_terminals.remove(&pane);
    }

    fn reset_kitty_images(&self) {
        self.state.lock().delivered_images.clear();
    }

    fn reset_pasted_images(&self) {
        self.state.lock().delivered_pasted_images.clear();
    }

    fn log_diagnostic_snapshot(&self, client: ClientId, reason: &str) {
        let state = self.state.lock();
        log::info!(
            target: "zz_daemon::diagnostics::outbound",
            "snapshot reason={reason} client={client} reliable_messages={} command_output_bytes={} agent_panes={} agent_frames={} terminal_messages={} delivered_terminals={} delivered_image_panes={} terminal_order={} recycled_frames={} recycled_capacity={} queued_bytes={} closed={}",
            state.reliable.len(),
            state.command_output.as_ref().map_or(0, Vec::len),
            state.agent.len(),
            state.agent.values().map(|queued| queued.frames.len()).sum::<usize>(),
            state.terminals.len(),
            state.delivered_terminals.len(),
            state.delivered_images.len(),
            state.terminal_order.len(),
            state.recycled_frames.len(),
            state.recycled_capacity,
            state.queued_bytes,
            state.closed,
        );
        log::trace!(
            target: "zz_daemon::diagnostics::outbound",
            "snapshot reason={reason} client={client} reliable_frame_lengths={:?} command_output_capacity={:?} terminals={:#?} delivered_terminals={:#?} terminal_order={:#?} recycled_frame_capacities={:?}",
            state.reliable.iter().map(Vec::len).collect::<Vec<_>>(),
            state.command_output.as_ref().map(Vec::capacity),
            state.terminals.iter().map(|(pane, pending)| (*pane, pending.encoded.len(), pending.encoded.capacity(), pending.current)).collect::<Vec<_>>(),
            state.delivered_terminals,
            state.terminal_order,
            state.recycled_frames.iter().map(Vec::capacity).collect::<Vec<_>>(),
        );
    }
}

fn take_recycled_frame(state: &mut OutboundState) -> Vec<u8> {
    let Some(frame) = state.recycled_frames.pop() else {
        return Vec::new();
    };
    state.recycled_capacity = state.recycled_capacity.saturating_sub(frame.capacity());
    frame
}

fn recycle_outbound_frame(state: &mut OutboundState, mut frame: Vec<u8>) {
    let capacity = frame.capacity();
    if state.closed
        || capacity == 0
        || state.recycled_frames.len() >= MAX_RECYCLED_FRAME_BUFFERS
        || state
            .recycled_capacity
            .checked_add(capacity)
            .is_none_or(|total| total > MAX_RECYCLED_FRAME_CAPACITY)
    {
        return;
    }
    frame.clear();
    state.recycled_capacity += capacity;
    state.recycled_frames.push(frame);
}

fn clear_pending_agent(state: &mut OutboundState, pane: PaneId) {
    if let Some(queued) = state.agent.remove(&pane) {
        state.queued_bytes = state.queued_bytes.saturating_sub(queued.bytes);
        for (_, frame) in queued.frames {
            recycle_outbound_frame(state, frame);
        }
    }
    state.agent_order.retain(|queued| *queued != pane);
}

fn remove_pending_terminal(state: &mut OutboundState, pane: PaneId) {
    if let Some(pending) = state.terminals.remove(&pane) {
        state.queued_bytes = state.queued_bytes.saturating_sub(pending.encoded.len());
        recycle_outbound_frame(state, pending.encoded);
    }
    state.terminal_order.retain(|queued| *queued != pane);
}

fn reserve_outbound_bytes(state: &mut OutboundState, incoming: usize, replaced: usize) -> bool {
    state
        .queued_bytes
        .saturating_sub(replaced)
        .checked_add(incoming)
        .is_some_and(|total| total <= MAX_OUTBOUND_BYTES)
}

fn close_outbound(state: &mut OutboundState) {
    state.closed = true;
    state.reliable.clear();
    state.command_output = None;
    state.agent.clear();
    state.agent_order.clear();
    state.terminals.clear();
    state.delivered_terminals.clear();
    state.delivered_images.clear();
    state.delivered_pasted_images.clear();
    state.terminal_order.clear();
    state.recycled_frames.clear();
    state.recycled_capacity = 0;
    state.queued_bytes = 0;
}

fn close_outbound_too_far_behind(state: &mut OutboundState) {
    let message = ProtocolMessage::Event(Event {
        sequence: 0,
        payload: EventPayload::ControlExit {
            reason: "too far behind".to_owned(),
        },
    });
    let mut encoded = Vec::new();
    let encoded = encode_protocol_message_into(&message, &mut encoded)
        .is_ok()
        .then_some(encoded);
    close_outbound(state);
    if let Some(encoded) = encoded {
        state.queued_bytes = encoded.len();
        state.reliable.push_back(encoded);
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DaemonCommandDispatch {
    CapturePane,
    RunShell,
    IfShell,
    AgentSend,
    SendLastOutput,
    CaptureBrowser,
    DebugMarker,
    Tools,
    Buffer,
    ListClients,
    ShowMessages,
    RefreshClient,
    WaitFor,
    PipePane,
    DisplayPopup,
    DisplayMenu,
    ConfirmBefore,
    Lock,
}

const DAEMON_COMMAND_DISPATCHES: &[(&str, DaemonCommandDispatch)] = &[
    ("capture-pane", DaemonCommandDispatch::CapturePane),
    ("capturep", DaemonCommandDispatch::CapturePane),
    ("run-shell", DaemonCommandDispatch::RunShell),
    ("run", DaemonCommandDispatch::RunShell),
    ("if-shell", DaemonCommandDispatch::IfShell),
    ("if", DaemonCommandDispatch::IfShell),
    ("agent-send", DaemonCommandDispatch::AgentSend),
    ("send-last-output", DaemonCommandDispatch::SendLastOutput),
    ("capture-browser", DaemonCommandDispatch::CaptureBrowser),
    ("debug-marker", DaemonCommandDispatch::DebugMarker),
    ("tools", DaemonCommandDispatch::Tools),
    ("set-buffer", DaemonCommandDispatch::Buffer),
    ("setb", DaemonCommandDispatch::Buffer),
    ("show-buffer", DaemonCommandDispatch::Buffer),
    ("showb", DaemonCommandDispatch::Buffer),
    ("list-buffers", DaemonCommandDispatch::Buffer),
    ("lsb", DaemonCommandDispatch::Buffer),
    ("load-buffer", DaemonCommandDispatch::Buffer),
    ("loadb", DaemonCommandDispatch::Buffer),
    ("save-buffer", DaemonCommandDispatch::Buffer),
    ("saveb", DaemonCommandDispatch::Buffer),
    ("delete-buffer", DaemonCommandDispatch::Buffer),
    ("deleteb", DaemonCommandDispatch::Buffer),
    ("paste-buffer", DaemonCommandDispatch::Buffer),
    ("pasteb", DaemonCommandDispatch::Buffer),
    ("list-clients", DaemonCommandDispatch::ListClients),
    ("lsc", DaemonCommandDispatch::ListClients),
    ("show-messages", DaemonCommandDispatch::ShowMessages),
    ("showmsgs", DaemonCommandDispatch::ShowMessages),
    ("refresh-client", DaemonCommandDispatch::RefreshClient),
    ("refresh", DaemonCommandDispatch::RefreshClient),
    ("wait-for", DaemonCommandDispatch::WaitFor),
    ("wait", DaemonCommandDispatch::WaitFor),
    ("pipe-pane", DaemonCommandDispatch::PipePane),
    ("pipep", DaemonCommandDispatch::PipePane),
    ("display-popup", DaemonCommandDispatch::DisplayPopup),
    ("popup", DaemonCommandDispatch::DisplayPopup),
    ("display-menu", DaemonCommandDispatch::DisplayMenu),
    ("menu", DaemonCommandDispatch::DisplayMenu),
    ("confirm-before", DaemonCommandDispatch::ConfirmBefore),
    ("confirm", DaemonCommandDispatch::ConfirmBefore),
    ("lock-client", DaemonCommandDispatch::Lock),
    ("lockc", DaemonCommandDispatch::Lock),
    ("lock-server", DaemonCommandDispatch::Lock),
    ("lock", DaemonCommandDispatch::Lock),
    ("lock-session", DaemonCommandDispatch::Lock),
    ("locks", DaemonCommandDispatch::Lock),
];

fn daemon_command_dispatch(name: &str) -> Option<DaemonCommandDispatch> {
    let name = canonical_command(name);
    DAEMON_COMMAND_DISPATCHES
        .iter()
        .find_map(|(candidate, dispatch)| (*candidate == name).then_some(*dispatch))
}

struct Shared {
    inner: Mutex<ServerState>,
    pipe_effects: Mutex<()>,
    /// Built on the first agent pane rather than at startup: a daemon that
    /// never opens one never touches the journal directory.
    #[cfg(feature = "agent")]
    agent: Mutex<Option<Arc<crate::agent::fanout::AgentRuntime>>>,
    #[cfg(feature = "agent")]
    agent_effects: Mutex<()>,
    #[cfg(feature = "agent")]
    agent_stopped: AtomicBool,
    kitty_image_frames: Mutex<BTreeMap<KittyImageKey, Arc<[Vec<u8>]>>>,
    pasted_images: Mutex<BTreeMap<PaneId, PanePastedImages>>,
    status: Mutex<StatusRenderer>,
    display_panes_deadline_tx: crossbeam_channel::Sender<DisplayPanesDeadlineCommand>,
    display_panes_deadline_rx:
        Mutex<Option<crossbeam_channel::Receiver<DisplayPanesDeadlineCommand>>>,
    stopping: AtomicBool,
    startup_ready: Mutex<bool>,
    startup_changed: Condvar,
    exit_empty_armed: AtomicBool,
    server_id: u64,
    load_user_config: bool,
    paste_directory: PathBuf,
    socket_path: PathBuf,
    #[cfg(test)]
    delivered_wrap_search_commands: Mutex<Vec<bool>>,
    #[cfg(unix)]
    tmux_shim: Mutex<Option<TmuxShimGuard>>,
}

#[derive(Clone)]
struct PendingHookEvent {
    name: &'static str,
    context: ExecutionContext,
    variables: BTreeMap<String, String>,
    exclude_client: Option<ClientId>,
}

#[derive(Clone)]
struct HookSessionState {
    name: String,
    active_window: WindowId,
}

#[derive(Clone)]
struct HookWindowState {
    session: SessionId,
    name: String,
    active_pane: PaneId,
    zoomed_pane: Option<PaneId>,
    layout: CellLayout,
    extent: (u16, u16),
}

#[derive(Clone)]
struct HookPaneState {
    session: SessionId,
    window: WindowId,
    title: String,
}

struct MuxHookSnapshot {
    sessions: BTreeMap<SessionId, HookSessionState>,
    windows: BTreeMap<WindowId, HookWindowState>,
    panes: BTreeMap<PaneId, HookPaneState>,
    links: BTreeSet<(SessionId, WindowId)>,
}

impl PendingHookEvent {
    fn session(
        name: &'static str,
        session: SessionId,
        state: &HookSessionState,
        snapshot: &MuxHookSnapshot,
    ) -> Self {
        let context = snapshot.session_context(session);
        Self {
            name,
            context,
            exclude_client: None,
            variables: BTreeMap::from([
                ("hook".to_owned(), name.to_owned()),
                ("hook_session".to_owned(), session.to_string()),
                ("hook_session_name".to_owned(), state.name.clone()),
            ]),
        }
    }

    fn window(
        name: &'static str,
        window: WindowId,
        state: &HookWindowState,
        snapshot: &MuxHookSnapshot,
    ) -> Self {
        let session_name = snapshot
            .sessions
            .get(&state.session)
            .map(|session| session.name.clone())
            .unwrap_or_default();
        Self {
            name,
            context: snapshot.window_context(window),
            exclude_client: None,
            variables: BTreeMap::from([
                ("hook".to_owned(), name.to_owned()),
                ("hook_session".to_owned(), state.session.to_string()),
                ("hook_session_name".to_owned(), session_name),
                ("hook_window".to_owned(), window.to_string()),
                ("hook_window_name".to_owned(), state.name.clone()),
                ("hook_pane".to_owned(), state.active_pane.to_string()),
            ]),
        }
    }

    fn winlink(
        name: &'static str,
        session: SessionId,
        session_state: &HookSessionState,
        window: WindowId,
        window_state: &HookWindowState,
        snapshot: &MuxHookSnapshot,
    ) -> Self {
        Self {
            name,
            context: snapshot.window_context(window),
            exclude_client: None,
            variables: BTreeMap::from([
                ("hook".to_owned(), name.to_owned()),
                ("hook_session".to_owned(), session.to_string()),
                ("hook_session_name".to_owned(), session_state.name.clone()),
                ("hook_window".to_owned(), window.to_string()),
                ("hook_window_name".to_owned(), window_state.name.clone()),
            ]),
        }
    }

    fn pane(
        name: &'static str,
        pane: PaneId,
        state: &HookPaneState,
        snapshot: &MuxHookSnapshot,
    ) -> Self {
        let window_name = snapshot
            .windows
            .get(&state.window)
            .map(|window| window.name.clone())
            .unwrap_or_default();
        let session_name = snapshot
            .sessions
            .get(&state.session)
            .map(|session| session.name.clone())
            .unwrap_or_default();
        Self {
            name,
            context: ExecutionContext::new(Some(state.session), Some(state.window), Some(pane)),
            exclude_client: None,
            variables: BTreeMap::from([
                ("hook".to_owned(), name.to_owned()),
                ("hook_session".to_owned(), state.session.to_string()),
                ("hook_session_name".to_owned(), session_name),
                ("hook_window".to_owned(), state.window.to_string()),
                ("hook_window_name".to_owned(), window_name),
                ("hook_pane".to_owned(), pane.to_string()),
            ]),
        }
    }

    fn client(
        name: &'static str,
        context: ExecutionContext,
        client: ClientId,
        client_name: Option<&str>,
        snapshot: &MuxHookSnapshot,
    ) -> Self {
        let mut variables = BTreeMap::from([
            ("hook".to_owned(), name.to_owned()),
            (
                "hook_client".to_owned(),
                client_name.map_or_else(|| format!("device-{}", client.0), str::to_owned),
            ),
        ]);
        if let Some(session) = context.session {
            variables.insert("hook_session".to_owned(), session.to_string());
            if let Some(state) = snapshot.sessions.get(&session) {
                variables.insert("hook_session_name".to_owned(), state.name.clone());
            }
        }
        Self {
            name,
            context,
            variables,
            exclude_client: (name == "client-detached").then_some(client),
        }
    }

    fn paste_buffer(name: &'static str, buffer: String) -> Self {
        Self {
            name,
            context: ExecutionContext::new(None, None, None),
            exclude_client: None,
            variables: BTreeMap::from([
                ("hook".to_owned(), name.to_owned()),
                ("hook_paste_buffer".to_owned(), buffer),
            ]),
        }
    }
}

impl MuxHookSnapshot {
    fn capture(engine: &MuxEngine) -> Self {
        let sessions = engine
            .state
            .sessions
            .iter()
            .map(|(session, state)| {
                (
                    *session,
                    HookSessionState {
                        name: state.name.clone(),
                        active_window: state.active_window,
                    },
                )
            })
            .collect();
        let windows = engine
            .state
            .windows
            .iter()
            .map(|(window, state)| {
                (
                    *window,
                    HookWindowState {
                        session: state.session,
                        name: state.name.clone(),
                        active_pane: state.active_pane,
                        zoomed_pane: state.zoomed_pane,
                        layout: state.layout.clone(),
                        extent: (
                            engine
                                .window_extent(*window, zz_protocol::Axis::Horizontal)
                                .unwrap_or_default(),
                            engine
                                .window_extent(*window, zz_protocol::Axis::Vertical)
                                .unwrap_or_default(),
                        ),
                    },
                )
            })
            .collect::<BTreeMap<_, _>>();
        let panes = engine
            .state
            .windows
            .iter()
            .flat_map(|(window, window_state)| {
                window_state.panes.iter().map(move |(pane, pane_state)| {
                    (
                        *pane,
                        HookPaneState {
                            session: window_state.session,
                            window: *window,
                            title: pane_state.title.clone(),
                        },
                    )
                })
            })
            .collect();
        let links = engine
            .state
            .sessions
            .iter()
            .flat_map(|(session, state)| {
                state.windows.iter().map(move |window| (*session, *window))
            })
            .collect();
        Self {
            sessions,
            windows,
            panes,
            links,
        }
    }

    fn session_context(&self, session: SessionId) -> ExecutionContext {
        let Some(state) = self.sessions.get(&session) else {
            return ExecutionContext::new(Some(session), None, None);
        };
        let pane = self
            .windows
            .get(&state.active_window)
            .map(|window| window.active_pane);
        ExecutionContext::new(Some(session), Some(state.active_window), pane)
    }

    fn window_context(&self, window: WindowId) -> ExecutionContext {
        self.windows.get(&window).map_or_else(
            || ExecutionContext::new(None, Some(window), None),
            |state| {
                ExecutionContext::new(Some(state.session), Some(window), Some(state.active_pane))
            },
        )
    }
}

fn mux_hook_events(
    before: &MuxHookSnapshot,
    after: &MuxHookSnapshot,
    command: &str,
) -> Vec<PendingHookEvent> {
    let mut events = Vec::new();
    for (session, window) in after.links.difference(&before.links) {
        if let (Some(session_state), Some(window_state)) =
            (after.sessions.get(session), after.windows.get(window))
        {
            events.push(PendingHookEvent::winlink(
                "window-linked",
                *session,
                session_state,
                *window,
                window_state,
                after,
            ));
        }
    }
    if command == "new-session" {
        for (session, state) in &after.sessions {
            if !before.sessions.contains_key(session) {
                events.push(PendingHookEvent::session(
                    "session-created",
                    *session,
                    state,
                    after,
                ));
            }
        }
    }
    if command == "rename-session" {
        for (session, state) in &after.sessions {
            if before
                .sessions
                .get(session)
                .is_some_and(|previous| previous.name != state.name)
            {
                events.push(PendingHookEvent::session(
                    "session-renamed",
                    *session,
                    state,
                    after,
                ));
            }
        }
    }
    for (session, state) in &after.sessions {
        if before
            .sessions
            .get(session)
            .is_some_and(|previous| previous.active_window != state.active_window)
            && let Some(window) = after.windows.get(&state.active_window)
        {
            events.push(PendingHookEvent::winlink(
                "session-window-changed",
                *session,
                state,
                state.active_window,
                window,
                after,
            ));
        }
    }
    for (window, state) in &after.windows {
        let Some(previous) = before.windows.get(window) else {
            continue;
        };
        if previous.name != state.name {
            events.push(PendingHookEvent::window(
                "window-renamed",
                *window,
                state,
                after,
            ));
        }
        if previous.layout != state.layout || previous.zoomed_pane != state.zoomed_pane {
            events.push(PendingHookEvent::window(
                "window-layout-changed",
                *window,
                state,
                after,
            ));
            if previous.extent != state.extent {
                events.push(PendingHookEvent::window(
                    "window-resized",
                    *window,
                    state,
                    after,
                ));
            }
        }
        if previous.active_pane != state.active_pane {
            events.push(PendingHookEvent::window(
                "window-pane-changed",
                *window,
                state,
                after,
            ));
        }
    }
    for (pane, state) in &after.panes {
        if before
            .panes
            .get(pane)
            .is_some_and(|previous| previous.title != state.title)
        {
            events.push(PendingHookEvent::pane(
                "pane-title-changed",
                *pane,
                state,
                after,
            ));
        }
    }
    let removed_links = before
        .links
        .difference(&after.links)
        .filter_map(|(session, window)| {
            Some(PendingHookEvent::winlink(
                "window-unlinked",
                *session,
                before.sessions.get(session)?,
                *window,
                before.windows.get(window)?,
                before,
            ))
        })
        .collect::<Vec<_>>();
    let closed_sessions = before
        .sessions
        .iter()
        .filter(|(session, _)| !after.sessions.contains_key(session))
        .map(|(session, state)| {
            PendingHookEvent::session("session-closed", *session, state, before)
        })
        .collect::<Vec<_>>();
    if command == "kill-session" {
        events.extend(closed_sessions);
        events.extend(removed_links);
    } else {
        events.extend(removed_links);
        events.extend(closed_sessions);
    }
    events
}

fn pane_mode_hook_events(
    before: &MuxHookSnapshot,
    after: &MuxHookSnapshot,
    before_modes: &BTreeSet<PaneId>,
    after_modes: &BTreeSet<PaneId>,
) -> Vec<PendingHookEvent> {
    before_modes
        .symmetric_difference(after_modes)
        .filter_map(|pane| {
            after
                .panes
                .get(pane)
                .map(|state| PendingHookEvent::pane("pane-mode-changed", *pane, state, after))
                .or_else(|| {
                    before.panes.get(pane).map(|state| {
                        PendingHookEvent::pane("pane-mode-changed", *pane, state, before)
                    })
                })
        })
        .collect()
}

#[derive(Clone, Copy)]
struct DisplayPanesDeadline {
    client: ClientId,
    token: u64,
    deadline: Instant,
}

enum DisplayPanesDeadlineCommand {
    Schedule(DisplayPanesDeadline),
    Cancel { client: ClientId, token: u64 },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct KittyImageKey {
    pane: PaneId,
    image_id: u32,
    generation: u64,
}

#[derive(Debug)]
struct PendingPastedImage {
    token: u64,
    format: PastedImageFormat,
    bytes: Arc<[u8]>,
}

#[derive(Debug)]
struct StoredPastedImage {
    token: u64,
    format: PastedImageFormat,
    bytes: Arc<[u8]>,
    frames: Option<Arc<[Vec<u8>]>>,
}

#[derive(Default, Debug)]
struct PanePastedImages {
    pending: VecDeque<PendingPastedImage>,
    images: BTreeMap<u32, StoredPastedImage>,
    order: VecDeque<(u32, u64)>,
    pending_bytes: usize,
    stored_bytes: usize,
}

struct PastedImageAdmission {
    evicted_numbers: Vec<u32>,
    retained: bool,
}

impl PanePastedImages {
    fn push_pending(&mut self, pending: PendingPastedImage) -> PastedImageAdmission {
        let token = pending.token;
        self.pending_bytes = self.pending_bytes.saturating_add(pending.bytes.len());
        self.pending.push_back(pending);
        let evicted_numbers = self.enforce_limits();
        PastedImageAdmission {
            evicted_numbers,
            retained: self.pending.iter().any(|pending| pending.token == token),
        }
    }

    fn bind(&mut self, token: u64, number: u32) -> Option<Vec<u32>> {
        let position = self
            .pending
            .iter()
            .position(|pending| pending.token == token)?;
        let pending = self.pending.remove(position)?;
        self.pending_bytes = self.pending_bytes.saturating_sub(pending.bytes.len());
        if let Some(replaced) = self.images.remove(&number) {
            self.stored_bytes = self.stored_bytes.saturating_sub(replaced.bytes.len());
            self.order.retain(|(stored_number, stored_token)| {
                *stored_number != number || *stored_token != replaced.token
            });
        }
        self.stored_bytes = self.stored_bytes.saturating_add(pending.bytes.len());
        self.order.push_back((number, token));
        self.images.insert(
            number,
            StoredPastedImage {
                token,
                format: pending.format,
                bytes: pending.bytes,
                frames: None,
            },
        );
        Some(self.enforce_limits())
    }

    fn enforce_limits(&mut self) -> Vec<u32> {
        let mut evicted = Vec::new();
        while self.images.len().saturating_add(self.pending.len()) > MAX_PASTED_IMAGES_PER_PANE
            || self.stored_bytes.saturating_add(self.pending_bytes)
                > MAX_PASTED_IMAGE_BYTES_PER_PANE
        {
            while self.order.front().is_some_and(|(number, token)| {
                self.images
                    .get(number)
                    .is_none_or(|image| image.token != *token)
            }) {
                self.order.pop_front();
            }
            if let Some((evicted_number, evicted_token)) = self.order.pop_front() {
                if let Some(image) = self.images.get(&evicted_number)
                    && image.token == evicted_token
                {
                    let image = self
                        .images
                        .remove(&evicted_number)
                        .expect("the pasted image was present");
                    self.stored_bytes = self.stored_bytes.saturating_sub(image.bytes.len());
                    evicted.push(evicted_number);
                }
            } else if let Some(pending) = self.pending.pop_back() {
                self.pending_bytes = self.pending_bytes.saturating_sub(pending.bytes.len());
            } else {
                break;
            }
        }
        evicted
    }

    fn expire(&mut self, token: u64) {
        if let Some(position) = self
            .pending
            .iter()
            .position(|pending| pending.token == token)
            && let Some(pending) = self.pending.remove(position)
        {
            self.pending_bytes = self.pending_bytes.saturating_sub(pending.bytes.len());
        }
    }
}

fn pasted_image_frames(
    pane: PaneId,
    number: u32,
    image: &mut StoredPastedImage,
) -> Option<Arc<[Vec<u8>]>> {
    if let Some(frames) = &image.frames {
        return Some(Arc::clone(frames));
    }
    let total_bytes = u32::try_from(image.bytes.len()).ok()?;
    let mut frames = Vec::with_capacity(
        1 + image
            .bytes
            .len()
            .div_ceil(zz_protocol::MAX_PASTE_UPLOAD_CHUNK_BYTES),
    );
    let begin = ProtocolMessage::PastedImageBegin {
        pane,
        number,
        format: image.format,
        total_bytes,
    };
    let mut encoded = Vec::new();
    encode_protocol_message_into(&begin, &mut encoded).ok()?;
    frames.push(encoded);
    for chunk in image
        .bytes
        .chunks(zz_protocol::MAX_PASTE_UPLOAD_CHUNK_BYTES)
    {
        let message = ProtocolMessage::PastedImageChunk {
            pane,
            number,
            bytes: chunk.to_vec(),
        };
        let mut encoded = Vec::new();
        encode_protocol_message_into(&message, &mut encoded).ok()?;
        frames.push(encoded);
    }
    let frames: Arc<[Vec<u8>]> = frames.into();
    image.frames = Some(Arc::clone(&frames));
    Some(frames)
}

struct ClientRegistrationGuard {
    shared: Arc<Shared>,
    client: ClientId,
    armed: bool,
}

impl ClientRegistrationGuard {
    fn new(shared: &Arc<Shared>, client: ClientId) -> Self {
        Self {
            shared: Arc::clone(shared),
            client,
            armed: true,
        }
    }

    fn unregister(&mut self) {
        if std::mem::take(&mut self.armed) {
            self.shared.unregister(self.client);
        }
    }
}

impl Drop for ClientRegistrationGuard {
    fn drop(&mut self) {
        self.unregister();
    }
}

impl Shared {
    #[cfg(unix)]
    fn install_tmux_shim(&self) -> Result<(), DaemonError> {
        let executable = std::env::var_os(crate::TMUX_SHIM_EXECUTABLE_ENVIRONMENT_VARIABLE)
            .map(PathBuf::from)
            .map_or_else(std::env::current_exe, Ok)?;
        let shim = TmuxShimGuard::install(executable)?;
        self.status
            .lock()
            .set_tmux_shim(shim.directory.clone(), shim.executable.clone());
        *self.tmux_shim.lock() = Some(shim);
        Ok(())
    }

    #[cfg(test)]
    fn with_appearance(server_id: u64, appearance: Arc<TerminalAppearance>) -> Self {
        Self::configured_with_boot_environment(
            server_id,
            appearance,
            AppearanceProvenance::default(),
            false,
            std::env::temp_dir().join("zz-test-paste"),
            std::env::temp_dir().join("zz-test.sock"),
            "emacs",
            "/usr/bin/vi",
            std::iter::empty::<(String, String)>(),
        )
    }

    fn configured(
        server_id: u64,
        appearance: Arc<TerminalAppearance>,
        appearance_provenance: AppearanceProvenance,
        load_user_config: bool,
        paste_directory: PathBuf,
        socket_path: PathBuf,
    ) -> Self {
        let visual = std::env::var_os("VISUAL");
        let editor = std::env::var_os("EDITOR");
        let default_editor = editor_from_environment(visual.as_deref(), editor.as_deref());
        Self::configured_with_boot_environment(
            server_id,
            appearance,
            appearance_provenance,
            load_user_config,
            paste_directory,
            socket_path,
            mode_keys_from_environment(visual.as_deref(), editor.as_deref()),
            &default_editor,
            daemon_environment(),
        )
    }

    fn configured_with_boot_environment<I, K, V>(
        server_id: u64,
        appearance: Arc<TerminalAppearance>,
        appearance_provenance: AppearanceProvenance,
        load_user_config: bool,
        paste_directory: PathBuf,
        socket_path: PathBuf,
        default_mode_keys: &str,
        default_editor: &str,
        environment: I,
    ) -> Self
    where
        I: IntoIterator<Item = (K, V)>,
        K: Into<String>,
        V: Into<String>,
    {
        let environment = environment
            .into_iter()
            .map(|(name, value)| (name.into(), value.into()))
            .collect::<Vec<(String, String)>>();
        let default_shell = resolve_runtime_default_shell(
            environment
                .iter()
                .find_map(|(name, value)| (name == "SHELL").then(|| OsStr::new(value))),
        );
        let mut state = ServerState {
            active_color_scheme: appearance.color_scheme,
            appearance,
            appearance_provenance,
            ..ServerState::default()
        };
        state
            .engine
            .set_default_mode_keys(default_mode_keys)
            .expect("daemon mode-keys default is valid");
        state.engine.initialize_default_editor(default_editor);
        state.engine.initialize_default_shell(default_shell);
        state.engine.seed_global_environment(environment);
        let (host, host_short) = host_names();
        state.engine.set_format_server_context(
            host.clone(),
            host_short.clone(),
            socket_path.display().to_string(),
            unix_timestamp(),
        );
        state
            .engine
            .set_format_server_identity(std::process::id(), daemon_uid(), daemon_user());
        for option in MuxOptionKey::ALL {
            let value = state.engine.mux_option_value(option);
            state
                .mux_options
                .set(option, value.clone(), MuxOptionSource::Default);
            state
                .mux_option_underlay
                .set(option, value, MuxOptionSource::Default);
        }
        let (display_panes_deadline_tx, display_panes_deadline_rx) = crossbeam_channel::unbounded();
        Self {
            inner: Mutex::new(state),
            pipe_effects: Mutex::new(()),
            #[cfg(feature = "agent")]
            agent: Mutex::new(None),
            #[cfg(feature = "agent")]
            agent_effects: Mutex::new(()),
            #[cfg(feature = "agent")]
            agent_stopped: AtomicBool::new(false),
            kitty_image_frames: Mutex::new(BTreeMap::new()),
            pasted_images: Mutex::new(BTreeMap::new()),
            status: Mutex::new(StatusRenderer::default()),
            display_panes_deadline_tx,
            display_panes_deadline_rx: Mutex::new(Some(display_panes_deadline_rx)),
            stopping: AtomicBool::new(false),
            startup_ready: Mutex::new(true),
            startup_changed: Condvar::new(),
            exit_empty_armed: AtomicBool::new(false),
            server_id,
            load_user_config,
            paste_directory,
            socket_path,
            #[cfg(test)]
            delivered_wrap_search_commands: Mutex::new(Vec::new()),
            #[cfg(unix)]
            tmux_shim: Mutex::new(None),
        }
    }

    fn begin_startup(&self) {
        *self.startup_ready.lock() = false;
    }

    fn finish_startup(&self) {
        *self.startup_ready.lock() = true;
        self.startup_changed.notify_all();
    }

    fn wait_for_startup(&self) -> bool {
        let mut ready = self.startup_ready.lock();
        while !*ready && !self.stopping.load(Ordering::Acquire) {
            self.startup_changed.wait(&mut ready);
        }
        *ready
    }

    #[cfg(test)]
    fn new(server_id: u64) -> Self {
        Self::with_appearance(server_id, Arc::new(TerminalAppearance::default()))
    }

    #[cfg(test)]
    fn initialize(self: &Arc<Self>, load_user_config: bool) -> Result<(), DaemonError> {
        self.initialize_with_mux_config_files(load_user_config, None)
    }

    fn initialize_with_mux_config_files(
        self: &Arc<Self>,
        load_user_config: bool,
        mux_config_files: Option<&[PathBuf]>,
    ) -> Result<(), DaemonError> {
        self.start_display_panes_deadline_dispatcher()?;
        let mut context = ExecutionContext::default();
        if load_user_config {
            if let Some(configs) = mux_config_files {
                for config in configs {
                    self.load_config_file(config, &mut context, 0)?;
                }
            } else if let Some(config) = default_mux_config().filter(|path| path.is_file()) {
                self.load_config_file(&config, &mut context, 0)?;
            }
        }
        self.apply_stored_mux_config_overrides("startup-mux-replay");
        let history_settings = {
            let inner = self.inner.lock();
            prompt_history_path(inner.engine.history_file())
                .map(|path| (path, inner.engine.prompt_history_limit()))
        };
        if let Some((path, limit)) = history_settings {
            let history = load_command_prompt_history(&path, limit);
            self.inner.lock().command_history = history;
        }
        // Building the runtime is what warms the adapter cache, so a daemon
        // that has agent panes enabled pays the npx download before the first
        // pane asks for it.
        #[cfg(feature = "agent")]
        {
            let agent_panes_enabled = self.inner.lock().engine.experimental_agent_pane();
            if agent_panes_enabled {
                let _ = self.agent_runtime();
            }
        }
        Ok(())
    }

    fn start_display_panes_deadline_dispatcher(self: &Arc<Self>) -> Result<(), DaemonError> {
        let Some(receiver) = self.display_panes_deadline_rx.lock().take() else {
            return Ok(());
        };
        let shared = Arc::downgrade(self);
        let (ready_tx, ready_rx) = crossbeam_channel::bounded(1);
        thread::Builder::new()
            .name("zz-display-panes".to_owned())
            .spawn(move || {
                if ready_tx.send(()).is_err() {
                    return;
                }
                let mut deadlines = BTreeMap::<ClientId, DisplayPanesDeadline>::new();
                loop {
                    let next = deadlines
                        .values()
                        .min_by_key(|deadline| deadline.deadline)
                        .copied();
                    let command = if let Some(next) = next {
                        let now = Instant::now();
                        if next.deadline <= now {
                            deadlines.remove(&next.client);
                            let Some(shared) = shared.upgrade() else {
                                return;
                            };
                            shared.expire_display_panes(next, now);
                            continue;
                        }
                        match receiver.recv_deadline(next.deadline) {
                            Ok(command) => command,
                            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                                deadlines.remove(&next.client);
                                let Some(shared) = shared.upgrade() else {
                                    return;
                                };
                                shared.expire_display_panes(next, Instant::now());
                                continue;
                            }
                            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => return,
                        }
                    } else {
                        let Ok(command) = receiver.recv() else {
                            return;
                        };
                        command
                    };
                    match command {
                        DisplayPanesDeadlineCommand::Schedule(deadline) => {
                            let Some(shared) = shared.upgrade() else {
                                return;
                            };
                            if shared
                                .inner
                                .lock()
                                .display_panes
                                .get(&deadline.client)
                                .is_some_and(|overlay| {
                                    overlay.token == deadline.token
                                        && overlay.deadline == Some(deadline.deadline)
                                })
                            {
                                deadlines.insert(deadline.client, deadline);
                            }
                        }
                        DisplayPanesDeadlineCommand::Cancel { client, token } => {
                            if deadlines
                                .get(&client)
                                .is_some_and(|deadline| deadline.token == token)
                            {
                                deadlines.remove(&client);
                            }
                        }
                    }
                }
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        ready_rx
            .recv()
            .map_err(|error| DaemonError::Thread(error.to_string()))
    }

    /// Bounded wait for every subscriber's writer to flush its queue to the
    /// socket before the process exits, so a stopping server's final events
    /// (the `kill-server` response, `ServerStopping`) reach clients instead
    /// of dying in mailboxes — the contract tmux calls `control_all_done`.
    fn drain_subscribers_for_shutdown(&self, timeout: Duration) {
        let mailboxes = {
            let inner = self.inner.lock();
            inner.subscribers.values().cloned().collect::<Vec<_>>()
        };
        let deadline = Instant::now() + timeout;
        for mailbox in &mailboxes {
            mailbox.close_after_flush();
        }
        for mailbox in &mailboxes {
            if !mailbox.wait_writer_finished(deadline) {
                log::warn!("shutdown proceeding before a client writer drained");
            }
        }
    }

    fn request_shutdown(&self) {
        self.stopping.store(true, Ordering::Release);
        self.startup_changed.notify_all();
        let (wakes, pipes, output_taps, shell_jobs, popups, menu_waiters, confirm_waiters) = {
            let mut inner = self.inner.lock();
            let wakes = take_all_wait_wakes(&mut inner.wait_channels);
            let pipes = std::mem::take(&mut inner.pane_pipes)
                .into_values()
                .collect::<Vec<_>>();
            let output_taps = std::mem::take(&mut inner.control_output_taps)
                .into_values()
                .collect::<Vec<_>>();
            let shell_jobs = std::mem::take(&mut inner.shell_jobs)
                .into_values()
                .collect::<Vec<_>>();
            let popups = std::mem::take(&mut inner.popups)
                .into_iter()
                .map(|(client, popup)| {
                    let subscriber = inner.subscribers.get(&client).cloned();
                    (client, (popup, subscriber))
                })
                .collect::<Vec<_>>();
            let menu_waiters = std::mem::take(&mut inner.menus)
                .into_values()
                .filter_map(|menu| menu.waiter)
                .collect::<Vec<_>>();
            let confirm_waiters = std::mem::take(&mut inner.confirms)
                .into_values()
                .filter_map(|confirm| match confirm.execution {
                    ConfirmExecution::Blocking { wake, .. } => Some(wake),
                    ConfirmExecution::Deferred { .. } | ConfirmExecution::Background { .. } => None,
                })
                .collect::<Vec<_>>();
            (
                wakes,
                pipes,
                output_taps,
                shell_jobs,
                popups,
                menu_waiters,
                confirm_waiters,
            )
        };
        wake_wait_items(wakes);
        for pipe in pipes {
            stop_pane_pipe(pipe);
        }
        for tap in output_taps {
            stop_control_output_tap(tap);
        }
        for process in shell_jobs {
            terminate_managed_process(&process);
        }
        for (client, popup) in popups {
            Self::retire_popup(client, popup, true);
        }
        for waiter in menu_waiters {
            let _ = waiter.wake.try_send(());
        }
        for waiter in confirm_waiters {
            let _ = waiter.try_send(false);
        }
    }

    fn should_shutdown_if_empty(&self, state: &ServerState) -> bool {
        self.exit_empty_armed.load(Ordering::Acquire)
            && state.engine.state.sessions.is_empty()
            && state.subscribers.is_empty()
    }

    fn refresh_status(&self, refresh: bool) {
        let requests = {
            let mut inner = self.inner.lock();
            inner.engine.set_format_now(unix_timestamp());
            let snapshot = inner.engine.state.snapshot();
            let facts = format_hook_facts(&inner);
            inner
                .subscribers
                .keys()
                .copied()
                .map(|client| {
                    let attached = client_attached_session(&inner, client);
                    StatusRequest {
                        client,
                        formats: inner.engine.status_formats_for_session(attached),
                        context: status_context(
                            &snapshot,
                            &inner.engine,
                            attached,
                            client_focused_window_for_attachment(&inner, client),
                        ),
                        facts: facts.clone(),
                    }
                })
                .collect::<Vec<_>>()
        };
        if requests.is_empty() {
            return;
        }
        let changed = self.status.lock().render_changed(&requests, refresh);
        for (client, status) in changed {
            self.publish_to_client(client, EventPayload::StatusChanged { status });
        }
    }

    fn refresh_control_subscriptions(&self) {
        let events = {
            let mut inner = self.inner.lock();
            inner.engine.set_format_now(unix_timestamp());
            let base_facts = format_hook_facts(&inner);
            let clients = inner.control_outputs.keys().copied().collect::<Vec<_>>();
            let mut events = Vec::new();
            for client in clients {
                let Some(session) = client_attached_session(&inner, client) else {
                    continue;
                };
                let client_facts = client_format_facts(&inner, client, session);
                let mut subscriptions = inner
                    .control_outputs
                    .get_mut(&client)
                    .map(|output| std::mem::take(&mut output.subscriptions))
                    .unwrap_or_default();
                for (name, subscription) in &mut subscriptions {
                    let mut current = BTreeMap::new();
                    for target in control_subscription_targets(&inner, session, subscription.scope)
                    {
                        let context = inner.engine.format_status_context(
                            Some(target.session),
                            target.window,
                            target.pane,
                        );
                        let facts = FormatHookFacts {
                            client: Some(client_facts.clone()),
                            ..base_facts.clone()
                        };
                        let mut hooks = DaemonFormatHooks::command(&facts);
                        let value =
                            expand_format_values(&subscription.format, &context, &mut hooks);
                        if subscription.previous.get(&target) != Some(&value) {
                            events.push((
                                client,
                                EventPayload::SubscriptionChanged {
                                    name: name.clone(),
                                    session: target.session,
                                    window: target.window,
                                    window_index: target.window_index,
                                    pane: target.pane,
                                    value: value.clone(),
                                },
                            ));
                        }
                        current.insert(target, value);
                    }
                    subscription.previous = current;
                }
                if let Some(output) = inner.control_outputs.get_mut(&client) {
                    output.subscriptions = subscriptions;
                }
            }
            events
        };
        for (client, payload) in events {
            self.publish_to_client(client, payload);
        }
    }

    fn start_status_sampler(self: &Arc<Self>) -> Result<(), DaemonError> {
        let shared = Arc::downgrade(self);
        thread::Builder::new()
            .name("zz-daemon-status".to_owned())
            .spawn(move || {
                let mut due = Instant::now();
                loop {
                    thread::sleep(CONTROL_SUBSCRIPTION_INTERVAL);
                    let Some(shared) = shared.upgrade() else {
                        break;
                    };
                    if shared.stopping.load(Ordering::Acquire) {
                        break;
                    }
                    shared.refresh_control_subscriptions();
                    let interval = {
                        let inner = shared.inner.lock();
                        inner
                            .subscribers
                            .keys()
                            .map(|client| {
                                inner
                                    .engine
                                    .status_formats_for_session(client_attached_session(
                                        &inner, *client,
                                    ))
                                    .interval
                            })
                            .filter(|interval| !interval.is_zero())
                            .min()
                            .unwrap_or_default()
                    };
                    if interval.is_zero() {
                        due = Instant::now();
                        continue;
                    }
                    let now = Instant::now();
                    if now < due {
                        continue;
                    }
                    due = now + interval;
                    shared.refresh_status(true);
                }
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        Ok(())
    }

    fn start_diagnostic_sampler(self: &Arc<Self>) -> Result<(), DaemonError> {
        if !log::log_enabled!(target: "zz_daemon::diagnostics::state", log::Level::Trace) {
            return Ok(());
        }
        let shared = Arc::downgrade(self);
        thread::Builder::new()
            .name("zz-daemon-diagnostics".to_owned())
            .spawn(move || {
                loop {
                    thread::sleep(DIAGNOSTIC_STATE_INTERVAL);
                    let Some(shared) = shared.upgrade() else {
                        break;
                    };
                    shared.log_diagnostic_snapshot("periodic");
                    if shared.stopping.load(Ordering::Acquire) {
                        break;
                    }
                }
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        Ok(())
    }

    fn log_diagnostic_snapshot(&self, reason: &str) {
        if !log::log_enabled!(target: "zz_daemon::diagnostics::state", log::Level::Trace) {
            return;
        }
        let DiagnosticSample {
            mux,
            terminals,
            command_outputs,
            subscribers,
            attached,
            visible_terminals,
            key_clients,
            copy_sessions,
            swallowed_keys,
            suppressed_text,
            command_prompts,
            choose_trees,
            choose_buffers,
            display_panes,
            command_history,
            paste_buffers,
            active_copy_pipes,
        } = DiagnosticSample::capture(&self.inner.lock());
        let attachment_count = attached.values().map(BTreeSet::len).sum::<usize>();
        log::info!(
            target: "zz_daemon::diagnostics::state",
            "snapshot reason={reason} server_id={} stopping={} mux_generation={} sessions={} terminals={} command_outputs={} subscribers={} attachments={} visible_terminal_clients={} key_clients={} copy_sessions={} swallowed_key_clients={} suppressed_text_clients={} command_prompts={} choose_trees={} choose_buffers={} display_panes={} command_history={} paste_buffers={} active_copy_pipes={}",
            self.server_id,
            self.stopping.load(Ordering::Acquire),
            mux.generation,
            mux.sessions.len(),
            terminals.len(),
            command_outputs.len(),
            subscribers.len(),
            attachment_count,
            visible_terminals.len(),
            key_clients.len(),
            copy_sessions.len(),
            swallowed_keys.len(),
            suppressed_text.len(),
            command_prompts.len(),
            choose_trees.len(),
            choose_buffers.len(),
            display_panes.len(),
            command_history.len(),
            paste_buffers.len(),
            active_copy_pipes,
        );
        log::trace!(
            target: "zz_daemon::diagnostics::state",
            "snapshot reason={reason} mux={mux:#?} attached={attached:#?} visible_terminals={visible_terminals:#?} key_clients={key_clients:#?} copy_sessions={copy_sessions:#?} swallowed_keys={swallowed_keys:#?} suppressed_text={suppressed_text:#?} command_prompt_clients={command_prompts:#?} choose_tree_clients={choose_trees:#?} choose_buffer_clients={choose_buffers:#?} display_panes_clients={display_panes:#?} command_history={command_history:#?} paste_buffers={paste_buffers:#?}",
        );
        for (pane, terminal) in terminals {
            let viewport = terminal.latest_viewport();
            log::info!(
                target: "zz_daemon::diagnostics::terminal_state",
                "snapshot reason={reason} pane={pane} terminal_strong_count={} diagnostics={:?}",
                Arc::strong_count(&terminal),
                terminal.diagnostics(),
            );
            log::trace!(
                target: "zz_daemon::diagnostics::terminal_state",
                "snapshot reason={reason} pane={pane} viewport={viewport:#?}"
            );
        }
        for (client, pane, terminal) in command_outputs {
            let viewport = terminal.latest_viewport();
            log::info!(
                target: "zz_daemon::diagnostics::terminal_state",
                "snapshot reason={reason} command_output_client={client} pane={pane} terminal_strong_count={} diagnostics={:?}",
                Arc::strong_count(&terminal),
                terminal.diagnostics(),
            );
            log::trace!(
                target: "zz_daemon::diagnostics::terminal_state",
                "snapshot reason={reason} command_output_client={client} pane={pane} viewport={viewport:#?}"
            );
        }
        for (client, subscriber) in subscribers {
            subscriber.log_diagnostic_snapshot(client, reason);
        }
    }

    fn register(
        &self,
        kind: ClientKind,
        client_instance_id: ClientInstanceId,
        device_name: Option<String>,
        color_scheme: Option<TerminalColorScheme>,
        client_has_terminal: bool,
    ) -> (ClientId, ServerHello) {
        let mut inner = self.inner.lock();
        inner.engine.set_format_now(unix_timestamp());
        let client = ClientId(inner.next_client_id);
        inner.next_client_id = inner.next_client_id.saturating_add(1);
        inner.client_instances.insert(client, client_instance_id);
        inner.client_kinds.insert(client, kind);
        if kind == ClientKind::Interactive && client_has_terminal {
            inner.client_terminals.insert(client);
        }
        if let Some(device_name) = device_name {
            inner.client_names.insert(client, device_name);
        }
        if kind == ClientKind::Interactive {
            let color_scheme = color_scheme.unwrap_or(inner.active_color_scheme);
            inner.client_color_schemes.insert(client, color_scheme);
            inner.active_color_scheme = color_scheme;
        }
        let capabilities = vec![
            "mux-v1".to_owned(),
            "terminal-viewport-v3".to_owned(),
            "terminal-row-patches".to_owned(),
            "terminal-visible-window-subscriptions".to_owned(),
            "terminal-native-selection".to_owned(),
            "terminal-async-regex-search".to_owned(),
            "terminal-osc8-links".to_owned(),
            "terminal-appearance-v2".to_owned(),
            "terminal-appearance-reload".to_owned(),
            "config-overrides-v1".to_owned(),
            "terminal-copy-pipe".to_owned(),
            "native-synchronize-panes".to_owned(),
            "native-command-prompt".to_owned(),
            "native-command-output-view".to_owned(),
            "native-choose-tree".to_owned(),
            "native-choose-buffer".to_owned(),
            "native-display-panes".to_owned(),
            "native-display-popup".to_owned(),
            "native-display-menu".to_owned(),
            "native-confirm-before".to_owned(),
            "native-split-resize".to_owned(),
            "native-pane-swap".to_owned(),
            "native-pane-relocation".to_owned(),
            "native-preset-layouts".to_owned(),
            "native-pane-rotation".to_owned(),
            "browser-panes".to_owned(),
            "tmux-config-subset".to_owned(),
            NEW_SESSION_ATTACH_CAPABILITY.to_owned(),
        ];
        let hello = ServerHello {
            protocol_version: PROTOCOL_VERSION,
            server_id: self.server_id,
            client_id: client,
            client_instance_id,
            capabilities,
            appearance: (*inner.appearance).clone(),
            appearance_provenance: inner.appearance_provenance.clone(),
            mux_options: inner.mux_options.clone(),
            status: StatusLine::default(),
            key_tables: inner.engine.keys.snapshot(),
        };
        let attached = client_attached_session(&inner, client);
        let request = StatusRequest {
            client,
            formats: inner.engine.status_formats_for_session(attached),
            context: status_context(
                &inner.engine.state.snapshot(),
                &inner.engine,
                attached,
                client_focused_window_for_attachment(&inner, client),
            ),
            facts: format_hook_facts(&inner),
        };
        drop(inner);
        let mut hello = hello;
        hello.status = self.status.lock().render_initial(&request);
        (client, hello)
    }

    fn subscribe(&self, client: ClientId, outbound: Arc<OutboundMailbox>) {
        let mut inner = self.inner.lock();
        inner.subscribers.insert(client, outbound);
        if inner.client_kinds.get(&client) == Some(&ClientKind::Control) {
            inner.control_outputs.entry(client).or_default();
        }
    }

    fn client_instance_id(&self, client: ClientId) -> Option<ClientInstanceId> {
        self.inner.lock().client_instances.get(&client).copied()
    }

    #[cfg(test)]
    fn register_subscribed(
        &self,
        kind: ClientKind,
        device_name: Option<String>,
        color_scheme: Option<TerminalColorScheme>,
        outbound: Arc<OutboundMailbox>,
    ) -> (ClientId, ServerHello) {
        let (client, hello) = self.register(
            kind,
            ClientInstanceId::default(),
            device_name,
            color_scheme,
            kind == ClientKind::Interactive,
        );
        if matches!(kind, ClientKind::Interactive | ClientKind::Control) {
            self.subscribe(client, outbound);
        }
        (client, hello)
    }

    fn unregister(self: &Arc<Self>, client: ClientId) {
        let (detached, _) = self.detach_client_state(client, false);
        if detached {
            self.publish_snapshot();
        }
        self.fail_gui_requests_for(client);
        self.status.lock().forget(client);
        let (terminals, command_output, popup_waiters, menu_waiters, confirm_waiters, shutdown) = {
            let mut inner = self.inner.lock();
            inner.subscribers.remove(&client);
            inner.client_color_schemes.remove(&client);
            inner.client_names.remove(&client);
            inner.client_instances.remove(&client);
            inner.client_kinds.remove(&client);
            inner.client_terminals.remove(&client);
            inner.control_outputs.remove(&client);
            inner.key_engines.remove(&client);
            inner.copy_sessions.remove(&client);
            inner.prefix_armed.remove(&client);
            inner.swallowed_keys.remove(&client);
            inner.suppressed_text.remove(&client);
            inner.command_prompts.remove(&client);
            inner.choose_trees.remove(&client);
            inner.choose_buffers.remove(&client);
            let _ = take_display_panes(&mut inner, client);
            inner.focused_windows.remove(&client);
            inner.client_terminal_input_sequences.remove(&client);
            inner
                .paste_uploads
                .retain(|(uploader, _), _| *uploader != client);
            remove_client_wait_items(&mut inner.wait_channels, client);
            let popup_waiters = inner
                .popups
                .values_mut()
                .filter_map(|popup| {
                    popup
                        .waiter
                        .as_ref()
                        .is_some_and(|waiter| waiter.client == client)
                        .then(|| popup.waiter.take())
                        .flatten()
                })
                .collect::<Vec<_>>();
            let menu_waiters = inner
                .menus
                .values_mut()
                .filter_map(|menu| {
                    menu.waiter
                        .as_ref()
                        .is_some_and(|waiter| waiter.client == client)
                        .then(|| menu.waiter.take())
                        .flatten()
                })
                .collect::<Vec<_>>();
            let confirm_waiters = inner
                .confirms
                .values_mut()
                .filter_map(|confirm| {
                    let ConfirmExecution::Blocking {
                        client: owner,
                        wake,
                    } = &confirm.execution
                    else {
                        return None;
                    };
                    (*owner == client).then(|| wake.clone())
                })
                .collect::<Vec<_>>();
            let shutdown = self.should_shutdown_if_empty(&inner);
            (
                inner.terminals.values().cloned().collect::<Vec<_>>(),
                inner.command_outputs.remove(&client),
                popup_waiters,
                menu_waiters,
                confirm_waiters,
                shutdown,
            )
        };
        let view = TerminalViewId(client.0);
        if let Some(command_output) = command_output {
            command_output.terminal.view_action(
                view,
                zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel),
            );
        }
        for terminal in terminals {
            terminal.release_view(view);
        }
        for waiter in popup_waiters {
            let _ = waiter.wake.try_send(129);
        }
        for waiter in menu_waiters {
            let _ = waiter.wake.try_send(());
        }
        for waiter in confirm_waiters {
            let _ = waiter.try_send(false);
        }
        self.refresh_control_output_taps();
        if shutdown {
            self.request_shutdown();
        }
    }

    fn execute_command_request(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        request_id: u64,
        command: &CommandInvocation,
    ) -> CommandResponse {
        let client_name = {
            let mut inner = self.inner.lock();
            let client_name = inner
                .client_names
                .get(&client)
                .cloned()
                .unwrap_or_else(|| format!("device-{}", client.0));
            let command = command_log_line(command);
            push_server_message(&mut inner, format!("{client_name} command: {command}"));
            client_name
        };
        let response = match self.execute(client, kind, context, command) {
            Ok(execution) => CommandResponse::Success {
                request_id,
                output: execution.output,
                exit_code: 0,
            },
            Err(DaemonError::CommandExit { output, exit_code }) => CommandResponse::Success {
                request_id,
                output,
                exit_code,
            },
            Err(DaemonError::CommandFailed { output, error }) => {
                let error = daemon_server_error(*error);
                let message = server_error_text(&error);
                let mut inner = self.inner.lock();
                push_server_message(&mut inner, format!("{client_name} message: {message}"));
                CommandResponse::Error {
                    request_id,
                    error,
                    output,
                }
            }
            Err(error) => {
                let error = daemon_server_error(error);
                let message = server_error_text(&error);
                let mut inner = self.inner.lock();
                push_server_message(&mut inner, format!("{client_name} message: {message}"));
                CommandResponse::Error {
                    request_id,
                    error,
                    output: String::new(),
                }
            }
        };
        let output = match &response {
            CommandResponse::Success { output, .. } | CommandResponse::Error { output, .. } => {
                output
            }
        };
        if kind == ClientKind::Interactive
            && !output.is_empty()
            && canonical_command(&command.name) != "new-session"
            && let Err(error) =
                self.open_command_output(client, context.pane, command.name.clone(), output)
        {
            self.publish_to_client(
                client,
                EventPayload::ClientMessage {
                    pane: context.pane,
                    kind: ClientMessageKind::Error,
                    text: error.to_string(),
                },
            );
        }
        response
    }

    fn execute(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        command: &CommandInvocation,
    ) -> Result<Execution, DaemonError> {
        self.execute_with_mux_source(
            client,
            kind,
            context,
            command,
            MuxOptionSource::RuntimeCommand,
        )
    }

    fn execute_with_mux_source(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        command: &CommandInvocation,
        mux_source: MuxOptionSource,
    ) -> Result<Execution, DaemonError> {
        let client_terminal = if context.has_no_client() {
            ClientTerminal::NoClient
        } else {
            client_terminal(&self.inner.lock(), client, kind)
        };
        self.execute_with_mux_source_for_terminal(
            client,
            kind,
            context,
            command,
            mux_source,
            client_terminal,
        )
    }

    fn execute_with_mux_source_for_terminal(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        command: &CommandInvocation,
        mux_source: MuxOptionSource,
        client_terminal: ClientTerminal,
    ) -> Result<Execution, DaemonError> {
        let no_hooks = context.no_hooks;
        let original_context = context.clone();
        let name = canonical_command(&command.name).to_owned();
        let previous_client_terminal = context_client_terminal(context);
        set_context_client_terminal(context, client_terminal);
        let result = self.execute_with_mux_source_raw(
            client,
            kind,
            context,
            command,
            mux_source,
            client_terminal,
        );
        set_context_client_terminal(context, previous_client_terminal);
        let hook_output = if no_hooks {
            String::new()
        } else {
            let (hook, mut hook_context) = match &result {
                Ok(execution) => (
                    format!("after-{name}"),
                    self.command_hook_context(&name, execution, context),
                ),
                Err(_) => ("command-error".to_owned(), original_context),
            };
            {
                let inner = self.inner.lock();
                inner.engine.repair_context(&mut hook_context);
            }
            self.run_command_hook(client, kind, &hook_context, command, &hook)
        };
        match result {
            Ok(mut execution) => {
                append_inserted_output(&mut execution.output, &hook_output);
                Ok(execution)
            }
            Err(DaemonError::CommandExit {
                mut output,
                exit_code,
            }) => {
                append_inserted_output(&mut output, &hook_output);
                Err(DaemonError::CommandExit { output, exit_code })
            }
            Err(DaemonError::CommandFailed { mut output, error }) => {
                append_inserted_output(&mut output, &hook_output);
                Err(DaemonError::CommandFailed { output, error })
            }
            Err(error) if hook_output.is_empty() => Err(error),
            Err(error) => Err(DaemonError::CommandFailed {
                output: hook_output,
                error: Box::new(error),
            }),
        }
    }

    fn execute_with_mux_source_raw(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        command: &CommandInvocation,
        mux_source: MuxOptionSource,
        client_terminal: ClientTerminal,
    ) -> Result<Execution, DaemonError> {
        let canonical = canonical_command(&command.name);
        let preempted = zz_mux::CommandSpec::DAEMON_COMMAND_NAMES
            .contains(&canonical)
            .then(|| {
                match daemon_command_dispatch(canonical)
                    .expect("daemon command catalog and dispatch must agree")
                {
                    DaemonCommandDispatch::CapturePane => self.capture_pane(context, &command.args),
                    DaemonCommandDispatch::RunShell => {
                        self.run_shell(client, kind, context, &command.args)
                    }
                    DaemonCommandDispatch::IfShell => {
                        self.if_shell(client, kind, context, &command.args)
                    }
                    DaemonCommandDispatch::AgentSend => self.agent_send(context, &command.args),
                    DaemonCommandDispatch::SendLastOutput => {
                        self.send_last_output(context, &command.args)
                    }
                    DaemonCommandDispatch::CaptureBrowser => {
                        self.capture_browser(context, &command.args)
                    }
                    DaemonCommandDispatch::DebugMarker => {
                        Ok(debug_marker(client, context, &command.args))
                    }
                    DaemonCommandDispatch::Tools => Ok(workspace_tools_catalog()),
                    DaemonCommandDispatch::Buffer => {
                        self.buffer_command(context, canonical, &command.args)
                    }
                    DaemonCommandDispatch::ListClients => {
                        self.list_clients(context, canonical, &command.args)
                    }
                    DaemonCommandDispatch::ShowMessages => {
                        self.show_messages(canonical, &command.args)
                    }
                    DaemonCommandDispatch::RefreshClient => {
                        self.refresh_client(client, kind, canonical, &command.args)
                    }
                    DaemonCommandDispatch::WaitFor => self.wait_for(client, kind, &command.args),
                    DaemonCommandDispatch::PipePane => self.pipe_pane(context, &command.args),
                    DaemonCommandDispatch::DisplayPopup => {
                        self.display_popup(client, kind, context, &command.args)
                    }
                    DaemonCommandDispatch::DisplayMenu => {
                        self.display_menu(client, kind, context, &command.args)
                    }
                    DaemonCommandDispatch::ConfirmBefore => {
                        self.confirm_before(client, kind, context, &command.args)
                    }
                    DaemonCommandDispatch::Lock => {
                        self.lock_command(client, context, canonical, &command.args)
                    }
                }
            });
        if let Some(result) = preempted {
            if result.is_ok() {
                self.inner.lock().engine.repair_context(context);
            }
            return result;
        }
        let generation = self.inner.lock().engine.state.generation();
        let result = self.execute_with_mux_source_inner(
            client,
            kind,
            context,
            command,
            mux_source,
            client_terminal,
        );
        let publish_snapshot = {
            let inner = self.inner.lock();
            let current = inner.engine.state.generation();
            current != generation && inner.last_published_mux_generation != current
        };
        if publish_snapshot {
            self.publish_snapshot();
        }
        result
    }

    fn command_hook_context(
        &self,
        name: &str,
        execution: &Execution,
        context: &ExecutionContext,
    ) -> ExecutionContext {
        let mut hook_context = context.clone();
        if matches!(name, "new-session" | "new-window" | "split-window")
            && let Some(pane) = execution.effects.iter().find_map(|effect| match effect {
                MuxEffect::PaneCreated { pane, .. } => Some(*pane),
                _ => None,
            })
        {
            let inner = self.inner.lock();
            hook_context.retarget_to_pane(&inner.engine.state, pane);
        }
        hook_context
    }

    fn run_command_hook(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &ExecutionContext,
        command: &CommandInvocation,
        hook: &str,
    ) -> String {
        let commands = self
            .inner
            .lock()
            .engine
            .hook_commands(context.session, hook);
        let Some(commands) = commands else {
            return String::new();
        };
        self.run_hook_commands(
            client,
            kind,
            context,
            commands,
            &hook_format_variables(command, hook),
        )
    }

    fn run_hook_commands(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &ExecutionContext,
        commands: Vec<Vec<CommandInvocation>>,
        variables: &BTreeMap<String, String>,
    ) -> String {
        self.run_hook_commands_with_policy(client, kind, context, commands, variables, false)
    }

    fn run_hook_commands_with_policy(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &ExecutionContext,
        commands: Vec<Vec<CommandInvocation>>,
        variables: &BTreeMap<String, String>,
        skip_resolution_errors: bool,
    ) -> String {
        let mut output = String::new();
        for commands in commands {
            let mut hook_context = context.clone();
            hook_context.set_no_client();
            hook_context.enter_hook(variables.clone());
            for command in commands {
                hook_context.no_hooks = true;
                hook_context.format_variables.clone_from(variables);
                match self.execute(client, kind, &mut hook_context, &command) {
                    Ok(execution) => {
                        append_inserted_output(&mut output, &execution.output);
                    }
                    Err(error) => {
                        if skip_resolution_errors && hook_resolution_error(&error) {
                            break;
                        }
                        if let Some(error_output) = daemon_error_output(&error) {
                            append_inserted_output(&mut output, error_output);
                        }
                        self.publish_background_command_error(client, &hook_context, &error, false);
                        break;
                    }
                }
            }
        }
        output
    }

    fn run_event_hooks(self: &Arc<Self>, events: Vec<PendingHookEvent>) {
        for event in events {
            let attached_only = matches!(
                event.name,
                "window-layout-changed"
                    | "window-linked"
                    | "window-unlinked"
                    | "window-renamed"
                    | "client-session-changed"
            );
            self.publish_to_control_clients(
                EventPayload::HookEvent {
                    name: event.name.to_owned(),
                    variables: event.variables.clone(),
                },
                event.exclude_client,
                attached_only,
            );
            let (context, commands) = {
                let inner = self.inner.lock();
                let mut context = event.context.clone();
                inner.engine.repair_event_context(&mut context);
                let commands = inner.engine.event_hook_commands(&context, event.name);
                (context, commands)
            };
            let Some(commands) = commands else {
                continue;
            };
            let _ = self.run_hook_commands_with_policy(
                ClientId(u64::MAX),
                ClientKind::Command,
                &context,
                commands,
                &event.variables,
                true,
            );
        }
    }

    fn execute_with_mux_source_inner(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        command: &CommandInvocation,
        mux_source: MuxOptionSource,
        client_terminal: ClientTerminal,
    ) -> Result<Execution, DaemonError> {
        let format_variables = context.format_variables.clone();
        let event_hooks_enabled = !context.no_hooks;
        let command_name = canonical_command(&command.name);
        let mut terminals_to_watch = Vec::new();
        let mut client_events = Vec::new();
        let mut direct_events = Vec::new();
        let mut source_files = Vec::new();
        let mut removed_panes = Vec::new();
        let mut agent_panes_opened = Vec::new();
        #[cfg(feature = "agent")]
        let mut agent_panes_restarted = Vec::new();
        let mut relocated_terminal_views = Vec::new();
        let mut retired_command_outputs = Vec::new();
        let mut retired_popups = Vec::new();
        let mut deferred_terminal_commands = Vec::new();
        let mut unfocused_copy_mode_exits = Vec::new();
        let mut cleared_bells = Vec::new();
        let mut pipes_to_close = Vec::new();
        let mut pipe_taps_to_rearm = Vec::new();
        let mut display_panes_deadline = None;
        let mut attach = None;
        let mut detach = None;
        let mut detached_session = None;
        let mut reload_config = false;
        let mut snapshot_changed = false;
        let mut mux_options_changed = false;
        #[cfg(feature = "agent")]
        let mut agent_options_changed = false;
        let mut status_formats_changed = false;
        let mut shutdown_requested = false;
        let mut immediate_hooks = Vec::new();
        let mut pending_hook_events = Vec::new();
        let (mut execution, mux_options_event) = {
            let mut inner = self.inner.lock();
            let hook_snapshot_before =
                event_hooks_enabled.then(|| MuxHookSnapshot::capture(&inner.engine));
            let copy_modes_before = event_hooks_enabled.then(|| {
                inner
                    .copy_sessions
                    .values()
                    .map(|session| session.pane)
                    .collect::<BTreeSet<_>>()
            });
            let active_windows_before = inner
                .engine
                .state
                .sessions
                .iter()
                .map(|(session, state)| (*session, state.active_window))
                .collect::<BTreeMap<_, _>>();
            let active_panes_before = inner
                .engine
                .state
                .windows
                .iter()
                .map(|(window, state)| (*window, state.active_pane))
                .collect::<BTreeMap<_, _>>();
            let belled_panes_before = inner
                .engine
                .state
                .windows
                .values()
                .flat_map(|window| window.panes.values())
                .filter(|pane| pane.bell)
                .map(|pane| pane.id)
                .collect::<BTreeSet<_>>();
            let mut focused_windows_before = BTreeMap::new();
            for (session, clients) in &inner.attached {
                let Some(state) = inner.engine.state.sessions.get(session) else {
                    continue;
                };
                for attached_client in clients {
                    focused_windows_before.insert(
                        (*session, *attached_client),
                        client_focused_window(&inner, *attached_client, state),
                    );
                }
            }
            let facts = format_hook_facts(&inner);
            let mut hooks = DaemonFormatHooks::command_with_optional_variables(
                &facts,
                (!format_variables.is_empty()).then_some(&format_variables),
            );
            inner.engine.set_format_now(unix_timestamp());
            let previous_client_terminal = context_client_terminal(context);
            set_context_client_terminal(context, client_terminal);
            let execution = inner.engine.execute_with_shell_validator(
                context,
                command,
                &mut hooks,
                &mut |shell| shell_is_valid(Path::new(shell)),
            );
            set_context_client_terminal(context, previous_client_terminal);
            let execution = execution?;
            if !inner.engine.state.sessions.is_empty() {
                self.exit_empty_armed.store(true, Ordering::Release);
            }
            let selected_panes = inner
                .engine
                .state
                .windows
                .iter()
                .filter_map(|(window, state)| {
                    active_panes_before
                        .get(window)
                        .is_some_and(|previous| *previous != state.active_pane)
                        .then_some(state.active_pane)
                })
                .collect::<Vec<_>>();
            for pane in selected_panes {
                if inner.engine.state.set_pane_bell(pane, false) {
                    snapshot_changed = true;
                }
            }
            for pane in belled_panes_before {
                if inner.engine.state.pane(pane).is_none_or(|pane| !pane.bell) {
                    snapshot_changed = true;
                    if let Some(terminal) = inner.terminals.get(&pane) {
                        cleared_bells.push(Arc::clone(terminal));
                    }
                }
            }
            let changed_windows = inner
                .engine
                .state
                .sessions
                .iter()
                .filter_map(|(session, state)| {
                    active_windows_before
                        .get(session)
                        .is_some_and(|previous| *previous != state.active_window)
                        .then_some((*session, state.active_window))
                })
                .collect::<Vec<_>>();
            for (session, focused_window) in changed_windows {
                let attached = inner.attached.get(&session).cloned().unwrap_or_default();
                if attached.contains(&client) {
                    for attached_client in attached {
                        let focus = if attached_client == client {
                            focused_window
                        } else {
                            focused_windows_before
                                .get(&(session, attached_client))
                                .copied()
                                .unwrap_or(focused_window)
                        };
                        inner.focused_windows.insert(attached_client, focus);
                    }
                } else {
                    for attached_client in attached {
                        inner
                            .focused_windows
                            .insert(attached_client, focused_window);
                    }
                }
            }
            let resized_windows = focused_windows_before
                .iter()
                .filter_map(|((session, attached_client), previous)| {
                    let state = inner.engine.state.sessions.get(session)?;
                    let current = client_focused_window(&inner, *attached_client, state);
                    (*previous != current).then_some([*previous, current])
                })
                .flatten()
                .collect::<BTreeSet<_>>();
            let resized_panes = panes_for_windows(&inner, &resized_windows);
            snapshot_changed |= write_back_terminal_geometries(&mut inner, &resized_panes, true);
            for effect in &execution.effects {
                match effect {
                    MuxEffect::PaneCreated {
                        pane,
                        kind: PaneKindSnapshot::Terminal,
                        inherit_cwd_from,
                        cwd,
                        command,
                    }
                    | MuxEffect::PaneMaterialized {
                        pane,
                        kind: PaneKindSnapshot::Terminal,
                        inherit_cwd_from,
                        cwd,
                        command,
                    } => {
                        let history_limit = inner.engine.history_limit_for_pane(*pane)?;
                        let word_separators =
                            WordSeparators::new(inner.engine.word_separators_for_pane(*pane)?);
                        let working_directory = match cwd.as_deref().map(PathBuf::from) {
                            Some(path) if path.is_dir() => Some(path),
                            Some(_) => std::env::var_os("HOME")
                                .map(PathBuf::from)
                                .filter(|path| path.is_dir())
                                .or_else(|| Some(PathBuf::from("/"))),
                            None => inherit_cwd_from
                                .and_then(|source| inner.terminals.get(&source))
                                .and_then(|terminal| terminal_working_directory(terminal))
                                .or_else(|| std::env::current_dir().ok()),
                        };
                        let start_path = working_directory
                            .as_deref()
                            .map(|path| path.to_string_lossy().into_owned())
                            .unwrap_or_default();
                        let terminal_options =
                            terminal_worker_options(&inner.engine, &inner.appearance, *pane)?;
                        let appearance = Arc::clone(&terminal_options.appearance);
                        let pane_session = inner
                            .engine
                            .state
                            .window_for_pane(*pane)
                            .map(|window| inner.engine.state.windows[&window].session)
                            .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
                        let command = if let Some(command) =
                            command.clone().filter(|command| !command.is_empty())
                        {
                            Some(command)
                        } else {
                            let default = inner.engine.default_command_for_session(pane_session)?;
                            (!default.is_empty()).then(|| vec![default.to_owned()])
                        };
                        inner
                            .engine
                            .set_pane_start_command(*pane, command.clone().unwrap_or_default())?;
                        let shell = Some(terminal_shell_for_session(&inner.engine, pane_session)?);
                        let mut env =
                            terminal_environment_for_session(&inner.engine, pane_session)?;
                        env.extend([
                            ("ZZ_PANE".to_owned(), Some(pane.to_string())),
                            (
                                "ZZ_SOCKET".to_owned(),
                                Some(self.socket_path.display().to_string()),
                            ),
                            ("ZZ_SESSION".to_owned(), Some(pane_session.to_string())),
                            (
                                "TMUX".to_owned(),
                                Some(tmux_environment(&self.socket_path, Some(pane_session))),
                            ),
                            ("TMUX_PANE".to_owned(), Some(pane.to_string())),
                        ]);
                        if let Some(path) = &working_directory {
                            env.push(("PWD".to_owned(), Some(path.to_string_lossy().into_owned())));
                        }
                        let spawn = TerminalSpawn {
                            working_directory: working_directory.clone(),
                            command,
                            shell,
                            terminal_type: Some(
                                inner.engine.default_terminal_for_spawn().to_owned(),
                            ),
                            initial_size: None,
                            non_login_shell: false,
                            env,
                        };
                        let session = Arc::new(TerminalSession::spawn(
                            history_limit,
                            appearance,
                            spawn.clone(),
                        ));
                        let current_path = terminal_working_directory(&session)
                            .map(|path| path.to_string_lossy().into_owned())
                            .unwrap_or_default();
                        deferred_terminal_commands.push(
                            DeferredTerminalCommand::SetWordSeparators {
                                terminal: Arc::clone(&session),
                                separators: word_separators,
                            },
                        );
                        deferred_terminal_commands.push(
                            DeferredTerminalCommand::SetAllowPassthrough {
                                terminal: Arc::clone(&session),
                                enabled: terminal_options.allow_passthrough,
                            },
                        );
                        deferred_terminal_commands.push(DeferredTerminalCommand::SetWrapSearch {
                            terminal: Arc::clone(&session),
                            enabled: terminal_options.wrap_search,
                        });
                        inner.terminals.insert(*pane, Arc::clone(&session));
                        inner.terminal_spawns.insert(*pane, spawn);
                        inner.engine.set_pane_runtime_facts_with_hooks(
                            *pane,
                            PaneRuntimeFacts {
                                current_path,
                                start_path,
                                ..PaneRuntimeFacts::default()
                            },
                            &mut hooks,
                        );
                        let attached_clients = inner
                            .engine
                            .state
                            .window_for_pane(*pane)
                            .map(|window| inner.engine.state.windows[&window].session)
                            .and_then(|session| inner.attached.get(&session))
                            .cloned()
                            .unwrap_or_default();
                        for client in attached_clients {
                            deferred_terminal_commands.push(DeferredTerminalCommand::AttachView {
                                terminal: Arc::clone(&session),
                                view: TerminalViewId(client.0),
                            });
                        }
                        terminals_to_watch.push((*pane, session));
                    }
                    MuxEffect::PaneRespawned {
                        pane,
                        cwd,
                        command,
                        environment,
                        empty,
                    } => {
                        let previous = inner.terminal_spawns.get(pane).cloned().unwrap_or_default();
                        let history_limit = inner.engine.history_limit_for_pane(*pane)?;
                        let word_separators =
                            WordSeparators::new(inner.engine.word_separators_for_pane(*pane)?);
                        let working_directory = match cwd.as_deref().map(PathBuf::from) {
                            Some(path) => {
                                let path = if path.is_absolute() {
                                    path
                                } else if let Some(base) = &previous.working_directory {
                                    base.join(&path)
                                } else {
                                    path
                                };
                                if path.is_dir() {
                                    Some(path)
                                } else {
                                    std::env::var_os("HOME")
                                        .map(PathBuf::from)
                                        .filter(|path| path.is_dir())
                                        .or_else(|| Some(PathBuf::from("/")))
                                }
                            }
                            None => previous
                                .working_directory
                                .clone()
                                .or_else(|| std::env::current_dir().ok()),
                        };
                        let start_path = working_directory
                            .as_deref()
                            .map(|path| path.to_string_lossy().into_owned())
                            .unwrap_or_default();
                        let terminal_options =
                            terminal_worker_options(&inner.engine, &inner.appearance, *pane)?;
                        let appearance = Arc::clone(&terminal_options.appearance);
                        let pane_session = inner
                            .engine
                            .state
                            .window_for_pane(*pane)
                            .map(|window| inner.engine.state.windows[&window].session)
                            .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
                        let command = command
                            .clone()
                            .filter(|command| !command.is_empty())
                            .or_else(|| previous.command.clone());
                        let shell = match previous.shell.clone() {
                            Some(shell) => Some(shell),
                            None => Some(terminal_shell_for_session(&inner.engine, pane_session)?),
                        };
                        let mut env =
                            terminal_environment_for_session(&inner.engine, pane_session)?;
                        env.extend([
                            ("ZZ_PANE".to_owned(), Some(pane.to_string())),
                            (
                                "ZZ_SOCKET".to_owned(),
                                Some(self.socket_path.display().to_string()),
                            ),
                            ("ZZ_SESSION".to_owned(), Some(pane_session.to_string())),
                            (
                                "TMUX".to_owned(),
                                Some(tmux_environment(&self.socket_path, Some(pane_session))),
                            ),
                        ]);
                        env.extend(
                            environment
                                .iter()
                                .map(|(name, value)| (name.clone(), Some(value.clone()))),
                        );
                        env.push(("TMUX_PANE".to_owned(), Some(pane.to_string())));
                        if let Some(path) = &working_directory {
                            env.push(("PWD".to_owned(), Some(path.to_string_lossy().into_owned())));
                        }
                        let spawn = TerminalSpawn {
                            working_directory: working_directory.clone(),
                            command,
                            shell,
                            terminal_type: Some(
                                inner.engine.default_terminal_for_spawn().to_owned(),
                            ),
                            initial_size: None,
                            non_login_shell: false,
                            env,
                        };
                        let session = Arc::new(if *empty {
                            TerminalSession::spawn_empty_with_appearance(history_limit, appearance)
                        } else {
                            TerminalSession::spawn(history_limit, appearance, spawn.clone())
                        });
                        let current_path = if *empty {
                            start_path.clone()
                        } else {
                            terminal_working_directory(&session)
                                .map(|path| path.to_string_lossy().into_owned())
                                .unwrap_or_default()
                        };
                        deferred_terminal_commands.push(
                            DeferredTerminalCommand::SetWordSeparators {
                                terminal: Arc::clone(&session),
                                separators: word_separators,
                            },
                        );
                        deferred_terminal_commands.push(
                            DeferredTerminalCommand::SetAllowPassthrough {
                                terminal: Arc::clone(&session),
                                enabled: terminal_options.allow_passthrough,
                            },
                        );
                        deferred_terminal_commands.push(DeferredTerminalCommand::SetWrapSearch {
                            terminal: Arc::clone(&session),
                            enabled: terminal_options.wrap_search,
                        });
                        inner.terminals.insert(*pane, Arc::clone(&session));
                        inner.terminal_spawns.insert(*pane, spawn);
                        inner.engine.set_pane_runtime_facts_with_hooks(
                            *pane,
                            PaneRuntimeFacts {
                                current_path,
                                start_path,
                                ..PaneRuntimeFacts::default()
                            },
                            &mut hooks,
                        );
                        let attached_clients = inner
                            .attached
                            .get(&pane_session)
                            .cloned()
                            .unwrap_or_default();
                        for client in attached_clients {
                            deferred_terminal_commands.push(DeferredTerminalCommand::AttachView {
                                terminal: Arc::clone(&session),
                                view: TerminalViewId(client.0),
                            });
                        }
                        if let Some((_, geometry)) = terminal_resize_for_pane(&inner, *pane) {
                            deferred_terminal_commands.push(DeferredTerminalCommand::Resize {
                                terminal: Arc::clone(&session),
                                geometry,
                            });
                        }
                        let multiplexed = inner.control_output_taps.contains_key(pane);
                        if let Some(pipe) = inner.pane_pipes.get_mut(pane) {
                            *pipe.terminal.lock() = Arc::clone(&session);
                            if let Some(output) = pipe.tap_output.clone()
                                && !multiplexed
                            {
                                pipe_taps_to_rearm.push((
                                    *pane,
                                    pipe.token,
                                    Arc::clone(&session),
                                    output,
                                ));
                            }
                        }
                        terminals_to_watch.push((*pane, session));
                    }
                    MuxEffect::PaneCreated {
                        kind: PaneKindSnapshot::Browser(_) | PaneKindSnapshot::Picker,
                        ..
                    }
                    | MuxEffect::PaneMaterialized {
                        kind: PaneKindSnapshot::Browser(_) | PaneKindSnapshot::Picker,
                        ..
                    } => {}
                    MuxEffect::PaneCreated {
                        pane,
                        kind: PaneKindSnapshot::Agent(descriptor),
                        inherit_cwd_from,
                        ..
                    }
                    | MuxEffect::PaneMaterialized {
                        pane,
                        kind: PaneKindSnapshot::Agent(descriptor),
                        inherit_cwd_from,
                        ..
                    } => {
                        let working_directory = descriptor
                            .cwd
                            .clone()
                            .or_else(|| {
                                inherit_cwd_from
                                    .and_then(|source| inner.terminals.get(&source))
                                    .and_then(|terminal| terminal_working_directory(terminal))
                            })
                            .or_else(|| std::env::current_dir().ok());
                        inner
                            .engine
                            .state
                            .update_agent_cwd(*pane, working_directory)?;
                        agent_panes_opened.push(*pane);
                    }
                    MuxEffect::AgentPaneRestart { pane } => {
                        #[cfg(feature = "agent")]
                        agent_panes_restarted.push(*pane);
                        #[cfg(not(feature = "agent"))]
                        let _ = pane;
                    }
                    MuxEffect::PaneCreated {
                        pane,
                        kind: PaneKindSnapshot::Editor(_),
                        inherit_cwd_from,
                        ..
                    }
                    | MuxEffect::PaneMaterialized {
                        pane,
                        kind: PaneKindSnapshot::Editor(_),
                        inherit_cwd_from,
                        ..
                    } => {
                        let working_directory = inherit_cwd_from
                            .and_then(|source| inner.terminals.get(&source))
                            .and_then(|terminal| terminal_working_directory(terminal))
                            .or_else(|| std::env::current_dir().ok());
                        if let Some(working_directory) = working_directory {
                            inner.engine.state.update_editor_cwd(
                                *pane,
                                working_directory.to_string_lossy().into_owned(),
                            )?;
                        }
                    }
                    MuxEffect::PanesRemoved(panes) => {
                        let clients = inner
                            .command_outputs
                            .iter()
                            .filter_map(|(client, output)| {
                                panes.contains(&output.pane).then_some(*client)
                            })
                            .collect::<Vec<_>>();
                        for client in clients {
                            if let Some(output) = take_command_output(&mut inner, client) {
                                retired_command_outputs.push((client, output));
                            }
                        }
                        for pane in panes {
                            if let Some(pipe) = inner.pane_pipes.remove(pane) {
                                pipes_to_close.push(pipe);
                            }
                            inner.terminals.remove(pane);
                            inner.terminal_spawns.remove(pane);
                            inner.terminal_geometries.remove(pane);
                            inner.paste_uploads.retain(|_, upload| upload.pane != *pane);
                            removed_panes.push(*pane);
                        }
                    }
                    MuxEffect::PaneRelocated { pane, from, to } => {
                        if let Some(terminal) = inner.terminals.get(pane).cloned() {
                            let terminal_options =
                                terminal_worker_options(&inner.engine, &inner.appearance, *pane)?;
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetWordSeparators {
                                    terminal: Arc::clone(&terminal),
                                    separators: WordSeparators::new(
                                        inner.engine.word_separators_for_session(*to),
                                    ),
                                },
                            );
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetAllowPassthrough {
                                    terminal: Arc::clone(&terminal),
                                    enabled: terminal_options.allow_passthrough,
                                },
                            );
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetWrapSearch {
                                    terminal: Arc::clone(&terminal),
                                    enabled: terminal_options.wrap_search,
                                },
                            );
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetAppearance {
                                    terminal: Arc::clone(&terminal),
                                    appearance: terminal_options.appearance,
                                },
                            );
                            relocated_terminal_views.push((
                                terminal,
                                inner.attached.get(from).cloned().unwrap_or_default(),
                                inner.attached.get(to).cloned().unwrap_or_default(),
                            ));
                        }
                        for output in inner
                            .command_outputs
                            .values()
                            .filter(|output| output.pane == *pane)
                        {
                            let terminal_options =
                                terminal_worker_options(&inner.engine, &inner.appearance, *pane)?;
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetWrapSearch {
                                    terminal: Arc::clone(&output.terminal),
                                    enabled: terminal_options.wrap_search,
                                },
                            );
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetAppearance {
                                    terminal: Arc::clone(&output.terminal),
                                    appearance: terminal_options.appearance,
                                },
                            );
                        }
                    }
                    MuxEffect::SendKeys { pane, keys } => {
                        let sinks = resolve_input_sinks(&inner, *pane)?;
                        let mut terminals = Vec::new();
                        for sink in sinks {
                            match sink {
                                PaneSink::Terminal(terminal) => {
                                    terminals.push(terminal);
                                }
                                PaneSink::Browser(target) => {
                                    client_events.push(EventPayload::BrowserCommand {
                                        pane: target,
                                        command: BrowserCommand::SendKeys(keys.clone()),
                                    });
                                }
                            }
                        }
                        if !terminals.is_empty() {
                            deferred_terminal_commands.push(DeferredTerminalCommand::SendTokens {
                                terminals,
                                keys: keys.clone(),
                            });
                        }
                    }
                    MuxEffect::CopyModeRepeat { pane, count } => {
                        if inner
                            .copy_sessions
                            .get(&client)
                            .is_some_and(|session| session.pane == *pane)
                        {
                            inner
                                .key_engines
                                .entry(client)
                                .or_default()
                                .set_repeat_count(*count);
                        }
                    }
                    MuxEffect::TerminalView { pane, action } => {
                        let command_output = inner
                            .command_outputs
                            .get(&client)
                            .map(|output| Arc::clone(&output.terminal));
                        if let Some(terminal) = command_output {
                            deferred_terminal_commands.push(DeferredTerminalCommand::ViewAction {
                                terminal,
                                view: TerminalViewId(client.0),
                                action: action.clone(),
                            });
                            continue;
                        }
                        let terminal = inner
                            .terminals
                            .get(pane)
                            .cloned()
                            .ok_or(ServerError::PaneExited(*pane))?;
                        let targets: Vec<ClientId> =
                            if client_is_attached_to_pane(&inner, client, *pane) {
                                vec![client]
                            } else {
                                attached_clients_for_pane(&inner, *pane)
                                    .map(|clients| clients.iter().copied().collect())
                                    .unwrap_or_default()
                            };
                        if targets.is_empty() {
                            return Err(ServerError::PaneNotAttached(*pane).into());
                        }
                        for target in targets {
                            deferred_terminal_commands.push(DeferredTerminalCommand::ViewAction {
                                terminal: Arc::clone(&terminal),
                                view: TerminalViewId(target.0),
                                action: action.clone(),
                            });
                            if terminal_view_action_enters_copy_mode(action) {
                                enter_copy_session(&mut inner, target, *pane)?;
                            } else if terminal_view_action_exits_copy_mode(action) {
                                exit_copy_session(&mut inner, target);
                            } else if terminal_view_action_arms_scroll_exit(action)
                                && let Some(session) = inner.copy_sessions.get_mut(&target)
                                && session.pane == *pane
                            {
                                session.scroll_exit = true;
                            }
                        }
                    }
                    MuxEffect::TerminalUi { pane, command } => {
                        if let Some(output) = inner.command_outputs.get(&client) {
                            client_events.push(EventPayload::TerminalUiCommand {
                                pane: output.pane,
                                command: *command,
                            });
                        } else if !inner.terminals.contains_key(pane) {
                            return Err(ServerError::PaneExited(*pane).into());
                        } else {
                            client_events.push(EventPayload::TerminalUiCommand {
                                pane: *pane,
                                command: *command,
                            });
                        }
                    }
                    MuxEffect::FocusSidebar { pane } => {
                        if kind != ClientKind::Interactive
                            || !inner.subscribers.contains_key(&client)
                        {
                            return Err(ServerError::InvalidCommand(
                                "focus-sidebar requires an interactive client".to_owned(),
                            )
                            .into());
                        }
                        if !client_is_attached_to_pane(&inner, client, *pane) {
                            return Err(ServerError::PaneNotAttached(*pane).into());
                        }
                        dismiss_overlays(
                            &mut inner,
                            client,
                            None,
                            &mut direct_events,
                            &mut retired_command_outputs,
                            &mut retired_popups,
                        );
                        inner.swallowed_keys.remove(&client);
                        direct_events.push(EventPayload::FocusSidebar);
                    }
                    MuxEffect::CommandPrompt {
                        prompt,
                        input,
                        template,
                    } => {
                        if kind != ClientKind::Interactive
                            || !inner.subscribers.contains_key(&client)
                        {
                            return Err(ServerError::InvalidCommand(
                                "command-prompt requires an interactive client".to_owned(),
                            )
                            .into());
                        }
                        dismiss_overlays(
                            &mut inner,
                            client,
                            Some(Overlay::CommandPrompt),
                            &mut direct_events,
                            &mut retired_command_outputs,
                            &mut retired_popups,
                        );
                        if !inner.command_prompts.contains_key(&client) {
                            let prompt =
                                CommandPrompt::new(prompt.clone(), input.clone(), template.clone());
                            let state = prompt.state(&inner.command_history);
                            inner.command_prompts.insert(client, prompt);
                            direct_events.push(EventPayload::CommandPrompt { state: Some(state) });
                        }
                    }
                    MuxEffect::ChooseTree {
                        pane,
                        kind: tree_kind,
                    } => {
                        if kind != ClientKind::Interactive
                            || !inner.subscribers.contains_key(&client)
                        {
                            return Err(ServerError::InvalidCommand(
                                "choose-tree requires an interactive client".to_owned(),
                            )
                            .into());
                        }
                        let attached_session = client_attached_session(&inner, client);
                        let chooser = ChooseTreeSession::new(
                            *tree_kind,
                            *pane,
                            &inner.engine.state,
                            attached_session,
                        )?;
                        if attached_session != Some(chooser.source_session) {
                            return Err(ServerError::PaneNotAttached(*pane).into());
                        }
                        dismiss_overlays(
                            &mut inner,
                            client,
                            Some(Overlay::ChooseTree),
                            &mut direct_events,
                            &mut retired_command_outputs,
                            &mut retired_popups,
                        );
                        inner.swallowed_keys.remove(&client);
                        inner.suppressed_text.remove(&client);
                        let state = chooser.rendered.clone();
                        inner.choose_trees.insert(client, chooser);
                        direct_events.push(EventPayload::ChooseTree { state: Some(state) });
                    }
                    MuxEffect::ChooseBuffer { pane } => {
                        if kind != ClientKind::Interactive
                            || !inner.subscribers.contains_key(&client)
                        {
                            return Err(ServerError::InvalidCommand(
                                "choose-buffer requires an interactive client".to_owned(),
                            )
                            .into());
                        }
                        let attached_session = client_attached_session(&inner, client);
                        let Some(chooser) = ChooseBufferSession::new(
                            *pane,
                            &inner.engine.state,
                            &inner.paste_buffers,
                        )?
                        else {
                            continue;
                        };
                        if attached_session != Some(chooser.source_session) {
                            return Err(ServerError::PaneNotAttached(*pane).into());
                        }
                        dismiss_overlays(
                            &mut inner,
                            client,
                            Some(Overlay::ChooseBuffer),
                            &mut direct_events,
                            &mut retired_command_outputs,
                            &mut retired_popups,
                        );
                        inner.swallowed_keys.remove(&client);
                        inner.suppressed_text.remove(&client);
                        let state = chooser.rendered.clone();
                        inner.choose_buffers.insert(client, chooser);
                        direct_events.push(EventPayload::ChooseBuffer { state: Some(state) });
                    }
                    MuxEffect::DisplayPanes { pane, duration_ms } => {
                        if kind != ClientKind::Interactive
                            || !inner.subscribers.contains_key(&client)
                        {
                            return Err(ServerError::InvalidCommand(
                                "display-panes requires an interactive client".to_owned(),
                            )
                            .into());
                        }
                        let (source_session, source_window, state) =
                            build_display_panes_state(&inner.engine, *pane, *duration_ms)?;
                        if client_attached_session(&inner, client) != Some(source_session) {
                            return Err(ServerError::PaneNotAttached(*pane).into());
                        }
                        dismiss_overlays(
                            &mut inner,
                            client,
                            Some(Overlay::DisplayPanes),
                            &mut direct_events,
                            &mut retired_command_outputs,
                            &mut retired_popups,
                        );
                        let _ = take_display_panes(&mut inner, client);
                        inner.swallowed_keys.remove(&client);
                        inner.suppressed_text.remove(&client);
                        inner.next_display_panes_token =
                            inner.next_display_panes_token.wrapping_add(1).max(1);
                        let token = inner.next_display_panes_token;
                        let deadline = (*duration_ms != 0).then(|| {
                            Instant::now() + Duration::from_millis(u64::from(*duration_ms))
                        });
                        inner.display_panes.insert(
                            client,
                            DisplayPanesSession {
                                token,
                                source_pane: *pane,
                                source_session,
                                source_window,
                                state: state.clone(),
                                deadline,
                                cancel: deadline.map(|_| self.display_panes_deadline_tx.clone()),
                            },
                        );
                        if let Some(deadline) = deadline {
                            display_panes_deadline = Some(DisplayPanesDeadline {
                                client,
                                token,
                                deadline,
                            });
                        }
                        direct_events.push(EventPayload::DisplayPanes { state: Some(state) });
                    }
                    MuxEffect::DisplayMessage {
                        pane,
                        text,
                        duration_ms,
                    } => {
                        push_server_message(&mut inner, text.clone());
                        direct_events.push(EventPayload::TimedClientMessage {
                            pane: *pane,
                            kind: ClientMessageKind::Info,
                            text: text.clone(),
                            duration_ms: *duration_ms,
                        });
                    }
                    MuxEffect::BufferLimitChanged(limit) => {
                        inner.automatic_paste_buffer_limit = AutomaticPasteBufferLimit(*limit);
                    }
                    MuxEffect::WordSeparatorsChanged { session } => {
                        for (pane, terminal) in &inner.terminals {
                            let Some(window) = inner.engine.state.window_for_pane(*pane) else {
                                continue;
                            };
                            let pane_session = inner.engine.state.windows[&window].session;
                            if session.is_some_and(|target| target != pane_session) {
                                continue;
                            }
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetWordSeparators {
                                    terminal: Arc::clone(terminal),
                                    separators: WordSeparators::new(
                                        inner.engine.word_separators_for_session(pane_session),
                                    ),
                                },
                            );
                        }
                        for output in inner.command_outputs.values() {
                            let Some(window) = inner.engine.state.window_for_pane(output.pane)
                            else {
                                continue;
                            };
                            let output_session = inner.engine.state.windows[&window].session;
                            if session.is_some_and(|target| target != output_session) {
                                continue;
                            }
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetWordSeparators {
                                    terminal: Arc::clone(&output.terminal),
                                    separators: WordSeparators::new(
                                        inner.engine.word_separators_for_session(output_session),
                                    ),
                                },
                            );
                        }
                    }
                    MuxEffect::TerminalKnobsChanged { window, pane } => {
                        for (candidate, terminal) in &inner.terminals {
                            if pane.is_some_and(|pane| pane != *candidate)
                                || window.is_some_and(|window| {
                                    inner.engine.state.window_for_pane(*candidate) != Some(window)
                                })
                            {
                                continue;
                            }
                            let terminal_options = terminal_worker_options(
                                &inner.engine,
                                &inner.appearance,
                                *candidate,
                            )?;
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetAllowPassthrough {
                                    terminal: Arc::clone(terminal),
                                    enabled: terminal_options.allow_passthrough,
                                },
                            );
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetWrapSearch {
                                    terminal: Arc::clone(terminal),
                                    enabled: terminal_options.wrap_search,
                                },
                            );
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetAppearance {
                                    terminal: Arc::clone(terminal),
                                    appearance: terminal_options.appearance,
                                },
                            );
                        }
                        for output in inner.command_outputs.values() {
                            if pane.is_some_and(|pane| pane != output.pane)
                                || window.is_some_and(|window| {
                                    inner.engine.state.window_for_pane(output.pane) != Some(window)
                                })
                            {
                                continue;
                            }
                            let terminal_options = terminal_worker_options(
                                &inner.engine,
                                &inner.appearance,
                                output.pane,
                            )?;
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetWrapSearch {
                                    terminal: Arc::clone(&output.terminal),
                                    enabled: terminal_options.wrap_search,
                                },
                            );
                            deferred_terminal_commands.push(
                                DeferredTerminalCommand::SetAppearance {
                                    terminal: Arc::clone(&output.terminal),
                                    appearance: terminal_options.appearance,
                                },
                            );
                        }
                    }
                    MuxEffect::ModeKeysChanged { window } => {
                        retarget_copy_mode_tables(&mut inner, *window);
                    }
                    MuxEffect::AggressiveResizeChanged { window }
                    | MuxEffect::WindowSizeChanged { window } => {
                        let windows = window.map_or_else(
                            || inner.engine.state.windows.keys().copied().collect(),
                            |window| BTreeSet::from([window]),
                        );
                        let panes = panes_for_windows(&inner, &windows);
                        snapshot_changed |=
                            write_back_terminal_geometries(&mut inner, &panes, false);
                        for (terminal, geometry) in terminal_resizes_for_panes(&inner, &panes) {
                            deferred_terminal_commands
                                .push(DeferredTerminalCommand::Resize { terminal, geometry });
                        }
                    }
                    MuxEffect::MuxOptionChanged { option } => {
                        let value = inner.engine.mux_option_value(*option);
                        mux_options_changed |=
                            inner.mux_options.set(*option, value.clone(), mux_source);
                        if mux_source != MuxOptionSource::Override {
                            inner.mux_option_underlay.set(*option, value, mux_source);
                        }
                        #[cfg(feature = "agent")]
                        {
                            agent_options_changed |= matches!(
                                option,
                                MuxOptionKey::AgentCommand
                                    | MuxOptionKey::AgentClaudeCodeCommand
                                    | MuxOptionKey::AgentAutoApprove
                            );
                        }
                    }
                    MuxEffect::StatusFormatsChanged => status_formats_changed = true,
                    MuxEffect::Attach {
                        session,
                        detach_others,
                    } => attach = Some((*session, *detach_others)),
                    MuxEffect::Detach(scope) => {
                        detach = Some(*scope);
                        detached_session = client_attached_session(&inner, client);
                    }
                    MuxEffect::SourceFile { path, quiet } => {
                        source_files.push((path.clone(), *quiet));
                    }
                    MuxEffect::RunHook {
                        name,
                        commands,
                        context,
                    } => {
                        immediate_hooks.push((name.clone(), commands.clone(), context.clone()));
                    }
                    MuxEffect::ReloadConfig => reload_config = true,
                    MuxEffect::KillServer => shutdown_requested = true,
                    MuxEffect::SnapshotChanged => snapshot_changed = true,
                }
            }
            shutdown_requested |= self.should_shutdown_if_empty(&inner);
            if snapshot_changed {
                unfocused_copy_mode_exits = unfocused_copy_sessions(&mut inner);
                let clients = inner
                    .command_outputs
                    .iter()
                    .filter_map(|(client, output)| {
                        (client_context_pane(&inner, *client) != Some(output.pane))
                            .then_some(*client)
                    })
                    .collect::<Vec<_>>();
                for client in clients {
                    if let Some(output) = take_command_output(&mut inner, client) {
                        retired_command_outputs.push((client, output));
                    }
                }
            }
            if let Some(before) = hook_snapshot_before.as_ref() {
                let after = MuxHookSnapshot::capture(&inner.engine);
                pending_hook_events.extend(mux_hook_events(before, &after, command_name));
                for session in before
                    .sessions
                    .keys()
                    .filter(|session| !after.sessions.contains_key(session))
                {
                    if let Some(clients) = inner.attached.get(session) {
                        for attached_client in clients {
                            pending_hook_events.push(PendingHookEvent::client(
                                "client-detached",
                                before.session_context(*session),
                                *attached_client,
                                inner.client_names.get(attached_client).map(String::as_str),
                                before,
                            ));
                        }
                    }
                }
                if let Some(copy_modes_before) = copy_modes_before.as_ref() {
                    let copy_modes_after = inner
                        .copy_sessions
                        .values()
                        .map(|session| session.pane)
                        .collect::<BTreeSet<_>>();
                    pending_hook_events.extend(pane_mode_hook_events(
                        before,
                        &after,
                        copy_modes_before,
                        &copy_modes_after,
                    ));
                }
            }
            let mux_options_event = mux_options_changed.then(|| inner.mux_options.clone());
            (execution, mux_options_event)
        };

        for (name, commands, context) in immediate_hooks {
            let hook_output = self.run_hook_commands(
                client,
                kind,
                &context,
                commands,
                &BTreeMap::from([("hook".to_owned(), name)]),
            );
            append_inserted_output(&mut execution.output, &hook_output);
        }

        if shutdown_requested {
            self.request_shutdown();
        }

        for pipe in pipes_to_close {
            stop_pane_pipe(pipe);
        }

        for (pane, token, terminal, output) in pipe_taps_to_rearm {
            self.rearm_pane_pipe(pane, token, &terminal, output);
        }
        self.refresh_control_output_taps();

        for command in deferred_terminal_commands {
            #[cfg(test)]
            let wrap_search = command.wrap_search();
            command.run();
            #[cfg(test)]
            if let Some(enabled) = wrap_search {
                self.delivered_wrap_search_commands.lock().push(enabled);
            }
        }
        for terminal in cleared_bells {
            terminal.clear_bell();
        }
        for (client, terminal) in unfocused_copy_mode_exits {
            terminal.view_action(
                TerminalViewId(client.0),
                zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel),
            );
        }
        for (client, output) in retired_command_outputs {
            Self::retire_command_output(client, output);
        }
        for (client, popup) in retired_popups {
            Self::retire_popup(client, popup, true);
        }
        for (terminal, previous, next) in relocated_terminal_views {
            for client in previous.difference(&next) {
                terminal.detach_view(TerminalViewId(client.0));
            }
            for client in next.difference(&previous) {
                terminal.attach_view(TerminalViewId(client.0));
            }
        }
        match detach {
            None => {}
            Some(DetachScope::Client) => {
                if let Some(session) = detached_session {
                    self.publish_to_client(client, EventPayload::Detached { session, by: None });
                }
                self.detach_with_event_hooks(client, event_hooks_enabled);
            }
            Some(DetachScope::Others) => {
                self.evict_clients_with_event_hooks(None, client, event_hooks_enabled);
            }
            Some(DetachScope::Session(session)) => {
                self.evict_clients_with_event_hooks(Some(session), client, event_hooks_enabled);
                if detached_session == Some(session) {
                    self.publish_to_client(client, EventPayload::Detached { session, by: None });
                    self.detach_with_event_hooks(client, event_hooks_enabled);
                }
            }
        }
        if let Some((session, detach_others)) = attach {
            if client_terminal == ClientTerminal::Present {
                let (mut snapshot, attach_hook_events) =
                    self.attach_collect_event_hooks(client, session, event_hooks_enabled)?;
                pending_hook_events.extend(attach_hook_events);
                if detach_others {
                    self.evict_clients_with_event_hooks(Some(session), client, event_hooks_enabled);
                    let inner = self.inner.lock();
                    snapshot = inner.engine.state.snapshot();
                    let presence = snapshot_presence(&inner);
                    stamp_snapshot_for_client(&inner, client, &mut snapshot, &presence);
                }
                let outbound = self.inner.lock().subscribers.get(&client).cloned();
                if let Some(outbound) = outbound {
                    outbound.reset_kitty_images();
                    outbound.reset_pasted_images();
                    let _ =
                        outbound.enqueue_reliable(&ProtocolMessage::Attached { session, snapshot });
                    self.send_resync(client, &outbound);
                }
                self.publish_snapshot();
            } else if detach_others {
                self.evict_clients_with_event_hooks(Some(session), client, event_hooks_enabled);
                self.publish_snapshot();
            }
        }
        for (pane, terminal) in terminals_to_watch {
            self.watch_terminal(pane, &terminal)?;
        }
        for event in client_events {
            let pane = match &event {
                EventPayload::BrowserCommand { pane, .. }
                | EventPayload::TerminalUiCommand { pane, .. } => *pane,
                _ => continue,
            };
            self.publish_for_pane(pane, &event);
        }
        for event in direct_events {
            self.publish_to_client(client, event);
        }
        if let Some(deadline) = display_panes_deadline {
            self.display_panes_deadline_tx
                .send(DisplayPanesDeadlineCommand::Schedule(deadline))
                .map_err(|_| {
                    DaemonError::Thread("display-panes deadline dispatcher stopped".to_owned())
                })?;
        }
        #[cfg(feature = "agent")]
        {
            if agent_options_changed {
                self.reconfigure_agents();
            }
            self.close_agent_panes(&removed_panes);
            for pane in agent_panes_opened {
                self.open_agent_pane(pane);
            }
            for pane in agent_panes_restarted {
                self.restart_agent_pane(pane);
            }
        }
        for pane in removed_panes {
            self.publish(EventPayload::PaneRemoved(pane));
        }
        if let Some(options) = mux_options_event {
            self.publish(EventPayload::MuxOptionsChanged { options });
        }
        if snapshot_changed {
            self.publish_snapshot();
        } else if status_formats_changed {
            self.refresh_status(false);
        }
        let mut source_file_error = None;
        for (path, quiet) in source_files {
            if path == "-" {
                self.publish_to_client(
                    client,
                    EventPayload::ClientMessage {
                        pane: context.pane,
                        kind: ClientMessageKind::Warning,
                        text: "source-file from standard input is not supported".to_owned(),
                    },
                );
                continue;
            }
            let path = expand_path(&path);
            let matches = source_glob_matches(&path);
            for error in &matches.errors {
                self.publish_to_client(
                    client,
                    EventPayload::ClientMessage {
                        pane: context.pane,
                        kind: ClientMessageKind::Warning,
                        text: format!("source-file glob error for {}: {error}", path.display()),
                    },
                );
            }
            if matches.paths.is_empty() && matches.errors.is_empty() {
                if !quiet {
                    self.publish_to_client(
                        client,
                        EventPayload::ClientMessage {
                            pane: context.pane,
                            kind: ClientMessageKind::Warning,
                            text: format!("no such file: {}", path.display()),
                        },
                    );
                }
                continue;
            }
            for path in matches.paths {
                if is_default_mux_config(&path) {
                    reload_config = true;
                } else {
                    let mut report = ConfigLoadReport::default();
                    if let Err(error) = self.load_config_file_with_report_for_terminal(
                        &path,
                        context,
                        0,
                        &mut report,
                        client_terminal,
                    ) {
                        if source_file_error.is_none() {
                            source_file_error = Some(error);
                        }
                        continue;
                    }
                    self.apply_stored_mux_config_overrides("source-file-replay");
                    if let Some(summary) = report.message() {
                        self.publish_to_client(
                            client,
                            EventPayload::ClientMessage {
                                pane: context.pane,
                                kind: ClientMessageKind::Warning,
                                text: summary,
                            },
                        );
                    }
                }
            }
        }
        if reload_config
            && let Err(error) = self.reload_user_config(client, context)
            && source_file_error.is_none()
        {
            source_file_error = Some(error);
        }
        self.publish_key_tables_if_changed();
        self.run_event_hooks(pending_hook_events);
        source_file_error.map_or(Ok(execution), Err)
    }

    fn publish_key_tables_if_changed(&self) {
        let tables = {
            let mut inner = self.inner.lock();
            let tables = inner.engine.keys.snapshot();
            if tables == inner.key_tables {
                return;
            }
            inner.key_tables.clone_from(&tables);
            tables
        };
        self.publish(EventPayload::KeyTablesChanged { tables });
    }

    fn capture_pane(
        self: &Arc<Self>,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_capture_pane_args(args)?;
        let (pane, terminal) = {
            let inner = self.inner.lock();
            let pane = inner.engine.resolve_pane(
                parsed.target.as_deref(),
                context.window,
                context.pane,
            )?;
            let terminal = inner
                .terminals
                .get(&pane)
                .cloned()
                .ok_or(ServerError::PaneExited(pane))?;
            (pane, terminal)
        };
        let capture = match terminal.capture(parsed.options) {
            Err(TerminalCaptureError::ActorStopped) => {
                let retained = {
                    let inner = self.inner.lock();
                    inner
                        .terminals
                        .get(&pane)
                        .is_some_and(|current| Arc::ptr_eq(current, &terminal))
                        && inner.engine.state.pane(pane).is_some_and(|pane| pane.dead)
                };
                if retained {
                    terminal.capture_frozen_frame(parsed.options)
                } else {
                    Err(TerminalCaptureError::ActorStopped)
                }
            }
            result => result,
        };
        let output = match capture {
            Ok(output) => output,
            Err(TerminalCaptureError::AlternateUnavailable) if parsed.quiet => String::new(),
            Err(TerminalCaptureError::ActorStopped) => {
                return Err(ServerError::PaneExited(pane).into());
            }
            Err(TerminalCaptureError::TimedOut) => {
                return Err(ServerError::Internal("terminal capture timed out".to_owned()).into());
            }
            Err(TerminalCaptureError::Failed(error)) => {
                return Err(
                    ServerError::Internal(format!("terminal capture failed: {error}")).into(),
                );
            }
            Err(error) => return Err(ServerError::InvalidCommand(error.to_string()).into()),
        };
        if let Some(buffer_name) = parsed.buffer_name.as_deref() {
            let events = {
                let mut inner = self.inner.lock();
                insert_paste_buffer(
                    &mut inner,
                    Some(buffer_name),
                    "buffer",
                    output.into_bytes(),
                    true,
                )?
            };
            if !context.no_hooks {
                self.run_event_hooks(events);
            }
            return Ok(Execution::default());
        }
        Ok(Execution {
            output,
            effects: Vec::new(),
        })
    }

    fn wait_for(
        &self,
        client: ClientId,
        kind: ClientKind,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_buffer_command_args("wait-for", args, &[], &['L', 'S', 'U'])?;
        let [name] = parsed.positional.as_slice() else {
            return Err(ServerError::InvalidCommand(WAIT_FOR_USAGE.to_owned()).into());
        };
        if parsed.has('S') {
            let wakes = {
                let mut inner = self.inner.lock();
                let channel = inner.wait_channels.entry(name.clone()).or_default();
                if channel.waiters.is_empty() && !channel.woken {
                    channel.woken = true;
                    return Ok(Execution::default());
                }
                let wakes = channel
                    .waiters
                    .drain(..)
                    .map(|item| item.wake)
                    .collect::<Vec<_>>();
                remove_wait_channel_if_unused(&mut inner.wait_channels, name);
                wakes
            };
            wake_wait_items(wakes);
            return Ok(Execution::default());
        }
        if parsed.has('L') {
            if !matches!(kind, ClientKind::Command | ClientKind::Control)
                || client == ClientId(u64::MAX)
            {
                return Err(ServerError::InvalidCommand("not able to lock".to_owned()).into());
            }
            let receiver = {
                let mut inner = self.inner.lock();
                if self.stopping.load(Ordering::Acquire)
                    || !inner.client_instances.contains_key(&client)
                {
                    return Ok(Execution::default());
                }
                let token = next_wait_token(&mut inner);
                let channel = inner.wait_channels.entry(name.clone()).or_default();
                if !channel.locked {
                    channel.locked = true;
                    return Ok(Execution::default());
                }
                let (wake, receiver) = crossbeam_channel::bounded(1);
                channel.lockers.push_back(WaitItem {
                    token,
                    client,
                    wake,
                });
                (token, receiver)
            };
            let _ = receiver.1.recv();
            remove_wait_item(&mut self.inner.lock(), name, receiver.0);
            return Ok(Execution::default());
        }
        if parsed.has('U') {
            let wake = {
                let mut inner = self.inner.lock();
                let Some(channel) = inner.wait_channels.get_mut(name) else {
                    return Err(
                        ServerError::InvalidCommand(format!("channel {name} not locked")).into(),
                    );
                };
                if !channel.locked {
                    return Err(
                        ServerError::InvalidCommand(format!("channel {name} not locked")).into(),
                    );
                }
                if let Some(item) = channel.lockers.pop_front() {
                    Some(item.wake)
                } else {
                    channel.locked = false;
                    remove_wait_channel_if_unused(&mut inner.wait_channels, name);
                    None
                }
            };
            if let Some(wake) = wake {
                let _ = wake.try_send(());
            }
            return Ok(Execution::default());
        }
        if !matches!(kind, ClientKind::Command | ClientKind::Control)
            || client == ClientId(u64::MAX)
        {
            return Err(ServerError::InvalidCommand("not able to wait".to_owned()).into());
        }
        let receiver = {
            let mut inner = self.inner.lock();
            if self.stopping.load(Ordering::Acquire)
                || !inner.client_instances.contains_key(&client)
            {
                return Ok(Execution::default());
            }
            let token = next_wait_token(&mut inner);
            let channel = inner.wait_channels.entry(name.clone()).or_default();
            if channel.woken {
                remove_wait_channel_if_unused(&mut inner.wait_channels, name);
                return Ok(Execution::default());
            }
            let (wake, receiver) = crossbeam_channel::bounded(1);
            channel.waiters.push_back(WaitItem {
                token,
                client,
                wake,
            });
            (token, receiver)
        };
        let _ = receiver.1.recv();
        remove_wait_item(&mut self.inner.lock(), name, receiver.0);
        Ok(Execution::default())
    }

    fn pipe_pane(
        self: &Arc<Self>,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_buffer_command_args("pipe-pane", args, &['t'], &['I', 'O', 'o'])?;
        if parsed.positional.len() > 1 {
            return Err(ServerError::InvalidCommand(PIPE_PANE_USAGE.to_owned()).into());
        }
        let _serial = self.pipe_effects.lock();
        let (pane, terminal, old_pipe) = {
            let mut inner = self.inner.lock();
            let pane =
                inner
                    .engine
                    .resolve_pane(parsed.value('t'), context.window, context.pane)?;
            if inner.engine.state.pane(pane).is_some_and(|pane| pane.dead) {
                return Err(
                    ServerError::InvalidCommand("target pane has exited".to_owned()).into(),
                );
            }
            let terminal = inner
                .terminals
                .get(&pane)
                .cloned()
                .ok_or(ServerError::PaneExited(pane))?;
            let old_pipe = inner.pane_pipes.remove(&pane);
            (pane, terminal, old_pipe)
        };
        let had_pipe = old_pipe.is_some();
        if let Some(pipe) = old_pipe {
            stop_pane_pipe(pipe);
        }
        let Some(command) = parsed
            .positional
            .first()
            .filter(|command| !command.is_empty())
        else {
            self.refresh_status(false);
            return Ok(Execution::default());
        };
        if parsed.has('o') && had_pipe {
            self.refresh_status(false);
            return Ok(Execution::default());
        }
        let pipe_input = parsed.has('I');
        let pipe_output = parsed.has('O') || !pipe_input;
        let multiplexed = self.inner.lock().control_output_taps.contains_key(&pane);
        let (token, command) = {
            let mut inner = self.inner.lock();
            inner.next_pipe_token = inner.next_pipe_token.wrapping_add(1).max(1);
            inner.engine.set_format_now(unix_timestamp());
            let target = ExecutionContext::for_pane(&inner.engine.state, pane)
                .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
            let facts = format_hook_facts(&inner);
            let mut hooks = DaemonFormatHooks::command_with_optional_variables(
                &facts,
                context.format_variables(),
            );
            let command =
                inner
                    .engine
                    .expand_pane_format_time(command, &target, context.session, &mut hooks);
            (inner.next_pipe_token, command)
        };
        let mut process = shell_process(&command);
        #[cfg(unix)]
        {
            use std::os::unix::process::CommandExt as _;

            process.arg0("sh").process_group(0);
        }
        process
            .stdin(if pipe_output {
                Stdio::piped()
            } else {
                Stdio::null()
            })
            .stdout(if pipe_input {
                Stdio::piped()
            } else {
                Stdio::null()
            })
            .stderr(Stdio::null());
        let mut child = process.spawn().map_err(|error| {
            ServerError::InvalidCommand(format!("could not start pipe-pane command: {error}"))
        })?;
        let pid = child.id();
        let child_input = child.stdin.take();
        let child_output = child.stdout.take();
        let (tap_output, tap) = if pipe_output {
            let (output, receiver) = TerminalSession::raw_output_tap_channel();
            if !multiplexed {
                terminal
                    .arm_raw_output_tap(token, output.clone())
                    .map_err(|error| {
                        let _ = terminate_copy_pipe(&mut child);
                        ServerError::Internal(format!("could not arm pane output pipe: {error}"))
                    })?;
            }
            (Some(output), Some(receiver))
        } else {
            (None, None)
        };
        let process = Arc::new(Mutex::new(Some(child)));
        let stop = Arc::new(AtomicBool::new(false));
        let terminal_target = Arc::new(Mutex::new(Arc::clone(&terminal)));
        let (start, started) = crossbeam_channel::bounded(1);
        let worker_process = Arc::clone(&process);
        let worker_stop = Arc::clone(&stop);
        let worker_terminal = Arc::clone(&terminal_target);
        let weak = Arc::downgrade(self);
        let worker = thread::Builder::new()
            .name(format!("zz-pipe-{}", pane.0))
            .spawn(move || {
                if started.recv().is_err() {
                    return;
                }
                run_pane_pipe(
                    &weak,
                    pane,
                    token,
                    &worker_terminal,
                    &worker_process,
                    &worker_stop,
                    child_input,
                    child_output,
                    tap,
                );
            })
            .map_err(|error| {
                terminate_managed_process(&process);
                let _ = terminal.disarm_raw_output_tap(token);
                DaemonError::Thread(error.to_string())
            })?;
        let valid = {
            let mut inner = self.inner.lock();
            let valid = !self.stopping.load(Ordering::Acquire)
                && inner
                    .terminals
                    .get(&pane)
                    .is_some_and(|current| Arc::ptr_eq(current, &terminal))
                && inner.engine.state.pane(pane).is_some_and(|pane| !pane.dead);
            if valid {
                inner.pane_pipes.insert(
                    pane,
                    PanePipe {
                        token,
                        pid,
                        terminal: terminal_target,
                        tap_output,
                        process: Arc::clone(&process),
                        stop: Arc::clone(&stop),
                        thread: Some(worker),
                    },
                );
            }
            valid
        };
        if !valid {
            drop(start);
            stop.store(true, Ordering::Release);
            terminate_managed_process(&process);
            let _ = terminal.disarm_raw_output_tap(token);
            return Err(ServerError::PaneExited(pane).into());
        }
        let _ = start.send(());
        drop(_serial);
        self.refresh_control_output_taps();
        self.refresh_status(false);
        Ok(Execution::default())
    }

    fn pipe_finished(&self, pane: PaneId, token: u64) {
        let removed = {
            let mut inner = self.inner.lock();
            if inner
                .pane_pipes
                .get(&pane)
                .is_some_and(|pipe| pipe.token == token)
            {
                inner.pane_pipes.remove(&pane);
                true
            } else {
                false
            }
        };
        if removed {
            self.refresh_status(false);
        }
    }

    fn rearm_pane_pipe(
        &self,
        pane: PaneId,
        token: u64,
        terminal: &Arc<TerminalSession>,
        output: crossbeam_channel::Sender<Arc<[u8]>>,
    ) {
        let _serial = self.pipe_effects.lock();
        let (valid, multiplexed) = {
            let inner = self.inner.lock();
            (
                inner.pane_pipes.get(&pane).is_some_and(|pipe| {
                    pipe.token == token && Arc::ptr_eq(&pipe.terminal.lock(), terminal)
                }),
                inner.control_output_taps.contains_key(&pane),
            )
        };
        if !valid || multiplexed {
            return;
        }
        let Err(error) = terminal.arm_raw_output_tap(token, output) else {
            return;
        };
        log::warn!("could not rearm pipe tap for {pane}, stopping the pipe: {error}");
        let pipe = {
            let mut inner = self.inner.lock();
            inner
                .pane_pipes
                .get(&pane)
                .is_some_and(|pipe| pipe.token == token)
                .then(|| inner.pane_pipes.remove(&pane))
                .flatten()
        };
        if let Some(pipe) = pipe {
            stop_pane_pipe(pipe);
            self.refresh_status(false);
        }
    }

    fn pipe_tap_closed(&self, pane: PaneId, token: u64, terminal: &Arc<TerminalSession>) {
        let _serial = self.pipe_effects.lock();
        let pipe = {
            let mut inner = self.inner.lock();
            inner
                .pane_pipes
                .get(&pane)
                .is_some_and(|pipe| {
                    pipe.token == token && Arc::ptr_eq(&pipe.terminal.lock(), terminal)
                })
                .then(|| inner.pane_pipes.remove(&pane))
                .flatten()
        };
        if let Some(pipe) = pipe {
            stop_pane_pipe(pipe);
            self.refresh_status(false);
        }
    }

    fn refresh_control_output_taps(self: &Arc<Self>) {
        let serial = self.pipe_effects.lock();
        let (stale, desired) = {
            let mut inner = self.inner.lock();
            let desired = inner
                .terminals
                .iter()
                .filter(|(pane, _)| control_output_wanted(&inner, **pane))
                .map(|(pane, terminal)| (*pane, Arc::clone(terminal)))
                .collect::<BTreeMap<_, _>>();
            let stale_panes = inner
                .control_output_taps
                .iter()
                .filter_map(|(pane, tap)| {
                    desired
                        .get(pane)
                        .is_none_or(|terminal| !Arc::ptr_eq(terminal, &tap.terminal))
                        .then_some(*pane)
                })
                .collect::<Vec<_>>();
            let stale = stale_panes
                .into_iter()
                .filter_map(|pane| inner.control_output_taps.remove(&pane))
                .collect::<Vec<_>>();
            (stale, desired)
        };
        for tap in stale {
            stop_control_output_tap(tap);
        }
        for (pane, terminal) in desired {
            if self.inner.lock().control_output_taps.contains_key(&pane) {
                continue;
            }
            self.start_control_output_tap(pane, &terminal);
        }
        let direct_pipes = {
            let inner = self.inner.lock();
            inner
                .pane_pipes
                .iter()
                .filter(|(pane, pipe)| {
                    pipe.tap_output.is_some()
                        && !inner.control_output_taps.contains_key(pane)
                        && !control_output_wanted(&inner, **pane)
                })
                .filter_map(|(pane, pipe)| {
                    Some((
                        *pane,
                        pipe.token,
                        Arc::clone(&pipe.terminal.lock()),
                        pipe.tap_output.clone()?,
                    ))
                })
                .collect::<Vec<_>>()
        };
        drop(serial);
        for (pane, token, terminal, output) in direct_pipes {
            self.rearm_pane_pipe(pane, token, &terminal, output);
        }
    }

    fn start_control_output_tap(self: &Arc<Self>, pane: PaneId, terminal: &Arc<TerminalSession>) {
        let next_token = |daemon: &Self| {
            let mut inner = daemon.inner.lock();
            inner.next_pipe_token = inner.next_pipe_token.wrapping_add(1).max(1);
            inner.next_pipe_token
        };
        let (output, receiver) = TerminalSession::raw_output_tap_channel();
        let mut token = next_token(self);
        let receiver = match terminal.arm_raw_output_tap(token, output) {
            Ok(()) => receiver,
            Err(RawOutputTapError::TimedOut) => {
                log::warn!("control output tap arm timed out for {pane}, retrying once");
                let (output, retry_receiver) = TerminalSession::raw_output_tap_channel();
                token = next_token(self);
                if let Err(error) = terminal.arm_raw_output_tap(token, output) {
                    log::warn!("control output tap arm failed for {pane}: {error}");
                    return;
                }
                retry_receiver
            }
            Err(error) => {
                log::warn!("control output tap arm failed for {pane}: {error}");
                return;
            }
        };
        let stop = Arc::new(AtomicBool::new(false));
        let weak = Arc::downgrade(self);
        let worker_stop = Arc::clone(&stop);
        let Ok(worker) = thread::Builder::new()
            .name(format!("zz-control-output-{}", pane.0))
            .spawn(move || run_control_output_tap(&weak, pane, &worker_stop, &receiver))
        else {
            let _ = terminal.disarm_raw_output_tap(token);
            return;
        };
        let mut tap = Some(ControlOutputTap {
            token,
            terminal: Arc::clone(terminal),
            stop,
            thread: Some(worker),
        });
        let valid = {
            let mut inner = self.inner.lock();
            let valid = !self.stopping.load(Ordering::Acquire)
                && control_output_wanted(&inner, pane)
                && inner
                    .terminals
                    .get(&pane)
                    .is_some_and(|current| Arc::ptr_eq(current, terminal))
                && !inner.control_output_taps.contains_key(&pane);
            if valid {
                inner
                    .control_output_taps
                    .insert(pane, tap.take().expect("control output tap is present"));
            }
            valid
        };
        if !valid {
            stop_control_output_tap(tap.expect("invalid control output tap is retained"));
        }
    }

    fn publish_control_output_for_pane(&self, pane: PaneId, bytes: &Arc<[u8]>) {
        self.publish_pipe_output_for_pane(pane, bytes);

        loop {
            let queued = {
                let mut inner = self.inner.lock();
                let Some(window) = inner.engine.state.window_for_pane(pane) else {
                    return;
                };
                let clients = inner
                    .engine
                    .state
                    .sessions
                    .iter()
                    .filter(|(_, session)| session.windows.contains(&window))
                    .flat_map(|(session, _)| inner.attached.get(session).into_iter().flatten())
                    .filter(|client| {
                        inner.client_kinds.get(client) == Some(&ClientKind::Control)
                            && inner.subscribers.contains_key(client)
                    })
                    .copied()
                    .collect::<BTreeSet<_>>();
                let blocked = clients.iter().any(|client| {
                    let output = inner.control_outputs.entry(*client).or_default();
                    if output.no_output {
                        return false;
                    }
                    let pane_output = output.panes.entry(pane).or_default();
                    pane_output.mode == ControlPaneOutputMode::On
                        && pane_output.pending.len() >= CONTROL_PENDING_CHUNKS_PER_PANE
                });
                if blocked {
                    false
                } else {
                    let enqueued_at = Instant::now();
                    for client in clients {
                        let output = inner.control_outputs.entry(client).or_default();
                        if output.no_output {
                            continue;
                        }
                        let pane_output = output.panes.entry(pane).or_default();
                        if pane_output.mode == ControlPaneOutputMode::On {
                            pane_output.pending.push_back(PendingControlOutput {
                                bytes: Arc::clone(bytes),
                                offset: 0,
                                enqueued_at,
                            });
                        }
                    }
                    true
                }
            };
            self.pump_control_output_at(Instant::now());
            if queued {
                break;
            }
            thread::sleep(Duration::from_millis(1));
        }
    }

    fn publish_pipe_output_for_pane(&self, pane: PaneId, bytes: &Arc<[u8]>) {
        let pipe = {
            let inner = self.inner.lock();
            inner
                .pane_pipes
                .get(&pane)
                .and_then(|pipe| pipe.tap_output.clone())
        };
        if let Some(pipe) = pipe {
            let _ = pipe.send(Arc::clone(bytes));
        }
    }

    fn pump_control_output_at(&self, now: Instant) {
        loop {
            let (deliveries, kills, progressed) = {
                let mut inner = self.inner.lock();
                let clients = inner.control_outputs.keys().copied().collect::<Vec<_>>();
                let mut deliveries = Vec::new();
                let mut kills = Vec::new();
                let mut progressed = false;
                for client in clients {
                    let Some(subscriber) = inner.subscribers.get(&client).cloned() else {
                        continue;
                    };
                    let Some((queued_bytes, queued_messages)) = subscriber.queued_reliable() else {
                        if let Some(output) = inner.control_outputs.get_mut(&client) {
                            for pane in output.panes.values_mut() {
                                pane.pending.clear();
                            }
                        }
                        continue;
                    };
                    let output = inner
                        .control_outputs
                        .get_mut(&client)
                        .expect("control output state is present");
                    if output.no_output {
                        continue;
                    }
                    let pause_after_ms = output.pause_after_ms;
                    let pending_panes = output
                        .panes
                        .iter()
                        .filter_map(|(pane, output)| (!output.pending.is_empty()).then_some(*pane))
                        .collect::<Vec<_>>();
                    let mut kill = false;
                    for pane in pending_panes {
                        let pane_output = output
                            .panes
                            .get_mut(&pane)
                            .expect("pending control pane is present");
                        let enqueued_at = pane_output
                            .pending
                            .front()
                            .expect("pending control output is present")
                            .enqueued_at;
                        match control_output_age_action(pause_after_ms, enqueued_at, now) {
                            ControlOutputAgeAction::Output(_) => {}
                            ControlOutputAgeAction::Pause => {
                                pane_output.pending.clear();
                                pane_output.mode = ControlPaneOutputMode::Paused;
                                deliveries.push((
                                    client,
                                    Arc::clone(&subscriber),
                                    Self::event(EventPayload::PaneOutputState {
                                        pane,
                                        paused: true,
                                    }),
                                ));
                                progressed = true;
                            }
                            ControlOutputAgeAction::Kill => {
                                kill = true;
                                break;
                            }
                        }
                    }
                    if kill {
                        for pane in output.panes.values_mut() {
                            pane.pending.clear();
                        }
                        kills.push(subscriber);
                        progressed = true;
                        continue;
                    }
                    let pending_panes = output
                        .panes
                        .iter()
                        .filter_map(|(pane, output)| {
                            (!output.pending.is_empty() && output.mode == ControlPaneOutputMode::On)
                                .then_some(*pane)
                        })
                        .collect::<Vec<_>>();
                    if pending_panes.is_empty()
                        || queued_bytes >= CONTROL_BUFFER_HIGH
                        || queued_messages >= CONTROL_PENDING_MESSAGE_LIMIT
                    {
                        continue;
                    }
                    let limit = ((CONTROL_BUFFER_HIGH - queued_bytes) / pending_panes.len() / 3)
                        .max(CONTROL_WRITE_MINIMUM);
                    for pane in pending_panes {
                        let pane_output = output
                            .panes
                            .get_mut(&pane)
                            .expect("pending control pane is present");
                        let (age_ms, bytes) = drain_control_pane_output(pane_output, limit, now);
                        let payload = if pause_after_ms.is_some() {
                            EventPayload::PaneOutputAged {
                                pane,
                                age_ms,
                                bytes,
                            }
                        } else {
                            EventPayload::PaneOutput { pane, bytes }
                        };
                        deliveries.push((client, Arc::clone(&subscriber), Self::event(payload)));
                        progressed = true;
                    }
                }
                (deliveries, kills, progressed)
            };
            for subscriber in kills {
                subscriber.close_too_far_behind();
            }
            let mut failed = BTreeSet::new();
            for (client, subscriber, message) in deliveries {
                if !subscriber.enqueue_reliable(&message) {
                    failed.insert(client);
                }
            }
            if !failed.is_empty() {
                let mut inner = self.inner.lock();
                for client in failed {
                    if let Some(output) = inner.control_outputs.get_mut(&client) {
                        for pane in output.panes.values_mut() {
                            pane.pending.clear();
                        }
                    }
                }
            }
            if !progressed {
                break;
            }
        }
    }

    fn control_output_tap_closed(
        self: &Arc<Self>,
        pane: PaneId,
        token: u64,
        terminal: &Arc<TerminalSession>,
    ) -> bool {
        let tap = {
            let mut inner = self.inner.lock();
            inner
                .control_output_taps
                .get(&pane)
                .is_some_and(|tap| tap.token == token && Arc::ptr_eq(&tap.terminal, terminal))
                .then(|| inner.control_output_taps.remove(&pane))
                .flatten()
        };
        let Some(tap) = tap else {
            return false;
        };
        stop_control_output_tap(tap);
        self.refresh_control_output_taps();
        true
    }

    fn run_shell(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_run_shell_args(args)?;
        let (target, command_context, command, cwd, tmux) = {
            let mut inner = self.inner.lock();
            let target = parsed
                .target
                .as_deref()
                .and_then(|target| {
                    inner
                        .engine
                        .resolve_pane(Some(target), context.window, context.pane)
                        .ok()
                })
                .filter(|pane| {
                    inner
                        .engine
                        .state
                        .pane(*pane)
                        .is_some_and(|pane| !pane.dead)
                });
            let mut command_context = context.clone();
            if let Some(pane) = target {
                command_context.retarget_to_pane(&inner.engine.state, pane);
            }
            inner.engine.set_format_now(unix_timestamp());
            let format_context = inner.engine.format_status_context(
                command_context.session,
                command_context.window,
                command_context.pane,
            );
            let facts = format_hook_facts(&inner);
            let command = parsed.positional.first().map(|command| {
                if parsed.command_mode {
                    command_block_body(command).map_or_else(
                        || {
                            let mut hooks = DaemonFormatHooks::command_with_optional_variables(
                                &facts,
                                command_context.format_variables(),
                            );
                            InsertedCommandSource::String(expand_format_values(
                                command,
                                &format_context,
                                &mut hooks,
                            ))
                        },
                        |body| InsertedCommandSource::Block(body.to_owned()),
                    )
                } else if let Some(body) = command_block_body(command) {
                    InsertedCommandSource::Block(body.to_owned())
                } else {
                    let mut variables = command_context.format_variables.clone();
                    variables.extend(
                        parsed
                            .positional
                            .iter()
                            .skip(1)
                            .enumerate()
                            .map(|(index, value)| ((index + 1).to_string(), value.clone())),
                    );
                    let mut hooks = DaemonFormatHooks::command_with_variables(&facts, &variables);
                    InsertedCommandSource::Shell(expand_format_values(
                        command,
                        &format_context,
                        &mut hooks,
                    ))
                }
            });
            let cwd = job_working_directory(&inner, &command_context, parsed.cwd.as_deref());
            let tmux = tmux_environment(&self.socket_path, command_context.session);
            (target, command_context, command, cwd, tmux)
        };

        if matches!(&command, Some(InsertedCommandSource::Block(_))) && !parsed.command_mode {
            return Err(ServerError::InvalidCommand(RUN_SHELL_USAGE.to_owned()).into());
        }

        let route = RunShellRoute {
            client,
            kind,
            foreground: !parsed.background,
            target_requested: parsed.target.is_some(),
            target,
        };
        let delay = parsed.delay.unwrap_or_default();
        match command {
            None if parsed.delay.is_none() => Ok(Execution::default()),
            None => {
                if parsed.background {
                    self.spawn_delay(delay, || {})?;
                    Ok(Execution::default())
                } else {
                    let (sender, receiver) = mpsc::sync_channel(1);
                    self.spawn_delay(delay, move || {
                        let _ = sender.send(());
                    })?;
                    receiver.recv().map_err(|error| {
                        DaemonError::Thread(format!("run-shell delay worker stopped: {error}"))
                    })?;
                    Ok(Execution::default())
                }
            }
            Some(source @ (InsertedCommandSource::String(_) | InsertedCommandSource::Block(_))) => {
                if parsed.background {
                    let shared = Arc::clone(self);
                    self.spawn_delay(delay, move || {
                        let mut context = command_context;
                        match shared.execute_inserted_commands(
                            client,
                            kind,
                            &mut context,
                            &source,
                            "<run-shell -C>",
                        ) {
                            Ok(result) => {
                                let _ = shared.finish_inserted_run_shell(
                                    route,
                                    "run-shell".to_owned(),
                                    &result,
                                );
                            }
                            Err(error) => {
                                if let Some(output) = daemon_error_output(&error) {
                                    shared.route_background_inserted_output(
                                        client,
                                        kind,
                                        &context,
                                        "run-shell".to_owned(),
                                        output,
                                    );
                                }
                                shared.publish_background_command_error(
                                    client, &context, &error, true,
                                );
                            }
                        }
                    })?;
                    Ok(Execution::default())
                } else {
                    let (sender, receiver) = mpsc::sync_channel(1);
                    self.spawn_delay(delay, move || {
                        let _ = sender.send(());
                    })?;
                    receiver.recv().map_err(|error| {
                        DaemonError::Thread(format!("run-shell delay worker stopped: {error}"))
                    })?;
                    let mut command_context = command_context;
                    let result = self.execute_inserted_commands(
                        client,
                        kind,
                        &mut command_context,
                        &source,
                        "<run-shell -C>",
                    )?;
                    *context = command_context;
                    self.finish_inserted_run_shell(route, "run-shell".to_owned(), &result)
                }
            }
            Some(InsertedCommandSource::Shell(command)) => {
                if parsed.background {
                    let shared = Arc::clone(self);
                    let background_command = command.clone();
                    let worker_context = command_context.clone();
                    if let Err(error) = self.spawn_shell_job(
                        command,
                        cwd,
                        tmux,
                        parsed.show_stderr,
                        delay,
                        move |result| {
                            if let Ok(result) = result {
                                let _ =
                                    shared.finish_run_shell(route, &background_command, &result);
                            } else {
                                let error = ServerError::InvalidCommand(format!(
                                    "failed to run command: {background_command}"
                                ))
                                .into();
                                shared.publish_background_command_error(
                                    route.client,
                                    &worker_context,
                                    &error,
                                    false,
                                );
                            }
                        },
                    ) {
                        self.publish_background_command_error(
                            client,
                            &command_context,
                            &error,
                            false,
                        );
                    }
                    Ok(Execution::default())
                } else {
                    let (sender, receiver) = mpsc::sync_channel(1);
                    let failed_command = command.clone();
                    self.spawn_shell_job(
                        command.clone(),
                        cwd,
                        tmux,
                        parsed.show_stderr,
                        delay,
                        move |result| {
                            let _ = sender.send(result);
                        },
                    )?;
                    let result = receiver.recv().map_err(|error| {
                        DaemonError::Thread(format!("run-shell worker stopped: {error}"))
                    })?;
                    let result = result.map_err(|()| {
                        ServerError::InvalidCommand(format!(
                            "failed to run command: {failed_command}"
                        ))
                    })?;
                    self.finish_run_shell(route, &command, &result)
                }
            }
        }
    }

    fn if_shell(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_if_shell_args(args)?;
        let (condition, command_context, cwd, tmux) = {
            let mut inner = self.inner.lock();
            let target = parsed.target.as_deref().and_then(|target| {
                inner
                    .engine
                    .resolve_pane(Some(target), context.window, context.pane)
                    .ok()
            });
            let mut command_context = context.clone();
            if let Some(pane) = target {
                command_context.retarget_to_pane(&inner.engine.state, pane);
            }
            inner.engine.set_format_now(unix_timestamp());
            let format_context = inner.engine.format_status_context(
                command_context.session,
                command_context.window,
                command_context.pane,
            );
            let facts = format_hook_facts(&inner);
            let mut hooks = DaemonFormatHooks::command_with_optional_variables(
                &facts,
                command_context.format_variables(),
            );
            let condition =
                expand_format_values(&parsed.positional[0], &format_context, &mut hooks);
            let cwd = job_working_directory(&inner, &command_context, None);
            let tmux = tmux_environment(&self.socket_path, command_context.session);
            (condition, command_context, cwd, tmux)
        };

        if parsed.format {
            let Some(branch) =
                select_if_shell_branch(&parsed.positional, if_shell_truthy(&condition))
            else {
                return Ok(Execution::default());
            };
            let source = inserted_command_source(branch);
            let mut command_context = command_context;
            let result = self.execute_inserted_commands(
                client,
                kind,
                &mut command_context,
                &source,
                "<if-shell>",
            )?;
            *context = command_context;
            return inserted_execution(client, kind, result);
        }

        if parsed.background {
            let shared = Arc::clone(self);
            let branches = parsed.positional;
            let condition_for_error = condition.clone();
            self.spawn_shell_job(condition, cwd, tmux, false, Duration::ZERO, move |result| {
                if let Ok(result) = result {
                    let Some(branch) = select_if_shell_branch(&branches, result.status.success())
                    else {
                        return;
                    };
                    let source = inserted_command_source(branch);
                    let mut context = command_context;
                    match shared.execute_inserted_commands(
                        client,
                        kind,
                        &mut context,
                        &source,
                        "<if-shell>",
                    ) {
                        Ok(result) => shared.route_background_inserted_output(
                            client,
                            kind,
                            &context,
                            "if-shell".to_owned(),
                            &result.output,
                        ),
                        Err(error) => {
                            if let Some(output) = daemon_error_output(&error) {
                                shared.route_background_inserted_output(
                                    client,
                                    kind,
                                    &context,
                                    "if-shell".to_owned(),
                                    output,
                                );
                            }
                            shared.publish_background_command_error(client, &context, &error, true);
                        }
                    }
                } else {
                    let error = ServerError::InvalidCommand(format!(
                        "failed to run command: {condition_for_error}"
                    ))
                    .into();
                    shared.publish_background_command_error(
                        client,
                        &command_context,
                        &error,
                        false,
                    );
                }
            })?;
            return Ok(Execution::default());
        }

        let (sender, receiver) = mpsc::sync_channel(1);
        let failed_condition = condition.clone();
        self.spawn_shell_job(condition, cwd, tmux, false, Duration::ZERO, move |result| {
            let _ = sender.send(result);
        })?;
        let result = receiver
            .recv()
            .map_err(|error| DaemonError::Thread(format!("if-shell worker stopped: {error}")))?;
        let result = result.map_err(|()| {
            ServerError::InvalidCommand(format!("failed to run command: {failed_condition}"))
        })?;
        let Some(branch) = select_if_shell_branch(&parsed.positional, result.status.success())
        else {
            return Ok(Execution::default());
        };
        let source = inserted_command_source(branch);
        let mut command_context = command_context;
        let result = self.execute_inserted_commands(
            client,
            kind,
            &mut command_context,
            &source,
            "<if-shell>",
        )?;
        *context = command_context;
        inserted_execution(client, kind, result)
    }

    fn execute_inserted_commands(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        source: &InsertedCommandSource,
        label: &str,
    ) -> Result<InsertedCommandResult, DaemonError> {
        let input = match source {
            InsertedCommandSource::String(input) | InsertedCommandSource::Block(input) => input,
            InsertedCommandSource::Shell(_) => unreachable!(),
        };
        let parsed = {
            let inner = self.inner.lock();
            inner.engine.parse_config(label, input)
        };
        if let Some(diagnostic) = parsed.diagnostics.into_iter().next() {
            return Err(ServerError::InvalidCommand(diagnostic.message).into());
        }
        let mut result = InsertedCommandResult::default();
        for command in parsed.commands {
            match self.execute(client, kind, context, &command) {
                Ok(execution) => append_inserted_output(&mut result.output, &execution.output),
                Err(DaemonError::CommandExit { output, exit_code }) => {
                    append_inserted_output(&mut result.output, &output);
                    result.exit_code = exit_code;
                    break;
                }
                Err(error) => {
                    return Err(prepend_command_output(
                        std::mem::take(&mut result.output),
                        error,
                    ));
                }
            }
        }
        Ok(result)
    }

    fn finish_run_shell(
        self: &Arc<Self>,
        route: RunShellRoute,
        command: &str,
        result: &ShellJobResult,
    ) -> Result<Execution, DaemonError> {
        let (output, exit_code) = shell_job_output(command, result);
        let output = self.route_run_shell_output(route, command.to_owned(), &output);
        if route.foreground
            && matches!(route.kind, ClientKind::Command | ClientKind::Control)
            && route.client != ClientId(u64::MAX)
            && exit_code != 0
        {
            Err(DaemonError::CommandExit { output, exit_code })
        } else {
            Ok(Execution {
                output,
                effects: Vec::new(),
            })
        }
    }

    fn finish_inserted_run_shell(
        self: &Arc<Self>,
        route: RunShellRoute,
        title: String,
        result: &InsertedCommandResult,
    ) -> Result<Execution, DaemonError> {
        let output = self.route_run_shell_output(route, title, &result.output);
        inserted_execution(
            route.client,
            route.kind,
            InsertedCommandResult {
                output,
                exit_code: result.exit_code,
            },
        )
    }

    fn route_run_shell_output(
        self: &Arc<Self>,
        route: RunShellRoute,
        title: String,
        output: &str,
    ) -> String {
        if output.is_empty() {
            return String::new();
        }
        if route.kind == ClientKind::Control {
            return if route.foreground {
                output.to_owned()
            } else {
                String::new()
            };
        }
        if route.target_requested
            && let Some(target) = route.target
            && self
                .inner
                .lock()
                .engine
                .state
                .pane(target)
                .is_some_and(|pane| !pane.dead)
        {
            self.open_command_output_for_pane(target, &title, output);
            return String::new();
        }
        if route.foreground {
            if matches!(route.kind, ClientKind::Command | ClientKind::Control) {
                return output.to_owned();
            }
            let _ = self.open_command_output(route.client, None, title, output);
            return String::new();
        }
        let pane = self
            .inner
            .lock()
            .engine
            .state
            .most_recent_context()
            .map(|(_, _, pane)| pane);
        if let Some(pane) = pane {
            self.open_command_output_for_pane(pane, &title, output);
        }
        String::new()
    }

    fn open_command_output_for_pane(self: &Arc<Self>, pane: PaneId, title: &str, output: &str) {
        let clients = {
            let inner = self.inner.lock();
            attached_clients_for_pane(&inner, pane)
                .into_iter()
                .flatten()
                .copied()
                .filter(|client| {
                    inner.subscribers.contains_key(client)
                        && inner.client_kinds.get(client) == Some(&ClientKind::Interactive)
                })
                .collect::<Vec<_>>()
        };
        for client in clients {
            let _ = self.open_command_output(client, Some(pane), title.to_owned(), output);
        }
    }

    fn route_background_inserted_output(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &ExecutionContext,
        title: String,
        output: &str,
    ) {
        if kind == ClientKind::Interactive && !output.is_empty() {
            let _ = self.open_command_output(client, context.pane, title, output);
        }
    }

    fn publish_background_command_error(
        &self,
        client: ClientId,
        context: &ExecutionContext,
        error: &DaemonError,
        uppercase: bool,
    ) {
        let mut message = daemon_error_text(error);
        if uppercase {
            uppercase_first(&mut message);
        }
        push_server_message(&mut self.inner.lock(), message.clone());
        self.publish_to_client(
            client,
            EventPayload::ClientMessage {
                pane: context.pane,
                kind: ClientMessageKind::Error,
                text: message,
            },
        );
    }

    fn spawn_delay(
        &self,
        delay: Duration,
        callback: impl FnOnce() + Send + 'static,
    ) -> Result<(), DaemonError> {
        thread::Builder::new()
            .name("zz-run-shell".to_owned())
            .spawn(move || {
                thread::sleep(delay);
                callback();
            })
            .map(|_| ())
            .map_err(|error| DaemonError::Thread(error.to_string()))
    }

    fn spawn_shell_job(
        self: &Arc<Self>,
        command: String,
        cwd: PathBuf,
        tmux: String,
        show_stderr: bool,
        delay: Duration,
        callback: impl FnOnce(Result<ShellJobResult, ()>) + Send + 'static,
    ) -> Result<(), DaemonError> {
        let permit = ShellJobPermit::acquire(self).ok_or_else(|| {
            ServerError::InvalidCommand(format!("failed to run command: {command}"))
        })?;
        let failed_command = command.clone();
        let zz_socket = self.socket_path.clone();
        let startup_reentry = (!*self.startup_ready.lock()).then(|| self.server_id.to_string());
        #[cfg(unix)]
        let (tmux_shim, zz_executable) = self.tmux_shim.lock().as_ref().map_or_else(
            || (None, None),
            |shim| (Some(shim.directory.clone()), Some(shim.executable.clone())),
        );
        #[cfg(not(unix))]
        let (tmux_shim, zz_executable) = (None::<PathBuf>, None::<PathBuf>);
        thread::Builder::new()
            .name("zz-run-shell".to_owned())
            .spawn(move || {
                thread::sleep(delay);
                let result = run_shell_job(
                    &command,
                    &cwd,
                    &tmux,
                    &zz_socket,
                    startup_reentry.as_deref(),
                    tmux_shim.as_deref(),
                    zz_executable.as_deref(),
                    show_stderr,
                    &permit.process,
                    &permit.shared.stopping,
                );
                drop(permit);
                callback(result);
            })
            .map(|_| ())
            .map_err(|_| {
                ServerError::InvalidCommand(format!("failed to run command: {failed_command}"))
                    .into()
            })
    }

    fn agent_send(
        self: &Arc<Self>,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_agent_send_args(args)?;
        let payload = parsed.payload()?;
        let pane = self.resolve_agent_pane(context, parsed.target.as_deref())?;
        self.deliver_to_agent(pane, payload, parsed.submit)
    }

    fn send_last_output(
        self: &Arc<Self>,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let target = parse_target_only_args("send-last-output", args)?;
        let (pane, terminal) = {
            let inner = self.inner.lock();
            let pane =
                inner
                    .engine
                    .resolve_pane(target.as_deref(), context.window, context.pane)?;
            if !matches!(
                inner.engine.state.pane(pane).map(|pane| &pane.kind),
                Some(PaneKind::Terminal)
            ) {
                return Err(
                    ServerError::InvalidTarget(format!("{pane} is not a terminal pane")).into(),
                );
            }
            let terminal = inner
                .terminals
                .get(&pane)
                .cloned()
                .ok_or(ServerError::PaneExited(pane))?;
            (pane, terminal)
        };
        let capture = match terminal.capture_last_command() {
            Ok(capture) => capture,
            Err(TerminalCaptureError::NoSemanticMarks) => {
                return Err(ServerError::InvalidCommand(format!(
                    "{pane} has no shell-integration marks; send-last-output needs a shell that \
                     emits OSC 133 prompt marks (ghostty, kitty, wezterm, or starship shell \
                     integration all do)"
                ))
                .into());
            }
            Err(TerminalCaptureError::ActorStopped) => {
                return Err(ServerError::PaneExited(pane).into());
            }
            Err(TerminalCaptureError::TimedOut) => {
                return Err(ServerError::Internal("terminal capture timed out".to_owned()).into());
            }
            Err(error) => return Err(ServerError::Internal(error.to_string()).into()),
        };
        if capture.command.trim().is_empty() {
            return Err(ServerError::InvalidCommand(format!(
                "{pane} has not completed a command yet"
            ))
            .into());
        }
        let agent = self
            .inner
            .lock()
            .engine
            .state
            .recent_agent_pane(pane)
            .ok_or_else(|| {
                ServerError::MissingTarget(format!("no agent pane in the window holding {pane}"))
            })?;
        self.deliver_to_agent(agent, last_command_block(pane, &capture), false)?;
        Ok(Execution {
            output: format!("sent the last command from {pane} to {agent}"),
            effects: Vec::new(),
        })
    }

    fn capture_browser(
        &self,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_capture_browser_args(args)?;
        let output = parsed.output.ok_or_else(|| {
            ServerError::InvalidCommand("capture-browser needs an output path (-o)".to_owned())
        })?;
        let path = expand_path(&output);
        if !path.is_absolute() {
            return Err(ServerError::InvalidCommand(format!(
                "capture-browser output path must be absolute: {output}"
            ))
            .into());
        }
        let path = path
            .to_str()
            .ok_or_else(|| {
                ServerError::InvalidCommand(
                    "capture-browser output path is not valid UTF-8".to_owned(),
                )
            })?
            .to_owned();
        let pane = {
            let inner = self.inner.lock();
            let pane = inner.engine.resolve_pane(
                parsed.target.as_deref(),
                context.window,
                context.pane,
            )?;
            if !matches!(
                inner.engine.state.pane(pane).map(|pane| &pane.kind),
                Some(PaneKind::Browser(_))
            ) {
                return Err(
                    ServerError::InvalidTarget(format!("{pane} is not a browser pane")).into(),
                );
            }
            pane
        };
        let output = self.request_from_gui(pane, |request_id| EventPayload::BrowserCommand {
            pane,
            command: BrowserCommand::Screenshot { request_id, path },
        })?;
        Ok(Execution {
            output,
            effects: Vec::new(),
        })
    }

    fn resolve_agent_pane(
        &self,
        context: &ExecutionContext,
        target: Option<&str>,
    ) -> Result<PaneId, DaemonError> {
        let inner = self.inner.lock();
        let pane = inner
            .engine
            .resolve_pane(target, context.window, context.pane)?;
        match inner.engine.state.pane(pane).map(|pane| &pane.kind) {
            Some(PaneKind::Agent(_)) => Ok(pane),
            Some(_) => inner.engine.state.recent_agent_pane(pane).ok_or_else(|| {
                ServerError::MissingTarget(format!("no agent pane in the window holding {pane}"))
                    .into()
            }),
            None => Err(ServerError::MissingTarget(pane.to_string()).into()),
        }
    }

    fn deliver_to_agent(
        self: &Arc<Self>,
        pane: PaneId,
        text: String,
        submit: bool,
    ) -> Result<Execution, DaemonError> {
        // A submitted prompt is the daemon's own business now; only the
        // composer draft still belongs to whichever GUI owns the pane.
        #[cfg(feature = "agent")]
        if submit {
            if !self.submit_agent_prompt(pane, text) {
                return Err(ServerError::PaneExited(pane).into());
            }
            return Ok(Execution::default());
        }
        let command = if submit {
            AgentCommand::Prompt { text }
        } else {
            AgentCommand::ComposerAppend { text }
        };
        let output = self.request_from_gui(pane, move |request_id| EventPayload::AgentCommand {
            pane,
            request_id,
            command,
        })?;
        Ok(Execution {
            output,
            effects: Vec::new(),
        })
    }

    fn list_clients(
        &self,
        context: &ExecutionContext,
        name: &str,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_buffer_command_args(name, args, &['F', 't'], &[])?;
        require_no_positionals(name, &parsed)?;
        let mut inner = self.inner.lock();
        let target = parsed
            .value('t')
            .map(|target| {
                inner
                    .engine
                    .state
                    .resolve_session(Some(target), context.session)
            })
            .transpose()?;
        inner.engine.set_format_now(unix_timestamp());
        let mut clients = inner
            .attached
            .iter()
            .flat_map(|(session, clients)| {
                clients
                    .iter()
                    .copied()
                    .map(|client| (client, *session))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        clients.sort_by(|(left, _), (right, _)| {
            let left_name = inner
                .client_names
                .get(left)
                .cloned()
                .unwrap_or_else(|| format!("device-{}", left.0));
            let right_name = inner
                .client_names
                .get(right)
                .cloned()
                .unwrap_or_else(|| format!("device-{}", right.0));
            left_name.cmp(&right_name).then(left.0.cmp(&right.0))
        });
        let format = parsed.value('F').unwrap_or(
            "#{client_name}: #{session_name} [#{client_width}x#{client_height} #{client_termname}] #{?#{!=:#{client_uid},#{uid}},[user #{?client_user,#{client_user},#{client_uid},}] ,}#{?client_flags,(,}#{client_flags}#{?client_flags,),}",
        );
        let mut output = Vec::new();
        for (line, (client, session_id)) in clients.into_iter().enumerate() {
            if target.is_some_and(|target| target != session_id) {
                continue;
            }
            let session = inner
                .engine
                .state
                .sessions
                .get(&session_id)
                .ok_or_else(|| ServerError::MissingTarget(session_id.to_string()))?;
            let focused = client_focused_window(&inner, client, session);
            let format_context =
                inner
                    .engine
                    .format_status_context(Some(session_id), Some(focused), None);
            let mut client_facts = client_format_facts(&inner, client, session_id);
            client_facts.line = line;
            let facts = FormatHookFacts {
                client: Some(client_facts),
                ..FormatHookFacts::default()
            };
            let mut hooks = DaemonFormatHooks::command_with_optional_variables(
                &facts,
                context.format_variables(),
            );
            output.push(expand_format_values(format, &format_context, &mut hooks));
        }
        Ok(Execution {
            output: output.join("\n"),
            effects: Vec::new(),
        })
    }

    fn show_messages(&self, name: &str, args: &[String]) -> Result<Execution, DaemonError> {
        let parsed = parse_buffer_command_args(name, args, &[], &[])?;
        require_no_positionals(name, &parsed)?;
        let mut inner = self.inner.lock();
        inner.engine.set_format_now(unix_timestamp());
        let context = inner.engine.format_status_context(None, None, None);
        let output = inner
            .message_log
            .iter()
            .rev()
            .map(|message| {
                let facts = FormatHookFacts {
                    message: Some(MessageFormatFacts {
                        number: message.number,
                        text: message.text.clone(),
                        time: message.time,
                    }),
                    ..FormatHookFacts::default()
                };
                let mut hooks = DaemonFormatHooks::command(&facts);
                expand_format_values("#{t/p:message_time}: #{message_text}", &context, &mut hooks)
            })
            .collect::<Vec<_>>()
            .join("\n");
        Ok(Execution {
            output,
            effects: Vec::new(),
        })
    }

    fn set_control_client_flags(&self, client: ClientId, flags: &str) {
        let event = {
            let mut inner = self.inner.lock();
            if inner.client_kinds.get(&client) != Some(&ClientKind::Control) {
                return;
            }
            let (before, after) = {
                let output = inner.control_outputs.entry(client).or_default();
                let before = (output.wait_exit, output.pause_after_ms, output.no_output);
                apply_control_client_flags(output, flags);
                let after = (output.wait_exit, output.pause_after_ms, output.no_output);
                (before, after)
            };
            (before != after).then(|| {
                (
                    inner.subscribers.get(&client).cloned(),
                    EventPayload::ControlFlags {
                        wait_exit: after.0,
                        pause_after_ms: after.1,
                        no_output: after.2,
                    },
                )
            })
        };
        if let Some((Some(subscriber), payload)) = event {
            Self::send_event(&subscriber, payload);
        }
    }

    fn set_control_pane_state(&self, client: ClientId, value: &str) {
        let Some((pane, state)) = parse_control_pane_state(value) else {
            return;
        };
        let event = {
            let mut inner = self.inner.lock();
            if inner.engine.state.pane(pane).is_none() {
                return;
            }
            let output = inner.control_outputs.entry(client).or_default();
            let pane_output = output.panes.entry(pane).or_default();
            let paused = match state {
                "on" if pane_output.mode == ControlPaneOutputMode::Off => {
                    pane_output.pending.clear();
                    pane_output.mode = ControlPaneOutputMode::On;
                    None
                }
                "off" => {
                    pane_output.pending.clear();
                    pane_output.mode = ControlPaneOutputMode::Off;
                    None
                }
                "pause" if pane_output.mode != ControlPaneOutputMode::Paused => {
                    pane_output.pending.clear();
                    pane_output.mode = ControlPaneOutputMode::Paused;
                    Some(true)
                }
                "continue" if pane_output.mode == ControlPaneOutputMode::Paused => {
                    pane_output.pending.clear();
                    pane_output.mode = ControlPaneOutputMode::On;
                    Some(false)
                }
                "on" | "pause" | "continue" => None,
                _ => return,
            };
            paused.map(|paused| {
                (
                    inner.subscribers.get(&client).cloned(),
                    EventPayload::PaneOutputState { pane, paused },
                )
            })
        };
        if let Some((Some(subscriber), payload)) = event {
            Self::send_event(&subscriber, payload);
        }
    }

    fn set_control_client_size(&self, client: ClientId, value: &str) -> Result<(), DaemonError> {
        let update = parse_control_client_size(value)?;
        let (changed, resizes) = {
            let mut inner = self.inner.lock();
            let mut affected = control_client_sized_panes(&inner, client);
            let output = inner.control_outputs.entry(client).or_default();
            match update {
                ControlClientSizeUpdate::Client(geometry) => output.geometry = Some(geometry),
                ControlClientSizeUpdate::Window(window, Some(geometry)) => {
                    output.window_geometries.insert(window, geometry);
                }
                ControlClientSizeUpdate::Window(window, None) => {
                    output.window_geometries.remove(&window);
                }
            }
            affected.extend(control_client_sized_panes(&inner, client));
            let changed = write_back_terminal_geometries(&mut inner, &affected, false);
            let resizes = terminal_resizes_for_panes(&inner, &affected);
            (changed, resizes)
        };
        apply_terminal_resizes(resizes);
        if changed {
            self.publish_snapshot();
        }
        Ok(())
    }

    fn update_control_subscription(&self, client: ClientId, value: &str) {
        let mut inner = self.inner.lock();
        let output = inner.control_outputs.entry(client).or_default();
        match parse_control_subscription(value) {
            ControlSubscriptionUpdate::Remove(name) => {
                output.subscriptions.remove(name);
            }
            ControlSubscriptionUpdate::Set {
                name,
                scope,
                format,
            } => {
                output.subscriptions.insert(
                    name.to_owned(),
                    ControlSubscription {
                        scope,
                        format: format.to_owned(),
                        previous: BTreeMap::new(),
                    },
                );
            }
        }
    }

    fn refresh_client(
        &self,
        client: ClientId,
        _kind: ClientKind,
        name: &str,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_buffer_command_args(
            name,
            args,
            &['A', 'B', 'C', 'F', 'f', 'r', 't'],
            &['c', 'D', 'l', 'L', 'R', 'S', 'U'],
        )?;
        if parsed.positional.len() > 1 {
            return Err(ServerError::InvalidCommand(
                "refresh-client accepts at most one adjustment".to_owned(),
            )
            .into());
        }
        let target = {
            let inner = self.inner.lock();
            resolve_attached_client(&inner, client, parsed.value('t'))?
        };
        if parsed.has('c')
            || parsed.has('D')
            || parsed.has('L')
            || parsed.has('R')
            || parsed.has('U')
            || !parsed.positional.is_empty()
            || parsed.has('l')
        {
            return Err(ServerError::UnsupportedCommand(
                "refresh-client interactive behavior".to_owned(),
            )
            .into());
        }
        let mut handled_flags = false;
        for flags in parsed.values('F') {
            self.set_control_client_flags(target, flags);
            handled_flags = true;
        }
        for flags in parsed.values('f') {
            self.set_control_client_flags(target, flags);
            handled_flags = true;
        }
        if parsed.value('r').is_some() {
            return Err(ServerError::UnsupportedCommand(
                "refresh-client interactive behavior".to_owned(),
            )
            .into());
        }
        if parsed.value('A').is_some() {
            if self.inner.lock().client_kinds.get(&target) != Some(&ClientKind::Control) {
                return Err(ServerError::InvalidCommand("not a control client".to_owned()).into());
            }
            for value in parsed.values('A') {
                self.set_control_pane_state(target, value);
            }
            return Ok(Execution::default());
        }
        if parsed.value('B').is_some() {
            if self.inner.lock().client_kinds.get(&target) != Some(&ClientKind::Control) {
                return Err(ServerError::InvalidCommand("not a control client".to_owned()).into());
            }
            for value in parsed.values('B') {
                self.update_control_subscription(target, value);
            }
            return Ok(Execution::default());
        }
        if parsed.value('C').is_some() {
            if self.inner.lock().client_kinds.get(&target) != Some(&ClientKind::Control) {
                return Err(ServerError::InvalidCommand("not a control client".to_owned()).into());
            }
            for value in parsed.values('C') {
                self.set_control_client_size(target, value)?;
            }
            return Ok(Execution::default());
        }
        if handled_flags && !parsed.has('S') {
            return Ok(Execution::default());
        }
        Err(
            ServerError::UnsupportedCommand("refresh-client interactive behavior".to_owned())
                .into(),
        )
    }

    fn display_popup(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_display_popup_args(args)?;
        if kind == ClientKind::Control {
            return Ok(Execution::default());
        }
        let (target_client, mut target) = {
            let inner = self.inner.lock();
            let target_client =
                resolve_popup_client(&inner, client, context, parsed.target_client.as_deref())?;
            let pane = inner.engine.resolve_pane(
                parsed.target_pane.as_deref(),
                context.window,
                context.pane,
            )?;
            let mut target = ExecutionContext::for_pane(&inner.engine.state, pane)
                .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
            target
                .format_variables
                .clone_from(&context.format_variables);
            (target_client, target)
        };

        if parsed.clear {
            let mut events = Vec::new();
            let mut outputs = Vec::new();
            let mut popups = Vec::new();
            {
                let mut inner = self.inner.lock();
                dismiss_overlays(
                    &mut inner,
                    target_client,
                    None,
                    &mut events,
                    &mut outputs,
                    &mut popups,
                );
            }
            for event in events {
                self.publish_to_client(target_client, event);
            }
            for (owner, output) in outputs {
                Self::retire_command_output(owner, output);
            }
            for (owner, popup) in popups {
                Self::retire_popup(owner, popup, true);
            }
            return Ok(Execution::default());
        }

        let modifying = self.inner.lock().popups.contains_key(&target_client);
        if modifying {
            let (title, border_lines) = {
                let inner = self.inner.lock();
                let title = parsed.title.as_deref().map_or_else(String::new, |title| {
                    expand_popup_value(&inner, &target, context.session, title)
                });
                let border_lines = if parsed.borderless {
                    Some(PopupBorderLines::None)
                } else {
                    parsed
                        .border_lines
                        .as_deref()
                        .map(|value| {
                            value.parse().map_err(|()| {
                                ServerError::InvalidCommand(format!(
                                    "popup-border-lines unknown value: {value}"
                                ))
                            })
                        })
                        .transpose()?
                };
                (title, border_lines)
            };
            let (terminal, state, resize) = {
                let mut inner = self.inner.lock();
                let Some(popup) = inner.popups.get_mut(&target_client) else {
                    return Ok(Execution::default());
                };
                if border_lines.is_some_and(|lines| {
                    lines != PopupBorderLines::None
                        && (popup.state.width <= 2 || popup.state.height <= 2)
                }) {
                    return Ok(Execution::default());
                }
                popup.state.title = title;
                if let Some(style) = &parsed.style {
                    popup.state.style.clone_from(style);
                }
                if let Some(style) = &parsed.border_style {
                    popup.state.border_style.clone_from(style);
                }
                let previous_lines = popup.state.border_lines;
                if let Some(lines) = border_lines {
                    popup.state.border_lines = lines;
                }
                if let Some((close_on_exit, close_on_exit_zero, close_on_any_key)) =
                    popup_close_flags(&parsed, true)
                {
                    popup.state.close_on_exit = close_on_exit;
                    popup.state.close_on_exit_zero = close_on_exit_zero;
                    popup.state.close_on_any_key = close_on_any_key;
                }
                popup.state.dead |= popup.terminal.completion().is_some();
                let resize = (previous_lines != popup.state.border_lines && !popup.state.dead)
                    .then(|| popup_content_size(&popup.state))
                    .flatten()
                    .map(|(columns, rows)| {
                        (columns, rows, popup.cell_width_px, popup.cell_height_px)
                    });
                (Arc::clone(&popup.terminal), popup.state.clone(), resize)
            };
            if let Some((columns, rows, cell_width_px, cell_height_px)) = resize {
                terminal.resize(columns, rows, cell_width_px, cell_height_px);
            }
            self.publish_to_client(target_client, EventPayload::Popup { state: Some(state) });
            return Ok(Execution::default());
        }

        if popup_other_overlay_present(&self.inner.lock(), target_client) {
            return Ok(Execution::default());
        }

        let (geometry, history_limit, word_separators, appearance, spawn, mut state) = {
            let inner = self.inner.lock();
            let Some(geometry) = popup_client_geometry(&inner, target_client)? else {
                return Ok(Execution::default());
            };
            let width = parse_popup_dimension("width", parsed.width.as_deref(), geometry.columns)?;
            let height = parse_popup_dimension("height", parsed.height.as_deref(), geometry.rows)?;
            let window = target
                .window
                .ok_or_else(|| ServerError::MissingTarget("current window".to_owned()))?;
            let session = target
                .session
                .ok_or_else(|| ServerError::MissingTarget("current session".to_owned()))?;
            let pane = target
                .pane
                .ok_or_else(|| ServerError::MissingTarget("current pane".to_owned()))?;
            let style_window = inner
                .engine
                .state
                .sessions
                .get(&session)
                .map_or(window, |state| state.active_window);
            let defaults = inner.engine.popup_options_for_window(style_window)?;
            let border_lines = if parsed.borderless {
                PopupBorderLines::None
            } else if let Some(value) = parsed.border_lines.as_deref() {
                value.parse().map_err(|()| {
                    ServerError::InvalidCommand(format!(
                        "popup-border-lines unknown value: {value}"
                    ))
                })?
            } else {
                defaults.border_lines
            };
            let variables = popup_position_variables(
                &inner.engine,
                &target,
                geometry.columns,
                geometry.rows,
                width,
                height,
            );
            target.format_variables.extend(variables);
            let (left, top) = popup_position(
                parsed.x.as_deref(),
                parsed.y.as_deref(),
                geometry.columns,
                geometry.rows,
                width,
                height,
                |value| expand_popup_value(&inner, &target, context.session, value),
            );
            let title = parsed.title.as_deref().map_or_else(String::new, |title| {
                expand_popup_value(&inner, &target, context.session, title)
            });
            let requested_cwd = parsed
                .start_directory
                .as_deref()
                .map(|directory| expand_popup_value(&inner, &target, context.session, directory));
            let working_directory =
                job_working_directory(&inner, &target, requested_cwd.as_deref());
            let shell = terminal_shell_for_session(&inner.engine, session)?;
            let default_command = inner.engine.default_command_for_session(session)?;
            let command = popup_command_shape(default_command, &parsed.command);
            let mut env = terminal_environment_for_session(&inner.engine, session)?;
            for assignment in &parsed.environment {
                let (name, value) = assignment.split_once('=').ok_or_else(|| {
                    ServerError::InvalidCommand(format!(
                        "display-popup invalid environment: {assignment}"
                    ))
                })?;
                if name.is_empty() {
                    return Err(ServerError::InvalidCommand(format!(
                        "display-popup invalid environment: {assignment}"
                    ))
                    .into());
                }
                env.retain(|(existing, _)| existing != name);
                env.push((name.to_owned(), Some(value.to_owned())));
            }
            env.extend([
                ("ZZ_PANE".to_owned(), Some(pane.to_string())),
                (
                    "ZZ_SOCKET".to_owned(),
                    Some(self.socket_path.display().to_string()),
                ),
                ("ZZ_SESSION".to_owned(), Some(session.to_string())),
                (
                    "TMUX".to_owned(),
                    Some(tmux_environment(&self.socket_path, Some(session))),
                ),
                ("TMUX_PANE".to_owned(), Some(pane.to_string())),
                (
                    "PWD".to_owned(),
                    Some(working_directory.to_string_lossy().into_owned()),
                ),
            ]);
            let style = parsed.style.clone().unwrap_or(defaults.style);
            let border_style = parsed.border_style.clone().unwrap_or(defaults.border_style);
            let (close_on_exit, close_on_exit_zero, close_on_any_key) =
                popup_close_flags(&parsed, false).expect("new popup has close flags");
            let state = PopupState {
                pane: PaneId(0),
                left,
                top,
                width,
                height,
                client_columns: geometry.columns,
                client_rows: geometry.rows,
                cell_width_px: geometry.cell_width_px,
                cell_height_px: geometry.cell_height_px,
                title,
                style,
                border_style,
                border_lines,
                close_on_exit,
                close_on_exit_zero,
                close_on_any_key,
                dead: false,
            };
            let Some((columns, rows)) = popup_content_size(&state) else {
                return Ok(Execution::default());
            };
            let spawn = TerminalSpawn {
                working_directory: Some(working_directory),
                command,
                shell: Some(shell),
                terminal_type: Some(inner.engine.default_terminal_for_spawn().to_owned()),
                initial_size: Some(TerminalSize {
                    columns,
                    rows,
                    cell_width_px: geometry.cell_width_px,
                    cell_height_px: geometry.cell_height_px,
                }),
                non_login_shell: true,
                env,
            };
            (
                geometry,
                inner.engine.history_limit_for_session(session),
                WordSeparators::new(inner.engine.word_separators_for_pane(pane)?),
                Arc::clone(&inner.appearance),
                spawn,
                state,
            )
        };

        let terminal = Arc::new(TerminalSession::spawn(history_limit, appearance, spawn));
        terminal.set_word_separators(word_separators);
        terminal.attach_view(TerminalViewId(target_client.0));
        let (wake, wait) = crossbeam_channel::bounded(1);
        {
            let mut inner = self.inner.lock();
            if inner.popups.contains_key(&target_client)
                || popup_other_overlay_present(&inner, target_client)
            {
                terminal.terminate();
                return Ok(Execution::default());
            }
            inner.next_popup_token = inner.next_popup_token.wrapping_add(1).max(1);
            let token = inner.next_popup_token;
            state.pane = PaneId(u64::MAX.saturating_sub(token));
            inner.popups.insert(
                target_client,
                PopupSession {
                    terminal: Arc::clone(&terminal),
                    state: state.clone(),
                    cell_width_px: geometry.cell_width_px,
                    cell_height_px: geometry.cell_height_px,
                    waiter: matches!(kind, ClientKind::Command | ClientKind::Control)
                        .then_some(PopupWaiter { client, wake }),
                },
            );
        }
        self.publish_to_client(
            target_client,
            EventPayload::Popup {
                state: Some(state.clone()),
            },
        );
        if let Some(subscriber) = self.inner.lock().subscribers.get(&target_client).cloned() {
            let _ = subscriber.replace_terminal_viewport(
                state.pane,
                Self::next_sequence(),
                terminal.latest_viewport().as_ref(),
            );
        }
        if let Err(error) = self.watch_popup(target_client, &terminal) {
            self.close_popup(target_client, true);
            return Err(error);
        }
        if !matches!(kind, ClientKind::Command | ClientKind::Control) {
            return Ok(Execution::default());
        }
        let exit_code = wait.recv().unwrap_or(129);
        if exit_code == 0 {
            Ok(Execution::default())
        } else {
            Err(DaemonError::CommandExit {
                output: String::new(),
                exit_code,
            })
        }
    }

    fn display_menu(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_display_menu_args(args)?;
        if kind == ClientKind::Control {
            return Ok(Execution::default());
        }
        let (target_client, mut target) = {
            let inner = self.inner.lock();
            let target_client =
                resolve_popup_client(&inner, client, context, parsed.target_client.as_deref())?;
            let pane = inner.engine.resolve_pane(
                parsed.target_pane.as_deref(),
                context.window,
                context.pane,
            )?;
            let mut target = ExecutionContext::for_pane(&inner.engine.state, pane)
                .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
            target
                .format_variables
                .clone_from(&context.format_variables);
            (target_client, target)
        };
        if any_overlay_present(&self.inner.lock(), target_client) {
            return Ok(Execution::default());
        }
        let starting_choice = menu_starting_number(parsed.starting_choice.as_deref())?;
        let (state, commands) = {
            let inner = self.inner.lock();
            let Some(geometry) = popup_client_geometry(&inner, target_client)? else {
                return Ok(Execution::default());
            };
            let window = target
                .window
                .ok_or_else(|| ServerError::MissingTarget("current window".to_owned()))?;
            let defaults = inner.engine.menu_options_for_window(window)?;
            let title = parsed.title.as_deref().map_or_else(String::new, |title| {
                expand_popup_value(&inner, &target, context.session, title)
            });
            let mut items = Vec::new();
            let mut commands = Vec::new();
            let mut index = 0;
            while index < parsed.items.len() {
                let name = &parsed.items[index];
                index = index.saturating_add(1);
                if name.is_empty() {
                    if items.last().is_some_and(Option::is_some) {
                        items.push(None);
                        commands.push(None);
                    }
                    continue;
                }
                if parsed.items.len().saturating_sub(index) < 2 {
                    return Err(
                        ServerError::InvalidCommand("not enough arguments".to_owned()).into(),
                    );
                }
                let key = &parsed.items[index];
                let command = &parsed.items[index.saturating_add(1)];
                index = index.saturating_add(2);
                let name = expand_popup_value(&inner, &target, context.session, name);
                if name.is_empty() {
                    continue;
                }
                let enabled = !name.starts_with('-');
                let name = if enabled {
                    name
                } else {
                    name.strip_prefix('-').unwrap_or_default().to_owned()
                };
                let key = enabled.then(|| menu_shortcut(key)).flatten();
                let command = expand_popup_value(&inner, &target, context.session, command);
                items.push(Some(MenuItem { name, key, enabled }));
                commands.push(Some(command));
            }
            if items.is_empty() {
                return Ok(Execution::default());
            }
            let width = items
                .iter()
                .flatten()
                .map(|item| {
                    display_width(&item.name)
                        + item
                            .key
                            .as_deref()
                            .map_or(0, |key| display_width(key).saturating_add(3))
                })
                .max()
                .unwrap_or_default()
                .saturating_add(4);
            let height = items.len().saturating_add(2);
            let (Ok(width), Ok(height)) = (u16::try_from(width), u16::try_from(height)) else {
                return Ok(Execution::default());
            };
            if width > geometry.columns || height > geometry.rows {
                return Ok(Execution::default());
            }
            let selected = menu_starting_selection(&starting_choice, &items);
            let border_lines = if let Some(value) = parsed.border_lines.as_deref() {
                value.parse().map_err(|()| {
                    ServerError::InvalidCommand(format!("menu-border-lines unknown value: {value}"))
                })?
            } else {
                defaults.border_lines
            };
            let style = parsed.style.clone().unwrap_or(defaults.style);
            let selected_style = parsed
                .selected_style
                .clone()
                .unwrap_or(defaults.selected_style);
            let border_style = parsed.border_style.clone().unwrap_or(defaults.border_style);
            let variables = popup_position_variables(
                &inner.engine,
                &target,
                geometry.columns,
                geometry.rows,
                width,
                height,
            );
            target.format_variables.extend(variables);
            let (left, top) = popup_position(
                parsed.x.as_deref(),
                parsed.y.as_deref(),
                geometry.columns,
                geometry.rows,
                width,
                height,
                |value| expand_popup_value(&inner, &target, context.session, value),
            );
            (
                MenuState {
                    left,
                    top,
                    width,
                    height,
                    client_columns: geometry.columns,
                    client_rows: geometry.rows,
                    cell_width_px: geometry.cell_width_px,
                    cell_height_px: geometry.cell_height_px,
                    title,
                    style,
                    selected_style,
                    border_style,
                    border_lines,
                    items,
                    selected,
                    stay_open: parsed.stay_open,
                },
                commands,
            )
        };
        let (wake, wait) = crossbeam_channel::bounded(1);
        {
            let mut inner = self.inner.lock();
            if any_overlay_present(&inner, target_client) {
                return Ok(Execution::default());
            }
            inner.menus.insert(
                target_client,
                MenuSession {
                    state: state.clone(),
                    commands,
                    target,
                    waiter: matches!(kind, ClientKind::Command | ClientKind::Control)
                        .then_some(MenuWaiter { client, wake }),
                },
            );
        }
        self.publish_to_client(target_client, EventPayload::Menu { state: Some(state) });
        if matches!(kind, ClientKind::Command | ClientKind::Control) {
            let _ = wait.recv();
        }
        Ok(Execution::default())
    }

    fn confirm_before(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &ExecutionContext,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let parsed = parse_confirm_before_args(args)?;
        let (target_client, target, commands, prompt) = {
            let inner = self.inner.lock();
            let target_client =
                resolve_popup_client(&inner, client, context, parsed.target_client.as_deref())?;
            let pane = client_context_pane(&inner, target_client)
                .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))?;
            let mut target = ExecutionContext::for_pane(&inner.engine.state, pane)
                .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
            target
                .format_variables
                .clone_from(&context.format_variables);
            let command = parsed
                .command
                .as_deref()
                .expect("confirm command was required");
            let command = command_block_body(command).unwrap_or(command);
            let command = expand_popup_value(&inner, &target, context.session, command);
            let parsed_commands = inner.engine.parse_config("<confirm-before>", &command);
            if let Some(diagnostic) = parsed_commands.diagnostics.first() {
                return Err(ServerError::InvalidCommand(diagnostic.message.clone()).into());
            }
            let first = parsed_commands
                .commands
                .first()
                .ok_or_else(|| ServerError::InvalidCommand("empty command".to_owned()))?;
            let prompt = parsed.prompt.as_deref().map_or_else(
                || {
                    format!(
                        "Confirm '{}'? ({{confirm-key}}/n) ",
                        canonical_command(&first.name)
                    )
                },
                |prompt| format!("{prompt} "),
            );
            (target_client, target, parsed_commands.commands, prompt)
        };
        let confirm_key = parsed.confirm_key.as_deref().unwrap_or("y");
        let bytes = confirm_key.as_bytes();
        if bytes.len() != 1 || !(32..=126).contains(&bytes[0]) {
            return Err(ServerError::InvalidCommand("invalid confirm key".to_owned()).into());
        }
        let prompt = {
            let inner = self.inner.lock();
            let prompt = if parsed.prompt.is_some() {
                prompt
            } else {
                prompt.replace("{confirm-key}", confirm_key)
            };
            expand_popup_value(&inner, &target, context.session, &prompt)
        };
        let state = ConfirmState {
            prompt,
            confirm_key: bytes[0],
            default_yes: parsed.default_yes,
        };
        let (wake, wait) = crossbeam_channel::bounded(1);
        let blocking_commands = commands.clone();
        let execution = if parsed.background {
            ConfirmExecution::Background { commands }
        } else if matches!(kind, ClientKind::Command | ClientKind::Control) {
            ConfirmExecution::Blocking { client, wake }
        } else {
            ConfirmExecution::Deferred {
                commands,
                context: context.clone(),
            }
        };
        let mut events = Vec::new();
        let mut outputs = Vec::new();
        let mut popups = Vec::new();
        {
            let mut inner = self.inner.lock();
            dismiss_overlays(
                &mut inner,
                target_client,
                None,
                &mut events,
                &mut outputs,
                &mut popups,
            );
            inner.confirms.insert(
                target_client,
                ConfirmSession {
                    state: state.clone(),
                    execution,
                },
            );
        }
        for event in events {
            self.publish_to_client(target_client, event);
        }
        for (owner, output) in outputs {
            Self::retire_command_output(owner, output);
        }
        for (owner, popup) in popups {
            Self::retire_popup(owner, popup, true);
        }
        self.publish_to_client(target_client, EventPayload::Confirm { state: Some(state) });
        if parsed.background || !matches!(kind, ClientKind::Command | ClientKind::Control) {
            return Ok(Execution::default());
        }
        let accepted = wait.recv().unwrap_or(false);
        if !accepted {
            return Err(DaemonError::CommandExit {
                output: String::new(),
                exit_code: 1,
            });
        }
        let mut command_context = context.clone();
        self.execute_overlay_commands(
            client,
            kind,
            &mut command_context,
            blocking_commands,
            "confirm-before",
        );
        Ok(Execution::default())
    }

    fn lock_command(
        &self,
        client: ClientId,
        context: &ExecutionContext,
        name: &str,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        let target = if name == "lock-server" {
            let parsed = parse_buffer_command_args(name, args, &[], &[])?;
            require_no_positionals(name, &parsed)?;
            None
        } else {
            parse_target_only_args(name, args)?
        };
        let inner = self.inner.lock();
        match name {
            "lock-server" => {}
            "lock-session" => {
                inner
                    .engine
                    .state
                    .resolve_session(target.as_deref(), context.session)?;
            }
            "lock-client" => {
                resolve_attached_client(&inner, client, target.as_deref())?;
            }
            _ => unreachable!("lock command is catalogued"),
        }
        Ok(Execution::default())
    }

    fn buffer_command(
        self: &Arc<Self>,
        context: &ExecutionContext,
        name: &str,
        args: &[String],
    ) -> Result<Execution, DaemonError> {
        match name {
            "set-buffer" | "setb" => {
                let parsed = parse_buffer_command_args(name, args, &['b'], &['a'])?;
                let [data] = parsed.positional.as_slice() else {
                    return Err(ServerError::InvalidCommand(
                        "set-buffer requires exactly one data argument".to_owned(),
                    )
                    .into());
                };
                if data.is_empty() {
                    return Ok(Execution::default());
                }
                let requested_name = parsed.value('b');
                validate_paste_buffer_size(data.len())?;
                if let Some(name) = requested_name {
                    validate_paste_buffer_name(name)?;
                }
                let mut data = data.as_bytes().to_vec();
                let mut inner = self.inner.lock();
                if parsed.has('a')
                    && let Some(name) = requested_name
                    && let Some(buffer) = inner
                        .paste_buffers
                        .iter()
                        .find(|buffer| buffer.name == name)
                {
                    let combined = buffer.data.len().saturating_add(data.len());
                    validate_paste_buffer_size(combined)?;
                    let mut appended = Vec::with_capacity(combined);
                    appended.extend_from_slice(&buffer.data);
                    appended.append(&mut data);
                    data = appended;
                }
                let events = insert_paste_buffer(
                    &mut inner,
                    requested_name,
                    "buffer",
                    data,
                    !parsed.has('a'),
                )?;
                drop(inner);
                if !context.no_hooks {
                    self.run_event_hooks(events);
                }
                self.refresh_choose_buffers();
                Ok(Execution::default())
            }
            "show-buffer" | "showb" => {
                let parsed = parse_buffer_command_args(name, args, &['b'], &[])?;
                require_no_positionals(name, &parsed)?;
                let (buffer_name, data, utf8) = {
                    let inner = self.inner.lock();
                    let buffer = resolve_buffer(&inner, parsed.value('b'))?;
                    (buffer.name.clone(), Arc::clone(&buffer.data), buffer.utf8)
                };
                if !utf8 {
                    return Err(ServerError::InvalidCommand(format!(
                        "buffer {buffer_name} contains non-UTF-8 bytes; use save-buffer"
                    ))
                    .into());
                }
                let output = String::from_utf8(data.as_ref().to_vec())
                    .expect("paste-buffer UTF-8 validity is cached at insertion");
                Ok(Execution {
                    output,
                    effects: Vec::new(),
                })
            }
            "list-buffers" | "lsb" => {
                let parsed = parse_buffer_command_args(name, args, &['F'], &[])?;
                require_no_positionals(name, &parsed)?;
                let mut inner = self.inner.lock();
                if let Some(format) = parsed.value('F') {
                    inner.engine.set_format_now(unix_timestamp());
                    let format_context = inner.engine.format_status_context(None, None, None);
                    let output = inner
                        .paste_buffers
                        .iter()
                        .map(|buffer| {
                            let facts = FormatHookFacts {
                                buffer: Some(buffer_format_facts(buffer)),
                                ..FormatHookFacts::default()
                            };
                            let mut hooks = DaemonFormatHooks::command_with_optional_variables(
                                &facts,
                                context.format_variables(),
                            );
                            expand_format_values(format, &format_context, &mut hooks)
                        })
                        .collect::<Vec<_>>()
                        .join("\n");
                    return Ok(Execution {
                        output,
                        effects: Vec::new(),
                    });
                }
                let now = SystemTime::now();
                let output = inner
                    .paste_buffers
                    .iter()
                    .map(|buffer| {
                        let age = now
                            .duration_since(buffer.created)
                            .unwrap_or_default()
                            .as_secs();
                        format!(
                            "{}: {} bytes: \"{}\" ({}s ago)",
                            buffer.name,
                            buffer.data.len(),
                            bounded_buffer_sample(&buffer.data, MAX_PASTE_BUFFER_SAMPLE_BYTES),
                            age
                        )
                    })
                    .collect::<Vec<_>>()
                    .join("\n");
                Ok(Execution {
                    output,
                    effects: Vec::new(),
                })
            }
            "load-buffer" | "loadb" => {
                let parsed = parse_buffer_command_args(name, args, &['b'], &[])?;
                let path = require_one_positional(name, &parsed)?;
                if path == "-" {
                    return Err(ServerError::UnsupportedCommand(
                        "load-buffer from standard input".to_owned(),
                    )
                    .into());
                }
                let path = expand_path(path);
                let data = read_paste_buffer_file(&path)?;
                if data.is_empty() {
                    return Ok(Execution::default());
                }
                if let Some(name) = parsed.value('b') {
                    validate_paste_buffer_name(name)?;
                }
                let mut inner = self.inner.lock();
                let events =
                    insert_paste_buffer(&mut inner, parsed.value('b'), "buffer", data, true)?;
                drop(inner);
                if !context.no_hooks {
                    self.run_event_hooks(events);
                }
                self.refresh_choose_buffers();
                Ok(Execution::default())
            }
            "save-buffer" | "saveb" => {
                let parsed = parse_buffer_command_args(name, args, &['b'], &['a'])?;
                let path = require_one_positional(name, &parsed)?;
                if path == "-" {
                    return Err(ServerError::UnsupportedCommand(
                        "save-buffer to standard output".to_owned(),
                    )
                    .into());
                }
                let data = {
                    let inner = self.inner.lock();
                    Arc::clone(&resolve_buffer(&inner, parsed.value('b'))?.data)
                };
                write_paste_buffer_file(&expand_path(path), &data, parsed.has('a'))?;
                Ok(Execution::default())
            }
            "delete-buffer" | "deleteb" => {
                let parsed = parse_buffer_command_args(name, args, &['b'], &[])?;
                require_no_positionals(name, &parsed)?;
                let mut inner = self.inner.lock();
                let name = resolve_buffer(&inner, parsed.value('b'))?.name.clone();
                inner.paste_buffers.retain(|buffer| buffer.name != name);
                drop(inner);
                if !context.no_hooks {
                    self.run_event_hooks(vec![PendingHookEvent::paste_buffer(
                        "paste-buffer-deleted",
                        name,
                    )]);
                }
                self.refresh_choose_buffers();
                Ok(Execution::default())
            }
            "paste-buffer" | "pasteb" => {
                let parsed =
                    parse_buffer_command_args(name, args, &['b', 's', 't'], &['d', 'p', 'r', 'S'])?;
                require_no_positionals(name, &parsed)?;
                let pane = self.inner.lock().engine.resolve_pane(
                    parsed.value('t'),
                    context.window,
                    context.pane,
                )?;
                let separator = parsed.value('s').map_or_else(
                    || {
                        if parsed.has('r') {
                            b"\n".as_slice()
                        } else {
                            b"\r".as_slice()
                        }
                    },
                    str::as_bytes,
                );
                self.paste_buffer_to_pane(
                    pane,
                    PasteBufferPaste {
                        requested_name: parsed.value('b'),
                        delete: parsed.has('d'),
                        bracketed: parsed.has('p'),
                        separator,
                        literal: parsed.has('S'),
                        expected_client: None,
                        event_hooks_enabled: !context.no_hooks,
                    },
                )?;
                Ok(Execution::default())
            }
            _ => Err(ServerError::UnsupportedCommand(name.to_owned()).into()),
        }
    }

    fn paste_buffer_to_pane(
        self: &Arc<Self>,
        pane: PaneId,
        request: PasteBufferPaste<'_>,
    ) -> Result<(), DaemonError> {
        let PasteBufferPaste {
            requested_name,
            delete,
            bracketed,
            separator,
            literal,
            expected_client,
            event_hooks_enabled,
        } = request;
        let (client, sinks, buffer_name, data) = {
            let inner = self.inner.lock();
            let Some(buffer) = find_buffer(&inner, requested_name) else {
                if let Some(name) = requested_name {
                    return Err(ServerError::MissingTarget(name.to_owned()).into());
                }
                return Ok(());
            };
            let data = Arc::clone(&buffer.data);
            let buffer_name = buffer.name.clone();
            if expected_client
                .is_some_and(|expected| !client_is_attached_to_pane(&inner, expected, pane))
            {
                return Err(ServerError::PaneNotAttached(pane).into());
            }
            let sinks = resolve_input_sinks(&inner, pane)?;
            (expected_client, sinks, buffer_name, data)
        };
        let mut prepared = prepare_paste_buffer(&data, separator, literal)
            .map_err(|error| ServerError::InvalidCommand(error.to_string()))?;
        let has_terminal = sinks
            .iter()
            .any(|sink| matches!(sink, PaneSink::Terminal(_)));
        let browser_text = sinks
            .iter()
            .any(|sink| matches!(sink, PaneSink::Browser(_)))
            .then(|| {
                let bytes = if has_terminal {
                    prepared.clone()
                } else {
                    std::mem::take(&mut prepared)
                };
                String::from_utf8(bytes)
            })
            .transpose()
            .map_err(|_| {
                ServerError::InvalidCommand(format!(
                    "buffer {buffer_name} is not valid UTF-8 for a browser pane"
                ))
            })?;
        let prepared = has_terminal.then(|| Arc::<[u8]>::from(prepared));
        for sink in sinks {
            match sink {
                PaneSink::Terminal(terminal) => {
                    terminal.paste_prepared_bytes(
                        client.map(|client| TerminalViewId(client.0)),
                        Arc::clone(
                            prepared
                                .as_ref()
                                .expect("terminal paste retains prepared bytes"),
                        ),
                        bracketed,
                    );
                }
                PaneSink::Browser(target) => self.publish_for_pane(
                    target,
                    &EventPayload::BrowserCommand {
                        pane: target,
                        command: BrowserCommand::SendKeys(vec![zz_protocol::KeyToken::Literal(
                            browser_text
                                .as_ref()
                                .expect("browser text is validated before dispatch")
                                .clone(),
                        )]),
                    },
                ),
            }
        }
        let removed = delete && {
            let mut inner = self.inner.lock();
            let before = inner.paste_buffers.len();
            inner
                .paste_buffers
                .retain(|buffer| buffer.name != buffer_name || !Arc::ptr_eq(&buffer.data, &data));
            inner.paste_buffers.len() != before
        };
        if removed {
            if event_hooks_enabled {
                self.run_event_hooks(vec![PendingHookEvent::paste_buffer(
                    "paste-buffer-deleted",
                    buffer_name,
                )]);
            }
            self.refresh_choose_buffers();
        }
        Ok(())
    }

    fn attach(
        self: &Arc<Self>,
        client: ClientId,
        session: SessionId,
    ) -> Result<MuxSnapshot, ServerError> {
        self.attach_with_event_hooks(client, session, true)
    }

    fn attach_with_event_hooks(
        self: &Arc<Self>,
        client: ClientId,
        session: SessionId,
        event_hooks_enabled: bool,
    ) -> Result<MuxSnapshot, ServerError> {
        let (snapshot, events) =
            self.attach_collect_event_hooks(client, session, event_hooks_enabled)?;
        self.run_event_hooks(events);
        Ok(snapshot)
    }

    fn attach_collect_event_hooks(
        self: &Arc<Self>,
        client: ClientId,
        session: SessionId,
        event_hooks_enabled: bool,
    ) -> Result<(MuxSnapshot, Vec<PendingHookEvent>), ServerError> {
        let mut inner = self.inner.lock();
        if !inner.engine.state.sessions.contains_key(&session) {
            return Err(ServerError::MissingTarget(session.to_string()));
        }
        let hook_state_before = event_hooks_enabled.then(|| {
            (
                MuxHookSnapshot::capture(&inner.engine),
                inner
                    .copy_sessions
                    .values()
                    .map(|session| session.pane)
                    .collect::<BTreeSet<_>>(),
            )
        });
        let previous_session = client_attached_session(&inner, client);
        let client_name = inner.client_names.get(&client).cloned();
        let previous_sessions = inner
            .attached
            .iter()
            .filter_map(|(attached_session, clients)| {
                (clients.contains(&client) && *attached_session != session)
                    .then_some(*attached_session)
            })
            .collect::<Vec<_>>();
        let switches_session = !previous_sessions.is_empty();
        let previous = previous_sessions
            .iter()
            .flat_map(|attached_session| session_terminals(&inner, *attached_session))
            .collect::<Vec<_>>();
        let command_output = switches_session
            .then(|| take_command_output(&mut inner, client))
            .flatten();
        let choose_tree_closed = switches_session && inner.choose_trees.remove(&client).is_some();
        let choose_buffer_closed =
            switches_session && inner.choose_buffers.remove(&client).is_some();
        let display_panes_closed =
            switches_session && take_display_panes(&mut inner, client).is_some();
        let mut affected_panes = inner
            .visible_terminals
            .get(&client)
            .cloned()
            .unwrap_or_default();
        affected_panes.extend(control_client_sized_panes(&inner, client));
        if switches_session {
            affected_panes.extend(remove_client_terminal_geometries(&mut inner, client));
            inner.focused_windows.remove(&client);
        }
        for (attached_session, clients) in &mut inner.attached {
            if *attached_session != session {
                clients.remove(&client);
            }
        }
        inner.attached.retain(|_, clients| !clients.is_empty());
        inner.attached.entry(session).or_default().insert(client);
        if let Some(output) = inner.control_outputs.get_mut(&client) {
            for pane in output.panes.values_mut() {
                pane.pending.clear();
            }
        }
        inner.engine.mark_session_active(session);
        let visible = visible_terminal_panes(&inner, client, session);
        affected_panes.extend(visible.iter().copied());
        inner.visible_terminals.insert(client, visible);
        affected_panes.extend(control_client_sized_panes(&inner, client));
        #[cfg(feature = "agent")]
        {
            let visible = visible_agent_panes(&inner, client, session);
            inner.visible_agents.insert(client, visible);
        }
        let terminals = session_terminals(&inner, session);
        let unfocused_copy_mode_exits = unfocused_copy_sessions(&mut inner);
        write_back_terminal_geometries(&mut inner, &affected_panes, true);
        let resizes = terminal_resizes_for_panes(&inner, &affected_panes);
        let mut snapshot = inner.engine.state.snapshot();
        let presence = snapshot_presence(&inner);
        stamp_snapshot_for_client(&inner, client, &mut snapshot, &presence);
        let mut hook_events = Vec::new();
        if let Some((hook_snapshot_before, copy_modes_before)) = hook_state_before.as_ref() {
            let hook_snapshot_after = MuxHookSnapshot::capture(&inner.engine);
            hook_events.extend(mux_hook_events(
                hook_snapshot_before,
                &hook_snapshot_after,
                "",
            ));
            let copy_modes_after = inner
                .copy_sessions
                .values()
                .map(|session| session.pane)
                .collect::<BTreeSet<_>>();
            hook_events.extend(pane_mode_hook_events(
                hook_snapshot_before,
                &hook_snapshot_after,
                copy_modes_before,
                &copy_modes_after,
            ));
            if previous_session != Some(session) {
                let context = hook_snapshot_after.session_context(session);
                hook_events.push(PendingHookEvent::client(
                    "client-session-changed",
                    context.clone(),
                    client,
                    client_name.as_deref(),
                    &hook_snapshot_after,
                ));
                if previous_session.is_none() {
                    hook_events.push(PendingHookEvent::client(
                        "client-attached",
                        context,
                        client,
                        client_name.as_deref(),
                        &hook_snapshot_after,
                    ));
                }
            }
        }
        drop(inner);
        if let Some(output) = command_output {
            Self::retire_command_output(client, output);
        }
        if choose_tree_closed {
            self.publish_to_client(client, EventPayload::ChooseTree { state: None });
        }
        if choose_buffer_closed {
            self.publish_to_client(client, EventPayload::ChooseBuffer { state: None });
        }
        if display_panes_closed {
            self.publish_to_client(client, EventPayload::DisplayPanes { state: None });
        }
        let view = TerminalViewId(client.0);
        for (frozen_client, terminal) in unfocused_copy_mode_exits {
            terminal.view_action(
                TerminalViewId(frozen_client.0),
                zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel),
            );
        }
        for terminal in previous {
            terminal.detach_view(view);
        }
        for terminal in terminals {
            terminal.attach_view(view);
        }
        apply_terminal_resizes(resizes);
        self.refresh_control_output_taps();
        Ok((snapshot, hook_events))
    }

    fn attach_target(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        target: &str,
    ) -> Result<(SessionId, MuxSnapshot), ServerError> {
        if matches!(kind, ClientKind::Interactive | ClientKind::Control)
            && target.is_empty()
            && self.inner.lock().engine.state.sessions.is_empty()
        {
            let execution = self
                .execute(
                    client,
                    ClientKind::Command,
                    context,
                    &CommandInvocation::new("new-session", ["-A", "-d"]),
                )
                .map_err(daemon_server_error)?;
            if !execution.output.is_empty() {
                self.open_command_output(
                    client,
                    context.pane,
                    "new-session".to_owned(),
                    &execution.output,
                )
                .map_err(daemon_server_error)?;
            }
        }
        let session = {
            let inner = self.inner.lock();
            inner.engine.state.resolve_session(
                (!target.is_empty()).then_some(target),
                inner
                    .engine
                    .state
                    .default_context()
                    .map(|context| context.0),
            )?
        };
        let (window, pane) = {
            let inner = self.inner.lock();
            let session_state = inner
                .engine
                .state
                .sessions
                .get(&session)
                .ok_or_else(|| ServerError::MissingTarget(session.to_string()))?;
            let window = session_state.active_window;
            let pane = inner.engine.state.windows[&window].active_pane;
            (window, pane)
        };
        context.retarget(&ExecutionContext::new(
            Some(session),
            Some(window),
            Some(pane),
        ));
        let snapshot = self.attach(client, session)?;
        Ok((session, snapshot))
    }

    fn detach(self: &Arc<Self>, client: ClientId) {
        self.detach_with_event_hooks(client, true);
    }

    fn detach_with_event_hooks(self: &Arc<Self>, client: ClientId, event_hooks_enabled: bool) {
        let (detached, events) = self.detach_client_state(client, event_hooks_enabled);
        if detached {
            self.publish_snapshot();
        }
        self.refresh_control_output_taps();
        self.run_event_hooks(events);
    }

    /// Detach every attached client but `stealer`, either across the server or
    /// on one session.
    fn evict_clients_with_event_hooks(
        self: &Arc<Self>,
        session: Option<SessionId>,
        stealer: ClientId,
        event_hooks_enabled: bool,
    ) {
        let (victims, by) = {
            let inner = self.inner.lock();
            let victims = inner
                .attached
                .iter()
                .filter(|(attached, _)| session.is_none_or(|wanted| wanted == **attached))
                .flat_map(|(attached, clients)| {
                    clients.iter().map(move |client| (*attached, *client))
                })
                .filter(|(_, victim)| *victim != stealer)
                .collect::<Vec<_>>();
            let by = inner
                .client_names
                .get(&stealer)
                .cloned()
                .unwrap_or_else(|| format!("device-{}", stealer.0));
            (victims, by)
        };
        let evicted = !victims.is_empty();
        for (session, victim) in victims {
            self.publish_to_client(
                victim,
                EventPayload::Detached {
                    session,
                    by: Some(by.clone()),
                },
            );
            self.detach_with_event_hooks(victim, event_hooks_enabled);
        }
        if evicted {
            self.publish_snapshot();
        }
    }

    fn detach_client_state(
        &self,
        client: ClientId,
        event_hooks_enabled: bool,
    ) -> (bool, Vec<PendingHookEvent>) {
        let mut inner = self.inner.lock();
        let sessions = inner
            .attached
            .iter()
            .filter_map(|(session, clients)| clients.contains(&client).then_some(*session))
            .collect::<Vec<_>>();
        let was_attached = !sessions.is_empty();
        let hook_state_before = event_hooks_enabled.then(|| {
            (
                MuxHookSnapshot::capture(&inner.engine),
                inner
                    .copy_sessions
                    .values()
                    .map(|session| session.pane)
                    .collect::<BTreeSet<_>>(),
            )
        });
        let client_name = inner.client_names.get(&client).cloned();
        let terminals = sessions
            .iter()
            .flat_map(|session| session_terminals(&inner, *session))
            .collect::<Vec<_>>();
        let mut affected_panes = inner
            .visible_terminals
            .get(&client)
            .cloned()
            .unwrap_or_default();
        affected_panes.extend(control_client_sized_panes(&inner, client));
        affected_panes.extend(remove_client_terminal_geometries(&mut inner, client));
        for clients in inner.attached.values_mut() {
            clients.remove(&client);
        }
        inner.attached.retain(|_, clients| !clients.is_empty());
        if let Some(output) = inner.control_outputs.get_mut(&client) {
            for pane in output.panes.values_mut() {
                pane.pending.clear();
            }
        }
        inner.visible_terminals.remove(&client);
        inner.visible_agents.remove(&client);
        inner.focused_windows.remove(&client);
        inner.client_terminal_input_sequences.remove(&client);
        inner.key_engines.remove(&client);
        let copy_session = inner
            .copy_sessions
            .remove(&client)
            .and_then(|session| inner.terminals.get(&session.pane).cloned());
        let prefix_was_armed = inner.prefix_armed.remove(&client);
        inner.swallowed_keys.remove(&client);
        inner.suppressed_text.remove(&client);
        inner.command_prompts.remove(&client);
        inner.choose_trees.remove(&client);
        inner.choose_buffers.remove(&client);
        let _ = take_display_panes(&mut inner, client);
        let command_output = take_command_output(&mut inner, client);
        let popup = take_popup(&mut inner, client);
        let menu = inner.menus.remove(&client);
        let confirm = inner.confirms.remove(&client);
        write_back_terminal_geometries(&mut inner, &affected_panes, true);
        let resizes = terminal_resizes_for_panes(&inner, &affected_panes);
        let mut events = Vec::new();
        if let Some((hook_snapshot_before, copy_modes_before)) = hook_state_before.as_ref() {
            let hook_snapshot_after = MuxHookSnapshot::capture(&inner.engine);
            events.extend(mux_hook_events(
                hook_snapshot_before,
                &hook_snapshot_after,
                "",
            ));
            let copy_modes_after = inner
                .copy_sessions
                .values()
                .map(|session| session.pane)
                .collect::<BTreeSet<_>>();
            events.extend(pane_mode_hook_events(
                hook_snapshot_before,
                &hook_snapshot_after,
                copy_modes_before,
                &copy_modes_after,
            ));
            if let Some(session) = sessions.first() {
                events.push(PendingHookEvent::client(
                    "client-detached",
                    hook_snapshot_before.session_context(*session),
                    client,
                    client_name.as_deref(),
                    hook_snapshot_before,
                ));
            }
        }
        drop(inner);
        self.fail_gui_requests_for(client);
        let view = TerminalViewId(client.0);
        if let Some(command_output) = command_output {
            Self::retire_command_output(client, command_output);
        }
        if let Some(popup) = popup {
            Self::retire_popup(client, popup, true);
        }
        if let Some(menu) = menu {
            if let Some(waiter) = menu.waiter {
                let _ = waiter.wake.try_send(());
            }
            self.publish_to_client(client, EventPayload::Menu { state: None });
        }
        if let Some(confirm) = confirm {
            if let ConfirmExecution::Blocking { wake, .. } = confirm.execution {
                let _ = wake.try_send(false);
            }
            self.publish_to_client(client, EventPayload::Confirm { state: None });
        }
        if let Some(terminal) = copy_session {
            terminal.view_action(
                view,
                zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel),
            );
        }
        for terminal in terminals {
            terminal.detach_view(view);
        }
        apply_terminal_resizes(resizes);
        if prefix_was_armed {
            self.publish_to_client(client, EventPayload::PrefixArmed { armed: false });
        }
        (was_attached, events)
    }

    fn input(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        input: InputMessage,
    ) -> Result<(), DaemonError> {
        let started = diagnostic_timer();
        log::trace!(
            target: "zz_daemon::diagnostics::input",
            "dispatch begin client={client} kind={kind:?} context={context:#?} input={input:#?}"
        );
        let generation = self.inner.lock().engine.state.generation();
        let resize_split = matches!(&input, InputMessage::ResizeSplit { .. });
        let copy_mode_change = matches!(
            &input,
            InputMessage::TerminalView { action, .. }
                if terminal_view_action_enters_copy_mode(action)
                    || terminal_view_action_exits_copy_mode(action)
        );
        let hook_state_before = (!context.no_hooks
            && (matches!(
                &input,
                InputMessage::ResizeTerminal { .. } | InputMessage::ResizeSplit { .. }
            ) || copy_mode_change))
            .then(|| {
                let inner = self.inner.lock();
                let copy_modes = copy_mode_change.then(|| {
                    inner
                        .copy_sessions
                        .values()
                        .map(|session| session.pane)
                        .collect::<BTreeSet<_>>()
                });
                (MuxHookSnapshot::capture(&inner.engine), copy_modes)
            });
        let result = (|| -> Result<(), DaemonError> {
            match input {
                InputMessage::Text { pane, text } => {
                    self.reject_unattached_input(client, pane)?;
                    self.note_terminal_input(client, pane);
                    self.input_text(client, kind, context, pane, &text)?;
                }
                InputMessage::Key {
                    pane,
                    input,
                    text_follows,
                } => {
                    self.reject_unattached_input(client, pane)?;
                    self.note_terminal_input(client, pane);
                    self.input_key(client, kind, context, pane, input, text_follows)?;
                }
                InputMessage::BrowserSurfaceText { pane, text } => {
                    self.reject_invalid_browser_surface_input(client, pane)?;
                    self.note_terminal_input(client, pane);
                    self.input_browser_surface_text(client, pane, &text)?;
                }
                InputMessage::BrowserSurfaceKey {
                    pane,
                    input,
                    text_follows,
                } => {
                    self.reject_invalid_browser_surface_input(client, pane)?;
                    self.note_terminal_input(client, pane);
                    self.input_browser_surface_key(
                        client,
                        kind,
                        context,
                        pane,
                        input,
                        text_follows,
                    )?;
                }
                InputMessage::ResizeTerminal {
                    pane,
                    columns,
                    rows,
                    cell_width_px,
                    cell_height_px,
                } => {
                    let resize = {
                        let mut inner = self.inner.lock();
                        if !inner.terminals.contains_key(&pane) {
                            return Err(ServerError::PaneExited(pane).into());
                        }
                        if !client_is_attached_to_pane(&inner, client, pane) {
                            return Err(ServerError::PaneNotAttached(pane).into());
                        }
                        inner.terminal_geometries.entry(pane).or_default().insert(
                            client,
                            TerminalGeometry {
                                columns,
                                rows,
                                cell_width_px,
                                cell_height_px,
                            },
                        );
                        let resize = terminal_resize_for_pane(&inner, pane);
                        if let Some((_, geometry)) = &resize {
                            inner
                                .engine
                                .set_pane_geometry(pane, geometry.columns, geometry.rows);
                        }
                        resize
                    };
                    if let Some((terminal, geometry)) = resize {
                        terminal.resize(
                            geometry.columns,
                            geometry.rows,
                            geometry.cell_width_px,
                            geometry.cell_height_px,
                        );
                    }
                }
                InputMessage::TerminalView {
                    pane,
                    action: zz_terminal::TerminalViewAction::Paste(text),
                } => {
                    let modal_active = {
                        let inner = self.inner.lock();
                        inner.choose_trees.contains_key(&client)
                            || inner.choose_buffers.contains_key(&client)
                            || inner.display_panes.contains_key(&client)
                    };
                    if !modal_active {
                        self.note_terminal_input(client, pane);
                        self.input_paste(client, pane, &text)?;
                    }
                }
                InputMessage::TerminalView { pane, action } => {
                    let terminal = {
                        let inner = self.inner.lock();
                        if inner.choose_trees.contains_key(&client)
                            || inner.choose_buffers.contains_key(&client)
                            || inner.display_panes.contains_key(&client)
                        {
                            None
                        } else {
                            if !client_is_attached_to_pane(&inner, client, pane) {
                                return Err(ServerError::PaneNotAttached(pane).into());
                            }
                            if matches!(action, zz_terminal::TerminalViewAction::Focus(_))
                                && !inner.engine.focus_events()
                            {
                                None
                            } else {
                                Some(
                                    inner
                                        .terminals
                                        .get(&pane)
                                        .cloned()
                                        .ok_or(ServerError::PaneExited(pane))?,
                                )
                            }
                        }
                    };
                    if let Some(terminal) = terminal {
                        if terminal_view_action_is_input(&action) {
                            self.note_terminal_input(client, pane);
                        }
                        sync_copy_session_for_view_action(
                            &mut self.inner.lock(),
                            client,
                            pane,
                            &action,
                        )?;
                        terminal.view_action(TerminalViewId(client.0), action);
                    }
                }
                InputMessage::ResizeCommandOutput {
                    columns,
                    rows,
                    cell_width_px,
                    cell_height_px,
                } => {
                    let terminal = self
                        .inner
                        .lock()
                        .command_outputs
                        .get(&client)
                        .map(|output| Arc::clone(&output.terminal));
                    if let Some(terminal) = terminal {
                        terminal.resize(columns, rows, cell_width_px, cell_height_px);
                    }
                }
                InputMessage::CommandOutputView { action } => {
                    let terminal = self
                        .inner
                        .lock()
                        .command_outputs
                        .get(&client)
                        .map(|output| Arc::clone(&output.terminal));
                    if let Some(terminal) = terminal {
                        terminal.view_action(TerminalViewId(client.0), action);
                    }
                }
                InputMessage::ChooseTree { action } => {
                    self.input_choose_tree(client, kind, context, action)?;
                }
                InputMessage::ChooseBuffer { action } => {
                    self.input_choose_buffer(client, kind, action)?;
                }
                InputMessage::DisplayPanes { action } => {
                    self.input_display_panes(client, kind, context, action)?;
                }
                InputMessage::CommandPrompt { action } => {
                    self.input_command_prompt_action(client, kind, context, action)?;
                }
                InputMessage::ResizeSplit {
                    window,
                    split,
                    ratio_basis_points,
                } => {
                    self.input_resize_split(client, kind, window, split, ratio_basis_points)?;
                }
                InputMessage::CancelPrefix { request_id } => {
                    self.cancel_prefix(client, request_id);
                }
                InputMessage::Popup { action } => {
                    self.input_popup(client, action);
                }
                InputMessage::Menu { action } => {
                    self.input_menu(client, context, action);
                }
                InputMessage::Confirm { action } => {
                    self.input_confirm(client, context, action);
                }
            }
            Ok(())
        })();
        let publish_snapshot = {
            let inner = self.inner.lock();
            let current = inner.engine.state.generation();
            resize_split && result.is_ok()
                || current != generation && inner.last_published_mux_generation != current
        };
        if publish_snapshot {
            self.publish_snapshot();
        }
        if result.is_ok()
            && let Some((before, copy_modes_before)) = hook_state_before.as_ref()
        {
            let (after, copy_modes_after) = {
                let inner = self.inner.lock();
                let copy_modes = copy_modes_before.as_ref().map(|_| {
                    inner
                        .copy_sessions
                        .values()
                        .map(|session| session.pane)
                        .collect::<BTreeSet<_>>()
                });
                (MuxHookSnapshot::capture(&inner.engine), copy_modes)
            };
            let mut events = mux_hook_events(before, &after, "");
            if let (Some(copy_modes_before), Some(copy_modes_after)) =
                (copy_modes_before, copy_modes_after)
            {
                events.extend(pane_mode_hook_events(
                    before,
                    &after,
                    copy_modes_before,
                    &copy_modes_after,
                ));
            }
            self.run_event_hooks(events);
        }
        log::trace!(
            target: "zz_daemon::diagnostics::input",
            "dispatch end client={client} success={} elapsed_us={} context={context:#?}",
            result.is_ok(),
            diagnostic_elapsed_us(started),
        );
        result
    }

    fn input_popup(&self, client: ClientId, action: PopupAction) {
        let (terminal, state) = {
            let inner = self.inner.lock();
            let Some(popup) = inner.popups.get(&client) else {
                return;
            };
            (Arc::clone(&popup.terminal), popup.state.clone())
        };
        let dead = state.dead || terminal.completion().is_some();
        let close = match &action {
            PopupAction::Close => true,
            PopupAction::Key { input, .. }
                if !matches!(input.action, zz_terminal::KeyAction::Release) =>
            {
                let escape = input.key == zz_terminal::KeyCode::Escape;
                let control_c =
                    input.key == zz_terminal::KeyCode::Character('c') && input.modifiers.control();
                dead && state.close_on_any_key
                    || (escape || control_c)
                        && (dead || !state.close_on_exit && !state.close_on_exit_zero)
            }
            _ => false,
        };
        if close {
            self.close_popup(client, true);
            return;
        }
        match action {
            PopupAction::Text(text) => {
                terminal.send_text_for_view(TerminalViewId(client.0), text);
            }
            PopupAction::Key {
                input,
                text_follows,
            } => {
                if !text_follows {
                    terminal.send_key_for_view(TerminalViewId(client.0), input);
                }
            }
            PopupAction::TerminalView(action) => {
                terminal.view_action(TerminalViewId(client.0), action);
            }
            PopupAction::Close => {}
        }
    }

    fn input_menu(
        self: &Arc<Self>,
        client: ClientId,
        context: &ExecutionContext,
        action: MenuAction,
    ) {
        let session = {
            let mut inner = self.inner.lock();
            let Some(menu) = inner.menus.get(&client) else {
                return;
            };
            if let MenuAction::Choose(index) = action {
                let selectable = usize::try_from(index)
                    .ok()
                    .and_then(|index| menu.state.items.get(index))
                    .and_then(Option::as_ref)
                    .is_some_and(|item| item.enabled);
                if !selectable && menu.state.stay_open {
                    return;
                }
            }
            inner.menus.remove(&client).expect("menu was present")
        };
        self.publish_to_client(client, EventPayload::Menu { state: None });
        if let Some(waiter) = session.waiter {
            let _ = waiter.wake.try_send(());
        }
        let MenuAction::Choose(index) = action else {
            return;
        };
        let Some(command) = usize::try_from(index)
            .ok()
            .and_then(|index| session.commands.get(index))
            .and_then(Option::as_ref)
        else {
            return;
        };
        if !session
            .state
            .items
            .get(usize::try_from(index).unwrap_or(usize::MAX))
            .and_then(Option::as_ref)
            .is_some_and(|item| item.enabled)
        {
            return;
        }
        let mut target = session.target;
        let target_alive = target
            .pane
            .is_some_and(|pane| self.inner.lock().engine.state.pane(pane).is_some());
        if !target_alive {
            target = context.clone();
        }
        self.execute_overlay_source(client, &mut target, command, "display-menu");
    }

    fn input_confirm(
        self: &Arc<Self>,
        client: ClientId,
        context: &ExecutionContext,
        action: ConfirmAction,
    ) {
        let Some(session) = self.inner.lock().confirms.remove(&client) else {
            return;
        };
        self.publish_to_client(client, EventPayload::Confirm { state: None });
        let ConfirmAction::Reply(accepted) = action;
        match session.execution {
            ConfirmExecution::Blocking { wake, .. } => {
                let _ = wake.try_send(accepted);
            }
            ConfirmExecution::Deferred {
                commands,
                mut context,
            } if accepted => {
                self.inner.lock().engine.repair_context(&mut context);
                self.execute_overlay_commands(
                    client,
                    ClientKind::Interactive,
                    &mut context,
                    commands,
                    "confirm-before",
                );
            }
            ConfirmExecution::Background { commands } if accepted => {
                let mut target = {
                    let inner = self.inner.lock();
                    client_context_pane(&inner, client)
                        .and_then(|pane| ExecutionContext::for_pane(&inner.engine.state, pane))
                        .unwrap_or_else(|| context.clone())
                };
                self.execute_overlay_commands(
                    client,
                    ClientKind::Interactive,
                    &mut target,
                    commands,
                    "confirm-before",
                );
            }
            ConfirmExecution::Deferred { .. } | ConfirmExecution::Background { .. } => {}
        }
    }

    fn execute_overlay_source(
        self: &Arc<Self>,
        client: ClientId,
        context: &mut ExecutionContext,
        command: &str,
        title: &str,
    ) {
        let source = inserted_command_source(command);
        match self.execute_inserted_commands(
            client,
            ClientKind::Interactive,
            context,
            &source,
            &format!("<{title}>"),
        ) {
            Ok(result) => self.route_background_inserted_output(
                client,
                ClientKind::Interactive,
                context,
                title.to_owned(),
                &result.output,
            ),
            Err(error) => self.publish_background_command_error(client, context, &error, false),
        }
    }

    fn execute_overlay_commands(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        commands: Vec<CommandInvocation>,
        title: &str,
    ) {
        let mut output = String::new();
        for command in commands {
            match self.execute(client, kind, context, &command) {
                Ok(execution) => append_inserted_output(&mut output, &execution.output),
                Err(error) => {
                    if let Some(error_output) = daemon_error_output(&error) {
                        append_inserted_output(&mut output, error_output);
                    }
                    self.route_background_inserted_output(
                        client,
                        kind,
                        context,
                        title.to_owned(),
                        &output,
                    );
                    self.publish_background_command_error(client, context, &error, false);
                    return;
                }
            }
        }
        self.route_background_inserted_output(client, kind, context, title.to_owned(), &output);
    }

    fn reject_unattached_input(&self, client: ClientId, pane: PaneId) -> Result<(), ServerError> {
        if client_attached_session(&self.inner.lock(), client).is_some() {
            Ok(())
        } else {
            Err(ServerError::PaneNotAttached(pane))
        }
    }

    fn reject_invalid_browser_surface_input(
        &self,
        client: ClientId,
        pane: PaneId,
    ) -> Result<(), ServerError> {
        let inner = self.inner.lock();
        if !client_is_attached_to_pane(&inner, client, pane) {
            return Err(ServerError::PaneNotAttached(pane));
        }
        match inner.engine.state.pane(pane).map(|pane| &pane.kind) {
            Some(PaneKind::Browser(_)) => Ok(()),
            Some(_) => Err(ServerError::InvalidTarget(format!(
                "{pane} is not a browser pane"
            ))),
            None => Err(ServerError::PaneExited(pane)),
        }
    }

    fn note_terminal_input(&self, client: ClientId, pane: PaneId) {
        let resizes = {
            let mut inner = self.inner.lock();
            let session = client_is_attached_to_pane(&inner, client, pane)
                .then(|| inner.engine.state.window_for_pane(pane))
                .flatten()
                .and_then(|window| inner.engine.state.windows.get(&window))
                .map(|window| window.session);
            if let Some(session) = session {
                inner.engine.mark_session_active(session);
            }
            terminal_resizes_after_client_input(&mut inner, client, pane)
        };
        apply_terminal_resizes(resizes);
        if self.clear_pane_bell(pane) {
            self.publish_snapshot();
        }
    }

    fn input_resize_split(
        &self,
        client: ClientId,
        kind: ClientKind,
        window: WindowId,
        split: SplitId,
        ratio_basis_points: u16,
    ) -> Result<(), DaemonError> {
        if kind != ClientKind::Interactive {
            return Err(ServerError::InvalidCommand(
                "split dragging requires an interactive client".to_owned(),
            )
            .into());
        }
        if ratio_basis_points > SPLIT_RATIO_BASIS {
            return Err(ServerError::InvalidCommand(format!(
                "split ratio must be between 0 and {SPLIT_RATIO_BASIS}"
            ))
            .into());
        }
        {
            let mut inner = self.inner.lock();
            if !inner.subscribers.contains_key(&client) {
                return Err(ServerError::InvalidCommand(
                    "split dragging requires a subscribed client".to_owned(),
                )
                .into());
            }
            let attached = client_attached_session(&inner, client).ok_or_else(|| {
                ServerError::InvalidTarget("client is not attached to a session".to_owned())
            })?;
            let active_window = inner
                .engine
                .state
                .sessions
                .get(&attached)
                .map(|session| client_focused_window(&inner, client, session))
                .ok_or_else(|| {
                    ServerError::InvalidTarget("attached session no longer exists".to_owned())
                })?;
            let target = inner
                .engine
                .state
                .windows
                .get(&window)
                .ok_or_else(|| ServerError::MissingTarget(window.to_string()))?;
            if target.session != attached || active_window != window {
                return Err(ServerError::InvalidTarget(format!(
                    "window {window} is not active for the attached client"
                ))
                .into());
            }
            if target.zoomed_pane.is_some() {
                return Err(ServerError::InvalidCommand(
                    "cannot drag a split while its window is zoomed".to_owned(),
                )
                .into());
            }
            if !target.layout.project().contains_split(split) {
                return Err(ServerError::MissingTarget(split.to_string()).into());
            }
            inner.engine.state.resize_split(
                window,
                split,
                f32::from(ratio_basis_points) / f32::from(SPLIT_RATIO_BASIS),
            )?;
        }
        Ok(())
    }

    fn input_text(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        pane: PaneId,
        text: &str,
    ) -> Result<(), DaemonError> {
        let filtered_text = self.filter_suppressed_text(client, text);
        let text = filtered_text.as_ref();
        {
            let inner = self.inner.lock();
            if inner.choose_trees.contains_key(&client)
                || inner.choose_buffers.contains_key(&client)
                || inner.display_panes.contains_key(&client)
            {
                return Ok(());
            }
        }
        if text.is_empty() || self.input_command_prompt_text(client, text) {
            return Ok(());
        }
        let command_output_active = self.inner.lock().command_outputs.contains_key(&client);
        let mut sinks = None;
        let mut pass_start = None;
        for (offset, character) in text.char_indices() {
            let mut encoded = [0_u8; 4];
            let decision = self.key_decision(client, character.encode_utf8(&mut encoded), false);
            match decision {
                KeyDecision::Pass => {
                    if command_output_active
                        || self.inner.lock().command_outputs.contains_key(&client)
                    {
                        if let Some(start) = pass_start.take() {
                            self.dispatch_input_text(
                                client,
                                pane,
                                &mut sinks,
                                &text[start..offset],
                            )?;
                        }
                        continue;
                    }
                    if pass_start.is_none() {
                        pass_start = Some(offset);
                    }
                }
                KeyDecision::Prefix | KeyDecision::Ignore => {
                    if let Some(start) = pass_start.take() {
                        self.dispatch_input_text(client, pane, &mut sinks, &text[start..offset])?;
                    }
                }
                KeyDecision::Commands(commands) => {
                    if let Some(start) = pass_start.take() {
                        self.dispatch_input_text(client, pane, &mut sinks, &text[start..offset])?;
                    }
                    self.execute_key_commands(client, kind, context, pane, &commands)?;
                    sinks = None;
                    if self.inner.lock().command_prompts.contains_key(&client) {
                        let remaining = &text[offset + character.len_utf8()..];
                        if !remaining.is_empty() {
                            self.input_command_prompt_text(client, remaining);
                        }
                        break;
                    }
                }
            }
        }
        if let Some(start) = pass_start {
            self.dispatch_input_text(client, pane, &mut sinks, &text[start..])?;
        }
        self.sync_prefix_armed(client);
        Ok(())
    }

    fn input_browser_surface_text(
        &self,
        client: ClientId,
        pane: PaneId,
        text: &str,
    ) -> Result<(), DaemonError> {
        let blocked = {
            let inner = self.inner.lock();
            inner.choose_trees.contains_key(&client)
                || inner.choose_buffers.contains_key(&client)
                || inner.display_panes.contains_key(&client)
                || inner.command_outputs.contains_key(&client)
        };
        if blocked || text.is_empty() || self.input_command_prompt_text(client, text) {
            return Ok(());
        }
        self.dispatch_input_text(client, pane, &mut None, text)
            .map_err(Into::into)
    }

    fn dispatch_input_text(
        &self,
        client: ClientId,
        pane: PaneId,
        sinks: &mut Option<Vec<PaneSink>>,
        text: &str,
    ) -> Result<(), ServerError> {
        if text.is_empty() {
            return Ok(());
        }
        let sinks = if let Some(sinks) = sinks.as_ref() {
            sinks
        } else {
            sinks.insert(self.input_sinks(client, pane)?)
        };
        let terminal_text = sinks
            .iter()
            .any(|sink| matches!(sink, PaneSink::Terminal(_)))
            .then(|| Arc::<str>::from(text));
        for sink in sinks {
            match sink {
                PaneSink::Terminal(terminal) => terminal.send_text_for_view(
                    TerminalViewId(client.0),
                    Arc::clone(
                        terminal_text
                            .as_ref()
                            .expect("terminal text is allocated when a terminal sink exists"),
                    ),
                ),
                PaneSink::Browser(target) => self.publish_for_pane(
                    *target,
                    &EventPayload::BrowserCommand {
                        pane: *target,
                        command: BrowserCommand::SendKeys(vec![zz_protocol::KeyToken::Literal(
                            text.to_owned(),
                        )]),
                    },
                ),
            }
        }
        Ok(())
    }

    fn input_key(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        pane: PaneId,
        input: zz_terminal::KeyInput,
        text_follows: bool,
    ) -> Result<(), DaemonError> {
        let modal_active = {
            let inner = self.inner.lock();
            inner.choose_trees.contains_key(&client)
                || inner.choose_buffers.contains_key(&client)
                || inner.display_panes.contains_key(&client)
        };
        if modal_active {
            if input.action == zz_terminal::KeyAction::Release {
                let _ = self.key_decision(client, &input_key_name(&input), true);
            }
            return Ok(());
        }
        if self.input_command_prompt_key(client, kind, context, &input, text_follows) {
            return Ok(());
        }
        if input.action != zz_terminal::KeyAction::Release
            && self.inner.lock().engine.dead_pane_dismisses_on_key(pane)
        {
            let target = pane.to_string();
            self.execute_gesture(
                client,
                kind,
                context,
                "dead_pane_dismiss",
                &CommandInvocation::new("kill-pane", ["-t", target.as_str()]),
            )?;
            return Ok(());
        }
        let key = input_key_name(&input);
        let decision = self.key_decision(
            client,
            &key,
            input.action == zz_terminal::KeyAction::Release,
        );
        if decision != KeyDecision::Pass
            && input.action != zz_terminal::KeyAction::Release
            && text_follows
            && input.modifiers == zz_terminal::Modifiers::default()
            && let zz_terminal::KeyCode::Character(character) = input.key
        {
            *self
                .inner
                .lock()
                .suppressed_text
                .entry(client)
                .or_default()
                .entry(character)
                .or_default() += 1;
        }
        let result = match decision {
            KeyDecision::Pass => {
                if self.inner.lock().command_outputs.contains_key(&client) {
                    return Ok(());
                }
                self.dispatch_input_key(client, pane, input)
                    .map_err(Into::into)
            }
            KeyDecision::Prefix | KeyDecision::Ignore => Ok(()),
            KeyDecision::Commands(commands) => {
                self.execute_key_commands(client, kind, context, pane, &commands)
            }
        };
        self.sync_prefix_armed(client);
        result
    }

    fn input_browser_surface_key(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        pane: PaneId,
        input: zz_terminal::KeyInput,
        text_follows: bool,
    ) -> Result<(), DaemonError> {
        let blocked = {
            let inner = self.inner.lock();
            inner.choose_trees.contains_key(&client)
                || inner.choose_buffers.contains_key(&client)
                || inner.display_panes.contains_key(&client)
        };
        if blocked || self.input_command_prompt_key(client, kind, context, &input, text_follows) {
            return Ok(());
        }
        if self.inner.lock().command_outputs.contains_key(&client) {
            return Ok(());
        }
        self.dispatch_input_key(client, pane, input)
            .map_err(Into::into)
    }

    fn dispatch_input_key(
        &self,
        client: ClientId,
        pane: PaneId,
        input: zz_terminal::KeyInput,
    ) -> Result<(), ServerError> {
        let mut sinks = self.input_sinks(client, pane)?.into_iter().peekable();
        let mut owned_input = Some(input);
        while let Some(sink) = sinks.next() {
            let sink_input = if sinks.peek().is_none() {
                owned_input.take().expect("last sink owns key input")
            } else {
                owned_input
                    .as_ref()
                    .expect("key input is retained until the last sink")
                    .clone()
            };
            match sink {
                PaneSink::Terminal(terminal) => {
                    terminal.send_key_for_view(TerminalViewId(client.0), sink_input);
                }
                PaneSink::Browser(target) => self.publish_for_pane(
                    target,
                    &EventPayload::BrowserCommand {
                        pane: target,
                        command: BrowserCommand::Key(sink_input),
                    },
                ),
            }
        }
        Ok(())
    }

    fn input_choose_tree(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        action: ChooseTreeAction,
    ) -> Result<(), DaemonError> {
        if kind != ClientKind::Interactive {
            return Err(ServerError::InvalidCommand(
                "choose-tree input requires an interactive client".to_owned(),
            )
            .into());
        }
        let (result, state, delta) = {
            let mut inner = self.inner.lock();
            let Some(mut chooser) = inner.choose_trees.remove(&client) else {
                return Ok(());
            };
            let action = match action {
                ChooseTreeAction::Key(input) => {
                    let searching = chooser.search.is_some();
                    let Some(action) =
                        choose_tree_key_action(&inner.engine.keys, &input, searching)
                    else {
                        inner.choose_trees.insert(client, chooser);
                        return Ok(());
                    };
                    action
                }
                action => action,
            };
            let attached_session = client_attached_session(&inner, client);
            let result = match chooser.apply(action, &inner.engine.state, attached_session) {
                Ok(result) => result,
                Err(error) => {
                    inner.choose_trees.insert(client, chooser);
                    return Err(error.into());
                }
            };
            let state = (result == ChooseTreeResult::Updated(ChooseTreeUpdateKind::Full))
                .then(|| chooser.rendered.clone());
            let delta = (result == ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta))
                .then(|| (chooser.rendered.selected, chooser.rendered.search.clone()));
            if matches!(result, ChooseTreeResult::Updated(_)) {
                inner.choose_trees.insert(client, chooser);
            }
            (result, state, delta)
        };

        match result {
            ChooseTreeResult::Updated(ChooseTreeUpdateKind::Full) => {
                self.publish_to_client(client, EventPayload::ChooseTree { state });
            }
            ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta) => {
                let (selected, search) = delta.expect("updated chooser retains cursor state");
                self.publish_to_client(client, EventPayload::ChooseTreeUpdate { search, selected });
            }
            ChooseTreeResult::Close => {
                self.publish_to_client(client, EventPayload::ChooseTree { state: None });
            }
            ChooseTreeResult::Activate(target) => {
                self.publish_to_client(client, EventPayload::ChooseTree { state: None });
                self.activate_choose_tree_target(client, kind, context, target)?;
            }
        }
        Ok(())
    }

    fn input_choose_buffer(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        action: ChooseBufferAction,
    ) -> Result<(), DaemonError> {
        if kind != ClientKind::Interactive {
            return Err(ServerError::InvalidCommand(
                "choose-buffer input requires an interactive client".to_owned(),
            )
            .into());
        }

        let (outcome, deleted) = {
            let mut inner = self.inner.lock();
            let Some(mut chooser) = inner.choose_buffers.remove(&client) else {
                return Ok(());
            };
            let action = match action {
                ChooseBufferAction::Key(input) => {
                    let searching = chooser.search.is_some();
                    let Some(action) =
                        choose_buffer_key_action(&inner.engine.keys, &input, searching)
                    else {
                        inner.choose_buffers.insert(client, chooser);
                        return Ok(());
                    };
                    action
                }
                action => action,
            };
            let attached_session = client_attached_session(&inner, client);
            let source_session = inner
                .engine
                .state
                .window_for_pane(chooser.source_pane)
                .map(|window| inner.engine.state.windows[&window].session);
            if attached_session != Some(chooser.source_session)
                || source_session != Some(chooser.source_session)
            {
                (ChooseBufferInputOutcome::Close, None)
            } else {
                let result = match chooser.apply(action, &inner.paste_buffers) {
                    Ok(result) => result,
                    Err(error) => {
                        inner.choose_buffers.insert(client, chooser);
                        return Err(error.into());
                    }
                };
                let mut deleted = None;
                let outcome = match result {
                    ChooseBufferResult::Updated => {
                        let search = chooser.rendered.search.clone();
                        let selected = chooser.rendered.selected;
                        inner.choose_buffers.insert(client, chooser);
                        ChooseBufferInputOutcome::Delta { search, selected }
                    }
                    ChooseBufferResult::Delete(name) => {
                        let deleted_index = usize::try_from(chooser.rendered.selected)
                            .unwrap_or(usize::MAX)
                            .min(inner.paste_buffers.len().saturating_sub(1));
                        inner.paste_buffers.retain(|buffer| buffer.name != name);
                        deleted = Some(name);
                        chooser.selected = inner
                            .paste_buffers
                            .get(deleted_index)
                            .or_else(|| inner.paste_buffers.last())
                            .map(|buffer| buffer.name.clone());
                        chooser.rebuild(&inner.paste_buffers);
                        if chooser.rendered.items.is_empty() {
                            ChooseBufferInputOutcome::Full(None)
                        } else {
                            let state = chooser.rendered.clone();
                            inner.choose_buffers.insert(client, chooser);
                            ChooseBufferInputOutcome::Full(Some(state))
                        }
                    }
                    ChooseBufferResult::Paste(name) => ChooseBufferInputOutcome::Paste {
                        pane: chooser.source_pane,
                        name,
                    },
                    ChooseBufferResult::Close => ChooseBufferInputOutcome::Close,
                };
                (outcome, deleted)
            }
        };

        if let Some(name) = deleted {
            self.run_event_hooks(vec![PendingHookEvent::paste_buffer(
                "paste-buffer-deleted",
                name,
            )]);
        }

        match outcome {
            ChooseBufferInputOutcome::Delta { search, selected } => {
                self.publish_to_client(
                    client,
                    EventPayload::ChooseBufferUpdate { search, selected },
                );
            }
            ChooseBufferInputOutcome::Full(state) => {
                self.publish_to_client(client, EventPayload::ChooseBuffer { state });
                self.refresh_choose_buffers_except(Some(client));
            }
            ChooseBufferInputOutcome::Paste { pane, name } => {
                self.publish_to_client(client, EventPayload::ChooseBuffer { state: None });
                self.paste_buffer_to_pane(
                    pane,
                    PasteBufferPaste {
                        requested_name: Some(&name),
                        delete: false,
                        bracketed: true,
                        separator: b"\r",
                        literal: false,
                        expected_client: Some(client),
                        event_hooks_enabled: true,
                    },
                )?;
            }
            ChooseBufferInputOutcome::Close => {
                self.publish_to_client(client, EventPayload::ChooseBuffer { state: None });
            }
        }
        Ok(())
    }

    fn input_display_panes(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        action: DisplayPanesAction,
    ) -> Result<(), DaemonError> {
        if kind != ClientKind::Interactive {
            return Err(ServerError::InvalidCommand(
                "display-panes input requires an interactive client".to_owned(),
            )
            .into());
        }
        if matches!(
            &action,
            DisplayPanesAction::Key(input) if input.action == zz_terminal::KeyAction::Release
        ) {
            return Ok(());
        }

        let Some(overlay) = ({
            let mut inner = self.inner.lock();
            take_display_panes(&mut inner, client)
        }) else {
            return Ok(());
        };
        self.publish_to_client(client, EventPayload::DisplayPanes { state: None });

        let attached = client_attached_session(&self.inner.lock(), client);
        if attached != Some(overlay.source_session) {
            return Ok(());
        }
        match action {
            DisplayPanesAction::Close => {
                self.inner
                    .lock()
                    .swallowed_keys
                    .entry(client)
                    .or_default()
                    .insert("Escape".to_owned());
            }
            DisplayPanesAction::Select(pane) => {
                if overlay
                    .state
                    .indicators
                    .iter()
                    .any(|indicator| indicator.pane == pane)
                {
                    self.select_display_pane(client, kind, context, pane)?;
                }
            }
            DisplayPanesAction::Key(input) => {
                let selected = display_panes_selection_key(&input).and_then(|key| {
                    overlay
                        .state
                        .indicators
                        .iter()
                        .find(|indicator| indicator.select_key == key)
                        .map(|indicator| indicator.pane)
                });
                if let Some(pane) = selected {
                    self.inner
                        .lock()
                        .swallowed_keys
                        .entry(client)
                        .or_default()
                        .insert(input_key_name(&input).into_string());
                    self.select_display_pane(client, kind, context, pane)?;
                } else if self
                    .inner
                    .lock()
                    .engine
                    .state
                    .window_for_pane(overlay.source_pane)
                    .is_some()
                {
                    self.input_key(client, kind, context, overlay.source_pane, input, false)?;
                }
            }
        }
        Ok(())
    }

    fn select_display_pane(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        pane: PaneId,
    ) -> Result<(), DaemonError> {
        let zoomed = {
            let inner = self.inner.lock();
            let window = inner
                .engine
                .state
                .window_for_pane(pane)
                .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
            inner.engine.state.windows[&window].zoomed_pane.is_some()
        };
        if zoomed {
            self.execute_gesture(
                client,
                kind,
                context,
                "display_panes_select",
                &CommandInvocation::new("resize-pane", ["-Z", "-t", &pane.to_string()]),
            )?;
        }
        self.execute_gesture(
            client,
            kind,
            context,
            "display_panes_select",
            &CommandInvocation::new("select-pane", ["-t", &pane.to_string()]),
        )
    }

    fn execute_gesture(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        gesture: &str,
        command: &CommandInvocation,
    ) -> Result<(), DaemonError> {
        let error = match self.execute(client, kind, context, command) {
            Ok(execution) => {
                if kind == ClientKind::Interactive && !execution.output.is_empty() {
                    self.open_command_output(
                        client,
                        context.pane,
                        command.name.clone(),
                        &execution.output,
                    )?;
                }
                return Ok(());
            }
            Err(error) => error,
        };
        if kind == ClientKind::Interactive
            && let Some(output) = daemon_error_output(&error)
        {
            self.open_command_output(client, context.pane, command.name.clone(), output)?;
        }
        log::warn!(
            target: "zz_daemon::diagnostics::input",
            "gesture_command_failed client={client} gesture={gesture} command={} args={:?} error={error}",
            command.name,
            command.args,
        );
        self.publish_to_client(
            client,
            EventPayload::ClientMessage {
                pane: context.pane,
                kind: ClientMessageKind::Error,
                text: error.to_string(),
            },
        );
        Err(error)
    }

    fn expire_display_panes(&self, scheduled: DisplayPanesDeadline, now: Instant) -> bool {
        let mut inner = self.inner.lock();
        let due = inner
            .display_panes
            .get(&scheduled.client)
            .is_some_and(|overlay| {
                overlay.token == scheduled.token
                    && overlay.deadline == Some(scheduled.deadline)
                    && scheduled.deadline <= now
            });
        if !due {
            return false;
        }
        inner.display_panes.remove(&scheduled.client);
        if let Some(outbound) = inner.subscribers.get(&scheduled.client) {
            Self::send_event(outbound, EventPayload::DisplayPanes { state: None });
        }
        true
    }

    fn activate_choose_tree_target(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        target: ChooseTreeTarget,
    ) -> Result<(), DaemonError> {
        let (selection, session) = {
            let inner = self.inner.lock();
            let (selection, session) = match target {
                ChooseTreeTarget::Session(session) => (None, session),
                ChooseTreeTarget::Window(window) => {
                    let session = inner
                        .engine
                        .state
                        .windows
                        .get(&window)
                        .map(|window| window.session)
                        .ok_or_else(|| ServerError::MissingTarget(window.to_string()))?;
                    (
                        Some(CommandInvocation::new(
                            "select-window",
                            ["-t", &window.to_string()],
                        )),
                        session,
                    )
                }
                ChooseTreeTarget::Pane(pane) => {
                    let window = inner
                        .engine
                        .state
                        .window_for_pane(pane)
                        .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
                    let session = inner.engine.state.windows[&window].session;
                    (
                        Some(CommandInvocation::new(
                            "select-pane",
                            ["-t", &pane.to_string()],
                        )),
                        session,
                    )
                }
            };
            (selection, session)
        };
        if let Some(selection) = selection {
            self.execute_gesture(client, kind, context, "choose_tree_activate", &selection)?;
        }
        if client_attached_session(&self.inner.lock(), client) != Some(session) {
            self.execute_gesture(
                client,
                kind,
                context,
                "choose_tree_activate",
                &CommandInvocation::new("attach-session", ["-t", &session.to_string()]),
            )?;
        }
        Ok(())
    }

    fn execute_key_commands(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        pane: PaneId,
        commands: &[CommandInvocation],
    ) -> Result<(), DaemonError> {
        let mut output = String::new();
        let mut output_truncated = false;
        for command in commands {
            let execution = match self.execute(client, kind, context, command) {
                Ok(execution) => execution,
                Err(error) => {
                    if let Some(error_output) = daemon_error_output(&error)
                        && !output_truncated
                    {
                        output_truncated = append_command_prompt_output(&mut output, error_output);
                    }
                    if output_truncated {
                        if !output.is_empty() {
                            output.push('\n');
                        }
                        output.push_str(COMMAND_PROMPT_OUTPUT_TRUNCATED);
                    }
                    if kind == ClientKind::Interactive && !output.is_empty() {
                        let title = commands.first().map_or_else(
                            || "command output".to_owned(),
                            |command| {
                                if commands.len() == 1 {
                                    command.name.clone()
                                } else {
                                    "command output".to_owned()
                                }
                            },
                        );
                        self.open_command_output(client, Some(pane), title, &output)?;
                    }
                    log::warn!(
                        target: "zz_daemon::diagnostics::input",
                        "key_command_failed client={client} command={} args={:?} error={error}",
                        command.name,
                        command.args,
                    );
                    return Err(error);
                }
            };
            if !execution.output.is_empty() && !output_truncated {
                output_truncated = append_command_prompt_output(&mut output, &execution.output);
            }
        }
        if output_truncated {
            if !output.is_empty() {
                output.push('\n');
            }
            output.push_str(COMMAND_PROMPT_OUTPUT_TRUNCATED);
        }
        if kind == ClientKind::Interactive && !output.is_empty() {
            let title = commands.first().map_or_else(
                || "command output".to_owned(),
                |command| {
                    if commands.len() == 1 {
                        command.name.clone()
                    } else {
                        "command output".to_owned()
                    }
                },
            );
            self.open_command_output(client, Some(pane), title, &output)?;
        }
        Ok(())
    }

    fn input_command_prompt_text(&self, client: ClientId, text: &str) -> bool {
        let result = {
            let mut inner = self.inner.lock();
            let history = command_prompt_history_snapshot(&inner.command_history);
            let Some(prompt) = inner.command_prompts.get_mut(&client) else {
                return false;
            };
            if prompt.insert(text) {
                Ok(prompt.state(&history))
            } else {
                Err(())
            }
        };
        match result {
            Ok(state) => {
                self.publish_to_client(client, EventPayload::CommandPrompt { state: Some(state) });
            }
            Err(()) => {
                self.publish_to_client(
                    client,
                    EventPayload::ClientMessage {
                        pane: None,
                        kind: ClientMessageKind::Warning,
                        text: format!(
                            "command prompt input exceeds {} bytes",
                            zz_protocol::MAX_COMMAND_PROMPT_BYTES
                        ),
                    },
                );
            }
        }
        true
    }

    fn input_command_prompt_key(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        input: &zz_terminal::KeyInput,
        text_follows: bool,
    ) -> bool {
        let (event, submission, limit_exceeded) = {
            let mut inner = self.inner.lock();
            let Some(mut prompt) = inner.command_prompts.remove(&client) else {
                return false;
            };
            let action =
                command_prompt_key(&mut prompt, input, text_follows, &inner.command_history);
            match action {
                PromptKeyAction::Handled => {
                    inner.command_prompts.insert(client, prompt);
                    (None, None, false)
                }
                PromptKeyAction::Updated => {
                    let state = prompt.state(&inner.command_history);
                    inner.command_prompts.insert(client, prompt);
                    (Some(Some(state)), None, false)
                }
                PromptKeyAction::LimitExceeded => {
                    inner.command_prompts.insert(client, prompt);
                    (None, None, true)
                }
                PromptKeyAction::Close => (Some(None), None, false),
                PromptKeyAction::Submit => {
                    let submission = (!prompt.input.is_empty() || prompt.template.is_some())
                        .then_some(CommandPromptSubmission {
                            input: prompt.input,
                            template: prompt.template,
                        });
                    (Some(None), submission, false)
                }
            }
        };

        if let Some(state) = event {
            self.publish_to_client(client, EventPayload::CommandPrompt { state });
        }
        if let Some(submission) = &submission {
            self.record_command_history(&submission.input);
        }
        if limit_exceeded {
            self.publish_to_client(
                client,
                EventPayload::ClientMessage {
                    pane: context.pane,
                    kind: ClientMessageKind::Warning,
                    text: format!(
                        "command prompt input exceeds {} bytes",
                        zz_protocol::MAX_COMMAND_PROMPT_BYTES
                    ),
                },
            );
        }
        if let Some(submission) = submission {
            self.submit_command_prompt(client, kind, context, &submission);
        }
        true
    }

    fn input_command_prompt_action(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        action: CommandPromptAction,
    ) -> Result<(), DaemonError> {
        if kind != ClientKind::Interactive {
            return Err(ServerError::InvalidCommand(
                "command prompt actions require an interactive client".to_owned(),
            )
            .into());
        }

        match action {
            CommandPromptAction::Update { input, cursor } => {
                let mut inner = self.inner.lock();
                if let Some(prompt) = inner.command_prompts.get_mut(&client) {
                    prompt.replace_input(input, cursor)?;
                }
            }
            CommandPromptAction::Submit { input } => {
                if input.len() > zz_protocol::MAX_COMMAND_PROMPT_BYTES {
                    return Err(ServerError::InvalidCommand(format!(
                        "command prompt input exceeds {} bytes",
                        zz_protocol::MAX_COMMAND_PROMPT_BYTES
                    ))
                    .into());
                }
                let submission = {
                    let mut inner = self.inner.lock();
                    let Some(mut prompt) = inner.command_prompts.remove(&client) else {
                        return Ok(());
                    };
                    let cursor = u32::try_from(input.chars().count()).unwrap_or(u32::MAX);
                    prompt.replace_input(input, cursor)?;
                    (!prompt.input.is_empty() || prompt.template.is_some()).then_some(
                        CommandPromptSubmission {
                            input: prompt.input,
                            template: prompt.template,
                        },
                    )
                };
                if let Some(submission) = &submission {
                    self.record_command_history(&submission.input);
                }
                self.publish_to_client(client, EventPayload::CommandPrompt { state: None });
                if let Some(submission) = submission {
                    self.submit_command_prompt(client, kind, context, &submission);
                }
            }
            CommandPromptAction::Close => {
                if self.inner.lock().command_prompts.remove(&client).is_some() {
                    self.publish_to_client(client, EventPayload::CommandPrompt { state: None });
                }
            }
        }
        Ok(())
    }

    fn record_command_history(&self, input: &str) {
        if input.is_empty() {
            return;
        }
        let save = {
            let mut inner = self.inner.lock();
            let limit = inner.engine.prompt_history_limit();
            if !add_command_prompt_history(&mut inner.command_history, input, limit) {
                return;
            }
            prompt_history_path(inner.engine.history_file())
                .map(|path| (path, inner.command_history.clone()))
        };
        if let Some((path, history)) = save {
            save_command_prompt_history(&path, &history);
        }
    }

    fn submit_command_prompt(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        context: &mut ExecutionContext,
        submission: &CommandPromptSubmission,
    ) {
        let source = submission
            .template
            .as_deref()
            .unwrap_or(submission.input.as_str());
        let mut parsed = {
            let inner = self.inner.lock();
            inner.engine.parse_config("<command-prompt>", source)
        };
        if let Some(diagnostic) = parsed.diagnostics.first() {
            self.publish_to_client(
                client,
                EventPayload::ClientMessage {
                    pane: context.pane,
                    kind: ClientMessageKind::Error,
                    text: format!(
                        "{}:{}:{}: {}",
                        diagnostic.source, diagnostic.line, diagnostic.column, diagnostic.message
                    ),
                },
            );
            return;
        }
        if submission.template.is_some() {
            for command in &mut parsed.commands {
                command.name = command.name.replace("%%", &submission.input);
                for argument in &mut command.args {
                    *argument = argument.replace("%%", &submission.input);
                }
            }
        }

        let mut output = String::new();
        let mut output_truncated = false;
        for command in parsed.commands {
            match self.execute(client, kind, context, &command) {
                Ok(execution) if !execution.output.is_empty() && !output_truncated => {
                    output_truncated = append_command_prompt_output(&mut output, &execution.output);
                }
                Ok(_) => {}
                Err(error) => {
                    if let Some(error_output) = daemon_error_output(&error)
                        && !output_truncated
                    {
                        output_truncated = append_command_prompt_output(&mut output, error_output);
                    }
                    if output_truncated {
                        if !output.is_empty() {
                            output.push('\n');
                        }
                        output.push_str(COMMAND_PROMPT_OUTPUT_TRUNCATED);
                    }
                    if !output.is_empty()
                        && let Err(output_error) = self.open_command_output(
                            client,
                            context.pane,
                            "command output".to_owned(),
                            &output,
                        )
                    {
                        self.publish_to_client(
                            client,
                            EventPayload::ClientMessage {
                                pane: context.pane,
                                kind: ClientMessageKind::Error,
                                text: output_error.to_string(),
                            },
                        );
                    }
                    self.publish_to_client(
                        client,
                        EventPayload::ClientMessage {
                            pane: context.pane,
                            kind: ClientMessageKind::Error,
                            text: error.to_string(),
                        },
                    );
                    return;
                }
            }
        }
        if output_truncated {
            if !output.is_empty() {
                output.push('\n');
            }
            output.push_str(COMMAND_PROMPT_OUTPUT_TRUNCATED);
        }
        if !output.is_empty()
            && let Err(error) =
                self.open_command_output(client, context.pane, "command output".to_owned(), &output)
        {
            self.publish_to_client(
                client,
                EventPayload::ClientMessage {
                    pane: context.pane,
                    kind: ClientMessageKind::Error,
                    text: error.to_string(),
                },
            );
        }
    }

    fn input_paste(&self, client: ClientId, pane: PaneId, text: &str) -> Result<(), ServerError> {
        for sink in self.input_sinks(client, pane)? {
            match sink {
                PaneSink::Terminal(terminal) => terminal.view_action(
                    TerminalViewId(client.0),
                    zz_terminal::TerminalViewAction::Paste(text.to_owned()),
                ),
                PaneSink::Browser(target) => self.publish_for_pane(
                    target,
                    &EventPayload::BrowserCommand {
                        pane: target,
                        command: BrowserCommand::SendKeys(vec![zz_protocol::KeyToken::Literal(
                            text.to_owned(),
                        )]),
                    },
                ),
            }
        }
        Ok(())
    }

    fn begin_paste_upload(
        &self,
        client: ClientId,
        kind: ClientKind,
        upload_id: u64,
        pane: PaneId,
        purpose: PasteUploadPurpose,
        extension: String,
        total_bytes: u32,
    ) {
        if kind != ClientKind::Interactive {
            return;
        }
        if !zz_protocol::paste_upload_extension_is_valid(&extension)
            || purpose == PasteUploadPurpose::RecordPastedImage
                && PastedImageFormat::from_extension(&extension).is_none()
            || total_bytes == 0
            || total_bytes > zz_protocol::MAX_PASTE_UPLOAD_BYTES
        {
            self.reject_paste_upload(
                client,
                Some(pane),
                "the paste upload is malformed".to_owned(),
            );
            return;
        }
        let total_bytes = total_bytes as usize;
        let mut inner = self.inner.lock();
        if !client_is_attached_to_pane(&inner, client, pane) {
            drop(inner);
            self.reject_paste_upload(
                client,
                Some(pane),
                format!("cannot paste an image into {pane}: the pane is not attached"),
            );
            return;
        }
        let in_flight = inner
            .paste_uploads
            .keys()
            .filter(|(owner, id)| *owner == client && *id != upload_id)
            .count();
        if in_flight >= MAX_CONCURRENT_PASTE_UPLOADS {
            drop(inner);
            self.reject_paste_upload(
                client,
                Some(pane),
                format!("too many image pastes in flight (limit {MAX_CONCURRENT_PASTE_UPLOADS})"),
            );
            return;
        }
        inner.paste_uploads.insert(
            (client, upload_id),
            PasteUpload {
                pane,
                purpose,
                extension,
                total_bytes,
                bytes: Vec::with_capacity(total_bytes),
            },
        );
    }

    fn extend_paste_upload(&self, client: ClientId, upload_id: u64, bytes: &[u8]) {
        let key = (client, upload_id);
        let finished = {
            let mut inner = self.inner.lock();
            let Some(upload) = inner.paste_uploads.get(&key) else {
                return;
            };
            if upload.bytes.len().saturating_add(bytes.len()) > upload.total_bytes {
                let pane = upload.pane;
                inner.paste_uploads.remove(&key);
                drop(inner);
                self.reject_paste_upload(
                    client,
                    Some(pane),
                    "the pasted image sent more bytes than it declared".to_owned(),
                );
                return;
            }
            let upload = inner
                .paste_uploads
                .get_mut(&key)
                .expect("the upload was present a statement ago");
            upload.bytes.extend_from_slice(bytes);
            if upload.bytes.len() < upload.total_bytes {
                return;
            }
            inner.paste_uploads.remove(&key)
        };
        let Some(upload) = finished else {
            return;
        };
        self.finish_paste_upload(client, upload_id, upload);
    }

    fn finish_paste_upload(&self, client: ClientId, upload_id: u64, upload: PasteUpload) {
        if upload.purpose == PasteUploadPurpose::RecordPastedImage {
            self.record_pasted_image(client, upload);
            return;
        }
        let path = match write_paste_upload(
            &self.paste_directory,
            &format!("paste-{client}-{upload_id}.{}", upload.extension),
            &upload.bytes,
        ) {
            Ok(path) => path,
            Err(error) => {
                self.reject_paste_upload(
                    client,
                    Some(upload.pane),
                    format!("could not save the pasted image: {error}"),
                );
                return;
            }
        };
        prune_paste_uploads(&self.paste_directory, PASTE_UPLOAD_RETENTION);
        let Some(path) = path.to_str() else {
            self.reject_paste_upload(
                client,
                Some(upload.pane),
                "the pasted image landed on a path that is not valid UTF-8".to_owned(),
            );
            return;
        };
        // Record image PastePath bytes so remote placeholders can bind. Stage them before
        // input_paste to preserve the terminal actor's FIFO command order.
        if let Some(format) = PastedImageFormat::from_extension(&upload.extension) {
            self.stage_pending_pasted_image(client, upload.pane, format, Arc::from(upload.bytes));
        }
        if let Err(error) = self.input_paste(client, upload.pane, path) {
            self.reject_paste_upload(
                client,
                Some(upload.pane),
                format!("could not paste the image path: {error}"),
            );
        }
    }

    fn record_pasted_image(&self, client: ClientId, upload: PasteUpload) {
        let Some(format) = PastedImageFormat::from_extension(&upload.extension) else {
            self.reject_paste_upload(
                client,
                Some(upload.pane),
                "the recorded pasted image format is unsupported".to_owned(),
            );
            return;
        };
        if !self.stage_pending_pasted_image(client, upload.pane, format, Arc::from(upload.bytes)) {
            self.reject_paste_upload(
                client,
                Some(upload.pane),
                format!(
                    "cannot record an image for {}: the pane is no longer attached",
                    upload.pane
                ),
            );
        }
    }

    /// Stage pending bytes on the pane's terminal and open the bind window. The pending
    /// entry is inserted while `inner` is held so a concurrent pane removal either sees
    /// it (and purges it) or prevents the insert. Returns false when the client is no
    /// longer attached to a terminal pane.
    fn stage_pending_pasted_image(
        &self,
        client: ClientId,
        pane: PaneId,
        format: PastedImageFormat,
        bytes: Arc<[u8]>,
    ) -> bool {
        static NEXT_PASTED_IMAGE_TOKEN: AtomicU64 = AtomicU64::new(1);

        let token = NEXT_PASTED_IMAGE_TOKEN
            .fetch_add(1, Ordering::Relaxed)
            .max(1);
        let registered = {
            let inner = self.inner.lock();
            if client_is_attached_to_pane(&inner, client, pane) {
                inner.terminals.get(&pane).cloned().map(|terminal| {
                    let admission = self
                        .pasted_images
                        .lock()
                        .entry(pane)
                        .or_default()
                        .push_pending(PendingPastedImage {
                            token,
                            format,
                            bytes,
                        });
                    (terminal, admission)
                })
            } else {
                None
            }
        };
        let Some((terminal, admission)) = registered else {
            return false;
        };
        for number in admission.evicted_numbers {
            terminal.unbind_pasted_image(number);
        }
        if admission.retained {
            terminal.open_pending_paste(token);
        }
        true
    }

    fn bind_pasted_image(
        &self,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
        token: u64,
        number: u32,
    ) {
        if !self.is_current_terminal(pane, terminal) {
            return;
        }
        let evicted = self
            .pasted_images
            .lock()
            .get_mut(&pane)
            .and_then(|images| images.bind(token, number));
        let Some(evicted) = evicted else {
            terminal.unbind_pasted_image(number);
            return;
        };
        for number in evicted {
            terminal.unbind_pasted_image(number);
        }
    }

    fn expire_pending_pasted_image(
        &self,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
        token: u64,
    ) {
        if !self.is_current_terminal(pane, terminal) {
            return;
        }
        if let Some(images) = self.pasted_images.lock().get_mut(&pane) {
            images.expire(token);
        }
    }

    fn fetch_pasted_image(&self, client: ClientId, pane: PaneId, number: u32) {
        let subscriber = {
            let inner = self.inner.lock();
            client_is_attached_to_pane(&inner, client, pane)
                .then(|| inner.subscribers.get(&client).cloned())
                .flatten()
        };
        let Some(subscriber) = subscriber else {
            return;
        };
        let image = {
            let mut panes = self.pasted_images.lock();
            panes
                .get_mut(&pane)
                .and_then(|images| images.images.get_mut(&number))
                .and_then(|image| {
                    pasted_image_frames(pane, number, image).map(|frames| (image.token, frames))
                })
        };
        let Some((token, frames)) = image else {
            let _ = subscriber
                .enqueue_reliable(&ProtocolMessage::PastedImageUnavailable { pane, number });
            return;
        };
        let _ = subscriber.enqueue_pasted_image(pane, number, token, &frames);
    }

    fn reject_paste_upload(&self, client: ClientId, pane: Option<PaneId>, text: String) {
        log::warn!(
            target: "zz_daemon::diagnostics::input",
            "paste upload rejected client={client} pane={pane:?}: {text}"
        );
        self.publish_to_client(
            client,
            EventPayload::ClientMessage {
                pane,
                kind: ClientMessageKind::Error,
                text,
            },
        );
    }

    fn input_sinks(&self, client: ClientId, source: PaneId) -> Result<Vec<PaneSink>, ServerError> {
        let inner = self.inner.lock();
        if !client_is_attached_to_pane(&inner, client, source) {
            return Err(ServerError::PaneNotAttached(source));
        }
        resolve_input_sinks(&inner, source)
    }

    fn sync_prefix_armed(&self, client: ClientId) {
        let (changed, armed) = {
            let mut inner = self.inner.lock();
            let armed = inner
                .key_engines
                .get(&client)
                .is_some_and(|engine| engine.active_table() == Some("prefix"));
            let changed = if armed {
                inner.prefix_armed.insert(client)
            } else {
                inner.prefix_armed.remove(&client)
            };
            (changed, armed)
        };
        if changed {
            log::info!(
                target: "zz_daemon::diagnostics::input",
                "prefix_armed_published client={client} armed={armed}"
            );
            self.publish_to_client(client, EventPayload::PrefixArmed { armed });
        }
    }

    fn cancel_prefix(&self, client: ClientId, request_id: u64) {
        {
            let mut inner = self.inner.lock();
            if inner
                .key_engines
                .get(&client)
                .and_then(KeyEngine::active_table)
                == Some("prefix")
            {
                inner
                    .key_engines
                    .entry(client)
                    .or_default()
                    .switch_table(None);
            }
        }
        self.sync_prefix_armed(client);
        self.publish_to_client(client, EventPayload::PrefixCancelled { request_id });
    }

    fn key_decision(&self, client: ClientId, key: &str, release: bool) -> KeyDecision {
        let mut inner = self.inner.lock();
        if release {
            return if inner
                .swallowed_keys
                .get_mut(&client)
                .is_some_and(|keys| keys.remove(bare_key_name(key)))
            {
                KeyDecision::Prefix
            } else {
                KeyDecision::Pass
            };
        }
        let mut key_engine = inner.key_engines.remove(&client).unwrap_or_default();
        let table = key_engine.active_table().map(str::to_owned);
        let prefix_timeout_ms = inner.engine.prefix_timeout_ms();
        let (initial_repeat_time_ms, repeat_time_ms, root_table) = client_attached_session(
            &inner, client,
        )
        .map_or((0, 500, "root".to_owned()), |session| {
            (
                inner.engine.initial_repeat_time_for_session(session),
                inner.engine.repeat_time_for_session(session),
                inner.engine.key_table_for_session(session),
            )
        });
        let decision = key_engine.handle_with_repeat_times(
            &inner.engine.keys,
            key,
            Instant::now(),
            Duration::from_millis(u64::from(repeat_time_ms)),
            Duration::from_millis(u64::from(initial_repeat_time_ms)),
            Duration::from_millis(u64::from(prefix_timeout_ms)),
            &root_table,
        );
        inner.key_engines.insert(client, key_engine);
        if decision != KeyDecision::Pass {
            inner
                .swallowed_keys
                .entry(client)
                .or_default()
                .insert(bare_key_name(key).to_owned());
        }
        drop(inner);
        if decision != KeyDecision::Pass {
            log::info!(
                target: "zz_daemon::diagnostics::input",
                "key_decision client={client} key={key} table={} decision={decision:?}",
                table.as_deref().unwrap_or(&root_table)
            );
        }
        decision
    }

    fn filter_suppressed_text<'a>(&self, client: ClientId, text: &'a str) -> Cow<'a, str> {
        let mut inner = self.inner.lock();
        let Some(characters) = inner.suppressed_text.get_mut(&client) else {
            return Cow::Borrowed(text);
        };
        let mut filtered = String::with_capacity(text.len());
        let mut unrepaid = false;
        for character in text.chars() {
            match characters.get_mut(&character) {
                Some(count) if *count > 0 => *count -= 1,
                _ => {
                    unrepaid = true;
                    filtered.push(character);
                }
            }
        }
        characters.retain(|_, count| *count != 0);
        if unrepaid || characters.is_empty() {
            inner.suppressed_text.remove(&client);
        }
        Cow::Owned(filtered)
    }

    fn kitty_image_frames(
        &self,
        pane: PaneId,
        terminal: &TerminalSession,
        image_id: u32,
        generation: u64,
    ) -> Option<Arc<[Vec<u8>]>> {
        let key = KittyImageKey {
            pane,
            image_id,
            generation,
        };
        if let Some(frames) = self.kitty_image_frames.lock().get(&key).cloned() {
            return Some(frames);
        }
        let image = match terminal.kitty_image(image_id) {
            Ok(Some(image)) if image.generation == generation => image,
            Ok(Some(image)) => {
                log::debug!(
                    "Kitty image {image_id} moved from requested generation {generation} to {} before export",
                    image.generation
                );
                return None;
            }
            Ok(None) => return None,
            Err(error) => {
                log::warn!("could not fetch Kitty image {image_id} for {pane}: {error}");
                return None;
            }
        };
        let total_bytes = u32::try_from(image.bgra.len()).ok()?;
        let mut frames =
            Vec::with_capacity(1 + image.bgra.len().div_ceil(MAX_KITTY_IMAGE_CHUNK_BYTES));
        let begin = Self::event(EventPayload::KittyImageBegin {
            pane,
            image_id,
            generation,
            width: image.width,
            height: image.height,
            total_bytes,
        });
        let mut encoded = Vec::new();
        if let Err(error) = encode_protocol_message_into(&begin, &mut encoded) {
            log::warn!("could not encode Kitty image {image_id} header for {pane}: {error}");
            return None;
        }
        frames.push(encoded);
        for chunk in image.bgra.chunks(MAX_KITTY_IMAGE_CHUNK_BYTES) {
            let message = Self::event(EventPayload::KittyImageChunk {
                pane,
                image_id,
                generation,
                bytes: chunk.to_vec(),
            });
            let mut encoded = Vec::new();
            if let Err(error) = encode_protocol_message_into(&message, &mut encoded) {
                log::warn!("could not encode Kitty image {image_id} chunk for {pane}: {error}");
                return None;
            }
            frames.push(encoded);
        }
        let frames: Arc<[Vec<u8>]> = frames.into();
        let mut cache = self.kitty_image_frames.lock();
        Some(
            cache
                .entry(key)
                .or_insert_with(|| Arc::clone(&frames))
                .clone(),
        )
    }

    fn enqueue_kitty_images_for_viewport(
        &self,
        outbound: &OutboundMailbox,
        pane: PaneId,
        terminal: &TerminalSession,
        viewport: &TerminalViewport,
    ) {
        let referenced = viewport
            .kitty_placements
            .iter()
            .map(|placement| (placement.image_id, placement.image_generation))
            .collect::<BTreeSet<_>>();
        for (image_id, generation) in referenced {
            let Some(frames) = self.kitty_image_frames(pane, terminal, image_id, generation) else {
                continue;
            };
            match outbound.enqueue_kitty_image(pane, image_id, generation, &frames) {
                KittyImageEnqueue::AlreadyDelivered => {}
                KittyImageEnqueue::Queued | KittyImageEnqueue::Closed => break,
            }
        }
    }

    fn evict_absent_kitty_images(
        &self,
        pane: PaneId,
        terminal: &TerminalSession,
        referenced: &BTreeSet<(u32, u64)>,
    ) {
        let candidates = self
            .kitty_image_frames
            .lock()
            .keys()
            .filter(|key| key.pane == pane && !referenced.contains(&(key.image_id, key.generation)))
            .copied()
            .collect::<Vec<_>>();
        let mut removed = BTreeSet::new();
        let mut stale = Vec::new();
        for key in candidates {
            match terminal.kitty_image_generation(key.image_id) {
                Ok(generation) if generation == Some(key.generation) => {}
                Ok(_) => {
                    stale.push(key);
                    removed.insert(key.image_id);
                }
                Err(error) => log::warn!(
                    "could not verify Kitty image {} storage for {pane}: {error}",
                    key.image_id
                ),
            }
        }
        if stale.is_empty() {
            return;
        }
        let mut cache = self.kitty_image_frames.lock();
        for key in stale {
            cache.remove(&key);
        }
        drop(cache);
        let image_ids = removed.into_iter().collect::<Vec<_>>();
        let subscribers = self
            .inner
            .lock()
            .subscribers
            .values()
            .cloned()
            .collect::<Vec<_>>();
        for subscriber in subscribers {
            subscriber.enqueue_kitty_images_removed(pane, &image_ids);
        }
    }

    fn send_resync(&self, client: ClientId, outbound: &OutboundMailbox) {
        let (
            snapshot,
            viewports,
            command_prompt,
            choose_tree,
            choose_buffer,
            display_panes,
            popup,
            menu,
            confirm,
        ) = {
            let inner = self.inner.lock();
            let mut snapshot = inner.engine.state.snapshot();
            let presence = snapshot_presence(&inner);
            stamp_snapshot_for_client(&inner, client, &mut snapshot, &presence);
            let command_prompt = command_prompt_state(&inner, client);
            let choose_tree = inner
                .choose_trees
                .get(&client)
                .map(|chooser| chooser.rendered.clone());
            let choose_buffer = inner
                .choose_buffers
                .get(&client)
                .map(|chooser| chooser.rendered.clone());
            let display_panes = inner
                .display_panes
                .get(&client)
                .map(|overlay| overlay.state.clone());
            let popup = inner.popups.get(&client).map(|popup| {
                (
                    popup.state.clone(),
                    Arc::clone(&popup.terminal),
                    popup
                        .terminal
                        .latest_viewport_for(TerminalViewId(client.0))
                        .unwrap_or_else(|| popup.terminal.latest_viewport()),
                )
            });
            let menu = inner.menus.get(&client).map(|menu| menu.state.clone());
            let confirm = inner
                .confirms
                .get(&client)
                .map(|confirm| confirm.state.clone());
            let session = client_attached_session(&inner, client);
            let view = TerminalViewId(client.0);
            let viewports = session.map_or_else(Vec::new, |session| {
                visible_terminal_panes(&inner, client, session)
                    .into_iter()
                    .filter_map(|pane| {
                        terminal_viewport_for_pane(&inner, pane, view)
                            .map(|(terminal, viewport)| (pane, terminal, (*viewport).clone()))
                    })
                    .collect()
            });
            (
                snapshot,
                viewports,
                command_prompt,
                choose_tree,
                choose_buffer,
                display_panes,
                popup,
                menu,
                confirm,
            )
        };
        Self::send_event(outbound, EventPayload::Snapshot(snapshot));
        Self::send_event(
            outbound,
            EventPayload::CommandPrompt {
                state: command_prompt,
            },
        );
        Self::send_event(
            outbound,
            EventPayload::Popup {
                state: popup.as_ref().map(|(state, _, _)| state.clone()),
            },
        );
        Self::send_event(outbound, EventPayload::Menu { state: menu });
        Self::send_event(outbound, EventPayload::Confirm { state: confirm });
        Self::send_event(outbound, EventPayload::ChooseTree { state: choose_tree });
        Self::send_event(
            outbound,
            EventPayload::ChooseBuffer {
                state: choose_buffer,
            },
        );
        Self::send_event(
            outbound,
            EventPayload::DisplayPanes {
                state: display_panes,
            },
        );
        for (pane, terminal, viewport) in viewports {
            self.enqueue_kitty_images_for_viewport(outbound, pane, &terminal, &viewport);
            let viewport = Self::event(EventPayload::TerminalViewport { pane, viewport });
            if outbound.enqueue_terminal(pane, &viewport) == TerminalEnqueue::NeedsFull {
                let _ = outbound.replace_terminal(pane, &viewport);
            }
        }
        if let Some((state, _terminal, viewport)) = popup {
            let _ = outbound.replace_terminal_viewport(
                state.pane,
                Self::next_sequence(),
                viewport.as_ref(),
            );
        }
        #[cfg(feature = "agent")]
        self.send_agent_resync(client, outbound);
        let inner = self.inner.lock();
        if let Some(output) = inner.command_outputs.get(&client) {
            let message = Self::event(EventPayload::CommandOutput {
                pane: output.pane,
                viewport: output
                    .terminal
                    .latest_viewport_for(TerminalViewId(client.0))
                    .map(|viewport| (*viewport).clone()),
            });
            let _ = outbound.replace_command_output(&message);
        } else {
            Self::send_event(
                outbound,
                EventPayload::CommandOutput {
                    pane: client_context_pane(&inner, client).unwrap_or(PaneId(0)),
                    viewport: None,
                },
            );
        }
    }

    fn send_full(&self, client: ClientId, pane: PaneId, outbound: &OutboundMailbox) {
        let popup = {
            let inner = self.inner.lock();
            inner.popups.get(&client).and_then(|popup| {
                (popup.state.pane == pane).then(|| {
                    popup
                        .terminal
                        .latest_viewport_for(TerminalViewId(client.0))
                        .unwrap_or_else(|| popup.terminal.latest_viewport())
                })
            })
        };
        if let Some(viewport) = popup {
            let _ =
                outbound.replace_terminal_viewport(pane, Self::next_sequence(), viewport.as_ref());
            return;
        }
        let viewport = {
            let inner = self.inner.lock();
            let Some(session) = client_attached_session(&inner, client) else {
                return;
            };
            if !visible_terminal_panes(&inner, client, session).contains(&pane) {
                return;
            }
            let view = TerminalViewId(client.0);
            terminal_viewport_for_pane(&inner, pane, view)
        };
        if let Some((terminal, viewport)) = viewport {
            self.enqueue_kitty_images_for_viewport(outbound, pane, &terminal, &viewport);
            let _ =
                outbound.replace_terminal_viewport(pane, Self::next_sequence(), viewport.as_ref());
        }
    }

    fn send_history(
        &self,
        client: ClientId,
        pane: PaneId,
        start: u32,
        count: u32,
        outbound: &OutboundMailbox,
    ) {
        let terminal = {
            let inner = self.inner.lock();
            let Some(session) = client_attached_session(&inner, client) else {
                return;
            };
            if !visible_terminal_panes(&inner, client, session).contains(&pane) {
                return;
            }
            inner.terminals.get(&pane).cloned()
        };
        let Some(terminal) = terminal else {
            return;
        };
        let Ok((start, rows, dictionary, scrollbar, columns)) =
            terminal.history(start, count.min(MAX_HISTORY_CHUNK_ROWS))
        else {
            return;
        };
        Self::send_event(
            outbound,
            EventPayload::HistoryChunk {
                pane,
                start,
                total: scrollbar.total,
                offset: scrollbar.offset,
                columns,
                rows,
                dictionary,
            },
        );
    }

    fn open_command_output(
        self: &Arc<Self>,
        client: ClientId,
        preferred_pane: Option<PaneId>,
        title: String,
        text: &str,
    ) -> Result<(), DaemonError> {
        if text.is_empty() {
            return Ok(());
        }
        self.close_popup(client, true);
        let text = bounded_command_output(text);
        let (pane, word_separators, terminal_options) = {
            let inner = self.inner.lock();
            if !inner.subscribers.contains_key(&client) {
                return Err(ServerError::InvalidCommand(
                    "command output requires an interactive client".to_owned(),
                )
                .into());
            }
            let pane = preferred_pane
                .filter(|pane| inner.engine.state.window_for_pane(*pane).is_some())
                .or_else(|| client_context_pane(&inner, client))
                .ok_or_else(|| ServerError::MissingTarget("current pane".to_owned()))?;
            (
                pane,
                WordSeparators::new(inner.engine.word_separators_for_pane(pane)?),
                terminal_worker_options(&inner.engine, &inner.appearance, pane)?,
            )
        };
        let terminal = Arc::new(TerminalSession::spawn_output_view_with_appearance(
            title,
            text,
            Arc::clone(&terminal_options.appearance),
        ));
        terminal.set_wrap_search(terminal_options.wrap_search);
        let view = TerminalViewId(client.0);

        let (
            replaced,
            choose_tree_closed,
            choose_buffer_closed,
            display_panes_closed,
            command_prompt_closed,
        ) = {
            let mut inner = self.inner.lock();
            if !inner.subscribers.contains_key(&client) {
                return Err(ServerError::InvalidCommand(
                    "command output requires an interactive client".to_owned(),
                )
                .into());
            }
            if inner.engine.state.window_for_pane(pane).is_none() {
                return Err(ServerError::MissingTarget(pane.to_string()).into());
            }
            let choose_tree_closed = inner.choose_trees.remove(&client).is_some();
            let choose_buffer_closed = inner.choose_buffers.remove(&client).is_some();
            let display_panes_closed = take_display_panes(&mut inner, client).is_some();
            let command_prompt_closed = inner.command_prompts.remove(&client).is_some();
            let replaced = inner.command_outputs.remove(&client);
            let previous_key_table = replaced.as_ref().map_or_else(
                || {
                    inner
                        .key_engines
                        .entry(client)
                        .or_default()
                        .active_table()
                        .map(str::to_owned)
                },
                |output| output.previous_key_table.clone(),
            );
            let table = inner.engine.copy_mode_table_for_pane(pane)?.to_owned();
            inner
                .key_engines
                .entry(client)
                .or_default()
                .switch_table(Some(table));
            inner.command_outputs.insert(
                client,
                CommandOutputSession {
                    pane,
                    terminal: Arc::clone(&terminal),
                    previous_key_table,
                },
            );
            (
                replaced,
                choose_tree_closed,
                choose_buffer_closed,
                display_panes_closed,
                command_prompt_closed,
            )
        };

        terminal.set_word_separators(word_separators);
        terminal.attach_view(view);
        if choose_tree_closed {
            self.publish_to_client(client, EventPayload::ChooseTree { state: None });
        }
        if choose_buffer_closed {
            self.publish_to_client(client, EventPayload::ChooseBuffer { state: None });
        }
        if display_panes_closed {
            self.publish_to_client(client, EventPayload::DisplayPanes { state: None });
        }
        if command_prompt_closed {
            self.publish_to_client(client, EventPayload::CommandPrompt { state: None });
        }
        if let Some(replaced) = replaced {
            replaced.terminal.view_action(
                view,
                zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel),
            );
        }
        if let Err(error) = self.watch_command_output(client, pane, Arc::clone(&terminal)) {
            self.close_command_output(client, &terminal);
            return Err(error);
        }
        Ok(())
    }

    fn watch_command_output(
        self: &Arc<Self>,
        client: ClientId,
        pane: PaneId,
        terminal: Arc<TerminalSession>,
    ) -> Result<(), DaemonError> {
        let events = terminal.events();
        let shared = Arc::clone(self);
        thread::Builder::new()
            .name(format!("zz-output-{}", client.0))
            .spawn(move || {
                while let Ok(event) = events.recv_blocking() {
                    if !shared.is_current_command_output(client, &terminal) {
                        break;
                    }
                    match event {
                        TerminalEvent::ViewportReady => {
                            if let Some(viewport) =
                                terminal.latest_viewport_for(TerminalViewId(client.0))
                            {
                                shared.publish_command_output(client, pane, &terminal, &viewport);
                            }
                        }
                        TerminalEvent::CopyReady { view, copy }
                            if view == TerminalViewId(client.0) =>
                        {
                            let copy = *copy;
                            if let Some(buffer) = copy.buffer {
                                shared.store_copy_buffer(copy.text.clone(), buffer);
                            }
                            if let Some(command) = copy.pipe {
                                shared.spawn_copy_pipe(pane, client, command, copy.text.clone());
                            }
                            if let Some(target) = copy.clipboard {
                                shared.publish_to_client(
                                    client,
                                    EventPayload::Clipboard {
                                        pane,
                                        request_id: copy.request_id,
                                        target,
                                        text: copy.text,
                                    },
                                );
                            }
                        }
                        TerminalEvent::OpenUri(open) if open.view == TerminalViewId(client.0) => {
                            shared.publish_to_client(
                                client,
                                EventPayload::OpenUri {
                                    pane,
                                    uri: open.uri,
                                },
                            );
                        }
                        TerminalEvent::ViewClosed(view) if view == TerminalViewId(client.0) => {
                            shared.close_command_output(client, &terminal);
                            break;
                        }
                        TerminalEvent::CopyReady { .. }
                        | TerminalEvent::OpenUri(_)
                        | TerminalEvent::ViewClosed(_)
                        | TerminalEvent::ClipboardSet { .. }
                        | TerminalEvent::Bell
                        | TerminalEvent::PlaceholderBound { .. }
                        | TerminalEvent::PendingPasteExpired { .. }
                        | TerminalEvent::RawOutputTapClosed { .. } => {}
                    }
                }
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        Ok(())
    }

    fn watch_popup(
        self: &Arc<Self>,
        client: ClientId,
        terminal: &Arc<TerminalSession>,
    ) -> Result<(), DaemonError> {
        let events = terminal.events();
        let terminal = Arc::downgrade(terminal);
        let shared = Arc::clone(self);
        thread::Builder::new()
            .name(format!("zz-popup-{}", client.0))
            .spawn(move || {
                let mut previous = None::<Arc<TerminalViewport>>;
                let mut diff_scratch = TerminalDiffScratch::default();
                while let Ok(event) = events.recv_blocking() {
                    let Some(terminal) = terminal.upgrade() else {
                        return;
                    };
                    if !shared.is_current_popup(client, &terminal) {
                        return;
                    }
                    match event {
                        TerminalEvent::ViewportReady => {
                            let viewport = terminal
                                .latest_viewport_for(TerminalViewId(client.0))
                                .unwrap_or_else(|| terminal.latest_viewport());
                            let payload = previous
                                .as_ref()
                                .and_then(|previous| {
                                    TerminalViewport::diff_with_scratch(
                                        previous,
                                        &viewport,
                                        &mut diff_scratch,
                                    )
                                })
                                .map_or_else(|| TerminalFanout::Full, TerminalFanout::Patch);
                            shared.publish_popup_terminal(client, &terminal, payload, &viewport);
                            previous = Some(viewport);
                            if let Some(exit_code) = popup_exit_code(&terminal) {
                                shared.finish_popup(client, &terminal, exit_code);
                                return;
                            }
                        }
                        TerminalEvent::ClipboardSet { target, text } => {
                            let pane = shared
                                .inner
                                .lock()
                                .popups
                                .get(&client)
                                .map(|popup| popup.state.pane);
                            if let Some(pane) = pane {
                                shared.publish_to_client(
                                    client,
                                    EventPayload::Clipboard {
                                        pane,
                                        request_id: 0,
                                        target,
                                        text,
                                    },
                                );
                            }
                        }
                        TerminalEvent::OpenUri(open) if open.view == TerminalViewId(client.0) => {
                            let pane = shared
                                .inner
                                .lock()
                                .popups
                                .get(&client)
                                .map(|popup| popup.state.pane);
                            if let Some(pane) = pane {
                                shared.publish_to_client(
                                    client,
                                    EventPayload::OpenUri {
                                        pane,
                                        uri: open.uri,
                                    },
                                );
                            }
                        }
                        TerminalEvent::CopyReady { view, copy }
                            if view == TerminalViewId(client.0) =>
                        {
                            let copy = *copy;
                            if let Some(buffer) = copy.buffer {
                                shared.store_copy_buffer(copy.text.clone(), buffer);
                            }
                            if let Some(target) = copy.clipboard
                                && let Some(pane) = shared
                                    .inner
                                    .lock()
                                    .popups
                                    .get(&client)
                                    .map(|popup| popup.state.pane)
                            {
                                shared.publish_to_client(
                                    client,
                                    EventPayload::Clipboard {
                                        pane,
                                        request_id: copy.request_id,
                                        target,
                                        text: copy.text,
                                    },
                                );
                            }
                        }
                        TerminalEvent::ViewClosed(_)
                        | TerminalEvent::CopyReady { .. }
                        | TerminalEvent::OpenUri(_)
                        | TerminalEvent::Bell
                        | TerminalEvent::PlaceholderBound { .. }
                        | TerminalEvent::PendingPasteExpired { .. }
                        | TerminalEvent::RawOutputTapClosed { .. } => {}
                    }
                }
                let Some(terminal) = terminal.upgrade() else {
                    return;
                };
                if let Some(exit_code) = popup_exit_code(&terminal) {
                    shared.finish_popup(client, &terminal, exit_code);
                }
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        Ok(())
    }

    fn is_current_popup(&self, client: ClientId, terminal: &Arc<TerminalSession>) -> bool {
        self.inner
            .lock()
            .popups
            .get(&client)
            .is_some_and(|popup| Arc::ptr_eq(&popup.terminal, terminal))
    }

    fn publish_popup_terminal(
        &self,
        client: ClientId,
        terminal: &Arc<TerminalSession>,
        payload: TerminalFanout,
        viewport: &TerminalViewport,
    ) {
        let (pane, subscriber) = {
            let inner = self.inner.lock();
            let Some(popup) = inner.popups.get(&client) else {
                return;
            };
            if !Arc::ptr_eq(&popup.terminal, terminal) {
                return;
            }
            (popup.state.pane, inner.subscribers.get(&client).cloned())
        };
        let Some(subscriber) = subscriber else {
            return;
        };
        let sequence = Self::next_sequence();
        let result = match payload {
            TerminalFanout::Full => subscriber.enqueue_terminal_viewport(pane, sequence, viewport),
            TerminalFanout::Patch(patch) => subscriber.enqueue_terminal(
                pane,
                &ProtocolMessage::Event(Event {
                    sequence,
                    payload: EventPayload::TerminalPatch { pane, patch },
                }),
            ),
        };
        if result == TerminalEnqueue::NeedsFull {
            let _ = subscriber.replace_terminal_viewport(pane, Self::next_sequence(), viewport);
        }
    }

    fn finish_popup(&self, client: ClientId, terminal: &Arc<TerminalSession>, exit_code: u8) {
        let outcome = {
            let mut inner = self.inner.lock();
            let Some(popup) = inner.popups.get_mut(&client) else {
                return;
            };
            if !Arc::ptr_eq(&popup.terminal, terminal) {
                return;
            }
            popup.state.dead = true;
            if popup.state.close_on_exit || popup.state.close_on_exit_zero && exit_code == 0 {
                take_popup(&mut inner, client).map(EitherPopupFinish::Closed)
            } else {
                Some(EitherPopupFinish::Retained(popup.state.clone()))
            }
        };
        match outcome {
            Some(EitherPopupFinish::Closed(popup)) => Self::retire_popup(client, popup, false),
            Some(EitherPopupFinish::Retained(state)) => {
                self.publish_to_client(client, EventPayload::Popup { state: Some(state) });
            }
            None => {}
        }
    }

    fn close_popup(&self, client: ClientId, terminate: bool) {
        let popup = take_popup(&mut self.inner.lock(), client);
        if let Some(popup) = popup {
            Self::retire_popup(client, popup, terminate);
        }
    }

    fn retire_popup(client: ClientId, (mut popup, subscriber): RetiredPopup, terminate: bool) {
        let exit_code = popup_exit_code(&popup.terminal);
        if terminate && exit_code.is_none() {
            popup.terminal.terminate();
        }
        popup.terminal.release_view(TerminalViewId(client.0));
        if let Some(subscriber) = subscriber {
            subscriber.suspend_terminal(popup.state.pane);
            Self::send_event(&subscriber, EventPayload::Popup { state: None });
        }
        if let Some(waiter) = popup.waiter.take() {
            let _ = waiter.wake.try_send(exit_code.unwrap_or(129));
        }
    }

    fn publish_command_output(
        &self,
        client: ClientId,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
        viewport: &TerminalViewport,
    ) {
        self.publish_command_output_with_encoder(
            client,
            pane,
            terminal,
            viewport,
            OutboundMailbox::encode_message,
        );
    }

    fn publish_command_output_with_encoder(
        &self,
        client: ClientId,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
        viewport: &TerminalViewport,
        encode: impl FnOnce(&OutboundMailbox, &ProtocolMessage) -> Result<Vec<u8>, ProtocolError>,
    ) {
        let subscriber = {
            let inner = self.inner.lock();
            current_command_output_subscriber(&inner, client, pane, terminal)
        };
        let Some(subscriber) = subscriber else {
            return;
        };
        let message = Self::event(EventPayload::CommandOutput {
            pane,
            viewport: Some(viewport.clone()),
        });
        let Ok(encoded) = encode(&subscriber, &message) else {
            log::error!("failed to encode command-output viewport");
            return;
        };

        let mut encoded = Some(encoded);
        let installed = {
            let inner = self.inner.lock();
            current_command_output_subscriber(&inner, client, pane, terminal)
                .filter(|current| Arc::ptr_eq(current, &subscriber))
                .is_some_and(|_| {
                    subscriber.replace_encoded_command_output(
                        encoded.take().expect("encoded command output is available"),
                    )
                })
        };
        if !installed && let Some(encoded) = encoded {
            subscriber.recycle_frame(encoded);
        }
    }

    fn close_command_output(&self, client: ClientId, terminal: &Arc<TerminalSession>) {
        let (pane, subscriber) = {
            let mut inner = self.inner.lock();
            let Some(output) = inner.command_outputs.get(&client) else {
                return;
            };
            if !Arc::ptr_eq(&output.terminal, terminal) {
                return;
            }
            let output = inner
                .command_outputs
                .remove(&client)
                .expect("command output was checked above");
            inner
                .key_engines
                .entry(client)
                .or_default()
                .switch_table(output.previous_key_table);
            (output.pane, inner.subscribers.get(&client).cloned())
        };
        if let Some(subscriber) = subscriber {
            Self::send_event(
                &subscriber,
                EventPayload::CommandOutput {
                    pane,
                    viewport: None,
                },
            );
        }
    }

    fn retire_command_output(client: ClientId, (output, subscriber): RetiredCommandOutput) {
        output.terminal.view_action(
            TerminalViewId(client.0),
            zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel),
        );
        if let Some(subscriber) = subscriber {
            Self::send_event(
                &subscriber,
                EventPayload::CommandOutput {
                    pane: output.pane,
                    viewport: None,
                },
            );
        }
    }

    fn is_current_command_output(&self, client: ClientId, terminal: &Arc<TerminalSession>) -> bool {
        self.inner
            .lock()
            .command_outputs
            .get(&client)
            .is_some_and(|output| Arc::ptr_eq(&output.terminal, terminal))
    }

    fn watch_terminal(
        self: &Arc<Self>,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
    ) -> Result<(), DaemonError> {
        let events = terminal.events();
        let terminal = Arc::downgrade(terminal);
        let shared = Arc::clone(self);
        thread::Builder::new()
            .name(format!("zz-pane-{}", pane.0))
            .spawn(move || {
                let mut previous = BTreeMap::<TerminalViewId, Arc<TerminalViewport>>::new();
                let mut previous_title = None::<String>;
                let mut previous_foreground = None::<Option<u32>>;
                let mut current_command = String::new();
                let mut diff_scratch = TerminalDiffScratch::default();
                while let Ok(event) = events.recv_blocking() {
                    let Some(terminal) = terminal.upgrade() else {
                        break;
                    };
                    if !shared.is_current_terminal(pane, &terminal) {
                        break;
                    }
                    match event {
                        TerminalEvent::ViewportReady => {
                            let mut current =
                                terminal.latest_viewports().into_iter().collect::<Vec<_>>();
                            current.sort_by_key(|(view, _)| view.0);
                            let runtime_viewport = current.first().map_or_else(
                                || terminal.latest_viewport(),
                                |(_, viewport)| Arc::clone(viewport),
                            );
                            if !terminal_status_should_close(&runtime_viewport.status) {
                                let foreground = terminal.foreground_process_id();
                                if previous_foreground != Some(foreground) {
                                    current_command = terminal_current_command(&terminal);
                                    previous_foreground = Some(foreground);
                                }
                                shared.synchronize_pane_runtime(
                                    pane,
                                    &terminal,
                                    &runtime_viewport,
                                    &current_command,
                                );
                            }
                            let referenced_images = current
                                .iter()
                                .flat_map(|(_, viewport)| {
                                    viewport.kitty_placements.iter().map(|placement| {
                                        (placement.image_id, placement.image_generation)
                                    })
                                })
                                .collect::<BTreeSet<_>>();
                            shared.evict_absent_kitty_images(pane, &terminal, &referenced_images);
                            for (image_id, generation) in &referenced_images {
                                let _ = shared.kitty_image_frames(
                                    pane,
                                    &terminal,
                                    *image_id,
                                    *generation,
                                );
                            }
                            let active = current
                                .iter()
                                .map(|(view, _)| *view)
                                .collect::<BTreeSet<_>>();
                            let mut finished = false;
                            if active.is_empty() {
                                let viewport = terminal.latest_viewport();
                                if previous_title
                                    .as_deref()
                                    .is_none_or(|previous| previous != viewport.title())
                                {
                                    shared.synchronize_pane_title(
                                        pane,
                                        &terminal,
                                        viewport.title(),
                                    );
                                    previous_title = Some(viewport.title().to_owned());
                                }
                                finished = terminal_status_should_close(&viewport.status);
                            }
                            for (view, viewport) in current {
                                if previous_title
                                    .as_deref()
                                    .is_none_or(|previous| previous != viewport.title())
                                {
                                    shared.synchronize_pane_title(
                                        pane,
                                        &terminal,
                                        viewport.title(),
                                    );
                                    previous_title = Some(viewport.title().to_owned());
                                }
                                finished |= terminal_status_should_close(&viewport.status);
                                let payload = previous
                                    .get(&view)
                                    .and_then(|previous| {
                                        TerminalViewport::diff_with_scratch(
                                            previous,
                                            &viewport,
                                            &mut diff_scratch,
                                        )
                                    })
                                    .map_or_else(|| TerminalFanout::Full, TerminalFanout::Patch);
                                shared.publish_terminal_for_pane(
                                    pane,
                                    ClientId(view.0),
                                    payload,
                                    &viewport,
                                    &terminal,
                                );
                                previous.insert(view, viewport);
                            }
                            previous.retain(|view, _| active.contains(view));
                            if finished {
                                shared.close_exited_terminal(pane, &terminal);
                                return;
                            }
                        }
                        TerminalEvent::CopyReady { view, copy } => {
                            let client = ClientId(view.0);
                            let copy = *copy;
                            if let Some(buffer) = copy.buffer {
                                shared.store_copy_buffer(copy.text.clone(), buffer);
                            }
                            if let Some(command) = copy.pipe {
                                shared.spawn_copy_pipe(pane, client, command, copy.text.clone());
                            }
                            if let Some(target) = copy.clipboard {
                                shared.publish_to_client(
                                    client,
                                    EventPayload::Clipboard {
                                        pane,
                                        request_id: copy.request_id,
                                        target,
                                        text: copy.text,
                                    },
                                );
                            }
                        }
                        TerminalEvent::OpenUri(open) => {
                            shared.publish_to_client(
                                ClientId(open.view.0),
                                EventPayload::OpenUri {
                                    pane,
                                    uri: open.uri,
                                },
                            );
                        }
                        TerminalEvent::PlaceholderBound { token, number } => {
                            shared.bind_pasted_image(pane, &terminal, token, number);
                        }
                        TerminalEvent::PendingPasteExpired { token } => {
                            shared.expire_pending_pasted_image(pane, &terminal, token);
                        }
                        TerminalEvent::RawOutputTapClosed { token } => {
                            if !shared.control_output_tap_closed(pane, token, &terminal) {
                                shared.pipe_tap_closed(pane, token, &terminal);
                            }
                        }
                        TerminalEvent::ClipboardSet { target, text } => {
                            shared.deliver_clipboard_write(pane, target, text);
                        }
                        TerminalEvent::Bell => shared.raise_pane_bell(pane),
                        TerminalEvent::ViewClosed(_) => {}
                    }
                }
                let Some(terminal) = terminal.upgrade() else {
                    return;
                };
                if terminal_status_should_close(&terminal.latest_viewport().status) {
                    shared.close_exited_terminal(pane, &terminal);
                }
            })
            .map_err(|error| DaemonError::Thread(error.to_string()))?;
        Ok(())
    }

    fn close_exited_terminal(self: &Arc<Self>, pane: PaneId, terminal: &Arc<TerminalSession>) {
        let status = terminal.latest_viewport().status.clone();
        let (failed, dead_status, dead_signal) = match status {
            zz_terminal::SessionStatus::Exited(status) => {
                let failed = status.code != 0 || status.signal.is_some();
                let dead_status = status.signal.is_none().then_some(status.code);
                (failed, dead_status, status.signal.clone())
            }
            zz_terminal::SessionStatus::Failed(_) => (true, None, None),
            zz_terminal::SessionStatus::Starting | zz_terminal::SessionStatus::Running => return,
        };
        let pipe = {
            let mut inner = self.inner.lock();
            inner
                .terminals
                .get(&pane)
                .is_some_and(|current| Arc::ptr_eq(current, terminal))
                .then(|| inner.pane_pipes.remove(&pane))
                .flatten()
        };
        if let Some(pipe) = pipe {
            stop_pane_pipe(pipe);
        }
        let Some((mut context, retained, changed, mut events, before)) = ({
            let mut inner = self.inner.lock();
            if !inner
                .terminals
                .get(&pane)
                .is_some_and(|current| Arc::ptr_eq(current, terminal))
            {
                return;
            }
            let Some(context) = ExecutionContext::for_pane(&inner.engine.state, pane) else {
                return;
            };
            let before = MuxHookSnapshot::capture(&inner.engine);
            let retained = inner
                .engine
                .retain_exited_pane(pane, failed)
                .unwrap_or(false);
            let changed = if retained {
                let facts = format_hook_facts(&inner);
                let mut hooks = DaemonFormatHooks::command(&facts);
                inner
                    .engine
                    .mark_pane_dead_with_hooks(
                        pane,
                        dead_status,
                        dead_signal.as_deref(),
                        &mut hooks,
                    )
                    .unwrap_or(false)
            } else {
                false
            };
            let mut events = if retained {
                let after = MuxHookSnapshot::capture(&inner.engine);
                let mut events = mux_hook_events(&before, &after, "");
                if changed && let Some(state) = after.panes.get(&pane) {
                    events.push(PendingHookEvent::pane("pane-died", pane, state, &after));
                }
                events
            } else {
                before.panes.get(&pane).map_or_else(Vec::new, |state| {
                    vec![PendingHookEvent::pane("pane-exited", pane, state, &before)]
                })
            };
            if !changed && retained {
                events.clear();
            }
            Some((context, retained, changed, events, before))
        }) else {
            return;
        };

        if retained {
            log::debug!(
                target: "zz_daemon::diagnostics::terminal",
                "terminal worker finished pane={pane}; retaining dead pane"
            );
            if changed {
                self.publish_snapshot();
            }
            self.run_event_hooks(events);
            return;
        }

        log::debug!(
            target: "zz_daemon::diagnostics::terminal",
            "terminal worker finished pane={pane}; closing pane"
        );
        let target = pane.to_string();
        let command = CommandInvocation::new("kill-pane", ["-t", target.as_str()]);
        context.no_hooks = true;
        let result = self.execute(
            ClientId(u64::MAX),
            ClientKind::Command,
            &mut context,
            &command,
        );
        if let Err(error) = &result
            && self.is_current_terminal(pane, terminal)
        {
            log::error!(
                target: "zz_daemon::diagnostics::terminal",
                "failed to close exited terminal pane={pane}: {error}"
            );
        }
        if result.is_ok() {
            let after = MuxHookSnapshot::capture(&self.inner.lock().engine);
            events.extend(mux_hook_events(&before, &after, ""));
        }
        if result.is_ok() || !self.is_current_terminal(pane, terminal) {
            self.run_event_hooks(events);
        }
    }

    fn is_current_terminal(&self, pane: PaneId, terminal: &Arc<TerminalSession>) -> bool {
        self.inner
            .lock()
            .terminals
            .get(&pane)
            .is_some_and(|current| Arc::ptr_eq(current, terminal))
    }

    fn synchronize_pane_title(
        self: &Arc<Self>,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
        title: &str,
    ) {
        let event = {
            let mut inner = self.inner.lock();
            if !inner
                .terminals
                .get(&pane)
                .is_some_and(|current| Arc::ptr_eq(current, terminal))
            {
                return;
            }
            if !inner.engine.allow_set_title(pane) {
                return;
            }
            let changed = inner
                .engine
                .state
                .update_pane_title(pane, title)
                .unwrap_or(false);
            changed.then(|| {
                let snapshot = MuxHookSnapshot::capture(&inner.engine);
                PendingHookEvent::pane(
                    "pane-title-changed",
                    pane,
                    &snapshot.panes[&pane],
                    &snapshot,
                )
            })
        };
        if let Some(event) = event {
            self.publish_snapshot();
            self.run_event_hooks(vec![event]);
        }
    }

    fn synchronize_pane_runtime(
        self: &Arc<Self>,
        pane: PaneId,
        terminal: &Arc<TerminalSession>,
        viewport: &TerminalViewport,
        current_command: &str,
    ) {
        let current_path = terminal_working_directory(terminal)
            .map(|path| path.to_string_lossy().into_owned())
            .unwrap_or_default();
        let reported_path = viewport.working_directory().unwrap_or_default().to_owned();
        let pid = terminal.process_id();
        let tty = terminal
            .tty()
            .map(|path| path.to_string_lossy().into_owned())
            .unwrap_or_default();
        let (changed, events) = {
            let mut inner = self.inner.lock();
            if !inner
                .terminals
                .get(&pane)
                .is_some_and(|current| Arc::ptr_eq(current, terminal))
            {
                return;
            }
            let previous = inner
                .engine
                .pane_runtime_facts(pane)
                .cloned()
                .unwrap_or_default();
            let facts = format_hook_facts(&inner);
            let mut hooks = DaemonFormatHooks::command(&facts);
            let before = MuxHookSnapshot::capture(&inner.engine);
            let changed = inner.engine.set_pane_runtime_facts_with_hooks(
                pane,
                PaneRuntimeFacts {
                    current_command: current_command.to_owned(),
                    current_path,
                    dead_signal: previous.dead_signal,
                    reported_path,
                    start_path: previous.start_path,
                    pid,
                    tty,
                },
                &mut hooks,
            );
            let after = MuxHookSnapshot::capture(&inner.engine);
            (changed, mux_hook_events(&before, &after, ""))
        };
        if changed {
            self.publish_snapshot();
        }
        self.run_event_hooks(events);
    }

    fn detach_removed_sessions(&self) {
        let detached = {
            let inner = self.inner.lock();
            inner
                .attached
                .iter()
                .filter(|(session, _)| !inner.engine.state.sessions.contains_key(session))
                .flat_map(|(session, clients)| clients.iter().map(|client| (*session, *client)))
                .collect::<Vec<_>>()
        };
        for (session, client) in detached {
            self.publish_to_client(client, EventPayload::Detached { session, by: None });
            let _ = self.detach_client_state(client, false);
        }
    }

    fn publish_snapshot(&self) {
        self.detach_removed_sessions();
        let snapshots = {
            let mut inner = self.inner.lock();
            let snapshot = inner.engine.state.snapshot();
            inner.last_published_mux_generation = snapshot.generation;
            let presence = snapshot_presence(&inner);
            inner
                .subscribers
                .iter()
                .map(|(client, subscriber)| {
                    let mut client_snapshot = snapshot.clone();
                    stamp_snapshot_for_client(&inner, *client, &mut client_snapshot, &presence);
                    (*client, Arc::clone(subscriber), client_snapshot)
                })
                .collect::<Vec<_>>()
        };
        for (_, subscriber, snapshot) in snapshots {
            Self::send_event(&subscriber, EventPayload::Snapshot(snapshot));
        }
        self.refresh_status(false);
        self.refresh_terminal_visibility();
        #[cfg(feature = "agent")]
        self.refresh_agent_visibility();
        self.refresh_choose_trees();
        self.refresh_choose_buffers();
        self.refresh_display_panes();
    }

    fn refresh_choose_trees(&self) {
        let updates = {
            let mut inner = self.inner.lock();
            let clients = inner.choose_trees.keys().copied().collect::<Vec<_>>();
            let mut updates = Vec::with_capacity(clients.len());
            for client in clients {
                let Some(mut chooser) = inner.choose_trees.remove(&client) else {
                    continue;
                };
                let attached_session = client_attached_session(&inner, client);
                let source_session = inner
                    .engine
                    .state
                    .window_for_pane(chooser.source_pane)
                    .map(|window| inner.engine.state.windows[&window].session);
                if attached_session != Some(chooser.source_session)
                    || source_session != Some(chooser.source_session)
                {
                    updates.push((client, None));
                    continue;
                }
                chooser.rebuild(&inner.engine.state, attached_session);
                let state = chooser.rendered.clone();
                inner.choose_trees.insert(client, chooser);
                updates.push((client, Some(state)));
            }
            updates
        };
        for (client, state) in updates {
            self.publish_to_client(client, EventPayload::ChooseTree { state });
        }
    }

    fn refresh_choose_buffers(&self) {
        self.refresh_choose_buffers_except(None);
    }

    fn refresh_choose_buffers_except(&self, excluded: Option<ClientId>) {
        let updates = {
            let mut inner = self.inner.lock();
            let clients = inner
                .choose_buffers
                .keys()
                .copied()
                .filter(|client| Some(*client) != excluded)
                .collect::<Vec<_>>();
            let mut updates = Vec::with_capacity(clients.len());
            for client in clients {
                let Some(mut chooser) = inner.choose_buffers.remove(&client) else {
                    continue;
                };
                let attached_session = client_attached_session(&inner, client);
                let source_session = inner
                    .engine
                    .state
                    .window_for_pane(chooser.source_pane)
                    .map(|window| inner.engine.state.windows[&window].session);
                if attached_session != Some(chooser.source_session)
                    || source_session != Some(chooser.source_session)
                    || inner.paste_buffers.is_empty()
                {
                    updates.push((client, None));
                    continue;
                }
                chooser.rebuild(&inner.paste_buffers);
                let state = chooser.rendered.clone();
                inner.choose_buffers.insert(client, chooser);
                updates.push((client, Some(state)));
            }
            updates
        };
        for (client, state) in updates {
            self.publish_to_client(client, EventPayload::ChooseBuffer { state });
        }
    }

    fn refresh_display_panes(&self) {
        let updates = {
            let mut inner = self.inner.lock();
            let clients = inner.display_panes.keys().copied().collect::<Vec<_>>();
            let mut updates = Vec::with_capacity(clients.len());
            for client in clients {
                let Some(mut overlay) = inner.display_panes.remove(&client) else {
                    continue;
                };
                let attached_session = client_attached_session(&inner, client);
                let active_window = client_focused_window_for_attachment(&inner, client);
                let rebuilt = build_display_panes_state(
                    &inner.engine,
                    overlay.source_pane,
                    overlay.state.duration_ms,
                );
                let Ok((source_session, source_window, state)) = rebuilt else {
                    overlay.cancel_deadline(client);
                    updates.push((client, None));
                    continue;
                };
                if attached_session != Some(overlay.source_session)
                    || source_session != overlay.source_session
                    || source_window != overlay.source_window
                    || active_window != Some(overlay.source_window)
                {
                    overlay.cancel_deadline(client);
                    updates.push((client, None));
                    continue;
                }
                if overlay.state != state {
                    overlay.state = state.clone();
                    updates.push((client, Some(state)));
                }
                inner.display_panes.insert(client, overlay);
            }
            updates
        };
        for (client, state) in updates {
            self.publish_to_client(client, EventPayload::DisplayPanes { state });
        }
    }

    fn refresh_terminal_visibility(&self) {
        let (changes, resizes) = {
            let mut inner = self.inner.lock();
            let attachments = inner
                .attached
                .iter()
                .flat_map(|(session, clients)| clients.iter().map(|client| (*session, *client)))
                .collect::<Vec<_>>();
            let mut changes = Vec::new();
            let mut affected_panes = BTreeSet::new();
            for (session, client) in attachments {
                let next = visible_terminal_panes(&inner, client, session);
                let previous = inner
                    .visible_terminals
                    .get(&client)
                    .cloned()
                    .unwrap_or_default();
                if next == previous {
                    continue;
                }
                affected_panes.extend(previous.iter().copied());
                affected_panes.extend(next.iter().copied());
                let removed = previous.difference(&next).copied().collect::<Vec<_>>();
                let view = TerminalViewId(client.0);
                let newly_visible = next
                    .difference(&previous)
                    .filter_map(|pane| {
                        terminal_viewport_for_pane(&inner, *pane, view)
                            .map(|(terminal, viewport)| (*pane, terminal, (*viewport).clone()))
                    })
                    .collect::<Vec<_>>();
                if let Some(subscriber) = inner.subscribers.get(&client).cloned() {
                    changes.push((subscriber, removed, newly_visible));
                }
                inner.visible_terminals.insert(client, next);
            }
            let resizes = terminal_resizes_for_panes(&inner, &affected_panes);
            (changes, resizes)
        };

        for (subscriber, removed, newly_visible) in changes {
            for pane in removed {
                subscriber.suspend_terminal(pane);
            }
            for (pane, terminal, viewport) in newly_visible {
                self.enqueue_kitty_images_for_viewport(&subscriber, pane, &terminal, &viewport);
                let message = Self::event(EventPayload::TerminalViewport { pane, viewport });
                if subscriber.enqueue_terminal(pane, &message) == TerminalEnqueue::NeedsFull {
                    let _ = subscriber.replace_terminal(pane, &message);
                }
            }
        }
        apply_terminal_resizes(resizes);
    }

    fn publish(&self, payload: EventPayload) {
        if let EventPayload::PaneRemoved(pane) = &payload {
            self.kitty_image_frames
                .lock()
                .retain(|key, _| key.pane != *pane);
            self.pasted_images.lock().remove(pane);
        }
        let message = Self::event(payload);
        let subscribers = self
            .inner
            .lock()
            .subscribers
            .values()
            .cloned()
            .collect::<Vec<_>>();
        for subscriber in subscribers {
            let _ = subscriber.enqueue_reliable(&message);
        }
    }

    fn publish_to_control_clients(
        &self,
        payload: EventPayload,
        exclude: Option<ClientId>,
        attached_only: bool,
    ) {
        let message = Self::event(payload);
        let subscribers = {
            let inner = self.inner.lock();
            inner
                .subscribers
                .iter()
                .filter(|(client, _)| {
                    inner.client_kinds.get(client) == Some(&ClientKind::Control)
                        && Some(**client) != exclude
                        && (!attached_only
                            || inner
                                .attached
                                .values()
                                .any(|attached| attached.contains(client)))
                })
                .map(|(_, subscriber)| Arc::clone(subscriber))
                .collect::<Vec<_>>()
        };
        for subscriber in subscribers {
            let _ = subscriber.enqueue_reliable(&message);
        }
    }

    fn publish_to_client(&self, client: ClientId, payload: EventPayload) {
        let subscriber = self.inner.lock().subscribers.get(&client).cloned();
        if let Some(subscriber) = subscriber {
            Self::send_event(&subscriber, payload);
        }
    }

    fn next_gui_request_id() -> u64 {
        static REQUESTS: AtomicU64 = AtomicU64::new(1);
        REQUESTS.fetch_add(1, Ordering::Relaxed)
    }

    fn request_from_gui(
        &self,
        pane: PaneId,
        payload: impl FnOnce(u64) -> EventPayload,
    ) -> Result<String, DaemonError> {
        let request_id = Self::next_gui_request_id();
        let (reply, response) = crossbeam_channel::bounded(1);
        let subscriber = {
            let mut inner = self.inner.lock();
            let window = inner
                .engine
                .state
                .window_for_pane(pane)
                .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
            let session = inner.engine.state.windows[&window].session;
            let client = inner
                .attached
                .get(&session)
                .and_then(|clients| {
                    clients.iter().find(|client| {
                        inner.client_kinds.get(client) == Some(&ClientKind::Interactive)
                    })
                })
                .copied()
                .ok_or(ServerError::PaneNotAttached(pane))?;
            let subscriber = inner
                .subscribers
                .get(&client)
                .cloned()
                .ok_or(ServerError::PaneNotAttached(pane))?;
            inner
                .pending_gui_requests
                .insert(request_id, PendingGuiRequest { client, reply });
            subscriber
        };
        let message = Self::event(payload(request_id));
        if !subscriber.enqueue_reliable(&message) {
            self.inner.lock().pending_gui_requests.remove(&request_id);
            return Err(ServerError::PaneNotAttached(pane).into());
        }
        let outcome = response.recv_timeout(GUI_REQUEST_TIMEOUT);
        self.inner.lock().pending_gui_requests.remove(&request_id);
        match outcome {
            Ok(Ok(output)) => Ok(output),
            Ok(Err(message)) => Err(ServerError::InvalidCommand(message).into()),
            Err(_) => Err(ServerError::Internal(format!(
                "the zz window did not answer within {} seconds",
                GUI_REQUEST_TIMEOUT.as_secs()
            ))
            .into()),
        }
    }

    fn complete_gui_request(&self, client: ClientId, response: GuiResponse) {
        let request_id = response.request_id();
        let Some(pending) = self.inner.lock().pending_gui_requests.remove(&request_id) else {
            return;
        };
        if pending.client != client {
            log::warn!(
                target: "zz_daemon::diagnostics::connection",
                "discarding GUI response for request={request_id} from client={client}; owner is {}",
                pending.client,
            );
            return;
        }
        let _ = pending.reply.try_send(match response {
            GuiResponse::Success { output, .. } => Ok(output),
            GuiResponse::Error { message, .. } => Err(message),
        });
    }

    fn fail_gui_requests_for(&self, client: ClientId) {
        let pending = {
            let mut inner = self.inner.lock();
            let ids = inner
                .pending_gui_requests
                .iter()
                .filter_map(|(id, request)| (request.client == client).then_some(*id))
                .collect::<Vec<_>>();
            ids.into_iter()
                .filter_map(|id| inner.pending_gui_requests.remove(&id))
                .collect::<Vec<_>>()
        };
        for request in pending {
            let _ = request
                .reply
                .try_send(Err("the zz window disconnected".to_owned()));
        }
    }

    fn publish_for_pane(&self, pane: PaneId, payload: &EventPayload) {
        let subscribers = {
            let inner = self.inner.lock();
            let Some(window) = inner.engine.state.window_for_pane(pane) else {
                return;
            };
            let session = inner.engine.state.windows[&window].session;
            inner
                .attached
                .get(&session)
                .into_iter()
                .flatten()
                .filter_map(|client| inner.subscribers.get(client).cloned())
                .collect::<Vec<_>>()
        };
        for subscriber in subscribers {
            Self::send_event(&subscriber, payload.clone());
        }
    }

    fn publish_terminal_for_pane(
        self: &Arc<Self>,
        pane: PaneId,
        client: ClientId,
        payload: TerminalFanout,
        current: &TerminalViewport,
        terminal: &TerminalSession,
    ) {
        let (subscriber, unclaimed, mode_event) = {
            let mut inner = self.inner.lock();
            let (unclaimed, mode_changed) =
                reconcile_copy_session(&mut inner, pane, client, current.mode);
            let subscriber = inner
                .engine
                .state
                .window_for_pane(pane)
                .map(|window| inner.engine.state.windows[&window].session)
                .filter(|session| {
                    inner
                        .attached
                        .get(session)
                        .is_some_and(|clients| clients.contains(&client))
                        && inner
                            .visible_terminals
                            .get(&client)
                            .is_some_and(|visible| visible.contains(&pane))
                })
                .and_then(|_| inner.subscribers.get(&client).cloned());
            let mode_event = mode_changed
                .then(|| MuxHookSnapshot::capture(&inner.engine))
                .and_then(|snapshot| {
                    snapshot.panes.get(&pane).map(|state| {
                        PendingHookEvent::pane("pane-mode-changed", pane, state, &snapshot)
                    })
                });
            (subscriber, unclaimed, mode_event)
        };
        if let Some(terminal) = unclaimed {
            terminal.view_action(
                TerminalViewId(client.0),
                zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel),
            );
        }
        if let Some(subscriber) = subscriber {
            self.enqueue_kitty_images_for_viewport(&subscriber, pane, terminal, current);
            let sequence = Self::next_sequence();
            let result = match payload {
                TerminalFanout::Full => {
                    subscriber.enqueue_terminal_viewport(pane, sequence, current)
                }
                TerminalFanout::Patch(patch) => {
                    let message = ProtocolMessage::Event(Event {
                        sequence,
                        payload: EventPayload::TerminalPatch { pane, patch },
                    });
                    subscriber.enqueue_terminal(pane, &message)
                }
            };
            if result == TerminalEnqueue::NeedsFull {
                let _ = subscriber.replace_terminal_viewport(pane, Self::next_sequence(), current);
            }
        }
        if let Some(event) = mode_event {
            self.run_event_hooks(vec![event]);
        }
    }

    fn deliver_clipboard_write(
        self: &Arc<Self>,
        pane: PaneId,
        target: ClipboardTarget,
        text: String,
    ) {
        let set_clipboard = self
            .inner
            .lock()
            .engine
            .mux_option_value(MuxOptionKey::SetClipboard);
        match set_clipboard.as_str() {
            "off" => return,
            "on" => {
                self.store_copy_buffer(text.clone(), PasteBufferAction::Create { prefix: None });
            }
            _ => {}
        }
        self.publish_for_pane(
            pane,
            &EventPayload::Clipboard {
                pane,
                request_id: 0,
                target,
                text,
            },
        );
    }

    fn raise_pane_bell(self: &Arc<Self>, pane: PaneId) {
        let (snapshot_changed, clear_terminal, hook, notifications) = {
            let mut inner = self.inner.lock();
            let Some(window) = inner.engine.state.window_for_pane(pane) else {
                return;
            };
            let Some(window_state) = inner.engine.state.windows.get(&window) else {
                return;
            };
            let session = window_state.session;
            let window_index = window_state.index;
            let current = inner.engine.state.sessions[&session].active_window == window;
            let attached = inner
                .attached
                .get(&session)
                .is_some_and(|clients| !clients.is_empty());
            let suppressed = current && attached;
            let snapshot_changed = if suppressed {
                false
            } else {
                inner.engine.state.set_pane_bell(pane, true)
            };
            let clear_terminal = suppressed
                .then(|| inner.terminals.get(&pane).cloned())
                .flatten();
            let action = inner.engine.bell_action_for_session(session);
            let hook = action.applies(current).then(|| {
                let snapshot = MuxHookSnapshot::capture(&inner.engine);
                PendingHookEvent::pane("alert-bell", pane, &snapshot.panes[&pane], &snapshot)
            });
            let visual = inner.engine.visual_bell_for_session(session);
            let duration_ms = inner.engine.display_time_for_session(session);
            let notifications = inner
                .attached
                .get(&session)
                .into_iter()
                .flatten()
                .filter(|client| {
                    inner.client_kinds.get(*client) != Some(&ClientKind::Control)
                        && inner.subscribers.contains_key(*client)
                })
                .filter_map(|client| {
                    let session_state = &inner.engine.state.sessions[&session];
                    let current = client_focused_window(&inner, *client, session_state) == window;
                    action.applies(current).then(|| {
                        let mut events = Vec::with_capacity(2);
                        if visual.rings() {
                            events.push(EventPayload::Bell { pane });
                        }
                        if visual.shows_message() {
                            let text = if current {
                                "Bell in current window".to_owned()
                            } else {
                                format!("Bell in window {window_index}")
                            };
                            events.push(EventPayload::TimedClientMessage {
                                pane: Some(pane),
                                kind: ClientMessageKind::Info,
                                text,
                                duration_ms,
                            });
                        }
                        (*client, events)
                    })
                })
                .collect::<Vec<_>>();
            (snapshot_changed, clear_terminal, hook, notifications)
        };
        if snapshot_changed {
            self.publish_snapshot();
        }
        for (client, events) in notifications {
            for event in events {
                self.publish_to_client(client, event);
            }
        }
        if let Some(terminal) = clear_terminal {
            terminal.clear_bell();
        }
        if let Some(hook) = hook {
            self.run_event_hooks(vec![hook]);
        }
    }

    fn clear_pane_bell(&self, pane: PaneId) -> bool {
        let (cleared, terminal) = {
            let mut inner = self.inner.lock();
            let cleared = inner.engine.state.set_pane_bell(pane, false);
            let terminal = cleared
                .then(|| inner.terminals.get(&pane).cloned())
                .flatten();
            (cleared, terminal)
        };
        if let Some(terminal) = terminal {
            terminal.clear_bell();
        }
        cleared
    }

    fn store_copy_buffer(self: &Arc<Self>, data: String, action: PasteBufferAction) {
        if data.is_empty() {
            return;
        }
        let mut data = data.into_bytes();
        let mut inner = self.inner.lock();
        let (requested_name, prefix, replacement_delete) = match action {
            PasteBufferAction::Create { prefix } => {
                (None, prefix.unwrap_or_else(|| "buffer".to_owned()), true)
            }
            PasteBufferAction::Append => {
                let requested_name = inner
                    .paste_buffers
                    .iter()
                    .find(|buffer| buffer.automatic)
                    .map(|buffer| {
                        let combined = buffer.data.len().saturating_add(data.len());
                        validate_paste_buffer_size(combined)?;
                        let mut appended = Vec::with_capacity(combined);
                        appended.extend_from_slice(&buffer.data);
                        appended.append(&mut data);
                        data = appended;
                        Ok::<_, ServerError>(buffer.name.clone())
                    })
                    .transpose();
                let requested_name = match requested_name {
                    Ok(name) => name,
                    Err(error) => {
                        log::warn!("could not append native copy buffer: {error}");
                        return;
                    }
                };
                (requested_name, "buffer".to_owned(), false)
            }
        };
        let events = match insert_paste_buffer(
            &mut inner,
            requested_name.as_deref(),
            &prefix,
            data,
            replacement_delete,
        ) {
            Ok(events) => events,
            Err(error) => {
                log::warn!("could not create native copy buffer: {error}");
                return;
            }
        };
        drop(inner);
        self.run_event_hooks(events);
        self.refresh_choose_buffers();
    }

    fn spawn_copy_pipe(
        self: &Arc<Self>,
        pane: PaneId,
        client: ClientId,
        command: String,
        data: String,
    ) {
        let subscriber = self.inner.lock().subscribers.get(&client).cloned();
        let rejection = if command.is_empty() {
            Some("copy-pipe command is empty".to_owned())
        } else if command.len() > MAX_COPY_PIPE_COMMAND_BYTES {
            Some(format!(
                "copy-pipe command exceeds {MAX_COPY_PIPE_COMMAND_BYTES} bytes"
            ))
        } else if data.len() > MAX_COPY_PIPE_BYTES {
            Some(format!(
                "copy-pipe input exceeds {MAX_COPY_PIPE_BYTES} bytes"
            ))
        } else {
            let mut inner = self.inner.lock();
            if inner.active_copy_pipes >= MAX_COPY_PIPE_PROCESSES {
                Some(format!(
                    "copy-pipe process limit reached ({MAX_COPY_PIPE_PROCESSES})"
                ))
            } else {
                inner.active_copy_pipes += 1;
                None
            }
        };
        if let Some(message) = rejection {
            self.publish_copy_pipe_message(pane, subscriber.as_deref(), message);
            return;
        }

        let shared = Arc::clone(self);
        let worker_subscriber = subscriber.clone();
        let permit = CopyPipePermit {
            shared: Arc::clone(self),
        };
        if let Err(error) = thread::Builder::new()
            .name("zz-copy-pipe".to_owned())
            .spawn(move || {
                let result = run_copy_pipe(&command, &data);
                drop(permit);
                if let Err(error) = result {
                    shared.publish_copy_pipe_message(
                        pane,
                        worker_subscriber.as_deref(),
                        format!("copy-pipe failed: {error}"),
                    );
                }
            })
        {
            self.publish_copy_pipe_message(
                pane,
                subscriber.as_deref(),
                format!("copy-pipe failed to start worker: {error}"),
            );
        }
    }

    fn publish_copy_pipe_message(
        &self,
        pane: PaneId,
        subscriber: Option<&OutboundMailbox>,
        text: String,
    ) {
        log::warn!("{text}");
        let payload = EventPayload::ClientMessage {
            pane: Some(pane),
            kind: ClientMessageKind::Error,
            text,
        };
        if let Some(subscriber) = subscriber {
            Self::send_event(subscriber, payload);
        } else {
            self.publish_for_pane(pane, &payload);
        }
    }

    fn next_sequence() -> u64 {
        static SEQUENCE: AtomicU64 = AtomicU64::new(1);
        SEQUENCE.fetch_add(1, Ordering::Relaxed)
    }

    fn event(payload: EventPayload) -> ProtocolMessage {
        ProtocolMessage::Event(Event {
            sequence: Self::next_sequence(),
            payload,
        })
    }

    fn send_event(outbound: &OutboundMailbox, payload: EventPayload) {
        let _ = outbound.enqueue_reliable(&Self::event(payload));
    }

    fn set_config_overrides(
        self: &Arc<Self>,
        client: ClientId,
        kind: ClientKind,
        entries: &[ConfigOverrideEntry],
    ) {
        let (appearance_entries, mux_entries) = partition_config_overrides(entries);

        let (color_scheme, restore) = {
            let mut inner = self.inner.lock();
            if kind != ClientKind::Interactive || !inner.subscribers.contains_key(&client) {
                log::warn!(
                    target: "zz_daemon::diagnostics::appearance",
                    "ignored configuration overrides from non-interactive client={client}",
                );
                return;
            }
            let previous_mux_keys = inner
                .mux_config_overrides
                .iter()
                .filter_map(|(key, _)| MuxOptionKey::from_config_key(key))
                .collect::<BTreeSet<_>>();
            let restore = previous_mux_keys
                .into_iter()
                .filter_map(|key| {
                    inner
                        .mux_option_underlay
                        .get(key)
                        .cloned()
                        .map(|value| (key, value))
                })
                .collect::<Vec<_>>();
            inner
                .appearance_config_overrides
                .clone_from(&appearance_entries);
            inner.mux_config_overrides.clone_from(&mux_entries);
            (
                inner
                    .client_color_schemes
                    .get(&client)
                    .copied()
                    .unwrap_or(inner.active_color_scheme),
                restore,
            )
        };

        let load = resolve_appearance(color_scheme, &appearance_entries);
        log_appearance_load("config-overrides", &load);
        {
            let appearance = Arc::new(load.appearance);
            let provenance = load.provenance;
            let (terminals, changed) = {
                let mut inner = self.inner.lock();
                if inner.appearance_config_overrides != appearance_entries {
                    return;
                }
                let changed =
                    *inner.appearance != *appearance || inner.appearance_provenance != provenance;
                inner.active_color_scheme = color_scheme;
                inner.appearance = Arc::clone(&appearance);
                inner.appearance_provenance.clone_from(&provenance);
                let terminals = if changed {
                    terminal_appearance_updates(&inner)
                } else {
                    Vec::new()
                };
                (terminals, changed)
            };
            log::info!(
                target: "zz_daemon::diagnostics::appearance",
                "applied configuration override set entries={}",
                appearance_entries.len(),
            );
            if changed {
                for (terminal, pane_appearance) in terminals {
                    terminal.set_appearance(pane_appearance);
                }
                self.publish(EventPayload::AppearanceChanged {
                    appearance: Box::new((*appearance).clone()),
                    provenance,
                });
            }
        }

        self.restore_mux_option_underlay(&restore, "config-overrides");
        self.apply_mux_config_overrides(&mux_entries, "config-overrides");
    }

    fn restore_mux_option_underlay(
        self: &Arc<Self>,
        entries: &[(MuxOptionKey, zz_protocol::MuxOptionValue)],
        reason: &str,
    ) {
        let mut context = ExecutionContext::default();
        for (option, entry) in entries {
            let command = mux_set_option_command(*option, &entry.value);
            if let Err(error) = self.execute_with_mux_source(
                ClientId(u64::MAX),
                ClientKind::Command,
                &mut context,
                &command,
                entry.source,
            ) {
                log::warn!(
                    target: "zz_daemon::diagnostics::mux_config",
                    "could not restore mux option underlay reason={reason} key={} error={error}",
                    option.as_str(),
                );
            }
        }
    }

    fn apply_mux_config_overrides(
        self: &Arc<Self>,
        entries: &[ConfigOverrideEntry],
        reason: &str,
    ) -> MuxOverrideApplyReport {
        let mut report = MuxOverrideApplyReport::default();
        let mut context = ExecutionContext::default();
        for (key, value) in entries {
            let Some(option) = MuxOptionKey::from_config_key(key) else {
                let diagnostic = format!("unsupported mux override key: {key}");
                log::warn!(
                    target: "zz_daemon::diagnostics::mux_config",
                    "mux override reason={reason} key={key:?} disposition=invalid message={diagnostic}",
                );
                report.diagnostics.push(diagnostic);
                continue;
            };
            let command = mux_set_option_command(option, value);
            match self.execute_with_mux_source(
                ClientId(u64::MAX),
                ClientKind::Command,
                &mut context,
                &command,
                MuxOptionSource::Override,
            ) {
                Ok(_) => report.applied += 1,
                Err(error) => {
                    let diagnostic = error.to_string();
                    log::warn!(
                        target: "zz_daemon::diagnostics::mux_config",
                        "mux override reason={reason} key={} disposition=invalid message={diagnostic}",
                        option.as_str(),
                    );
                    report.diagnostics.push(diagnostic);
                }
            }
        }
        let (prefix, mode_keys) = {
            let inner = self.inner.lock();
            (
                inner.engine.mux_option_value(MuxOptionKey::Prefix),
                inner.engine.mux_option_value(MuxOptionKey::ModeKeys),
            )
        };
        log::info!(
            target: "zz_daemon::diagnostics::mux_config",
            "applied mux configuration override set reason={reason} entries={} prefix={prefix:?} mode_keys={mode_keys:?}",
            report.applied,
        );
        report
    }

    fn apply_stored_mux_config_overrides(self: &Arc<Self>, reason: &str) {
        let entries = self.inner.lock().mux_config_overrides.clone();
        self.apply_mux_config_overrides(&entries, reason);
    }

    fn set_client_color_scheme(
        self: &Arc<Self>,
        client: ClientId,
        color_scheme: TerminalColorScheme,
    ) {
        let (appearance_changed, appearance_config_overrides) = {
            let mut inner = self.inner.lock();
            if !inner.subscribers.contains_key(&client) {
                return;
            }
            inner.client_color_schemes.insert(client, color_scheme);
            inner.active_color_scheme = color_scheme;
            (
                inner.appearance.color_scheme != color_scheme,
                inner.appearance_config_overrides.clone(),
            )
        };
        log::debug!(
            target: "zz_daemon::diagnostics::appearance",
            "recorded system color scheme client={client} scheme={} appearance_changed={appearance_changed}",
            color_scheme.as_str(),
        );
        if !appearance_changed {
            return;
        }

        let load = resolve_appearance(color_scheme, &appearance_config_overrides);
        log_appearance_load("system-color-scheme", &load);
        let appearance = Arc::new(load.appearance);
        let provenance = load.provenance;
        let terminals = {
            let mut inner = self.inner.lock();
            if inner.active_color_scheme != color_scheme
                || !inner.subscribers.contains_key(&client)
                || inner.appearance_config_overrides != appearance_config_overrides
            {
                return;
            }
            inner.appearance = Arc::clone(&appearance);
            inner.appearance_provenance.clone_from(&provenance);
            terminal_appearance_updates(&inner)
        };
        for (terminal, pane_appearance) in terminals {
            terminal.set_appearance(pane_appearance);
        }
        self.publish(EventPayload::AppearanceChanged {
            appearance: Box::new((*appearance).clone()),
            provenance,
        });
    }

    fn reload_user_config(
        self: &Arc<Self>,
        client: ClientId,
        context: &mut ExecutionContext,
    ) -> Result<(), DaemonError> {
        let mux_config = self
            .load_user_config
            .then(default_mux_config)
            .flatten()
            .filter(|path| path.is_file());
        self.reload_user_config_with_mux_file(client, context, mux_config.as_deref())
    }

    fn reload_user_config_with_mux_file(
        self: &Arc<Self>,
        client: ClientId,
        context: &mut ExecutionContext,
        mux_config: Option<&Path>,
    ) -> Result<(), DaemonError> {
        let (color_scheme, appearance_config_overrides, config_client_terminal) = {
            let inner = self.inner.lock();
            let kind = inner
                .client_kinds
                .get(&client)
                .copied()
                .unwrap_or(ClientKind::Command);
            (
                inner
                    .client_color_schemes
                    .get(&client)
                    .copied()
                    .unwrap_or(inner.active_color_scheme),
                inner.appearance_config_overrides.clone(),
                client_terminal(&inner, client, kind),
            )
        };
        let load = resolve_appearance(color_scheme, &appearance_config_overrides);
        log_appearance_load("reload", &load);
        self.inner.lock().engine.keys = KeyTables::default();
        let mut report = ConfigLoadReport::default();
        if let Some(config) = mux_config {
            self.load_config_file_with_report_for_terminal(
                config,
                context,
                0,
                &mut report,
                config_client_terminal,
            )?;
        }
        self.apply_stored_mux_config_overrides("reload-mux-replay");

        let appearance = Arc::new(load.appearance);
        let provenance = load.provenance;
        let terminals = {
            let mut inner = self.inner.lock();
            if inner.appearance_config_overrides != appearance_config_overrides {
                return Ok(());
            }
            inner.active_color_scheme = color_scheme;
            inner.appearance = Arc::clone(&appearance);
            inner.appearance_provenance.clone_from(&provenance);
            terminal_appearance_updates(&inner)
        };
        for (terminal, pane_appearance) in terminals {
            terminal.set_appearance(pane_appearance);
        }
        self.publish(EventPayload::AppearanceChanged {
            appearance: Box::new((*appearance).clone()),
            provenance,
        });
        let (kind, text) = match report.summary() {
            Some(summary) => (
                ClientMessageKind::Warning,
                format!("Reloaded zz configuration; {summary}"),
            ),
            None => (
                ClientMessageKind::Success,
                "Reloaded zz configuration".to_owned(),
            ),
        };
        self.publish_to_client(
            client,
            EventPayload::ClientMessage {
                pane: context.pane,
                kind,
                text,
            },
        );
        self.publish_key_tables_if_changed();
        Ok(())
    }

    fn load_config_file(
        self: &Arc<Self>,
        path: &Path,
        context: &mut ExecutionContext,
        depth: usize,
    ) -> Result<(), DaemonError> {
        self.load_config_file_with_report_for_terminal(
            path,
            context,
            depth,
            &mut ConfigLoadReport::default(),
            ClientTerminal::NoClient,
        )
    }

    #[cfg(test)]
    fn load_config_file_with_report(
        self: &Arc<Self>,
        path: &Path,
        context: &mut ExecutionContext,
        depth: usize,
        report: &mut ConfigLoadReport,
    ) -> Result<(), DaemonError> {
        self.load_config_file_with_report_for_terminal(
            path,
            context,
            depth,
            report,
            ClientTerminal::NoClient,
        )
    }

    fn load_config_file_with_report_for_terminal(
        self: &Arc<Self>,
        path: &Path,
        context: &mut ExecutionContext,
        depth: usize,
        report: &mut ConfigLoadReport,
        client_terminal: ClientTerminal,
    ) -> Result<(), DaemonError> {
        if depth >= MAX_CONFIG_DEPTH {
            log::warn!(
                "ignoring config source past depth {MAX_CONFIG_DEPTH}: {}",
                path.display()
            );
            return Ok(());
        }
        let input = match fs::read_to_string(path) {
            Ok(input) => input,
            Err(error) if error.kind() == ErrorKind::NotFound => {
                log::warn!("ignoring missing config file: {}", path.display());
                return Ok(());
            }
            Err(error) => return Err(error.into()),
        };
        let parsed = {
            let inner = self.inner.lock();
            inner
                .engine
                .parse_config(path.display().to_string(), &input)
        };
        for diagnostic in parsed.diagnostics {
            log::warn!(
                "{}:{}:{}: {}",
                diagnostic.source,
                diagnostic.line,
                diagnostic.column,
                diagnostic.message
            );
            report.note_invalid_at(&diagnostic.source, diagnostic.line, &diagnostic.message);
        }
        for assignment in parsed.environment {
            self.inner.lock().engine.set_config_environment(
                assignment.name,
                assignment.value,
                assignment.hidden,
            );
        }
        for command in parsed.commands {
            if command.name == "reload-config" {
                log::warn!(
                    "{}: ignoring reload-config while loading configuration",
                    path.display()
                );
                continue;
            }
            if matches!(command.name.as_str(), "source" | "source-file") {
                let source_effects = {
                    let mut inner = self.inner.lock();
                    inner.engine.execute(context, &command)
                };
                let source_effects = match source_effects {
                    Ok(execution) => execution
                        .effects
                        .into_iter()
                        .filter_map(|effect| match effect {
                            MuxEffect::SourceFile { path, quiet } => Some((path, quiet)),
                            _ => None,
                        })
                        .collect::<Vec<_>>(),
                    Err(ServerError::UnsupportedCommand(command)) => {
                        log::warn!(
                            "{}: ignoring unsupported tmux command: {command}",
                            path.display()
                        );
                        report.note_skip(&command);
                        continue;
                    }
                    Err(ServerError::InvalidCommand(message)) => {
                        log::warn!(
                            "{}: ignoring invalid tmux command: {message}",
                            path.display()
                        );
                        report.note_invalid_command(&command, &message);
                        continue;
                    }
                    Err(error) => {
                        log::warn!("{}: ignoring tmux command error: {error}", path.display());
                        continue;
                    }
                };
                if source_effects.is_empty() {
                    log::warn!("{}: ignoring source-file without a path", path.display());
                }
                let mut source_error = None;
                for (source, quiet) in source_effects {
                    if source == "-" {
                        log::warn!("source-file from standard input is not supported");
                        report.note_invalid_command(
                            &command,
                            "source-file from standard input is not supported",
                        );
                        continue;
                    }
                    let source = expand_relative(path, &source);
                    let matches = source_glob_matches(&source);
                    for error in &matches.errors {
                        log::warn!("source-file glob error for {}: {error}", source.display());
                    }
                    if matches.paths.is_empty() && matches.errors.is_empty() {
                        if !quiet {
                            log::warn!("no such file: {}", source.display());
                        }
                        continue;
                    }
                    for source in matches.paths {
                        if let Err(error) = self.load_config_file_with_report_for_terminal(
                            &source,
                            context,
                            depth + 1,
                            report,
                            client_terminal,
                        ) && source_error.is_none()
                        {
                            source_error = Some(error);
                        }
                    }
                }
                if let Some(error) = source_error {
                    return Err(error);
                }
                continue;
            }
            match self
                .execute_with_mux_source_for_terminal(
                    ClientId(u64::MAX),
                    ClientKind::Command,
                    context,
                    &command,
                    MuxOptionSource::TmuxConfig,
                    client_terminal,
                )
                .map_err(discard_command_output)
            {
                Ok(_) => {}
                Err(DaemonError::Server(ServerError::UnsupportedCommand(command))) => {
                    log::warn!(
                        "{}: ignoring unsupported tmux command: {command}",
                        path.display()
                    );
                    report.note_skip(&command);
                }
                Err(DaemonError::Server(ServerError::InvalidCommand(message))) => {
                    log::warn!(
                        "{}: ignoring invalid tmux command: {message}",
                        path.display()
                    );
                    report.note_invalid_command(&command, &message);
                }
                Err(DaemonError::Server(error)) => {
                    log::warn!("{}: ignoring tmux command error: {error}", path.display());
                }
                Err(error) => return Err(error),
            }
        }
        Ok(())
    }
}

/// Everything the daemon owns on behalf of agent panes. Nothing in here may be
/// reached while the daemon's own state lock is held: the runtime calls back
/// into it from its pane threads.
#[cfg(feature = "agent")]
impl Shared {
    fn agent_runtime(self: &Arc<Self>) -> Option<Arc<AgentRuntime>> {
        if self.agent_stopped.load(Ordering::Acquire) {
            return None;
        }
        if let Some(runtime) = self.agent.lock().as_ref() {
            return Some(Arc::clone(runtime));
        }
        // Tests never journal and never spawn an adapter: the pane opens
        // against a runner that reports there is none, and whoever wants a
        // real conversation installs a fixture first.
        let journal = if cfg!(test) {
            None
        } else {
            load_persistent_journal()
        };
        self.build_agent_runtime(journal)
    }

    fn build_agent_runtime(
        self: &Arc<Self>,
        journal: Option<Arc<crate::agent::journal::AgentJournal>>,
    ) -> Option<Arc<AgentRuntime>> {
        let config = self.agent_spawn_config();
        let mut slot = self.agent.lock();
        if self.agent_stopped.load(Ordering::Acquire) {
            return None;
        }
        if let Some(runtime) = slot.as_ref() {
            return Some(Arc::clone(runtime));
        }
        let publisher: Arc<dyn AgentPublisher> = Arc::<Self>::clone(self);
        let runtime = Arc::new(AgentRuntime::new(&publisher, config, journal));
        runtime.prewarm();
        #[cfg(test)]
        runtime.set_runner_factory(Box::new(|_| {
            Box::new(|_| Box::pin(async { Err("no agent adapter in tests".to_owned()) }))
        }));
        *slot = Some(Arc::clone(&runtime));
        Some(runtime)
    }

    /// The runtime only if a pane has already asked for one.
    fn open_agent_runtime(&self) -> Option<Arc<AgentRuntime>> {
        self.agent.lock().clone()
    }

    fn agent_spawn_config(&self) -> AgentSpawnConfig {
        let inner = self.inner.lock();
        let options = inner.engine.agent_options();
        AgentSpawnConfig {
            command: options.command.clone(),
            claude_code_command: options.claude_code_command.clone(),
            auto_approve: options.auto_approve,
            workspace: AgentWorkspaceEnvironment {
                pane: None,
                session: None,
                socket: Some(self.socket_path.display().to_string()),
                tmux: None,
                tmux_pane: None,
            },
        }
    }

    fn reconfigure_agents(&self) {
        let _effects = self.agent_effects.lock();
        let config = self.agent_spawn_config();
        let Some(runtime) = self.open_agent_runtime() else {
            return;
        };
        runtime.reconfigure(config);
    }

    /// Start the adapter for a pane the mux just materialized.
    fn open_agent_pane(self: &Arc<Self>, pane: PaneId) {
        let _effects = self.agent_effects.lock();
        let Some(spec) = self.agent_pane_spec(pane) else {
            return;
        };
        let Some(runtime) = self.agent_runtime() else {
            return;
        };
        runtime.reconfigure(self.agent_spawn_config());
        if !runtime.open(pane, spec) {
            log::warn!(target: "zz::agent", "{pane} already has an agent runtime");
        }
    }

    fn restart_agent_pane(self: &Arc<Self>, pane: PaneId) {
        let _effects = self.agent_effects.lock();
        let Some(spec) = self.agent_pane_spec(pane) else {
            return;
        };
        let Some(runtime) = self.agent_runtime() else {
            return;
        };
        runtime.reconfigure(self.agent_spawn_config());
        if !runtime.restart(pane, spec) {
            log::warn!(target: "zz::agent", "could not restart the agent runtime for {pane}");
        }
    }

    fn agent_pane_spec(&self, pane: PaneId) -> Option<AgentPaneSpec> {
        let inner = self.inner.lock();
        let PaneKind::Agent(descriptor) = &inner.engine.state.pane(pane)?.kind else {
            return None;
        };
        let session = inner
            .engine
            .state
            .window_for_pane(pane)
            .map(|window| inner.engine.state.windows[&window].session);
        Some(AgentPaneSpec {
            provider: descriptor.provider,
            cwd: descriptor
                .cwd
                .clone()
                .or_else(|| std::env::current_dir().ok())
                .unwrap_or_else(|| PathBuf::from("/")),
            resume_session: descriptor.session_id.clone(),
            workspace: AgentWorkspaceEnvironment {
                pane: Some(pane.to_string()),
                session: session.map(|session| session.to_string()),
                socket: None,
                tmux: session.map(|session| tmux_environment(&self.socket_path, Some(session))),
                tmux_pane: Some(pane.to_string()),
            },
        })
    }

    fn close_agent_panes(&self, panes: &[PaneId]) {
        let _effects = self.agent_effects.lock();
        let Some(runtime) = self.open_agent_runtime() else {
            return;
        };
        for pane in panes {
            runtime.close(*pane);
        }
    }

    fn shutdown_agents(&self) {
        let runtime = {
            let _effects = self.agent_effects.lock();
            self.agent_stopped.store(true, Ordering::Release);
            self.agent.lock().take()
        };
        let Some(runtime) = runtime else {
            return;
        };
        runtime.shutdown();
    }

    /// One client's answer to an agent message, or the reason it was refused.
    fn agent_message(
        self: &Arc<Self>,
        client: ClientId,
        message: ProtocolMessage,
    ) -> Result<(), ServerError> {
        let pane = agent_message_pane(&message)?;
        {
            let inner = self.inner.lock();
            match inner.engine.state.pane(pane).map(|pane| &pane.kind) {
                Some(PaneKind::Agent(_)) => {}
                Some(_) => {
                    return Err(ServerError::InvalidTarget(format!(
                        "{pane} is not an agent pane"
                    )));
                }
                None => return Err(ServerError::MissingTarget(pane.to_string())),
            }
        };
        if let ProtocolMessage::AgentSessionOp { op, .. } = &message {
            let valid_directory = |path: &Path| {
                path.is_absolute()
                    && path.as_os_str().as_encoded_bytes().len() <= MAX_GUI_TEXT_BYTES
            };
            let valid = match op {
                AgentSessionOpKind::List { cwd, .. } => cwd.as_deref().is_none_or(valid_directory),
                AgentSessionOpKind::New { cwd } => valid_directory(cwd),
                AgentSessionOpKind::Switch {
                    cwd,
                    additional_directories,
                    ..
                } => {
                    valid_directory(cwd)
                        && additional_directories.len() <= MAX_AGENT_SESSION_DIRECTORIES
                        && additional_directories
                            .iter()
                            .all(|path| valid_directory(path))
                }
                AgentSessionOpKind::Delete { .. } => true,
            };
            if !valid {
                return Err(ServerError::InvalidCommand(
                    "agent session directories must be absolute on the daemon host".to_owned(),
                ));
            }
        }
        let Some(runtime) = self.agent_runtime() else {
            return Err(ServerError::PaneExited(pane));
        };
        let command = match message {
            ProtocolMessage::AgentReplay { from_seq, .. } => {
                runtime.replay(client, pane, from_seq);
                return Ok(());
            }
            ProtocolMessage::AgentAcknowledgePromptRestore { reclaim_id, .. } => {
                let owner = self
                    .client_instance_id(client)
                    .ok_or(ServerError::PaneExited(pane))?;
                runtime.acknowledge_prompt_restore(owner, pane, reclaim_id);
                return Ok(());
            }
            ProtocolMessage::AgentPrompt { text, images, .. } => {
                let owner = self
                    .client_instance_id(client)
                    .ok_or(ServerError::PaneExited(pane))?;
                return runtime
                    .prompt(
                        pane,
                        AgentPrompt {
                            owner,
                            text,
                            images: images
                                .into_iter()
                                .map(|image| AgentImage {
                                    format: image.format,
                                    data: image.data,
                                })
                                .collect(),
                        },
                    )
                    .then_some(())
                    .ok_or(ServerError::PaneExited(pane));
            }
            ProtocolMessage::AgentCancel { .. } => HostCommand::Cancel,
            ProtocolMessage::AgentUnqueue { .. } => HostCommand::Unqueue,
            ProtocolMessage::AgentRespondPermission {
                request_id,
                option_id,
                ..
            } => HostCommand::RespondPermission {
                request_id,
                option_id,
            },
            ProtocolMessage::AgentSetConfigOption {
                option_id, value, ..
            } => HostCommand::SetConfigOption { option_id, value },
            ProtocolMessage::AgentSetMode { mode_id, .. } => HostCommand::SetMode { mode_id },
            ProtocolMessage::AgentAuthenticate { method_id, .. } => {
                HostCommand::Authenticate { method_id }
            }
            ProtocolMessage::AgentSessionOp { op, .. } => match op {
                AgentSessionOpKind::List {
                    cwd,
                    cursor,
                    replace,
                } => HostCommand::ListSessions {
                    client,
                    cwd,
                    cursor,
                    replace,
                },
                AgentSessionOpKind::New { cwd } => HostCommand::NewSession { cwd },
                AgentSessionOpKind::Switch {
                    session_id,
                    cwd,
                    additional_directories,
                } => HostCommand::SwitchSession {
                    session: AgentSessionSummary {
                        session_id,
                        cwd,
                        additional_directories,
                        title: None,
                        updated_at: None,
                    },
                },
                AgentSessionOpKind::Delete { session_id } => {
                    HostCommand::DeleteSession { client, session_id }
                }
            },
            _ => return Ok(()),
        };
        runtime
            .command(pane, command)
            .then_some(())
            .ok_or(ServerError::PaneExited(pane))
    }

    /// Dispatch `agent-send --submit` straight into the pane's runtime; the
    /// composer half still round-trips through the GUI that owns the draft.
    fn submit_agent_prompt(self: &Arc<Self>, pane: PaneId, text: String) -> bool {
        self.agent_runtime().is_some_and(|runtime| {
            runtime.prompt(
                pane,
                AgentPrompt {
                    owner: ClientInstanceId(u64::MAX),
                    text,
                    images: Vec::new(),
                },
            )
        })
    }

    /// Push the pane state of every agent pane a reattaching client can see.
    /// The stream itself is not pushed: the client asks for the replay it
    /// wants from the sequence it kept.
    fn send_agent_resync(&self, client: ClientId, outbound: &OutboundMailbox) {
        let Some(runtime) = self.open_agent_runtime() else {
            return;
        };
        let panes = {
            let inner = self.inner.lock();
            let Some(session) = client_attached_session(&inner, client) else {
                return;
            };
            session_agent_panes(&inner, session)
        };
        for pane in panes {
            let Some(state) = runtime.wire_state(pane) else {
                continue;
            };
            Self::send_event(outbound, EventPayload::AgentState { pane, state });
        }
    }

    /// A pane entering a client's visible set gets its state pushed; the
    /// client replays the stream from the sequence it cached.
    fn refresh_agent_visibility(&self) {
        let changes = {
            let mut inner = self.inner.lock();
            let attachments = inner
                .attached
                .iter()
                .flat_map(|(session, clients)| clients.iter().map(|client| (*session, *client)))
                .collect::<Vec<_>>();
            let mut changes = Vec::new();
            for (session, client) in attachments {
                let next = visible_agent_panes(&inner, client, session);
                let previous = inner
                    .visible_agents
                    .get(&client)
                    .cloned()
                    .unwrap_or_default();
                if next == previous {
                    continue;
                }
                let removed = previous.difference(&next).copied().collect::<Vec<_>>();
                let entered = next.difference(&previous).copied().collect::<Vec<_>>();
                if let Some(subscriber) = inner.subscribers.get(&client).cloned() {
                    changes.push((subscriber, removed, entered));
                }
                inner.visible_agents.insert(client, next);
            }
            changes
        };
        if changes.is_empty() {
            return;
        }
        let runtime = self.open_agent_runtime();
        for (subscriber, removed, entered) in changes {
            for pane in removed {
                subscriber.cancel_agent(pane);
            }
            let Some(runtime) = runtime.as_ref() else {
                continue;
            };
            for pane in entered {
                let Some(state) = runtime.wire_state(pane) else {
                    continue;
                };
                Self::send_event(&subscriber, EventPayload::AgentState { pane, state });
            }
        }
    }
}

#[cfg(feature = "agent")]
impl AgentPublisher for Shared {
    fn publish_agent_updates(
        &self,
        pane: PaneId,
        first_seq: u64,
        items: Vec<Vec<u8>>,
        also: Option<ClientId>,
    ) {
        let message = Self::event(EventPayload::AgentUpdates {
            pane,
            first_seq,
            items,
        });
        let subscribers = {
            let inner = self.inner.lock();
            let mut clients = attached_clients_for_pane(&inner, pane)
                .into_iter()
                .flatten()
                .filter(|client| {
                    inner
                        .visible_agents
                        .get(client)
                        .is_some_and(|visible| visible.contains(&pane))
                })
                .copied()
                .collect::<BTreeSet<_>>();
            clients.extend(also.filter(|client| client_is_attached_to_pane(&inner, *client, pane)));
            clients
                .into_iter()
                .filter_map(|client| inner.subscribers.get(&client).cloned())
                .collect::<Vec<_>>()
        };
        for subscriber in subscribers {
            let Ok(encoded) = subscriber.encode_message(&message) else {
                log::error!("failed to encode an agent update batch for {pane}");
                continue;
            };
            subscriber.enqueue_agent(pane, first_seq, encoded);
        }
    }

    fn send_agent_replay(&self, client: ClientId, pane: PaneId, frames: Vec<(u64, Vec<Vec<u8>>)>) {
        let Some(subscriber) = self.inner.lock().subscribers.get(&client).cloned() else {
            return;
        };
        let mut encoded = Vec::with_capacity(frames.len());
        for (first_seq, items) in frames {
            let message = Self::event(EventPayload::AgentUpdates {
                pane,
                first_seq,
                items,
            });
            let Ok(frame) = subscriber.encode_message(&message) else {
                log::error!("failed to encode an agent replay batch for {pane}");
                return;
            };
            encoded.push((first_seq, frame));
        }
        subscriber.enqueue_agent_replay(pane, encoded);
    }

    fn publish_agent_replay(
        &self,
        pane: PaneId,
        frames: Vec<(u64, Vec<Vec<u8>>)>,
        also: Option<ClientId>,
    ) {
        let subscribers = {
            let inner = self.inner.lock();
            let mut clients = attached_clients_for_pane(&inner, pane)
                .into_iter()
                .flatten()
                .filter(|client| {
                    inner
                        .visible_agents
                        .get(client)
                        .is_some_and(|visible| visible.contains(&pane))
                })
                .copied()
                .collect::<BTreeSet<_>>();
            clients.extend(also.filter(|client| client_is_attached_to_pane(&inner, *client, pane)));
            clients
                .into_iter()
                .filter_map(|client| inner.subscribers.get(&client).cloned())
                .collect::<Vec<_>>()
        };
        for subscriber in subscribers {
            let mut encoded = Vec::with_capacity(frames.len());
            for (first_seq, items) in &frames {
                let message = Self::event(EventPayload::AgentUpdates {
                    pane,
                    first_seq: *first_seq,
                    items: items.clone(),
                });
                let Ok(frame) = subscriber.encode_message(&message) else {
                    log::error!("failed to encode an agent replay batch for {pane}");
                    encoded.clear();
                    break;
                };
                encoded.push((*first_seq, frame));
            }
            if !encoded.is_empty() {
                subscriber.enqueue_agent_replay(pane, encoded);
            }
        }
    }

    fn publish_agent_state(&self, pane: PaneId, state: AgentPaneWire) {
        self.publish_for_pane(pane, &EventPayload::AgentState { pane, state });
    }

    fn send_agent_reply(&self, pane: PaneId, reply: AgentRequestReply) {
        let AgentRequestReply::Sessions { client, result } = reply;
        let payload = EventPayload::AgentSessions {
            pane,
            request_id: 0,
            result,
        };
        let subscriber = self.inner.lock().subscribers.get(&client).cloned();
        if let Some(subscriber) = subscriber {
            Self::send_event(&subscriber, payload);
        }
    }

    fn adopt_agent_session(
        &self,
        pane: PaneId,
        provider: AgentProvider,
        session_id: String,
        cwd: Option<PathBuf>,
    ) {
        let changed = {
            let mut inner = self.inner.lock();
            let matches_provider = inner.engine.state.pane(pane).is_some_and(
                |pane| matches!(&pane.kind, PaneKind::Agent(agent) if agent.provider == provider),
            );
            if !matches_provider {
                return;
            }
            match inner
                .engine
                .state
                .update_agent_session(pane, session_id, cwd)
            {
                Ok(()) => true,
                Err(error) => {
                    log::debug!(target: "zz::agent", "could not adopt the session for {pane}: {error}");
                    false
                }
            }
        };
        if changed {
            self.publish_snapshot();
        }
    }

    fn title_agent_pane(&self, pane: PaneId, title: String) {
        let changed = {
            let mut inner = self.inner.lock();
            let keeps_default_title = inner
                .engine
                .state
                .pane(pane)
                .is_some_and(|pane| is_default_agent_title(&pane.title));
            keeps_default_title
                && inner
                    .engine
                    .state
                    .update_pane_title(pane, title)
                    .unwrap_or(false)
        };
        if changed {
            self.publish_snapshot();
        }
    }
}

/// Which pane an agent message addresses.
#[cfg(feature = "agent")]
fn agent_message_pane(message: &ProtocolMessage) -> Result<PaneId, ServerError> {
    match message {
        ProtocolMessage::AgentPrompt { pane, .. }
        | ProtocolMessage::AgentCancel { pane }
        | ProtocolMessage::AgentUnqueue { pane }
        | ProtocolMessage::AgentRespondPermission { pane, .. }
        | ProtocolMessage::AgentSetConfigOption { pane, .. }
        | ProtocolMessage::AgentSetMode { pane, .. }
        | ProtocolMessage::AgentAuthenticate { pane, .. }
        | ProtocolMessage::AgentSessionOp { pane, .. }
        | ProtocolMessage::AgentReplay { pane, .. }
        | ProtocolMessage::AgentAcknowledgePromptRestore { pane, .. } => Ok(*pane),
        _ => Err(ServerError::InvalidCommand(
            "not an agent message".to_owned(),
        )),
    }
}

#[cfg(feature = "agent")]
fn session_agent_panes(inner: &ServerState, session: SessionId) -> Vec<PaneId> {
    inner
        .engine
        .state
        .sessions
        .get(&session)
        .into_iter()
        .flat_map(|session| session.windows.iter())
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys())
        .filter(|pane| {
            inner
                .engine
                .state
                .pane(**pane)
                .is_some_and(|pane| matches!(pane.kind, PaneKind::Agent(_)))
        })
        .copied()
        .collect()
}

#[derive(Default)]
struct ConfigLoadReport {
    skipped_count: usize,
    skipped: Vec<String>,
    invalid_count: usize,
    invalid: Vec<String>,
}

impl ConfigLoadReport {
    const SUMMARY_NAMES: usize = 6;

    fn note_skip(&mut self, name: &str) {
        self.skipped_count += 1;
        if !self.skipped.iter().any(|existing| existing == name) {
            self.skipped.push(name.to_owned());
        }
    }

    fn note_invalid(&mut self, message: &str) {
        self.invalid_count += 1;
        if !self.invalid.iter().any(|existing| existing == message) {
            self.invalid.push(message.to_owned());
        }
    }

    fn note_invalid_at(&mut self, source: &str, line: u32, message: &str) {
        self.note_invalid(&format!("{source}:{line}: {message}"));
    }

    fn note_invalid_command(&mut self, command: &CommandInvocation, message: &str) {
        match &command.source {
            Some(source) => self.note_invalid_at(&source.source, source.line, message),
            None => self.note_invalid(message),
        }
    }

    fn message(&self) -> Option<String> {
        if self.skipped_count == 0 && self.invalid_count == 1 {
            return self.invalid.first().cloned();
        }
        self.summary()
    }

    fn summary(&self) -> Option<String> {
        if self.skipped_count == 0 && self.invalid_count == 0 {
            return None;
        }
        let mut parts = Vec::new();
        if self.skipped_count != 0 {
            parts.push(format!(
                "skipped {} unsupported tmux command{}: {}",
                self.skipped_count,
                if self.skipped_count == 1 { "" } else { "s" },
                Self::summary_names(&self.skipped),
            ));
        }
        if self.invalid_count != 0 {
            parts.push(format!(
                "{} invalid line{}: {}",
                self.invalid_count,
                if self.invalid_count == 1 { "" } else { "s" },
                Self::summary_names(&self.invalid),
            ));
        }
        Some(parts.join("; "))
    }

    fn summary_names(entries: &[String]) -> String {
        let mut names =
            entries
                .iter()
                .take(Self::SUMMARY_NAMES)
                .fold(String::new(), |mut names, name| {
                    if !names.is_empty() {
                        names.push_str(", ");
                    }
                    names.push_str(name);
                    names
                });
        if entries.len() > Self::SUMMARY_NAMES {
            names.push_str(", …");
        }
        names
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ClientTerminal {
    NoClient,
    Absent,
    Present,
}

fn context_client_terminal(context: &ExecutionContext) -> ClientTerminal {
    if context.has_no_client() {
        ClientTerminal::NoClient
    } else if context.has_client_terminal() {
        ClientTerminal::Present
    } else {
        ClientTerminal::Absent
    }
}

fn set_context_client_terminal(context: &mut ExecutionContext, terminal: ClientTerminal) {
    match terminal {
        ClientTerminal::NoClient => context.set_no_client(),
        ClientTerminal::Absent => context.set_client_terminal(false),
        ClientTerminal::Present => context.set_client_terminal(true),
    }
}

fn client_terminal(inner: &ServerState, client: ClientId, kind: ClientKind) -> ClientTerminal {
    match kind {
        ClientKind::Control => ClientTerminal::Present,
        ClientKind::Interactive if inner.client_terminals.contains(&client) => {
            ClientTerminal::Present
        }
        ClientKind::Interactive | ClientKind::Command => ClientTerminal::Absent,
    }
}

