impl ChooseTreeSession {
    fn new(
        kind: ChooseTreeKind,
        source_pane: PaneId,
        state: &MuxState,
        attached_session: Option<SessionId>,
    ) -> Result<Self, ServerError> {
        let source_window = state
            .window_for_pane(source_pane)
            .ok_or_else(|| ServerError::MissingTarget(source_pane.to_string()))?;
        let source_session = state.windows[&source_window].session;
        let expanded_sessions = state.sessions.keys().copied().collect();
        let expanded_windows = if kind == ChooseTreeKind::Panes {
            state.windows.keys().copied().collect()
        } else {
            BTreeSet::new()
        };
        let selected = Some(match kind {
            ChooseTreeKind::Windows => ChooseTreeTarget::Window(source_window),
            ChooseTreeKind::Panes => ChooseTreeTarget::Pane(source_pane),
        });
        let mut chooser = Self {
            source_pane,
            source_session,
            kind,
            expanded_sessions,
            expanded_windows,
            selected,
            search: None,
            last_search: None,
            rendered: ChooseTreeState {
                items: Vec::new(),
                search: None,
                selected: 0,
                kind,
            },
        };
        chooser.rebuild(state, attached_session);
        Ok(chooser)
    }

    fn rebuild(&mut self, state: &MuxState, attached_session: Option<SessionId>) {
        let mut items = Vec::new();
        'sessions: for session in state.sessions.values() {
            let session_has_children = session
                .windows
                .iter()
                .any(|window| state.windows.contains_key(window));
            let session_expanded =
                session_has_children && self.expanded_sessions.contains(&session.id);
            if !push_choose_tree_item(
                &mut items,
                ChooseTreeItem {
                    label: bounded_choose_tree_text(&session.name),
                    detail: format_count(session.windows.len(), "window"),
                    target: ChooseTreeTarget::Session(session.id),
                    depth: 0,
                    flags: choose_tree_flags(
                        session_expanded,
                        session_has_children,
                        attached_session == Some(session.id),
                    ),
                    pane_kind: None,
                },
            ) {
                break;
            }
            if !session_expanded {
                continue;
            }

            for window_id in &session.windows {
                let Some(window) = state.windows.get(window_id) else {
                    continue;
                };
                let window_has_children =
                    self.kind == ChooseTreeKind::Panes && !window.panes.is_empty();
                let window_expanded =
                    window_has_children && self.expanded_windows.contains(window_id);
                if !push_choose_tree_item(
                    &mut items,
                    ChooseTreeItem {
                        label: bounded_choose_tree_text(&format!(
                            "{}:{}",
                            window.index, window.name
                        )),
                        detail: format_count(window.panes.len(), "pane"),
                        target: ChooseTreeTarget::Window(*window_id),
                        depth: 1,
                        flags: choose_tree_flags(
                            window_expanded,
                            window_has_children,
                            session.active_window == *window_id,
                        ),
                        pane_kind: None,
                    },
                ) {
                    break 'sessions;
                }
                if !window_expanded {
                    continue;
                }

                for pane_id in window.pane_order().iter().copied() {
                    let Some(pane) = window.panes.get(&pane_id) else {
                        continue;
                    };
                    let (pane_kind, detail) = match &pane.kind {
                        PaneKind::Picker { .. } => (None, "Choose pane type".to_owned()),
                        PaneKind::Terminal => {
                            (Some(ChooseTreePaneKind::Terminal), "Terminal".to_owned())
                        }
                        PaneKind::Browser(browser) => (
                            Some(ChooseTreePaneKind::Browser),
                            format!("Browser · {} · {}", browser.profile, browser.url()),
                        ),
                        PaneKind::Agent(_) => (Some(ChooseTreePaneKind::Agent), "Agent".to_owned()),
                        PaneKind::Editor(editor) => (
                            Some(ChooseTreePaneKind::Editor),
                            editor.path.as_ref().map_or_else(
                                || "Editor · scratch".to_owned(),
                                |path| format!("Editor · {path}"),
                            ),
                        ),
                    };
                    if !push_choose_tree_item(
                        &mut items,
                        ChooseTreeItem {
                            label: bounded_choose_tree_text(&pane.title),
                            detail: bounded_choose_tree_text(&detail),
                            target: ChooseTreeTarget::Pane(pane_id),
                            depth: 2,
                            flags: choose_tree_flags(false, false, window.active_pane == pane_id),
                            pane_kind,
                        },
                    ) {
                        break 'sessions;
                    }
                }
            }
        }

        let fallback = state
            .window_for_pane(self.source_pane)
            .map(|window| match self.kind {
                ChooseTreeKind::Windows => ChooseTreeTarget::Window(window),
                ChooseTreeKind::Panes => ChooseTreeTarget::Pane(self.source_pane),
            });
        let selected = self
            .selected
            .and_then(|target| items.iter().position(|item| item.target == target))
            .or_else(|| {
                fallback.and_then(|target| items.iter().position(|item| item.target == target))
            })
            .unwrap_or(0)
            .min(items.len().saturating_sub(1));
        self.selected = items.get(selected).map(|item| item.target);
        self.rendered = ChooseTreeState {
            items,
            search: self.search.clone(),
            selected: u32::try_from(selected).unwrap_or(u32::MAX),
            kind: self.kind,
        };
    }

    fn apply(
        &mut self,
        action: ChooseTreeAction,
        state: &MuxState,
        attached_session: Option<SessionId>,
    ) -> Result<ChooseTreeResult, ServerError> {
        let len = self.rendered.items.len();
        let current = usize::try_from(self.rendered.selected)
            .unwrap_or(usize::MAX)
            .min(len.saturating_sub(1));
        let mut update = ChooseTreeUpdateKind::Delta;
        match action {
            ChooseTreeAction::Previous => self.select_index(current.saturating_sub(1)),
            ChooseTreeAction::Next => self.select_index((current + 1).min(len.saturating_sub(1))),
            ChooseTreeAction::PagePrevious => {
                self.select_index(current.saturating_sub(CHOOSE_TREE_PAGE_ROWS));
            }
            ChooseTreeAction::PageNext => self.select_index(
                current
                    .saturating_add(CHOOSE_TREE_PAGE_ROWS)
                    .min(len.saturating_sub(1)),
            ),
            ChooseTreeAction::First => self.select_index(0),
            ChooseTreeAction::Last => self.select_index(len.saturating_sub(1)),
            ChooseTreeAction::Select(index) => {
                self.select_index(usize::try_from(index).unwrap_or(usize::MAX));
            }
            ChooseTreeAction::ActivateIndex(index) => {
                self.select_index(usize::try_from(index).unwrap_or(usize::MAX));
                return Ok(self.selected.map_or(
                    ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta),
                    ChooseTreeResult::Activate,
                ));
            }
            ChooseTreeAction::Collapse => {
                if let Some(item) = self.rendered.items.get(current).cloned() {
                    if item.expanded() {
                        self.set_expanded(item.target, false);
                        self.rebuild(state, attached_session);
                        update = ChooseTreeUpdateKind::Full;
                    } else if item.depth > 0
                        && let Some(parent) = self.rendered.items[..current]
                            .iter()
                            .rev()
                            .position(|candidate| candidate.depth < item.depth)
                    {
                        self.select_index(current - parent - 1);
                    }
                }
            }
            ChooseTreeAction::Expand => {
                if let Some(item) = self.rendered.items.get(current).cloned() {
                    if item.has_children() && !item.expanded() {
                        self.set_expanded(item.target, true);
                        self.rebuild(state, attached_session);
                        update = ChooseTreeUpdateKind::Full;
                    } else {
                        self.select_index((current + 1).min(len.saturating_sub(1)));
                    }
                }
            }
            ChooseTreeAction::Activate => {
                return Ok(self.selected.map_or(
                    ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta),
                    ChooseTreeResult::Activate,
                ));
            }
            ChooseTreeAction::SearchStart { reverse } => {
                self.search = Some(ChooseTreeSearchState {
                    query: String::new(),
                    reverse,
                });
                self.rendered.search.clone_from(&self.search);
            }
            ChooseTreeAction::SearchAppend(text) => {
                let Some(search) = self.search.as_mut() else {
                    return Ok(ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta));
                };
                if search.query.len().saturating_add(text.len()) > MAX_CHOOSE_TREE_QUERY_BYTES {
                    return Err(ServerError::InvalidCommand(format!(
                        "choose-tree search exceeds {MAX_CHOOSE_TREE_QUERY_BYTES} bytes"
                    )));
                }
                search.query.push_str(&text);
                let search = search.clone();
                self.rendered.search = Some(search.clone());
                self.select_search_match(&search.query, search.reverse, true);
            }
            ChooseTreeAction::SearchBackspace => {
                let Some(search) = self.search.as_mut() else {
                    return Ok(ChooseTreeResult::Updated(ChooseTreeUpdateKind::Delta));
                };
                search.query.pop();
                let search = search.clone();
                self.rendered.search = Some(search.clone());
                self.select_search_match(&search.query, search.reverse, true);
            }
            ChooseTreeAction::SearchAccept => {
                if let Some(search) = self.search.take()
                    && !search.query.is_empty()
                {
                    self.last_search = Some(search);
                }
                self.rendered.search = None;
            }
            ChooseTreeAction::SearchCancel => {
                self.search = None;
                self.rendered.search = None;
            }
            ChooseTreeAction::SearchNext { reverse } => {
                if let Some(search) = self.last_search.clone() {
                    self.select_search_match(&search.query, search.reverse ^ reverse, false);
                }
            }
            ChooseTreeAction::Close => return Ok(ChooseTreeResult::Close),
            ChooseTreeAction::Key(_) => {}
        }
        Ok(ChooseTreeResult::Updated(update))
    }

    fn select_index(&mut self, index: usize) {
        let index = index.min(self.rendered.items.len().saturating_sub(1));
        self.rendered.selected = u32::try_from(index).unwrap_or(u32::MAX);
        self.selected = self.rendered.items.get(index).map(|item| item.target);
    }

    fn set_expanded(&mut self, target: ChooseTreeTarget, expanded: bool) {
        match target {
            ChooseTreeTarget::Session(session) => {
                if expanded {
                    self.expanded_sessions.insert(session);
                } else {
                    self.expanded_sessions.remove(&session);
                }
            }
            ChooseTreeTarget::Window(window) => {
                if expanded {
                    self.expanded_windows.insert(window);
                } else {
                    self.expanded_windows.remove(&window);
                }
            }
            ChooseTreeTarget::Pane(_) => {}
        }
    }

    fn select_search_match(&mut self, query: &str, reverse: bool, include_current: bool) {
        if query.is_empty() || self.rendered.items.is_empty() {
            return;
        }
        let query = query.to_lowercase();
        let len = self.rendered.items.len();
        let current = usize::try_from(self.rendered.selected)
            .unwrap_or(usize::MAX)
            .min(len - 1);
        let start = usize::from(!include_current);
        for offset in start..start.saturating_add(len) {
            let index = if reverse {
                (current + len - (offset % len)) % len
            } else {
                (current + offset) % len
            };
            let item = &self.rendered.items[index];
            if item.label.to_lowercase().contains(&query)
                || item.detail.to_lowercase().contains(&query)
                || item.target.to_string().to_lowercase().contains(&query)
            {
                self.select_index(index);
                return;
            }
        }
    }
}

fn push_choose_tree_item(items: &mut Vec<ChooseTreeItem>, item: ChooseTreeItem) -> bool {
    if items.len() >= MAX_CHOOSE_TREE_ITEMS {
        return false;
    }
    items.push(item);
    true
}

fn bounded_choose_tree_text(text: &str) -> String {
    if text.len() <= MAX_CHOOSE_TREE_ITEM_BYTES {
        return text.to_owned();
    }
    let mut end = MAX_CHOOSE_TREE_ITEM_BYTES.saturating_sub('…'.len_utf8());
    while !text.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}…", &text[..end])
}

fn format_count(count: usize, noun: &str) -> String {
    if count == 1 {
        format!("1 {noun}")
    } else {
        format!("{count} {noun}s")
    }
}

const fn choose_tree_flags(expanded: bool, has_children: bool, active: bool) -> u8 {
    let mut flags = 0;
    if expanded {
        flags |= ChooseTreeItem::EXPANDED;
    }
    if has_children {
        flags |= ChooseTreeItem::HAS_CHILDREN;
    }
    if active {
        flags |= ChooseTreeItem::ACTIVE;
    }
    flags
}

#[derive(Debug)]
struct CommandOutputSession {
    pane: PaneId,
    terminal: Arc<TerminalSession>,
    previous_key_table: Option<String>,
}

struct PopupWaiter {
    client: ClientId,
    wake: crossbeam_channel::Sender<u8>,
}

struct PopupSession {
    terminal: Arc<TerminalSession>,
    state: PopupState,
    cell_width_px: u32,
    cell_height_px: u32,
    waiter: Option<PopupWaiter>,
}

struct MenuSession {
    state: MenuState,
    commands: Vec<Option<String>>,
    target: ExecutionContext,
    waiter: Option<MenuWaiter>,
}

struct MenuWaiter {
    client: ClientId,
    wake: crossbeam_channel::Sender<()>,
}

enum ConfirmExecution {
    Blocking {
        client: ClientId,
        wake: crossbeam_channel::Sender<bool>,
    },
    Deferred {
        commands: Vec<CommandInvocation>,
        context: ExecutionContext,
    },
    Background {
        commands: Vec<CommandInvocation>,
    },
}

struct ConfirmSession {
    state: ConfirmState,
    execution: ConfirmExecution,
}

enum EitherPopupFinish {
    Closed(RetiredPopup),
    Retained(PopupState),
}

fn current_command_output_subscriber(
    inner: &ServerState,
    client: ClientId,
    pane: PaneId,
    terminal: &Arc<TerminalSession>,
) -> Option<Arc<OutboundMailbox>> {
    let output = inner.command_outputs.get(&client)?;
    if output.pane != pane || !Arc::ptr_eq(&output.terminal, terminal) {
        return None;
    }
    inner.subscribers.get(&client).cloned()
}

type RetiredCommandOutput = (CommandOutputSession, Option<Arc<OutboundMailbox>>);
type RetiredPopup = (PopupSession, Option<Arc<OutboundMailbox>>);

#[derive(Clone, Copy, PartialEq, Eq)]
enum Overlay {
    CommandPrompt,
    ChooseTree,
    ChooseBuffer,
    DisplayPanes,
    Popup,
    Menu,
    Confirm,
}

fn dismiss_overlays(
    inner: &mut ServerState,
    client: ClientId,
    raising: Option<Overlay>,
    events: &mut Vec<EventPayload>,
    retired: &mut Vec<(ClientId, RetiredCommandOutput)>,
    retired_popups: &mut Vec<(ClientId, RetiredPopup)>,
) {
    if raising != Some(Overlay::CommandPrompt) && inner.command_prompts.remove(&client).is_some() {
        events.push(EventPayload::CommandPrompt { state: None });
    }
    if raising != Some(Overlay::ChooseTree) && inner.choose_trees.remove(&client).is_some() {
        events.push(EventPayload::ChooseTree { state: None });
    }
    if raising != Some(Overlay::ChooseBuffer) && inner.choose_buffers.remove(&client).is_some() {
        events.push(EventPayload::ChooseBuffer { state: None });
    }
    if raising != Some(Overlay::DisplayPanes) && take_display_panes(inner, client).is_some() {
        events.push(EventPayload::DisplayPanes { state: None });
    }
    if let Some(output) = take_command_output(inner, client) {
        retired.push((client, output));
    }
    if raising != Some(Overlay::Popup)
        && let Some(popup) = take_popup(inner, client)
    {
        retired_popups.push((client, popup));
    }
    if raising != Some(Overlay::Menu)
        && let Some(menu) = inner.menus.remove(&client)
    {
        if let Some(waiter) = menu.waiter {
            let _ = waiter.wake.try_send(());
        }
        events.push(EventPayload::Menu { state: None });
    }
    if raising != Some(Overlay::Confirm)
        && let Some(confirm) = inner.confirms.remove(&client)
    {
        if let ConfirmExecution::Blocking { wake, .. } = confirm.execution {
            let _ = wake.try_send(false);
        }
        events.push(EventPayload::Confirm { state: None });
    }
}

fn take_command_output(inner: &mut ServerState, client: ClientId) -> Option<RetiredCommandOutput> {
    let output = inner.command_outputs.remove(&client)?;
    inner
        .key_engines
        .entry(client)
        .or_default()
        .switch_table(output.previous_key_table.clone());
    let subscriber = inner.subscribers.get(&client).cloned();
    Some((output, subscriber))
}

fn take_popup(inner: &mut ServerState, client: ClientId) -> Option<RetiredPopup> {
    let popup = inner.popups.remove(&client)?;
    let subscriber = inner.subscribers.get(&client).cloned();
    Some((popup, subscriber))
}

#[derive(Clone, Debug)]
struct PasteBuffer {
    name: String,
    data: Arc<[u8]>,
    created: SystemTime,
    automatic: bool,
    utf8: bool,
}

#[derive(Clone, Debug)]
struct ServerMessage {
    number: u64,
    time: SystemTime,
    text: String,
}

#[derive(Clone, Copy, Debug)]
struct PasteBufferPaste<'a> {
    requested_name: Option<&'a str>,
    separator: &'a [u8],
    expected_client: Option<ClientId>,
    delete: bool,
    bracketed: bool,
    literal: bool,
    event_hooks_enabled: bool,
}

#[derive(Clone, Debug)]
struct CommandPrompt {
    prompt: String,
    input: String,
    cursor: usize,
    template: Option<String>,
    history_index: Option<usize>,
    history_draft: String,
}

impl CommandPrompt {
    fn new(prompt: String, input: String, template: Option<String>) -> Self {
        let cursor = input.len();
        Self {
            prompt,
            history_draft: input.clone(),
            input,
            cursor,
            template,
            history_index: None,
        }
    }

    fn kind(&self) -> CommandPromptKind {
        if self.template.is_some() {
            CommandPromptKind::Value
        } else {
            CommandPromptKind::Command
        }
    }

    fn state(&self, history: &[String]) -> CommandPromptState {
        CommandPromptState {
            prompt: self.prompt.clone(),
            input: self.input.clone(),
            cursor: u32::try_from(self.input[..self.cursor].chars().count()).unwrap_or(u32::MAX),
            kind: self.kind(),
            history: if self.kind() == CommandPromptKind::Command {
                command_prompt_history_snapshot(history)
            } else {
                Vec::new()
            },
        }
    }

    fn replace_input(&mut self, input: String, cursor: u32) -> Result<(), ServerError> {
        if input.len() > zz_protocol::MAX_COMMAND_PROMPT_BYTES {
            return Err(ServerError::InvalidCommand(format!(
                "command prompt input exceeds {} bytes",
                zz_protocol::MAX_COMMAND_PROMPT_BYTES
            )));
        }
        let cursor = usize::try_from(cursor).unwrap_or(usize::MAX);
        let cursor = char_index_to_byte(&input, cursor).ok_or_else(|| {
            ServerError::InvalidCommand("command prompt cursor is out of bounds".to_owned())
        })?;
        self.input = input;
        self.cursor = cursor;
        self.finish_edit();
        Ok(())
    }

    fn insert(&mut self, text: &str) -> bool {
        if text.is_empty()
            || self.input.len().saturating_add(text.len()) > zz_protocol::MAX_COMMAND_PROMPT_BYTES
        {
            return false;
        }
        self.input.insert_str(self.cursor, text);
        self.cursor += text.len();
        self.finish_edit();
        true
    }

    fn move_left(&mut self) -> bool {
        let next = previous_char_boundary(&self.input, self.cursor);
        let changed = next != self.cursor;
        self.cursor = next;
        changed
    }

    fn move_right(&mut self) -> bool {
        let next = next_char_boundary(&self.input, self.cursor);
        let changed = next != self.cursor;
        self.cursor = next;
        changed
    }

    fn move_word_left(&mut self) -> bool {
        let original = self.cursor;
        while self.cursor > 0 {
            let previous = previous_char_boundary(&self.input, self.cursor);
            if !self.input[previous..self.cursor]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = previous;
        }
        while self.cursor > 0 {
            let previous = previous_char_boundary(&self.input, self.cursor);
            if self.input[previous..self.cursor]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = previous;
        }
        self.cursor != original
    }

    fn move_word_right(&mut self) -> bool {
        let original = self.cursor;
        while self.cursor < self.input.len() {
            let next = next_char_boundary(&self.input, self.cursor);
            if !self.input[self.cursor..next]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = next;
        }
        while self.cursor < self.input.len() {
            let next = next_char_boundary(&self.input, self.cursor);
            if self.input[self.cursor..next]
                .chars()
                .next()
                .is_some_and(char::is_whitespace)
            {
                break;
            }
            self.cursor = next;
        }
        self.cursor != original
    }

    fn delete_backward(&mut self) -> bool {
        let previous = previous_char_boundary(&self.input, self.cursor);
        if previous == self.cursor {
            return false;
        }
        self.input.replace_range(previous..self.cursor, "");
        self.cursor = previous;
        self.finish_edit();
        true
    }

    fn delete_forward(&mut self) -> bool {
        let next = next_char_boundary(&self.input, self.cursor);
        if next == self.cursor {
            return false;
        }
        self.input.replace_range(self.cursor..next, "");
        self.finish_edit();
        true
    }

    fn delete_previous_word(&mut self) -> bool {
        let end = self.cursor;
        self.move_word_left();
        if self.cursor == end {
            return false;
        }
        self.input.replace_range(self.cursor..end, "");
        self.finish_edit();
        true
    }

    fn clear(&mut self) -> bool {
        if self.input.is_empty() {
            return false;
        }
        self.input.clear();
        self.cursor = 0;
        self.finish_edit();
        true
    }

    fn delete_to_end(&mut self) -> bool {
        if self.cursor == self.input.len() {
            return false;
        }
        self.input.truncate(self.cursor);
        self.finish_edit();
        true
    }

    fn history_up(&mut self, history: &[String]) -> bool {
        if history.is_empty() {
            return false;
        }
        let index = self.history_index.map_or_else(
            || {
                self.history_draft.clone_from(&self.input);
                history.len() - 1
            },
            |index| index.saturating_sub(1),
        );
        if self.history_index == Some(index) {
            return false;
        }
        self.history_index = Some(index);
        self.input.clone_from(&history[index]);
        self.cursor = self.input.len();
        true
    }

    fn history_down(&mut self, history: &[String]) -> bool {
        let Some(index) = self.history_index else {
            return false;
        };
        if index + 1 < history.len() {
            self.history_index = Some(index + 1);
            self.input.clone_from(&history[index + 1]);
        } else {
            self.history_index = None;
            self.input.clone_from(&self.history_draft);
        }
        self.cursor = self.input.len();
        true
    }

    fn finish_edit(&mut self) {
        self.history_index = None;
        self.history_draft.clone_from(&self.input);
    }
}

fn command_prompt_history_snapshot(history: &[String]) -> Vec<String> {
    let mut bytes: usize = 0;
    let mut snapshot = history
        .iter()
        .rev()
        .take(MAX_COMMAND_PROMPT_HISTORY_SNAPSHOT_ITEMS)
        .take_while(|entry| {
            let next = bytes.saturating_add(entry.len());
            if next > MAX_COMMAND_PROMPT_HISTORY_SNAPSHOT_BYTES {
                false
            } else {
                bytes = next;
                true
            }
        })
        .cloned()
        .collect::<Vec<_>>();
    snapshot.reverse();
    snapshot
}

fn command_prompt_state(inner: &ServerState, client: ClientId) -> Option<CommandPromptState> {
    inner
        .command_prompts
        .get(&client)
        .map(|prompt| prompt.state(&inner.command_history))
}

fn char_index_to_byte(input: &str, index: usize) -> Option<usize> {
    input
        .char_indices()
        .nth(index)
        .map(|(offset, _)| offset)
        .or_else(|| (index == input.chars().count()).then_some(input.len()))
}

fn previous_char_boundary(text: &str, index: usize) -> usize {
    text[..index]
        .char_indices()
        .next_back()
        .map_or(0, |(index, _)| index)
}

fn next_char_boundary(text: &str, index: usize) -> usize {
    text[index..]
        .char_indices()
        .nth(1)
        .map_or(text.len(), |(offset, _)| index + offset)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PromptKeyAction {
    Handled,
    Updated,
    Close,
    Submit,
    LimitExceeded,
}

struct CommandPromptSubmission {
    input: String,
    template: Option<String>,
}

fn append_command_prompt_output(output: &mut String, piece: &str) -> bool {
    let content_limit =
        MAX_COMMAND_PROMPT_OUTPUT_BYTES.saturating_sub(COMMAND_PROMPT_OUTPUT_TRUNCATED.len() + 1);
    let separator_bytes = usize::from(!output.is_empty());
    let available = content_limit.saturating_sub(output.len());
    if separator_bytes.saturating_add(piece.len()) <= available {
        if separator_bytes != 0 {
            output.push('\n');
        }
        output.push_str(piece);
        return false;
    }

    let piece_available = available.saturating_sub(separator_bytes);
    let mut prefix_bytes = piece.len().min(piece_available);
    while !piece.is_char_boundary(prefix_bytes) {
        prefix_bytes -= 1;
    }
    if prefix_bytes != 0 {
        if separator_bytes != 0 {
            output.push('\n');
        }
        output.push_str(&piece[..prefix_bytes]);
    }
    true
}

fn bounded_command_output(text: &str) -> String {
    let mut output = String::new();
    if append_command_prompt_output(&mut output, text) {
        if !output.is_empty() {
            output.push('\n');
        }
        output.push_str(COMMAND_PROMPT_OUTPUT_TRUNCATED);
    }
    output
}

fn client_context_pane(inner: &ServerState, client: ClientId) -> Option<PaneId> {
    client_attached_session(inner, client)
        .and_then(|session| inner.engine.state.sessions.get(&session))
        .and_then(|session| {
            inner
                .engine
                .state
                .windows
                .get(&client_focused_window(inner, client, session))
        })
        .map(|window| window.active_pane)
        .or_else(|| {
            inner
                .engine
                .state
                .default_context()
                .map(|(_, _, pane)| pane)
        })
}

fn enter_copy_session(
    inner: &mut ServerState,
    client: ClientId,
    pane: PaneId,
) -> Result<(), ServerError> {
    let table = inner.engine.copy_mode_table_for_pane(pane)?.to_owned();
    inner
        .key_engines
        .entry(client)
        .or_default()
        .switch_table(Some(table));
    inner.copy_sessions.insert(
        client,
        CopySession {
            pane,
            observed: false,
            scroll_exit: false,
        },
    );
    Ok(())
}

fn terminal_view_action_arms_scroll_exit(action: &zz_terminal::TerminalViewAction) -> bool {
    matches!(
        action,
        zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::PageDownScrollExit)
    )
}

fn exit_copy_session(inner: &mut ServerState, client: ClientId) {
    inner.copy_sessions.remove(&client);
    inner
        .key_engines
        .entry(client)
        .or_default()
        .switch_table(None);
}

fn sync_copy_session_for_view_action(
    inner: &mut ServerState,
    client: ClientId,
    pane: PaneId,
    action: &zz_terminal::TerminalViewAction,
) -> Result<(), ServerError> {
    if terminal_view_action_enters_copy_mode(action) {
        enter_copy_session(inner, client, pane)?;
    } else if terminal_view_action_exits_copy_mode(action) {
        exit_copy_session(inner, client);
    } else if terminal_view_action_arms_scroll_exit(action)
        && let Some(session) = inner.copy_sessions.get_mut(&client)
        && session.pane == pane
    {
        session.scroll_exit = true;
    }
    Ok(())
}

fn terminal_view_action_enters_copy_mode(action: &zz_terminal::TerminalViewAction) -> bool {
    matches!(
        action,
        zz_terminal::TerminalViewAction::EnterCopyMode
            | zz_terminal::TerminalViewAction::EnterCopyModeScrollExit
    )
}

fn terminal_view_action_exits_copy_mode(action: &zz_terminal::TerminalViewAction) -> bool {
    match action {
        zz_terminal::TerminalViewAction::ClearHistory
        | zz_terminal::TerminalViewAction::CopyMode(zz_terminal::CopyModeAction::Cancel) => true,
        zz_terminal::TerminalViewAction::CopyMode(
            zz_terminal::CopyModeAction::CopySelection(copy)
            | zz_terminal::CopyModeAction::CopyEndOfLine(copy),
        ) => copy.cancel,
        _ => false,
    }
}

fn retarget_copy_mode_tables(inner: &mut ServerState, changed_window: Option<WindowId>) {
    let retargeted = inner
        .copy_sessions
        .iter()
        .filter_map(|(client, session)| {
            let window = inner.engine.state.window_for_pane(session.pane)?;
            changed_window
                .is_none_or(|changed| changed == window)
                .then_some((*client, session.pane))
        })
        .collect::<Vec<_>>();
    for (client, pane) in retargeted {
        let Ok(table) = inner.engine.copy_mode_table_for_pane(pane) else {
            continue;
        };
        let table = table.to_owned();
        inner
            .key_engines
            .entry(client)
            .or_default()
            .switch_table(Some(table));
    }
}

fn unfocused_copy_sessions(inner: &mut ServerState) -> Vec<(ClientId, Arc<TerminalSession>)> {
    let stale = inner
        .copy_sessions
        .iter()
        .filter(|(client, session)| client_context_pane(inner, **client) != Some(session.pane))
        .map(|(client, session)| (*client, session.pane))
        .collect::<Vec<_>>();
    stale
        .into_iter()
        .filter_map(|(client, pane)| {
            exit_copy_session(inner, client);
            Some((client, inner.terminals.get(&pane).cloned()?))
        })
        .collect()
}

fn reconcile_copy_session(
    inner: &mut ServerState,
    pane: PaneId,
    client: ClientId,
    mode: TerminalMode,
) -> (Option<Arc<TerminalSession>>, bool) {
    match (mode, inner.copy_sessions.get_mut(&client)) {
        (TerminalMode::Copy { .. }, Some(session)) if session.pane == pane => {
            session.observed = true;
            (None, false)
        }
        (TerminalMode::Copy { .. }, _) => (inner.terminals.get(&pane).cloned(), false),
        (TerminalMode::Live, Some(session))
            if session.pane == pane && (session.observed || session.scroll_exit) =>
        {
            exit_copy_session(inner, client);
            (None, true)
        }
        _ => (None, false),
    }
}

fn client_attached_session(inner: &ServerState, client: ClientId) -> Option<SessionId> {
    inner
        .attached
        .iter()
        .find_map(|(session, clients)| clients.contains(&client).then_some(*session))
}

fn format_client_flags(inner: &ServerState, client: ClientId) -> String {
    if inner.client_kinds.get(&client) != Some(&ClientKind::Control) {
        return String::new();
    }
    let mut flags = vec!["control-mode".to_owned()];
    if let Some(output) = inner.control_outputs.get(&client) {
        if output.no_output {
            flags.push("no-output".to_owned());
        }
        if output.wait_exit {
            flags.push("wait-exit".to_owned());
        }
        if let Some(pause_after_ms) = output.pause_after_ms {
            flags.push(format!("pause-after={}", pause_after_ms / 1000));
        }
    }
    flags.join(",")
}

fn control_client_geometry(
    inner: &ServerState,
    client: ClientId,
    window: WindowId,
) -> Option<TerminalGeometry> {
    let output = inner.control_outputs.get(&client)?;
    output
        .window_geometries
        .get(&window)
        .copied()
        .or(output.geometry)
}

fn control_client_sized_panes(inner: &ServerState, client: ClientId) -> BTreeSet<PaneId> {
    let Some(session) = client_attached_session(inner, client)
        .and_then(|session| inner.engine.state.sessions.get(&session))
    else {
        return BTreeSet::new();
    };
    let Some(output) = inner.control_outputs.get(&client) else {
        return BTreeSet::new();
    };
    session
        .windows
        .iter()
        .filter(|window| output.geometry.is_some() || output.window_geometries.contains_key(window))
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys().copied())
        .collect()
}

fn client_format_facts(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
) -> ClientFormatFacts {
    let session_state = &inner.engine.state.sessions[&session];
    let window = client_focused_window(inner, client, session_state);
    let geometry = if inner.client_kinds.get(&client) == Some(&ClientKind::Control) {
        control_client_geometry(inner, client, window)
    } else {
        None
    };
    let format_context = inner
        .engine
        .format_status_context(Some(session), Some(window), None);
    ClientFormatFacts {
        name: inner
            .client_names
            .get(&client)
            .cloned()
            .unwrap_or_else(|| format!("device-{}", client.0)),
        session: session_state.name.clone(),
        width: geometry.map_or(0, |geometry| geometry.columns),
        height: geometry.map_or(0, |geometry| geometry.rows),
        termname: String::new(),
        uid: format_context.uid,
        user: format_context.user,
        flags: format_client_flags(inner, client),
        theme: inner
            .client_color_schemes
            .get(&client)
            .copied()
            .unwrap_or_default()
            .as_str()
            .to_owned(),
        line: 0,
    }
}

fn client_focused_window(
    inner: &ServerState,
    client: ClientId,
    session: &zz_mux::Session,
) -> WindowId {
    inner
        .focused_windows
        .get(&client)
        .copied()
        .filter(|focused| session.windows.contains(focused))
        .unwrap_or(session.active_window)
}

fn client_focused_window_for_attachment(inner: &ServerState, client: ClientId) -> Option<WindowId> {
    client_attached_session(inner, client)
        .and_then(|session| inner.engine.state.sessions.get(&session))
        .map(|session| client_focused_window(inner, client, session))
}

fn resolve_popup_client(
    inner: &ServerState,
    invoking_client: ClientId,
    context: &ExecutionContext,
    target: Option<&str>,
) -> Result<ClientId, ServerError> {
    let eligible = inner
        .subscribers
        .keys()
        .copied()
        .filter(|client| client_attached_session(inner, *client).is_some())
        .collect::<Vec<_>>();
    if let Some(target) = target {
        return eligible
            .into_iter()
            .find(|client| {
                inner
                    .client_names
                    .get(client)
                    .is_some_and(|name| name == target)
                    || target == client.0.to_string()
                    || target == format!("client-{}", client.0)
                    || target == format!("device-{}", client.0)
            })
            .ok_or_else(|| ServerError::InvalidCommand(format!("can't find client: {target}")));
    }
    if eligible.contains(&invoking_client) {
        return Ok(invoking_client);
    }
    if let Some(owner) = context
        .pane
        .and_then(|pane| terminal_geometry_owner(inner, pane))
        && eligible.contains(&owner)
    {
        return Ok(owner);
    }
    eligible
        .into_iter()
        .next()
        .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))
}

fn resolve_attached_client(
    inner: &ServerState,
    invoking_client: ClientId,
    target: Option<&str>,
) -> Result<ClientId, ServerError> {
    let attached = inner
        .attached
        .values()
        .flat_map(BTreeSet::iter)
        .copied()
        .collect::<BTreeSet<_>>();
    if let Some(target) = target {
        return attached
            .into_iter()
            .find(|client| {
                inner
                    .client_names
                    .get(client)
                    .is_some_and(|name| name == target)
                    || target == client.0.to_string()
                    || target == format!("client-{}", client.0)
                    || target == format!("device-{}", client.0)
            })
            .ok_or_else(|| ServerError::InvalidCommand(format!("can't find client: {target}")));
    }
    attached
        .contains(&invoking_client)
        .then_some(invoking_client)
        .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))
}

fn popup_client_geometry(
    inner: &ServerState,
    client: ClientId,
) -> Result<Option<TerminalGeometry>, ServerError> {
    let session_id = client_attached_session(inner, client)
        .ok_or_else(|| ServerError::InvalidCommand("no current client".to_owned()))?;
    let session = inner
        .engine
        .state
        .sessions
        .get(&session_id)
        .ok_or_else(|| ServerError::MissingTarget(session_id.to_string()))?;
    let window_id = client_focused_window(inner, client, session);
    if inner.client_kinds.get(&client) == Some(&ClientKind::Control) {
        return Ok(control_client_geometry(inner, client, window_id));
    }
    let window = inner
        .engine
        .state
        .windows
        .get(&window_id)
        .ok_or_else(|| ServerError::MissingTarget(window_id.to_string()))?;
    let pane = window.active_pane;
    let measured = inner
        .terminal_geometries
        .get(&pane)
        .and_then(|geometries| geometries.get(&client))
        .copied();
    let columns = inner
        .engine
        .window_extent(window_id, zz_protocol::Axis::Horizontal)
        .unwrap_or(80);
    let rows = inner
        .engine
        .window_extent(window_id, zz_protocol::Axis::Vertical)
        .unwrap_or(24);
    Ok(Some(measured.map_or(
        TerminalGeometry {
            columns,
            rows,
            cell_width_px: CONTROL_CELL_WIDTH_PX,
            cell_height_px: CONTROL_CELL_HEIGHT_PX,
        },
        |geometry| TerminalGeometry {
            columns,
            rows,
            ..geometry
        },
    )))
}

fn popup_position_variables(
    engine: &MuxEngine,
    target: &ExecutionContext,
    columns: u16,
    rows: u16,
    width: u16,
    height: u16,
) -> BTreeMap<String, String> {
    let status = engine.format_status_context(target.session, target.window, target.pane);
    let centre_x = i64::from(columns.saturating_sub(1)) / 2 - i64::from(width) / 2;
    let centre_x = centre_x.max(0);
    let centre_y = i64::from(rows.saturating_sub(1)) / 2 + i64::from(height) / 2;
    let centre_y = if centre_y >= i64::from(rows) {
        i64::from(rows.saturating_sub(height))
    } else {
        centre_y
    };
    let pane_left = status.pane_left.unwrap_or_default();
    let pane_top = status.pane_top.unwrap_or_default();
    let pane_width = status.pane_width.unwrap_or(columns);
    let pane_height = status.pane_height.unwrap_or(rows);
    let pane_popup_top = i64::from(pane_top) + i64::from(height);
    let pane_popup_top = if pane_popup_top >= i64::from(rows) {
        i64::from(rows.saturating_sub(height))
    } else {
        pane_popup_top
    };
    let pane_right = i64::from(pane_left) + i64::from(pane_width) - i64::from(width);
    let mut variables = BTreeMap::from([
        ("popup_width".to_owned(), width.to_string()),
        ("popup_height".to_owned(), height.to_string()),
        ("popup_centre_x".to_owned(), centre_x.to_string()),
        ("popup_centre_y".to_owned(), centre_y.to_string()),
        ("popup_pane_top".to_owned(), pane_popup_top.to_string()),
        (
            "popup_pane_bottom".to_owned(),
            pane_top.saturating_add(pane_height).to_string(),
        ),
        ("popup_pane_left".to_owned(), pane_left.to_string()),
        ("popup_pane_right".to_owned(), pane_right.max(0).to_string()),
        ("popup_last_x".to_owned(), "0".to_owned()),
        ("popup_last_y".to_owned(), height.to_string()),
    ]);
    for (name, value) in [
        ("popup_mouse_x", i64::from(columns) / 2),
        ("popup_mouse_y", i64::from(rows) / 2),
        ("popup_mouse_centre_x", centre_x),
        ("popup_mouse_centre_y", centre_y),
        ("popup_mouse_top", centre_y),
        ("popup_mouse_bottom", centre_y),
        ("popup_status_line_y", centre_y),
        ("popup_window_status_line_x", centre_x),
        ("popup_window_status_line_y", centre_y),
    ] {
        variables.insert(name.to_owned(), value.to_string());
    }
    variables
}

fn popup_position(
    x: Option<&str>,
    y: Option<&str>,
    columns: u16,
    rows: u16,
    width: u16,
    height: u16,
    mut expand: impl FnMut(&str) -> String,
) -> (u16, u16) {
    let x = match x.unwrap_or("C") {
        "C" => "#{popup_centre_x}",
        "R" => "#{popup_pane_right}",
        "P" => "#{popup_pane_left}",
        "M" => "#{popup_mouse_centre_x}",
        "L" => "#{popup_last_x}",
        "W" => "#{popup_window_status_line_x}",
        value => value,
    };
    let y = match y.unwrap_or("C") {
        "C" => "#{popup_centre_y}",
        "P" => "#{popup_pane_bottom}",
        "M" => "#{popup_mouse_top}",
        "L" => "#{popup_last_y}",
        "S" => "#{popup_status_line_y}",
        "W" => "#{popup_window_status_line_y}",
        value => value,
    };
    let left = popup_position_value(&expand(x), columns);
    let left = left.clamp(0, i64::from(columns.saturating_sub(width)));
    let bottom = popup_position_value(&expand(y), rows);
    let top = if bottom < i64::from(height) {
        0
    } else {
        bottom - i64::from(height)
    };
    let top = top.clamp(0, i64::from(rows.saturating_sub(height)));
    (
        u16::try_from(left).unwrap_or_default(),
        u16::try_from(top).unwrap_or_default(),
    )
}

fn popup_position_value(value: &str, dimension: u16) -> i64 {
    if let Some(percent) = value.strip_suffix('%') {
        let percent = percent.parse::<u64>().unwrap_or_default();
        return i64::try_from(
            u64::from(dimension)
                .saturating_mul(percent)
                .checked_div(100)
                .unwrap_or_default(),
        )
        .unwrap_or(i64::MAX);
    }
    value.parse().unwrap_or_default()
}

type SnapshotPresence = BTreeMap<SessionId, Vec<(ClientId, SessionViewer)>>;

fn snapshot_presence(inner: &ServerState) -> SnapshotPresence {
    inner
        .attached
        .iter()
        .filter_map(|(session, clients)| {
            let session_state = inner.engine.state.sessions.get(session)?;
            let viewers = clients
                .iter()
                .map(|client| {
                    let name = inner
                        .client_names
                        .get(client)
                        .cloned()
                        .unwrap_or_else(|| format!("device-{}", client.0));
                    (
                        *client,
                        SessionViewer {
                            name,
                            window: client_focused_window(inner, *client, session_state),
                            is_self: false,
                        },
                    )
                })
                .collect();
            Some((*session, viewers))
        })
        .collect()
}

fn stamp_snapshot_for_client(
    inner: &ServerState,
    client: ClientId,
    snapshot: &mut MuxSnapshot,
    presence: &SnapshotPresence,
) {
    snapshot.focused_window = client_focused_window_for_attachment(inner, client);
    for session in &mut snapshot.sessions {
        session.viewers = presence
            .get(&session.id)
            .into_iter()
            .flatten()
            .map(|(viewer_client, viewer)| SessionViewer {
                is_self: *viewer_client == client,
                ..viewer.clone()
            })
            .collect();
    }
    let facts = format_hook_facts(inner);
    expand_window_status_labels(&inner.engine, &facts, snapshot);
}

fn expand_window_status_labels(
    engine: &MuxEngine,
    facts: &FormatHookFacts,
    snapshot: &mut MuxSnapshot,
) {
    for session in &mut snapshot.sessions {
        for window in &mut session.windows {
            let formats = engine.window_status_formats(window.id);
            let format = if window.id == session.active_window {
                &formats.current_format
            } else {
                &formats.format
            };
            let context = engine.format_status_context(
                Some(session.id),
                Some(window.id),
                Some(window.active_pane),
            );
            let mut hooks = DaemonFormatHooks::command(facts);
            let style = expand_window_status_style(&formats, &context, &mut hooks);
            let label = expand_status(format, &context, &mut hooks);
            window.status_label =
                truncate_window_status_label(format!("#[{style}]#[push-default]{label}"));
        }
    }
}

fn expand_window_status_style(
    formats: &zz_mux::WindowStatusFormats,
    context: &zz_mux::StatusContext,
    hooks: &mut DaemonFormatHooks<'_>,
) -> String {
    let mut style = if context.window_active == Some(true) {
        let current = expand_status(&formats.current_style, context, hooks);
        if current == "default" {
            expand_status(&formats.style, context, hooks)
        } else {
            current
        }
    } else {
        expand_status(&formats.style, context, hooks)
    };
    if context.window_last == Some(true) {
        let last = expand_status(&formats.last_style, context, hooks);
        append_window_status_style(&mut style, &last);
    }
    if context.window_bell {
        let bell = expand_status(&formats.bell_style, context, hooks);
        append_window_status_style(&mut style, &bell);
    }
    style
}

fn append_window_status_style(style: &mut String, layer: &str) {
    if layer == "default" || layer.is_empty() {
        return;
    }
    if !style.is_empty() {
        style.push(' ');
    }
    style.push_str(layer);
}

fn truncate_window_status_label(mut label: String) -> String {
    if label.len() <= MAX_WINDOW_STATUS_LABEL_BYTES {
        return label;
    }
    let boundary = (0..=MAX_WINDOW_STATUS_LABEL_BYTES)
        .rev()
        .find(|index| label.is_char_boundary(*index))
        .unwrap_or_default();
    label.truncate(boundary);
    label
}

fn command_prompt_key(
    prompt: &mut CommandPrompt,
    input: &zz_terminal::KeyInput,
    text_follows: bool,
    history: &[String],
) -> PromptKeyAction {
    if input.action == zz_terminal::KeyAction::Release {
        return PromptKeyAction::Handled;
    }
    let changed = |changed| {
        if changed {
            PromptKeyAction::Updated
        } else {
            PromptKeyAction::Handled
        }
    };
    let control = input.modifiers.control();
    let alt = input.modifiers.alt();
    let platform = input.modifiers.platform();

    match input.key {
        zz_terminal::KeyCode::Enter => PromptKeyAction::Submit,
        zz_terminal::KeyCode::Escape => PromptKeyAction::Close,
        zz_terminal::KeyCode::Backspace => changed(prompt.delete_backward()),
        zz_terminal::KeyCode::Delete => changed(prompt.delete_forward()),
        zz_terminal::KeyCode::Home => changed({
            let changed = prompt.cursor != 0;
            prompt.cursor = 0;
            changed
        }),
        zz_terminal::KeyCode::End => changed({
            let changed = prompt.cursor != prompt.input.len();
            prompt.cursor = prompt.input.len();
            changed
        }),
        zz_terminal::KeyCode::ArrowLeft if control || alt => changed(prompt.move_word_left()),
        zz_terminal::KeyCode::ArrowRight if control || alt => changed(prompt.move_word_right()),
        zz_terminal::KeyCode::ArrowLeft if platform => changed({
            let changed = prompt.cursor != 0;
            prompt.cursor = 0;
            changed
        }),
        zz_terminal::KeyCode::ArrowRight if platform => changed({
            let changed = prompt.cursor != prompt.input.len();
            prompt.cursor = prompt.input.len();
            changed
        }),
        zz_terminal::KeyCode::ArrowLeft => changed(prompt.move_left()),
        zz_terminal::KeyCode::ArrowRight => changed(prompt.move_right()),
        zz_terminal::KeyCode::ArrowUp => changed(prompt.history_up(history)),
        zz_terminal::KeyCode::ArrowDown => changed(prompt.history_down(history)),
        zz_terminal::KeyCode::Character(character) if control => {
            match character.to_ascii_lowercase() {
                'a' => changed({
                    let changed = prompt.cursor != 0;
                    prompt.cursor = 0;
                    changed
                }),
                'e' => changed({
                    let changed = prompt.cursor != prompt.input.len();
                    prompt.cursor = prompt.input.len();
                    changed
                }),
                'b' => changed(prompt.move_left()),
                'f' => changed(prompt.move_right()),
                'p' => changed(prompt.history_up(history)),
                'n' => changed(prompt.history_down(history)),
                'h' => changed(prompt.delete_backward()),
                'd' => changed(prompt.delete_forward()),
                'u' => changed(prompt.clear()),
                'k' => changed(prompt.delete_to_end()),
                'w' => changed(prompt.delete_previous_word()),
                'c' | 'g' | '[' => PromptKeyAction::Close,
                _ => PromptKeyAction::Handled,
            }
        }
        zz_terminal::KeyCode::Character(character) if alt => match character.to_ascii_lowercase() {
            'b' => changed(prompt.move_word_left()),
            'f' => changed(prompt.move_word_right()),
            _ => PromptKeyAction::Handled,
        },
        zz_terminal::KeyCode::Character(_) if platform => PromptKeyAction::Handled,
        zz_terminal::KeyCode::Character(character) => {
            if text_follows {
                PromptKeyAction::Handled
            } else {
                let text = input
                    .text
                    .as_deref()
                    .map_or_else(|| character.to_string(), str::to_owned);
                if prompt.insert(&text) {
                    PromptKeyAction::Updated
                } else {
                    PromptKeyAction::LimitExceeded
                }
            }
        }
        zz_terminal::KeyCode::Tab
        | zz_terminal::KeyCode::Insert
        | zz_terminal::KeyCode::PageUp
        | zz_terminal::KeyCode::PageDown
        | zz_terminal::KeyCode::Function(_)
        | zz_terminal::KeyCode::Unidentified => PromptKeyAction::Handled,
    }
}

struct ShellJobPermit {
    shared: Arc<Shared>,
    token: u64,
    process: Arc<Mutex<Option<Child>>>,
}

impl ShellJobPermit {
    fn acquire(shared: &Arc<Shared>) -> Option<Self> {
        let mut inner = shared.inner.lock();
        if shared.stopping.load(Ordering::Acquire) || inner.active_shell_jobs >= MAX_SHELL_JOBS {
            return None;
        }
        inner.next_shell_job_token = inner.next_shell_job_token.wrapping_add(1).max(1);
        let token = inner.next_shell_job_token;
        let process = Arc::new(Mutex::new(None));
        inner.active_shell_jobs += 1;
        inner.shell_jobs.insert(token, Arc::clone(&process));
        drop(inner);
        Some(Self {
            shared: Arc::clone(shared),
            token,
            process,
        })
    }
}

impl Drop for ShellJobPermit {
    fn drop(&mut self) {
        let mut inner = self.shared.inner.lock();
        inner.shell_jobs.remove(&self.token);
        inner.active_shell_jobs = inner.active_shell_jobs.saturating_sub(1);
    }
}

struct ShellJobResult {
    output: Vec<u8>,
    status: ExitStatus,
}

#[cfg(unix)]
fn run_shell_job(
    command: &str,
    cwd: &Path,
    tmux: &str,
    zz_socket: &Path,
    startup_reentry: Option<&str>,
    tmux_shim: Option<&Path>,
    zz_executable: Option<&Path>,
    show_stderr: bool,
    job_process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
) -> Result<ShellJobResult, ()> {
    use std::{
        os::{fd::OwnedFd, unix::net::UnixStream, unix::process::CommandExt as _},
        process::Stdio,
    };

    let (mut output, child_socket) = UnixStream::pair().map_err(|_| ())?;
    let stdin = OwnedFd::from(child_socket.try_clone().map_err(|_| ())?);
    let stdout = OwnedFd::from(child_socket.try_clone().map_err(|_| ())?);
    let cwd = existing_job_working_directory(cwd);
    let mut process = shell_process(command);
    process
        .arg0("sh")
        .process_group(0)
        .current_dir(&cwd)
        .env("PWD", cwd.as_os_str())
        .env("TMUX", tmux)
        .env("ZZ_SOCKET", zz_socket)
        .env_remove("TMUX_PANE")
        .stdin(Stdio::from(stdin))
        .stdout(Stdio::from(stdout));
    if let Some(startup_reentry) = startup_reentry {
        process.env(crate::STARTUP_REENTRY_ENVIRONMENT_VARIABLE, startup_reentry);
    }
    crate::configure_tmux_shim(&mut process, tmux_shim, zz_executable);
    if show_stderr {
        let stderr = OwnedFd::from(child_socket.try_clone().map_err(|_| ())?);
        process.stderr(Stdio::from(stderr));
    } else {
        process.stderr(Stdio::null());
    }
    let child = process.spawn().map_err(|_| ())?;
    drop(process);
    drop(child_socket);
    install_shell_job_process(job_process, stopping, child)?;
    let mut bytes = Vec::new();
    if output.read_to_end(&mut bytes).is_err() {
        terminate_managed_process(job_process);
        return Err(());
    }
    let status = wait_shell_job_process(job_process)?;
    Ok(ShellJobResult {
        output: bytes,
        status,
    })
}

#[cfg(not(unix))]
fn run_shell_job(
    command: &str,
    cwd: &Path,
    tmux: &str,
    zz_socket: &Path,
    startup_reentry: Option<&str>,
    tmux_shim: Option<&Path>,
    zz_executable: Option<&Path>,
    show_stderr: bool,
    job_process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
) -> Result<ShellJobResult, ()> {
    let cwd = existing_job_working_directory(cwd);
    let mut process = shell_process(command);
    process
        .current_dir(&cwd)
        .env("PWD", cwd.as_os_str())
        .env("TMUX", tmux)
        .env("ZZ_SOCKET", zz_socket)
        .env_remove("TMUX_PANE")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(if show_stderr {
            Stdio::piped()
        } else {
            Stdio::null()
        });
    if let Some(startup_reentry) = startup_reentry {
        process.env(crate::STARTUP_REENTRY_ENVIRONMENT_VARIABLE, startup_reentry);
    }
    crate::configure_tmux_shim(&mut process, tmux_shim, zz_executable);
    let mut child = process.spawn().map_err(|_| ())?;
    let _stdin = child.stdin.take();
    let Some(mut stdout) = child.stdout.take() else {
        let _ = terminate_copy_pipe(&mut child);
        return Err(());
    };
    let stderr = child.stderr.take();
    install_shell_job_process(job_process, stopping, child)?;
    let stdout = thread::spawn(move || {
        let mut output = Vec::new();
        stdout.read_to_end(&mut output).map(|_| output)
    });
    let stderr = stderr.map(|mut stderr| {
        thread::spawn(move || {
            let mut output = Vec::new();
            stderr.read_to_end(&mut output).map(|_| output)
        })
    });
    let status = wait_shell_job_process(job_process);
    let mut output = stdout.join().map_err(|_| ())?.map_err(|_| ())?;
    if let Some(stderr) = stderr {
        output.extend(stderr.join().map_err(|_| ())?.map_err(|_| ())?);
    }
    let status = status?;
    Ok(ShellJobResult { output, status })
}

fn install_shell_job_process(
    process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
    mut child: Child,
) -> Result<(), ()> {
    let mut process = process.lock();
    if stopping.load(Ordering::Acquire) {
        drop(process);
        let _ = terminate_copy_pipe(&mut child);
        return Err(());
    }
    *process = Some(child);
    Ok(())
}

fn wait_shell_job_process(process: &Mutex<Option<Child>>) -> Result<ExitStatus, ()> {
    loop {
        let mut process = process.lock();
        let Some(child) = process.as_mut() else {
            return Err(());
        };
        match child.try_wait() {
            Ok(Some(status)) => {
                process.take();
                return Ok(status);
            }
            Ok(None) => drop(process),
            Err(_) => {
                let mut child = process.take().expect("shell job process was present");
                drop(process);
                let _ = terminate_copy_pipe(&mut child);
                return Err(());
            }
        }
        thread::sleep(COPY_PIPE_POLL_INTERVAL);
    }
}

fn shell_job_output(command: &str, result: &ShellJobResult) -> (String, u8) {
    let mut output = String::from_utf8_lossy(&result.output).into_owned();
    let (exit_code, message) = shell_exit(result.status).map_or_else(
        || {
            let exit_code = result
                .status
                .code()
                .and_then(|code| u8::try_from(code).ok())
                .unwrap_or(1);
            let message = (exit_code != 0).then(|| format!("'{command}' returned {exit_code}"));
            (exit_code, message)
        },
        |signal| {
            let exit_code = u8::try_from(128_i32.saturating_add(signal)).unwrap_or(u8::MAX);
            (
                exit_code,
                Some(format!("'{command}' terminated by signal {signal}")),
            )
        },
    );
    if let Some(message) = message {
        append_inserted_output(&mut output, &message);
    }
    (output, exit_code)
}

#[cfg(unix)]
fn shell_exit(status: ExitStatus) -> Option<i32> {
    use std::os::unix::process::ExitStatusExt as _;

    status.signal()
}

#[cfg(not(unix))]
fn shell_exit(_: ExitStatus) -> Option<i32> {
    None
}

struct CopyPipePermit {
    shared: Arc<Shared>,
}

impl Drop for CopyPipePermit {
    fn drop(&mut self) {
        let mut inner = self.shared.inner.lock();
        inner.active_copy_pipes = inner.active_copy_pipes.saturating_sub(1);
    }
}

fn run_copy_pipe(command: &str, data: &str) -> Result<(), String> {
    run_copy_pipe_with_timeout(command, data, COPY_PIPE_TIMEOUT)
}

fn run_copy_pipe_with_timeout(command: &str, data: &str, timeout: Duration) -> Result<(), String> {
    let mut input = tempfile::tempfile()
        .map_err(|error| format!("could not stage input in a temporary file: {error}"))?;
    input
        .write_all(data.as_bytes())
        .map_err(|error| format!("could not stage input: {error}"))?;
    input
        .seek(SeekFrom::Start(0))
        .map_err(|error| format!("could not rewind staged input: {error}"))?;

    let mut process = shell_process(command);
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _;

        process.process_group(0);
    }
    process
        .stdin(Stdio::from(input))
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    let mut child = process
        .spawn()
        .map_err(|error| format!("could not start process: {error}"))?;
    let started = Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) if status.success() => return Ok(()),
            Ok(Some(status)) => return Err(format!("process exited unsuccessfully ({status})")),
            Ok(None) if started.elapsed() >= timeout => {
                let (kill_error, wait_error) = terminate_copy_pipe(&mut child);
                if let Some(error) = kill_error {
                    return Err(format!(
                        "process timed out after {} seconds and could not be terminated: {error}",
                        timeout.as_secs()
                    ));
                }
                if let Some(error) = wait_error {
                    return Err(format!(
                        "process timed out after {} seconds and could not be reaped: {error}",
                        timeout.as_secs()
                    ));
                }
                return Err(format!(
                    "process timed out after {} seconds",
                    timeout.as_secs()
                ));
            }
            Ok(None) => thread::sleep(COPY_PIPE_POLL_INTERVAL),
            Err(error) => {
                terminate_copy_pipe(&mut child);
                return Err(format!("could not query process status: {error}"));
            }
        }
    }
}

fn terminate_copy_pipe(child: &mut Child) -> (Option<String>, Option<std::io::Error>) {
    #[cfg(unix)]
    let tree_result = rustix::process::kill_process_group(
        rustix::process::Pid::from_child(&*child),
        rustix::process::Signal::KILL,
    )
    .or_else(|error| {
        if error == rustix::io::Errno::SRCH {
            Ok(())
        } else {
            Err(error)
        }
    })
    .map_err(|error| format!("could not terminate process group: {error}"));
    #[cfg(windows)]
    let tree_result = {
        let pid = child.id().to_string();
        std::process::Command::new("taskkill")
            .args(["/PID", pid.as_str(), "/T", "/F"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .map_err(|error| format!("could not run taskkill: {error}"))
            .and_then(|status| {
                if status.success() {
                    Ok(())
                } else {
                    Err(format!("taskkill exited unsuccessfully ({status})"))
                }
            })
    };
    #[cfg(not(any(unix, windows)))]
    let tree_result = Err("process-tree termination is unsupported".to_owned());
    let child_error = child.kill().err();
    let kill_error = tree_result.err().map(|tree_error| match child_error {
        Some(child_error) => {
            format!("{tree_error}; could not terminate immediate child: {child_error}")
        }
        None => tree_error,
    });
    let wait_error = child.wait().err();
    (kill_error, wait_error)
}

fn terminate_managed_process(process: &Mutex<Option<Child>>) {
    let Some(mut child) = process.lock().take() else {
        return;
    };
    let _ = terminate_copy_pipe(&mut child);
}

fn pane_pipe_process_exited(process: &Mutex<Option<Child>>) -> bool {
    let mut process = process.lock();
    let Some(child) = process.as_mut() else {
        return true;
    };
    match child.try_wait() {
        Ok(Some(_)) => {
            process.take();
            true
        }
        Ok(None) => false,
        Err(_) => {
            let mut child = process.take().expect("pipe process was present");
            drop(process);
            let _ = terminate_copy_pipe(&mut child);
            true
        }
    }
}

fn stop_pane_pipe(mut pipe: PanePipe) {
    pipe.stop.store(true, Ordering::Release);
    terminate_managed_process(&pipe.process);
    if let Some(worker) = pipe.thread.take()
        && worker.join().is_err()
    {
        log::error!("pipe-pane worker panicked for pane process {}", pipe.pid);
    }
    let terminal = Arc::clone(&pipe.terminal.lock());
    let _ = terminal.disarm_raw_output_tap(pipe.token);
}

fn control_output_wanted(inner: &ServerState, pane: PaneId) -> bool {
    let Some(window) = inner.engine.state.window_for_pane(pane) else {
        return false;
    };
    inner
        .engine
        .state
        .sessions
        .iter()
        .filter(|(_, session)| session.windows.contains(&window))
        .filter_map(|(session, _)| inner.attached.get(session))
        .flatten()
        .any(|client| inner.client_kinds.get(client) == Some(&ClientKind::Control))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ControlOutputAgeAction {
    Output(u64),
    Pause,
    Kill,
}

fn control_output_age_action(
    pause_after_ms: Option<u64>,
    enqueued_at: Instant,
    now: Instant,
) -> ControlOutputAgeAction {
    let age = now.saturating_duration_since(enqueued_at);
    let age_ms = u64::try_from(age.as_millis()).unwrap_or(u64::MAX);
    if let Some(pause_after_ms) = pause_after_ms {
        if age_ms >= pause_after_ms {
            ControlOutputAgeAction::Pause
        } else {
            ControlOutputAgeAction::Output(age_ms)
        }
    } else if age >= CONTROL_MAXIMUM_AGE {
        ControlOutputAgeAction::Kill
    } else {
        ControlOutputAgeAction::Output(age_ms)
    }
}

fn drain_control_pane_output(
    output: &mut ControlPaneOutput,
    limit: usize,
    now: Instant,
) -> (u64, Vec<u8>) {
    let enqueued_at = output
        .pending
        .front()
        .expect("pending control output is present")
        .enqueued_at;
    let age_ms =
        u64::try_from(now.saturating_duration_since(enqueued_at).as_millis()).unwrap_or(u64::MAX);
    let mut bytes = Vec::with_capacity(limit);
    while bytes.len() < limit {
        let Some(chunk) = output.pending.front_mut() else {
            break;
        };
        let take = (limit - bytes.len()).min(chunk.bytes.len().saturating_sub(chunk.offset));
        bytes.extend_from_slice(&chunk.bytes[chunk.offset..chunk.offset + take]);
        chunk.offset += take;
        if chunk.offset == chunk.bytes.len() {
            output.pending.pop_front();
        }
    }
    (age_ms, bytes)
}

fn stop_control_output_tap(mut tap: ControlOutputTap) {
    tap.stop.store(true, Ordering::Release);
    let _ = tap.terminal.disarm_raw_output_tap(tap.token);
    if let Some(worker) = tap.thread.take()
        && worker.join().is_err()
    {
        log::error!("control output worker panicked");
    }
}

fn run_control_output_tap(
    shared: &std::sync::Weak<Shared>,
    pane: PaneId,
    stop: &Arc<AtomicBool>,
    receiver: &crossbeam_channel::Receiver<Arc<[u8]>>,
) {
    loop {
        match receiver.recv_timeout(COPY_PIPE_POLL_INTERVAL) {
            Ok(bytes) => {
                let Some(shared) = shared.upgrade() else {
                    break;
                };
                if stop.load(Ordering::Acquire) {
                    shared.publish_pipe_output_for_pane(pane, &bytes);
                } else {
                    shared.publish_control_output_for_pane(pane, &bytes);
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                let Some(shared) = shared.upgrade() else {
                    break;
                };
                shared.pump_control_output_at(Instant::now());
                if stop.load(Ordering::Acquire) {
                    break;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn run_pane_pipe(
    shared: &std::sync::Weak<Shared>,
    pane: PaneId,
    token: u64,
    terminal: &Arc<Mutex<Arc<TerminalSession>>>,
    process: &Arc<Mutex<Option<Child>>>,
    stop: &Arc<AtomicBool>,
    mut child_input: Option<std::process::ChildStdin>,
    child_output: Option<std::process::ChildStdout>,
    tap: Option<crossbeam_channel::Receiver<Arc<[u8]>>>,
) {
    let input_worker = child_output.map(|mut output| {
        let terminal = Arc::clone(terminal);
        let stop = Arc::clone(stop);
        thread::Builder::new()
            .name(format!("zz-pipe-input-{}", pane.0))
            .spawn(move || {
                let mut buffer = vec![0_u8; 64 * 1024];
                while !stop.load(Ordering::Acquire) {
                    match output.read(&mut buffer) {
                        Ok(0) | Err(_) => break,
                        Ok(length) => {
                            let target = Arc::clone(&terminal.lock());
                            if !target.send_raw_input(Arc::from(&buffer[..length])) {
                                break;
                            }
                        }
                    }
                }
            })
    });
    let input_worker = match input_worker {
        Some(Ok(worker)) => Some(worker),
        Some(Err(_)) => {
            stop.store(true, Ordering::Release);
            None
        }
        None => None,
    };
    let mut exited = false;
    while !stop.load(Ordering::Acquire) {
        let Some(tap) = tap.as_ref() else {
            if pane_pipe_process_exited(process) {
                exited = true;
                break;
            }
            thread::sleep(COPY_PIPE_POLL_INTERVAL);
            continue;
        };
        match tap.recv_timeout(COPY_PIPE_POLL_INTERVAL) {
            Ok(bytes) => {
                let Some(input) = child_input.as_mut() else {
                    break;
                };
                if input.write_all(&bytes).is_err() {
                    exited = pane_pipe_process_exited(process);
                    break;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Timeout) => {
                if pane_pipe_process_exited(process) {
                    exited = true;
                    break;
                }
            }
            Err(crossbeam_channel::RecvTimeoutError::Disconnected) => break,
        }
    }
    drop(tap);
    drop(child_input);
    if !exited {
        terminate_managed_process(process);
    }
    if let Some(worker) = input_worker {
        let _ = worker.join();
    }
    let terminal = Arc::clone(&terminal.lock());
    let _ = terminal.disarm_raw_output_tap(token);
    if let Some(shared) = shared.upgrade() {
        shared.pipe_finished(pane, token);
    }
}

enum PaneSink {
    Terminal(Arc<TerminalSession>),
    Browser(PaneId),
}

enum DeferredTerminalCommand {
    SetWordSeparators {
        terminal: Arc<TerminalSession>,
        separators: WordSeparators,
    },
    SetAllowPassthrough {
        terminal: Arc<TerminalSession>,
        enabled: bool,
    },
    SetWrapSearch {
        terminal: Arc<TerminalSession>,
        enabled: bool,
    },
    SetAppearance {
        terminal: Arc<TerminalSession>,
        appearance: Arc<TerminalAppearance>,
    },
    AttachView {
        terminal: Arc<TerminalSession>,
        view: TerminalViewId,
    },
    Resize {
        terminal: Arc<TerminalSession>,
        geometry: TerminalGeometry,
    },
    ViewAction {
        terminal: Arc<TerminalSession>,
        view: TerminalViewId,
        action: zz_terminal::TerminalViewAction,
    },
    SendTokens {
        terminals: Vec<Arc<TerminalSession>>,
        keys: Vec<zz_protocol::KeyToken>,
    },
}

impl DeferredTerminalCommand {
    #[cfg(test)]
    const fn wrap_search(&self) -> Option<bool> {
        match self {
            Self::SetWrapSearch { enabled, .. } => Some(*enabled),
            _ => None,
        }
    }

    fn run(self) {
        match self {
            Self::SetWordSeparators {
                terminal,
                separators,
            } => terminal.set_word_separators(separators),
            Self::SetAllowPassthrough { terminal, enabled } => {
                terminal.set_allow_passthrough(enabled);
            }
            Self::SetWrapSearch { terminal, enabled } => terminal.set_wrap_search(enabled),
            Self::SetAppearance {
                terminal,
                appearance,
            } => terminal.set_appearance(appearance),
            Self::AttachView { terminal, view } => terminal.attach_view(view),
            Self::Resize { terminal, geometry } => terminal.resize(
                geometry.columns,
                geometry.rows,
                geometry.cell_width_px,
                geometry.cell_height_px,
            ),
            Self::ViewAction {
                terminal,
                view,
                action,
            } => terminal.view_action(view, action),
            Self::SendTokens { terminals, keys } => send_tokens(&terminals, &keys),
        }
    }
}

fn resolve_input_sinks(inner: &ServerState, source: PaneId) -> Result<Vec<PaneSink>, ServerError> {
    let targets = inner.engine.synchronized_input_targets(source)?;
    let mut sinks = Vec::with_capacity(targets.len());
    for pane in targets {
        if let Some(terminal) = inner.terminals.get(&pane) {
            sinks.push(PaneSink::Terminal(Arc::clone(terminal)));
        } else if matches!(
            inner.engine.state.pane(pane).map(|pane| &pane.kind),
            Some(
                zz_mux::PaneKind::Picker { .. }
                    | zz_mux::PaneKind::Agent(_)
                    | zz_mux::PaneKind::Editor(_)
            )
        ) {
        } else if matches!(
            inner.engine.state.pane(pane).map(|pane| &pane.kind),
            Some(zz_mux::PaneKind::Browser(_))
        ) {
            ensure_browser_attached(inner, pane)?;
            sinks.push(PaneSink::Browser(pane));
        } else {
            return Err(ServerError::PaneExited(pane));
        }
    }
    Ok(sinks)
}

fn session_terminals(inner: &ServerState, session: SessionId) -> Vec<Arc<TerminalSession>> {
    inner
        .engine
        .state
        .sessions
        .get(&session)
        .into_iter()
        .flat_map(|session| session.windows.iter())
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys())
        .filter_map(|pane| inner.terminals.get(pane).cloned())
        .collect()
}

fn terminal_viewport_for_pane(
    inner: &ServerState,
    pane: PaneId,
    view: TerminalViewId,
) -> Option<(Arc<TerminalSession>, Arc<TerminalViewport>)> {
    let terminal = inner.terminals.get(&pane)?;
    let viewport = terminal.latest_viewport_for(view).or_else(|| {
        inner
            .engine
            .state
            .pane(pane)
            .is_some_and(|pane| pane.dead)
            .then(|| terminal.latest_viewport())
    })?;
    Some((Arc::clone(terminal), viewport))
}

fn visible_terminal_panes(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
) -> BTreeSet<PaneId> {
    if inner.client_kinds.get(&client) == Some(&ClientKind::Control) {
        return BTreeSet::new();
    }
    let Some(session) = inner.engine.state.sessions.get(&session) else {
        return BTreeSet::new();
    };
    let focused_window = client_focused_window(inner, client, session);
    let Some(window) = inner.engine.state.windows.get(&focused_window) else {
        return BTreeSet::new();
    };
    window
        .panes
        .keys()
        .filter(|pane| {
            window.zoomed_pane.is_none_or(|zoomed| **pane == zoomed)
                && inner.terminals.contains_key(pane)
        })
        .copied()
        .collect()
}

/// The agent panes a client can actually see, derived exactly like the
/// terminal ones: attached session, focused window, zoom.
#[cfg(feature = "agent")]
fn visible_agent_panes(
    inner: &ServerState,
    client: ClientId,
    session: SessionId,
) -> BTreeSet<PaneId> {
    let Some(session) = inner.engine.state.sessions.get(&session) else {
        return BTreeSet::new();
    };
    let focused_window = client_focused_window(inner, client, session);
    let Some(window) = inner.engine.state.windows.get(&focused_window) else {
        return BTreeSet::new();
    };
    window
        .panes
        .keys()
        .filter(|pane| {
            window.zoomed_pane.is_none_or(|zoomed| **pane == zoomed)
                && inner
                    .engine
                    .state
                    .pane(**pane)
                    .is_some_and(|pane| matches!(pane.kind, PaneKind::Agent(_)))
        })
        .copied()
        .collect()
}

fn attached_clients_for_pane(inner: &ServerState, pane: PaneId) -> Option<&BTreeSet<ClientId>> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let session = inner.engine.state.windows.get(&window)?.session;
    inner.attached.get(&session)
}

fn client_is_attached_to_pane(inner: &ServerState, client: ClientId, pane: PaneId) -> bool {
    attached_clients_for_pane(inner, pane).is_some_and(|clients| clients.contains(&client))
}

fn remove_client_terminal_geometries(
    inner: &mut ServerState,
    client: ClientId,
) -> BTreeSet<PaneId> {
    let mut affected = BTreeSet::new();
    inner.terminal_geometries.retain(|pane, geometries| {
        if geometries.remove(&client).is_some() {
            affected.insert(*pane);
        }
        !geometries.is_empty()
    });
    affected
}

fn terminal_geometry_owner(inner: &ServerState, pane: PaneId) -> Option<ClientId> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let session = inner.engine.state.windows.get(&window)?.session;
    inner
        .attached
        .get(&session)?
        .iter()
        .filter(|client| {
            inner.client_kinds.get(*client) == Some(&ClientKind::Control)
                || inner
                    .visible_terminals
                    .get(*client)
                    .is_some_and(|visible| visible.contains(&pane))
        })
        .filter(|client| client_terminal_geometry(inner, **client, pane).is_some())
        .min_by_key(|client| {
            (
                Reverse(
                    inner
                        .client_terminal_input_sequences
                        .get(*client)
                        .copied()
                        .unwrap_or_default(),
                ),
                client.0,
            )
        })
        .copied()
}

fn client_terminal_geometry(
    inner: &ServerState,
    client: ClientId,
    pane: PaneId,
) -> Option<TerminalGeometry> {
    if inner.client_kinds.get(&client) != Some(&ClientKind::Control) {
        return inner.terminal_geometries.get(&pane)?.get(&client).copied();
    }
    let window = inner.engine.state.window_for_pane(pane)?;
    let session = inner.engine.state.windows.get(&window)?.session;
    if client_attached_session(inner, client) != Some(session) {
        return None;
    }
    let geometry = control_client_geometry(inner, client, window)?;
    let (columns, rows) =
        inner
            .engine
            .pane_geometry_at_window_extent(pane, geometry.columns, geometry.rows)?;
    Some(TerminalGeometry {
        columns,
        rows,
        ..geometry
    })
}

#[cfg(test)]
fn aggressive_terminal_geometry(inner: &ServerState, pane: PaneId) -> Option<TerminalGeometry> {
    terminal_geometry_for_mode(inner, pane, true, WindowSize::Smallest)
}

fn terminal_geometry_for_mode(
    inner: &ServerState,
    pane: PaneId,
    aggressive: bool,
    mode: WindowSize,
) -> Option<TerminalGeometry> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let window_state = inner.engine.state.windows.get(&window)?;
    if window_state
        .zoomed_pane
        .is_some_and(|zoomed| zoomed != pane)
    {
        return None;
    }
    let session = window_state.session;
    let candidates = inner
        .attached
        .get(&session)?
        .iter()
        .filter(|client| {
            if aggressive {
                client_focused_window_for_attachment(inner, **client) == Some(window)
            } else {
                inner.client_kinds.get(*client) == Some(&ClientKind::Control)
                    || inner
                        .visible_terminals
                        .get(*client)
                        .is_some_and(|visible| visible.contains(&pane))
            }
        })
        .filter_map(|client| {
            client_terminal_geometry(inner, *client, pane).map(|geometry| (*client, geometry))
        })
        .collect::<Vec<_>>();
    let owner = candidates.iter().min_by_key(|(client, _)| {
        (
            Reverse(
                inner
                    .client_terminal_input_sequences
                    .get(client)
                    .copied()
                    .unwrap_or_default(),
            ),
            client.0,
        )
    })?;
    if matches!(mode, WindowSize::Latest | WindowSize::Manual) {
        return Some(owner.1);
    }
    let first_geometry = candidates.first()?.1;
    let mut columns = first_geometry.columns;
    let mut rows = first_geometry.rows;
    for (_, geometry) in &candidates[1..] {
        if mode == WindowSize::Largest {
            columns = columns.max(geometry.columns);
            rows = rows.max(geometry.rows);
        } else {
            columns = columns.min(geometry.columns);
            rows = rows.min(geometry.rows);
        }
    }
    Some(TerminalGeometry {
        columns,
        rows,
        ..owner.1
    })
}

fn terminal_resize_for_pane(
    inner: &ServerState,
    pane: PaneId,
) -> Option<(Arc<TerminalSession>, TerminalGeometry)> {
    let window = inner.engine.state.window_for_pane(pane)?;
    let aggressive = inner.engine.state.window_aggressive_resize(window).ok()?;
    let mode = inner.engine.window_size(window);
    let geometry = terminal_geometry_for_mode(inner, pane, aggressive, mode)?;
    let terminal = inner.terminals.get(&pane).cloned()?;
    Some((terminal, geometry))
}

fn write_back_terminal_geometries(
    inner: &mut ServerState,
    panes: &BTreeSet<PaneId>,
    aggressive_only: bool,
) -> bool {
    let measurements = panes
        .iter()
        .filter_map(|pane| {
            let window = inner.engine.state.window_for_pane(*pane)?;
            if aggressive_only && !inner.engine.state.window_aggressive_resize(window).ok()? {
                return None;
            }
            terminal_resize_for_pane(inner, *pane)
                .map(|(_, geometry)| (*pane, geometry.columns, geometry.rows))
        })
        .collect::<Vec<_>>();
    measurements
        .into_iter()
        .fold(false, |changed, (pane, columns, rows)| {
            inner.engine.set_pane_geometry(pane, columns, rows) || changed
        })
}

fn panes_for_windows(inner: &ServerState, windows: &BTreeSet<WindowId>) -> BTreeSet<PaneId> {
    windows
        .iter()
        .filter_map(|window| inner.engine.state.windows.get(window))
        .flat_map(|window| window.panes.keys().copied())
        .collect()
}

fn terminal_resizes_after_client_input(
    inner: &mut ServerState,
    client: ClientId,
    source_pane: PaneId,
) -> Vec<(Arc<TerminalSession>, TerminalGeometry)> {
    let Some(visible_panes) = inner.visible_terminals.get(&client) else {
        return Vec::new();
    };
    if !visible_panes.contains(&source_pane) || !inner.terminals.contains_key(&source_pane) {
        return Vec::new();
    }
    let previous_owners = visible_panes
        .iter()
        .map(|pane| (*pane, terminal_geometry_owner(inner, *pane)))
        .collect::<Vec<_>>();

    let sequence = inner
        .terminal_input_sequence
        .checked_add(1)
        .expect("terminal input sequence exhausted");
    inner.terminal_input_sequence = sequence;
    inner
        .client_terminal_input_sequences
        .insert(client, sequence);

    previous_owners
        .into_iter()
        .filter(|(pane, previous)| terminal_geometry_owner(inner, *pane) != *previous)
        .filter_map(|(pane, _)| terminal_resize_for_pane(inner, pane))
        .collect()
}

fn terminal_view_action_is_input(action: &zz_terminal::TerminalViewAction) -> bool {
    use zz_terminal::TerminalViewAction as Action;

    match action {
        Action::Focus(_) | Action::ClearLinkHover => false,
        Action::Mouse(input) => input.phase() != zz_terminal::TerminalMousePhase::Motion,
        Action::ScrollLines(_)
        | Action::ScrollPages(_)
        | Action::ScrollTop
        | Action::ScrollBottom
        | Action::ScrollToFraction(_)
        | Action::ScrollToOffset(_)
        | Action::ScrollWheel { .. }
        | Action::SelectionPress(_)
        | Action::SelectionDrag(_)
        | Action::SelectionAutoscroll { .. }
        | Action::SelectionRelease(_)
        | Action::SelectAll
        | Action::ClearSelection
        | Action::ClearHistory
        | Action::EnterCopyMode
        | Action::EnterCopyModeScrollExit
        | Action::CopyMode(_)
        | Action::CopySelection { .. }
        | Action::SearchBegin(_)
        | Action::SearchUpdate(_)
        | Action::SearchNext
        | Action::SearchPrevious
        | Action::SearchClose
        | Action::Paste(_) => true,
    }
}

fn terminal_resizes_for_panes(
    inner: &ServerState,
    panes: &BTreeSet<PaneId>,
) -> Vec<(Arc<TerminalSession>, TerminalGeometry)> {
    panes
        .iter()
        .filter_map(|pane| terminal_resize_for_pane(inner, *pane))
        .collect()
}

fn apply_terminal_resizes(resizes: Vec<(Arc<TerminalSession>, TerminalGeometry)>) {
    for (terminal, geometry) in resizes {
        terminal.resize(
            geometry.columns,
            geometry.rows,
            geometry.cell_width_px,
            geometry.cell_height_px,
        );
    }
}

fn find_buffer<'a>(inner: &'a ServerState, name: Option<&str>) -> Option<&'a PasteBuffer> {
    inner
        .paste_buffers
        .iter()
        .find(|buffer| name.map_or(buffer.automatic, |name| buffer.name == name))
}

fn buffer_format_facts(buffer: &PasteBuffer) -> BufferFormatFacts {
    BufferFormatFacts {
        name: buffer.name.clone(),
        data: Arc::clone(&buffer.data),
        created: buffer.created,
    }
}

fn format_hook_facts(inner: &ServerState) -> FormatHookFacts {
    FormatHookFacts {
        terminals: Arc::new(inner.terminals.clone()),
        pane_pipes: Arc::new(
            inner
                .pane_pipes
                .iter()
                .map(|(pane, pipe)| (*pane, pipe.pid))
                .collect(),
        ),
        session_attachments: Arc::new(
            inner
                .attached
                .iter()
                .map(|(session, clients)| {
                    let names = clients
                        .iter()
                        .filter_map(|client| inner.client_names.get(client))
                        .cloned()
                        .collect::<Vec<_>>()
                        .join(",");
                    (*session, (clients.len(), names))
                })
                .collect(),
        ),
        buffer: inner
            .paste_buffers
            .iter()
            .find(|buffer| buffer.automatic)
            .map(buffer_format_facts),
        ..FormatHookFacts::default()
    }
}

fn resolve_buffer<'a>(
    inner: &'a ServerState,
    name: Option<&str>,
) -> Result<&'a PasteBuffer, ServerError> {
    find_buffer(inner, name).ok_or_else(|| {
        name.map_or_else(
            || ServerError::MissingTarget("paste buffer".to_owned()),
            |name| ServerError::MissingTarget(name.to_owned()),
        )
    })
}

const RUN_SHELL_USAGE: &str = "usage: run-shell [-bCE] [-c start-directory] [-d delay] [-t target-pane] [shell-command [argument ...]]";
const IF_SHELL_USAGE: &str =
    "usage: if-shell [-bF] [-t target-pane] shell-command command [command]";
const WAIT_FOR_USAGE: &str = "usage: wait-for [-L|-S|-U] channel";
const PIPE_PANE_USAGE: &str = "usage: pipe-pane [-IOo] [-t target-pane] [shell-command]";

fn next_wait_token(inner: &mut ServerState) -> u64 {
    inner.next_wait_token = inner.next_wait_token.wrapping_add(1).max(1);
    inner.next_wait_token
}

fn remove_wait_channel_if_unused(channels: &mut BTreeMap<String, WaitChannel>, name: &str) {
    if channels
        .get(name)
        .is_some_and(|channel| !channel.locked && channel.waiters.is_empty() && channel.woken)
    {
        channels.remove(name);
    }
}

fn remove_wait_item(inner: &mut ServerState, name: &str, token: u64) {
    let Some(channel) = inner.wait_channels.get_mut(name) else {
        return;
    };
    channel.waiters.retain(|item| item.token != token);
    channel.lockers.retain(|item| item.token != token);
    remove_wait_channel_if_unused(&mut inner.wait_channels, name);
}

fn wake_wait_items(wakes: impl IntoIterator<Item = crossbeam_channel::Sender<()>>) {
    for wake in wakes {
        let _ = wake.try_send(());
    }
}

fn take_all_wait_wakes(
    channels: &mut BTreeMap<String, WaitChannel>,
) -> Vec<crossbeam_channel::Sender<()>> {
    let mut wakes = Vec::new();
    for (_, mut channel) in std::mem::take(channels) {
        wakes.extend(channel.waiters.drain(..).map(|item| item.wake));
        wakes.extend(channel.lockers.drain(..).map(|item| item.wake));
    }
    wakes
}

fn remove_client_wait_items(channels: &mut BTreeMap<String, WaitChannel>, client: ClientId) {
    for channel in channels.values_mut() {
        channel.waiters.retain(|item| item.client != client);
        channel.lockers.retain(|item| item.client != client);
    }
}

#[derive(Clone)]
enum InsertedCommandSource {
    Shell(String),
    String(String),
    Block(String),
}

#[derive(Default)]
struct InsertedCommandResult {
    output: String,
    exit_code: u8,
}

#[derive(Clone, Copy)]
struct RunShellRoute {
    client: ClientId,
    kind: ClientKind,
    foreground: bool,
    target_requested: bool,
    target: Option<PaneId>,
}

struct ParsedRunShellArgs {
    background: bool,
    command_mode: bool,
    show_stderr: bool,
    cwd: Option<String>,
    delay: Option<Duration>,
    target: Option<String>,
    positional: Vec<String>,
}

struct ParsedIfShellArgs {
    background: bool,
    format: bool,
    target: Option<String>,
    positional: Vec<String>,
}

fn parse_run_shell_args(args: &[String]) -> Result<ParsedRunShellArgs, ServerError> {
    let parsed =
        parse_buffer_command_args("run-shell", args, &['c', 'd', 's', 't'], &['b', 'C', 'E'])?;
    let delay = parsed.value('d').map(parse_shell_delay).transpose()?;
    Ok(ParsedRunShellArgs {
        background: parsed.has('b'),
        command_mode: parsed.has('C'),
        show_stderr: parsed.has('E'),
        cwd: parsed.value('c').map(str::to_owned),
        delay,
        target: parsed.value('t').map(str::to_owned),
        positional: parsed.positional,
    })
}

fn parse_if_shell_args(args: &[String]) -> Result<ParsedIfShellArgs, ServerError> {
    let parsed = parse_buffer_command_args("if-shell", args, &['t'], &['b', 'F'])?;
    if !(2..=3).contains(&parsed.positional.len()) {
        return Err(ServerError::InvalidCommand(IF_SHELL_USAGE.to_owned()));
    }
    Ok(ParsedIfShellArgs {
        background: parsed.has('b'),
        format: parsed.has('F'),
        target: parsed.value('t').map(str::to_owned),
        positional: parsed.positional,
    })
}

fn parse_shell_delay(value: &str) -> Result<Duration, ServerError> {
    let seconds = parse_shell_delay_seconds(value)
        .ok_or_else(|| ServerError::InvalidCommand(format!("invalid delay time: {value}")))?;
    Duration::try_from_secs_f64(seconds)
        .map_err(|_| ServerError::InvalidCommand(format!("invalid delay time: {value}")))
}

fn parse_shell_delay_seconds(value: &str) -> Option<f64> {
    if value.is_empty() {
        return Some(0.0);
    }
    let value = value.trim_start_matches(char::is_whitespace);
    if value.is_empty() {
        return Some(0.0);
    }
    let (negative, unsigned) = value
        .strip_prefix('-')
        .map_or((false, value), |value| (true, value));
    let unsigned = unsigned.strip_prefix('+').unwrap_or(unsigned);
    let seconds = if let Some(hex) = unsigned
        .strip_prefix("0x")
        .or_else(|| unsigned.strip_prefix("0X"))
    {
        u64::from_str_radix(hex, 16).ok()? as f64
    } else {
        value.parse::<f64>().ok()?
    };
    let seconds = if negative { -seconds } else { seconds };
    (seconds.is_finite() && seconds >= 0.0).then_some(seconds)
}

fn inserted_command_source(argument: &str) -> InsertedCommandSource {
    command_block_body(argument).map_or_else(
        || InsertedCommandSource::String(argument.to_owned()),
        |body| InsertedCommandSource::Block(body.to_owned()),
    )
}

fn select_if_shell_branch(positional: &[String], truthy: bool) -> Option<&str> {
    if truthy {
        positional.get(1)
    } else {
        positional.get(2)
    }
    .map(String::as_str)
}

fn append_inserted_output(output: &mut String, addition: &str) {
    if addition.is_empty() {
        return;
    }
    if !output.is_empty() && !output.ends_with('\n') {
        output.push('\n');
    }
    output.push_str(addition);
}

fn prepend_command_output(mut output: String, error: DaemonError) -> DaemonError {
    if output.is_empty() {
        return error;
    }
    match error {
        DaemonError::CommandExit {
            output: error_output,
            exit_code,
        } => {
            append_inserted_output(&mut output, &error_output);
            DaemonError::CommandExit { output, exit_code }
        }
        DaemonError::CommandFailed {
            output: error_output,
            error,
        } => {
            append_inserted_output(&mut output, &error_output);
            DaemonError::CommandFailed { output, error }
        }
        error => DaemonError::CommandFailed {
            output,
            error: Box::new(error),
        },
    }
}

fn inserted_execution(
    client: ClientId,
    kind: ClientKind,
    result: InsertedCommandResult,
) -> Result<Execution, DaemonError> {
    if matches!(kind, ClientKind::Command | ClientKind::Control)
        && client != ClientId(u64::MAX)
        && result.exit_code != 0
    {
        Err(DaemonError::CommandExit {
            output: result.output,
            exit_code: result.exit_code,
        })
    } else {
        Ok(Execution {
            output: result.output,
            effects: Vec::new(),
        })
    }
}

fn job_working_directory(
    inner: &ServerState,
    context: &ExecutionContext,
    requested: Option<&str>,
) -> PathBuf {
    if let Some(requested) = requested {
        return PathBuf::from(requested);
    }
    context
        .pane
        .and_then(|pane| inner.terminals.get(&pane))
        .and_then(|terminal| terminal_working_directory(terminal))
        .filter(|path| path.is_dir())
        .or_else(|| std::env::current_dir().ok().filter(|path| path.is_dir()))
        .unwrap_or_else(fallback_job_working_directory)
}

fn fallback_job_working_directory() -> PathBuf {
    home_directory()
        .filter(|path| path.is_dir())
        .unwrap_or_else(|| PathBuf::from("/"))
}

fn existing_job_working_directory(path: &Path) -> Cow<'_, Path> {
    if path.is_dir() {
        Cow::Borrowed(path)
    } else {
        Cow::Owned(fallback_job_working_directory())
    }
}

fn daemon_error_text(error: &DaemonError) -> String {
    match error {
        DaemonError::CommandFailed { error, .. } => daemon_error_text(error),
        DaemonError::Server(error) => server_error_text(error),
        error => error.to_string(),
    }
}

fn server_error_text(error: &ServerError) -> String {
    match error {
        ServerError::InvalidCommand(message) => message.clone(),
        error => error.to_string(),
    }
}

fn discard_command_output(error: DaemonError) -> DaemonError {
    match error {
        DaemonError::CommandFailed { error, .. } => discard_command_output(*error),
        error => error,
    }
}

fn daemon_error_output(error: &DaemonError) -> Option<&str> {
    match error {
        DaemonError::CommandExit { output, .. } | DaemonError::CommandFailed { output, .. }
            if !output.is_empty() =>
        {
            Some(output)
        }
        _ => None,
    }
}

fn hook_resolution_error(error: &DaemonError) -> bool {
    match error {
        DaemonError::CommandFailed { error, .. } => hook_resolution_error(error),
        DaemonError::Server(
            ServerError::MissingTarget(_)
            | ServerError::SessionNotFound(_)
            | ServerError::WindowNotFound(_)
            | ServerError::PaneNotFound(_)
            | ServerError::PaneNotAttached(_)
            | ServerError::PaneExited(_),
        ) => true,
        _ => false,
    }
}

fn uppercase_first(message: &mut String) {
    let Some(first) = message.chars().next() else {
        return;
    };
    let length = first.len_utf8();
    message.replace_range(..length, &first.to_uppercase().collect::<String>());
}

#[derive(Debug, Default)]
struct ParsedBufferCommandArgs {
    flags: BTreeSet<char>,
    values: BTreeMap<char, String>,
    repeated_values: BTreeMap<char, Vec<String>>,
    positional: Vec<String>,
}

impl ParsedBufferCommandArgs {
    fn has(&self, flag: char) -> bool {
        self.flags.contains(&flag)
    }

    fn value(&self, option: char) -> Option<&str> {
        self.values.get(&option).map(String::as_str)
    }

    fn values(&self, option: char) -> impl Iterator<Item = &str> {
        self.repeated_values
            .get(&option)
            .into_iter()
            .flatten()
            .map(String::as_str)
    }
}

fn parse_control_pane_state(value: &str) -> Option<(PaneId, &str)> {
    let (pane, state) = value.split_once(':')?;
    Some((pane.parse().ok()?, state))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ControlClientSizeUpdate {
    Client(TerminalGeometry),
    Window(WindowId, Option<TerminalGeometry>),
}

fn parse_control_dimensions(value: &str, separator: char) -> Option<(u64, u64)> {
    let (columns, rows) = value.split_once(separator)?;
    if columns.is_empty() || rows.is_empty() || rows.contains(separator) {
        return None;
    }
    Some((columns.parse().ok()?, rows.parse().ok()?))
}

fn checked_control_geometry(columns: u64, rows: u64) -> Result<TerminalGeometry, ServerError> {
    let in_range = |value| {
        (u64::from(CONTROL_SIZE_MINIMUM)..=u64::from(CONTROL_SIZE_MAXIMUM)).contains(&value)
    };
    if !in_range(columns) || !in_range(rows) {
        return Err(ServerError::InvalidCommand(
            "size too small or too big".to_owned(),
        ));
    }
    Ok(TerminalGeometry {
        columns: u16::try_from(columns).expect("validated control columns fit u16"),
        rows: u16::try_from(rows).expect("validated control rows fit u16"),
        cell_width_px: CONTROL_CELL_WIDTH_PX,
        cell_height_px: CONTROL_CELL_HEIGHT_PX,
    })
}

fn parse_control_client_size(value: &str) -> Result<ControlClientSizeUpdate, ServerError> {
    if let Some((window, size)) = value.split_once(':')
        && value.matches(':').count() == 1
        && let Ok(window) = window.parse::<WindowId>()
    {
        if size.is_empty() {
            return Ok(ControlClientSizeUpdate::Window(window, None));
        }
        let (columns, rows) = parse_control_dimensions(size, 'x')
            .ok_or_else(|| ServerError::InvalidCommand("bad size argument".to_owned()))?;
        return checked_control_geometry(columns, rows)
            .map(|geometry| ControlClientSizeUpdate::Window(window, Some(geometry)));
    }
    let dimensions = parse_control_dimensions(value, ',')
        .or_else(|| parse_control_dimensions(value, 'x'))
        .ok_or_else(|| ServerError::InvalidCommand("bad size argument".to_owned()))?;
    checked_control_geometry(dimensions.0, dimensions.1).map(ControlClientSizeUpdate::Client)
}

enum ControlSubscriptionUpdate<'a> {
    Remove(&'a str),
    Set {
        name: &'a str,
        scope: ControlSubscriptionScope,
        format: &'a str,
    },
}

fn parse_control_subscription(value: &str) -> ControlSubscriptionUpdate<'_> {
    let mut fields = value.splitn(3, ':');
    let name = fields.next().unwrap_or_default();
    let Some(what) = fields.next() else {
        return ControlSubscriptionUpdate::Remove(value);
    };
    let Some(format) = fields.next() else {
        return ControlSubscriptionUpdate::Remove(value);
    };
    let scope = match what {
        "%*" => ControlSubscriptionScope::AllPanes,
        "@*" => ControlSubscriptionScope::AllWindows,
        what if what.starts_with('%') => what.parse().map_or(
            ControlSubscriptionScope::Session,
            ControlSubscriptionScope::Pane,
        ),
        what if what.starts_with('@') => what.parse().map_or(
            ControlSubscriptionScope::Session,
            ControlSubscriptionScope::Window,
        ),
        _ => ControlSubscriptionScope::Session,
    };
    ControlSubscriptionUpdate::Set {
        name,
        scope,
        format,
    }
}

fn control_subscription_target(
    session: SessionId,
    window: Option<&zz_mux::Window>,
    pane: Option<PaneId>,
) -> ControlSubscriptionTarget {
    ControlSubscriptionTarget {
        session,
        window: window.map(|window| window.id),
        window_index: window.map(|window| window.index),
        pane,
    }
}

fn control_subscription_targets(
    inner: &ServerState,
    session: SessionId,
    scope: ControlSubscriptionScope,
) -> Vec<ControlSubscriptionTarget> {
    let Some(session_state) = inner.engine.state.sessions.get(&session) else {
        return Vec::new();
    };
    match scope {
        ControlSubscriptionScope::Session => {
            vec![control_subscription_target(session, None, None)]
        }
        ControlSubscriptionScope::Pane(pane) => {
            let Some(window) = inner
                .engine
                .state
                .window_for_pane(pane)
                .and_then(|window| inner.engine.state.windows.get(&window))
                .filter(|window| window.session == session)
            else {
                return Vec::new();
            };
            vec![control_subscription_target(
                session,
                Some(window),
                Some(pane),
            )]
        }
        ControlSubscriptionScope::Window(window) => inner
            .engine
            .state
            .windows
            .get(&window)
            .filter(|window| window.session == session)
            .map(|window| vec![control_subscription_target(session, Some(window), None)])
            .unwrap_or_default(),
        ControlSubscriptionScope::AllPanes => session_state
            .windows
            .iter()
            .filter_map(|window| inner.engine.state.windows.get(window))
            .flat_map(|window| {
                window
                    .panes
                    .keys()
                    .copied()
                    .map(|pane| control_subscription_target(session, Some(window), Some(pane)))
            })
            .collect(),
        ControlSubscriptionScope::AllWindows => session_state
            .windows
            .iter()
            .filter_map(|window| inner.engine.state.windows.get(window))
            .map(|window| control_subscription_target(session, Some(window), None))
            .collect(),
    }
}

fn apply_control_client_flags(output: &mut ControlClientOutput, flags: &str) {
    for raw in flags.split(',') {
        let (clear, flag) = raw
            .strip_prefix('!')
            .map_or((false, raw), |flag| (true, flag));
        match flag {
            "no-output" => {
                output.no_output = !clear;
                output.panes.clear();
            }
            "wait-exit" => output.wait_exit = !clear,
            "pause-after" => {
                output.pause_after_ms = (!clear).then_some(0);
            }
            _ => {
                let Some(seconds) = flag
                    .strip_prefix("pause-after=")
                    .and_then(|seconds| seconds.parse::<u64>().ok())
                else {
                    continue;
                };
                let Some(milliseconds) = seconds.checked_mul(1000) else {
                    continue;
                };
                output.pause_after_ms = (!clear).then_some(milliseconds);
            }
        }
    }
}

fn parse_buffer_command_args(
    command: &str,
    args: &[String],
    value_options: &[char],
    flags: &[char],
) -> Result<ParsedBufferCommandArgs, ServerError> {
    let mut parsed = ParsedBufferCommandArgs::default();
    let mut index = 0;
    while let Some(argument) = args.get(index) {
        if argument == "--" {
            parsed.positional.extend(args[index + 1..].iter().cloned());
            break;
        }
        if !argument.starts_with('-') || argument == "-" {
            parsed.positional.push(argument.clone());
            index += 1;
            continue;
        }

        let mut consumed_next = false;
        for (offset, option) in argument[1..].char_indices() {
            if value_options.contains(&option) {
                let value_start = 1 + offset + option.len_utf8();
                let value = if value_start < argument.len() {
                    argument[value_start..].to_owned()
                } else {
                    consumed_next = true;
                    args.get(index + 1).cloned().ok_or_else(|| {
                        ServerError::InvalidCommand(format!("{command} -{option} requires a value"))
                    })?
                };
                parsed.values.insert(option, value.clone());
                parsed
                    .repeated_values
                    .entry(option)
                    .or_default()
                    .push(value);
                break;
            }
            if flags.contains(&option) {
                parsed.flags.insert(option);
            } else {
                return Err(ServerError::UnsupportedCommand(format!(
                    "{command} -{option}"
                )));
            }
        }
        index += usize::from(consumed_next) + 1;
    }
    Ok(parsed)
}

fn require_no_positionals(
    command: &str,
    parsed: &ParsedBufferCommandArgs,
) -> Result<(), ServerError> {
    if parsed.positional.is_empty() {
        Ok(())
    } else {
        Err(ServerError::InvalidCommand(format!(
            "{command} does not accept positional arguments"
        )))
    }
}

fn require_one_positional<'a>(
    command: &str,
    parsed: &'a ParsedBufferCommandArgs,
) -> Result<&'a str, ServerError> {
    let [value] = parsed.positional.as_slice() else {
        return Err(ServerError::InvalidCommand(format!(
            "{command} requires exactly one path"
        )));
    };
    Ok(value)
}

fn validate_paste_buffer_size(size: usize) -> Result<(), ServerError> {
    if size > MAX_PASTE_BUFFER_BYTES {
        Err(ServerError::InvalidCommand(format!(
            "paste buffer exceeds {MAX_PASTE_BUFFER_BYTES} bytes"
        )))
    } else {
        Ok(())
    }
}

fn validate_paste_buffer_name(name: &str) -> Result<(), ServerError> {
    if name.is_empty() {
        return Err(ServerError::InvalidCommand(
            "paste buffer name cannot be empty".to_owned(),
        ));
    }
    if name.len() > MAX_PASTE_BUFFER_NAME_BYTES {
        return Err(ServerError::InvalidCommand(format!(
            "paste buffer name exceeds {MAX_PASTE_BUFFER_NAME_BYTES} bytes"
        )));
    }
    if name.chars().any(char::is_control) {
        return Err(ServerError::InvalidCommand(
            "paste buffer name contains control characters".to_owned(),
        ));
    }
    Ok(())
}

fn insert_paste_buffer(
    inner: &mut ServerState,
    requested_name: Option<&str>,
    automatic_prefix: &str,
    data: Vec<u8>,
    replacement_delete: bool,
) -> Result<Vec<PendingHookEvent>, ServerError> {
    if data.is_empty() {
        return Ok(Vec::new());
    }
    let mut events = Vec::new();
    validate_paste_buffer_size(data.len())?;
    let (name, automatic) = if let Some(name) = requested_name {
        validate_paste_buffer_name(name)?;
        (name.to_owned(), false)
    } else {
        let mut name = None;
        for _ in 0..inner.paste_buffers.len().saturating_add(1) {
            let candidate = format!("{automatic_prefix}{}", inner.next_buffer_id);
            inner.next_buffer_id = inner.next_buffer_id.wrapping_add(1);
            validate_paste_buffer_name(&candidate)?;
            if !inner
                .paste_buffers
                .iter()
                .any(|buffer| buffer.name == candidate)
            {
                name = Some(candidate);
                break;
            }
        }
        let name = name.ok_or_else(|| {
            ServerError::InvalidCommand("no automatic paste buffer names available".to_owned())
        })?;
        while inner
            .paste_buffers
            .iter()
            .filter(|buffer| buffer.automatic)
            .count()
            >= inner.automatic_paste_buffer_limit.0
        {
            let Some(index) = inner
                .paste_buffers
                .iter()
                .rposition(|buffer| buffer.automatic)
            else {
                break;
            };
            let removed = inner.paste_buffers.remove(index);
            events.push(PendingHookEvent::paste_buffer(
                "paste-buffer-deleted",
                removed.name,
            ));
        }
        (name, true)
    };

    let utf8 = std::str::from_utf8(&data).is_ok();
    inner.paste_buffers.retain(|buffer| {
        if buffer.name == name {
            if replacement_delete {
                events.push(PendingHookEvent::paste_buffer(
                    "paste-buffer-deleted",
                    buffer.name.clone(),
                ));
            }
            false
        } else {
            true
        }
    });
    inner.paste_buffers.insert(
        0,
        PasteBuffer {
            name: name.clone(),
            data: Arc::from(data),
            created: SystemTime::now(),
            automatic,
            utf8,
        },
    );
    events.push(PendingHookEvent::paste_buffer("paste-buffer-changed", name));
    Ok(events)
}

fn read_paste_buffer_file(path: &Path) -> Result<Vec<u8>, ServerError> {
    let file =
        fs::File::open(path).map_err(|error| buffer_file_error("load-buffer", path, &error))?;
    if file
        .metadata()
        .map_err(|error| buffer_file_error("load-buffer", path, &error))?
        .len()
        > u64::try_from(MAX_PASTE_BUFFER_BYTES).expect("paste buffer limit fits in u64")
    {
        return Err(ServerError::InvalidCommand(format!(
            "{}: paste buffer exceeds {MAX_PASTE_BUFFER_BYTES} bytes",
            path.display()
        )));
    }
    let mut data = Vec::new();
    file.take(
        u64::try_from(MAX_PASTE_BUFFER_BYTES)
            .expect("paste buffer limit fits in u64")
            .saturating_add(1),
    )
    .read_to_end(&mut data)
    .map_err(|error| buffer_file_error("load-buffer", path, &error))?;
    validate_paste_buffer_size(data.len())?;
    Ok(data)
}

fn write_paste_buffer_file(path: &Path, data: &[u8], append: bool) -> Result<(), ServerError> {
    let mut options = fs::OpenOptions::new();
    options.write(true).create(true);
    if append {
        options.append(true);
    } else {
        options.truncate(true);
    }
    let mut file = options
        .open(path)
        .map_err(|error| buffer_file_error("save-buffer", path, &error))?;
    file.write_all(data)
        .and_then(|()| file.flush())
        .map_err(|error| buffer_file_error("save-buffer", path, &error))
}

fn buffer_file_error(command: &str, path: &Path, error: &std::io::Error) -> ServerError {
    ServerError::InvalidCommand(format!("{command}: {}: {error}", path.display()))
}

#[derive(Debug)]
struct ParsedCapturePane {
    target: Option<String>,
    buffer_name: Option<String>,
    options: CaptureOptions,
    quiet: bool,
}

fn parse_capture_pane_args(args: &[String]) -> Result<ParsedCapturePane, ServerError> {
    let mut parsed = ParsedCapturePane {
        target: None,
        buffer_name: None,
        options: CaptureOptions::default(),
        quiet: false,
    };
    let mut index = 0;
    while let Some(argument) = args.get(index) {
        if matches!(argument.as_str(), "-t" | "-S" | "-E" | "-b") {
            let value = args.get(index + 1).ok_or_else(|| {
                ServerError::InvalidCommand(format!("{argument} requires a value"))
            })?;
            apply_capture_value(&mut parsed, argument, value)?;
            index += 2;
            continue;
        }
        if let Some((option, value)) = ["-t", "-S", "-E", "-b"].iter().find_map(|option| {
            argument
                .strip_prefix(option)
                .filter(|value| !value.is_empty())
                .map(|value| (*option, value))
        }) {
            apply_capture_value(&mut parsed, option, value)?;
            index += 1;
            continue;
        }
        if argument == "--" {
            if index + 1 != args.len() {
                return Err(ServerError::InvalidCommand(
                    "capture-pane does not accept positional arguments".to_owned(),
                ));
            }
            break;
        }
        if !argument.starts_with('-') || argument == "-" {
            return Err(ServerError::InvalidCommand(format!(
                "unexpected capture-pane argument: {argument}"
            )));
        }
        for flag in argument[1..].chars() {
            match flag {
                'a' => parsed.options.alternate = true,
                'e' => parsed.options.escape_sequences = true,
                'J' => {
                    parsed.options.join_wrapped = true;
                    parsed.options.preserve_trailing = true;
                }
                'M' => parsed.options.mode = true,
                'N' => parsed.options.preserve_trailing = true,
                'p' | 'T' => {}
                'q' => parsed.quiet = true,
                unsupported => {
                    return Err(ServerError::UnsupportedCommand(format!(
                        "capture-pane -{unsupported}"
                    )));
                }
            }
        }
        index += 1;
    }
    Ok(parsed)
}

fn apply_capture_value(
    parsed: &mut ParsedCapturePane,
    option: &str,
    value: &str,
) -> Result<(), ServerError> {
    match option {
        "-t" => parsed.target = Some(value.to_owned()),
        "-S" => parsed.options.start = parse_capture_boundary(value, true)?,
        "-E" => parsed.options.end = parse_capture_boundary(value, false)?,
        "-b" => parsed.buffer_name = Some(value.to_owned()),
        _ => unreachable!("capture value option is validated by the caller"),
    }
    Ok(())
}

fn parse_capture_boundary(value: &str, start: bool) -> Result<CaptureBoundary, ServerError> {
    if value == "-" {
        return Ok(if start {
            CaptureBoundary::HistoryStart
        } else {
            CaptureBoundary::VisibleEnd
        });
    }
    value
        .parse::<i64>()
        .map(CaptureBoundary::Relative)
        .map_err(|_| ServerError::InvalidCommand(format!("invalid capture-pane line: {value}")))
}

#[derive(Debug, Default, PartialEq, Eq)]
struct ContextReference {
    path: String,
    start: Option<u32>,
    end: Option<u32>,
}

impl ContextReference {
    fn parse(value: &str) -> Result<Self, ServerError> {
        let invalid = |message: &str| ServerError::InvalidCommand(message.to_owned());
        let (path, range) = match value.rsplit_once(':') {
            Some((path, range)) if !path.is_empty() && parse_line_range(range).is_some() => {
                (path, parse_line_range(range))
            }
            _ => (value, None),
        };
        if path.is_empty() || path.len() > MAX_CONTEXT_PATH_BYTES {
            return Err(invalid("--context path must be 1..=4096 bytes"));
        }
        if path.chars().any(char::is_control) {
            return Err(invalid(
                "--context path must not contain control characters",
            ));
        }
        let (start, end) = range.unwrap_or((None, None));
        if let (Some(start), Some(end)) = (start, end)
            && start > end
        {
            return Err(invalid("--context line range must not run backwards"));
        }
        Ok(Self {
            path: path.to_owned(),
            start,
            end,
        })
    }

    fn header(&self) -> String {
        match (self.start, self.end) {
            (Some(start), Some(end)) => format!("{}:{start}-{end}", self.path),
            (Some(start), None) => format!("{}:{start}", self.path),
            _ => self.path.clone(),
        }
    }
}

fn parse_line_range(value: &str) -> Option<(Option<u32>, Option<u32>)> {
    if let Some((start, end)) = value.split_once('-') {
        return Some((Some(start.parse().ok()?), Some(end.parse().ok()?)));
    }
    Some((Some(value.parse().ok()?), None))
}

#[derive(Debug, Default)]
struct ParsedAgentSend {
    target: Option<String>,
    submit: bool,
    context: Option<ContextReference>,
    text: Vec<String>,
}

#[derive(Debug, Default, PartialEq, Eq)]
struct ParsedDisplayPopup {
    borderless: bool,
    clear: bool,
    close_on_exit_count: u8,
    close_on_any_key: bool,
    reset_close_flags: bool,
    border_lines: Option<String>,
    target_client: Option<String>,
    start_directory: Option<String>,
    environment: Vec<String>,
    height: Option<String>,
    style: Option<String>,
    border_style: Option<String>,
    target_pane: Option<String>,
    title: Option<String>,
    width: Option<String>,
    x: Option<String>,
    y: Option<String>,
    command: Vec<String>,
}

#[derive(Debug, Default, PartialEq, Eq)]
struct ParsedDisplayMenu {
    mouse: bool,
    stay_open: bool,
    border_lines: Option<String>,
    target_client: Option<String>,
    starting_choice: Option<String>,
    selected_style: Option<String>,
    style: Option<String>,
    border_style: Option<String>,
    target_pane: Option<String>,
    title: Option<String>,
    x: Option<String>,
    y: Option<String>,
    items: Vec<String>,
}

#[derive(Debug, Default, PartialEq, Eq)]
struct ParsedConfirmBefore {
    background: bool,
    default_yes: bool,
    confirm_key: Option<String>,
    prompt: Option<String>,
    target_client: Option<String>,
    command: Option<String>,
}

fn parse_display_popup_args(args: &[String]) -> Result<ParsedDisplayPopup, ServerError> {
    let mut parsed = ParsedDisplayPopup::default();
    let mut index = 0;
    while index < args.len() {
        let argument = &args[index];
        if argument == "--" {
            parsed
                .command
                .extend(args[index.saturating_add(1)..].iter().cloned());
            break;
        }
        if !argument.starts_with('-') || argument == "-" {
            parsed.command.extend(args[index..].iter().cloned());
            break;
        }
        for (offset, flag) in argument[1..].char_indices() {
            match flag {
                'B' => parsed.borderless = true,
                'C' => parsed.clear = true,
                'E' => {
                    parsed.close_on_exit_count = parsed.close_on_exit_count.saturating_add(1);
                }
                'k' => parsed.close_on_any_key = true,
                'N' => parsed.reset_close_flags = true,
                'b' | 'c' | 'd' | 'e' | 'h' | 's' | 'S' | 't' | 'T' | 'w' | 'x' | 'y' => {
                    let value_start = 1_usize
                        .saturating_add(offset)
                        .saturating_add(flag.len_utf8());
                    let value = if value_start < argument.len() {
                        argument[value_start..].to_owned()
                    } else {
                        index = index.saturating_add(1);
                        args.get(index).cloned().ok_or_else(|| {
                            ServerError::InvalidCommand(format!(
                                "display-popup -{flag} requires a value"
                            ))
                        })?
                    };
                    match flag {
                        'b' => parsed.border_lines = Some(value),
                        'c' => parsed.target_client = Some(value),
                        'd' => parsed.start_directory = Some(value),
                        'e' => parsed.environment.push(value),
                        'h' => parsed.height = Some(value),
                        's' => parsed.style = Some(value),
                        'S' => parsed.border_style = Some(value),
                        't' => parsed.target_pane = Some(value),
                        'T' => parsed.title = Some(value),
                        'w' => parsed.width = Some(value),
                        'x' => parsed.x = Some(value),
                        'y' => parsed.y = Some(value),
                        _ => unreachable!("valued popup option is matched"),
                    }
                    break;
                }
                _ => {
                    return Err(ServerError::UnsupportedCommand(format!(
                        "display-popup -{flag}"
                    )));
                }
            }
        }
        index = index.saturating_add(1);
    }
    Ok(parsed)
}

fn parse_display_menu_args(args: &[String]) -> Result<ParsedDisplayMenu, ServerError> {
    let mut parsed = ParsedDisplayMenu::default();
    let mut index = 0;
    while index < args.len() {
        let argument = &args[index];
        if argument == "--" {
            parsed
                .items
                .extend(args[index.saturating_add(1)..].iter().cloned());
            break;
        }
        if !argument.starts_with('-') || argument == "-" {
            parsed.items.extend(args[index..].iter().cloned());
            break;
        }
        for (offset, flag) in argument[1..].char_indices() {
            match flag {
                'M' => parsed.mouse = true,
                'O' => parsed.stay_open = true,
                'b' | 'c' | 'C' | 'H' | 's' | 'S' | 't' | 'T' | 'x' | 'y' => {
                    let value_start = 1_usize
                        .saturating_add(offset)
                        .saturating_add(flag.len_utf8());
                    let value = if value_start < argument.len() {
                        argument[value_start..].to_owned()
                    } else {
                        index = index.saturating_add(1);
                        args.get(index).cloned().ok_or_else(|| {
                            ServerError::InvalidCommand(format!(
                                "display-menu -{flag} requires a value"
                            ))
                        })?
                    };
                    match flag {
                        'b' => parsed.border_lines = Some(value),
                        'c' => parsed.target_client = Some(value),
                        'C' => parsed.starting_choice = Some(value),
                        'H' => parsed.selected_style = Some(value),
                        's' => parsed.style = Some(value),
                        'S' => parsed.border_style = Some(value),
                        't' => parsed.target_pane = Some(value),
                        'T' => parsed.title = Some(value),
                        'x' => parsed.x = Some(value),
                        'y' => parsed.y = Some(value),
                        _ => unreachable!("valued menu option is matched"),
                    }
                    break;
                }
                _ => {
                    return Err(ServerError::UnsupportedCommand(format!(
                        "display-menu -{flag}"
                    )));
                }
            }
        }
        index = index.saturating_add(1);
    }
    if parsed.items.is_empty() {
        return Err(ServerError::InvalidCommand(
            "display-menu requires at least one argument".to_owned(),
        ));
    }
    Ok(parsed)
}

fn parse_confirm_before_args(args: &[String]) -> Result<ParsedConfirmBefore, ServerError> {
    let mut parsed = ParsedConfirmBefore::default();
    let mut index = 0;
    while index < args.len() {
        let argument = &args[index];
        if argument == "--" {
            let positional = &args[index.saturating_add(1)..];
            if positional.len() != 1 {
                return Err(ServerError::InvalidCommand(
                    "confirm-before requires exactly one command".to_owned(),
                ));
            }
            parsed.command = positional.first().cloned();
            break;
        }
        if !argument.starts_with('-') || argument == "-" {
            let positional = &args[index..];
            if positional.len() != 1 {
                return Err(ServerError::InvalidCommand(
                    "confirm-before requires exactly one command".to_owned(),
                ));
            }
            parsed.command = positional.first().cloned();
            break;
        }
        for (offset, flag) in argument[1..].char_indices() {
            match flag {
                'b' => parsed.background = true,
                'y' => parsed.default_yes = true,
                'c' | 'p' | 't' => {
                    let value_start = 1_usize
                        .saturating_add(offset)
                        .saturating_add(flag.len_utf8());
                    let value = if value_start < argument.len() {
                        argument[value_start..].to_owned()
                    } else {
                        index = index.saturating_add(1);
                        args.get(index).cloned().ok_or_else(|| {
                            ServerError::InvalidCommand(format!(
                                "confirm-before -{flag} requires a value"
                            ))
                        })?
                    };
                    match flag {
                        'c' => parsed.confirm_key = Some(value),
                        'p' => parsed.prompt = Some(value),
                        't' => parsed.target_client = Some(value),
                        _ => unreachable!("valued confirm option is matched"),
                    }
                    break;
                }
                _ => {
                    return Err(ServerError::UnsupportedCommand(format!(
                        "confirm-before -{flag}"
                    )));
                }
            }
        }
        index = index.saturating_add(1);
    }
    if parsed.command.is_none() {
        return Err(ServerError::InvalidCommand(
            "confirm-before requires exactly one command".to_owned(),
        ));
    }
    Ok(parsed)
}

fn parse_popup_dimension(
    name: &str,
    value: Option<&str>,
    dimension: u16,
) -> Result<u16, ServerError> {
    let Some(value) = value else {
        return Ok(dimension / 2);
    };
    let error = |reason: &str| ServerError::InvalidCommand(format!("{name} {reason}"));
    if value.is_empty() {
        return Err(error("empty"));
    }
    if let Some(percent) = value.strip_suffix('%') {
        if percent.is_empty() {
            return Err(error("invalid"));
        }
        let percent = parse_popup_number(percent, 0, 1000).map_err(&error)?;
        let cells = u64::from(dimension)
            .saturating_mul(percent)
            .checked_div(100)
            .unwrap_or_default();
        if cells == 0 {
            return Err(error("too small"));
        }
        if cells > u64::from(dimension) {
            return Err(error("too large"));
        }
        return Ok(u16::try_from(cells).unwrap_or(dimension));
    }
    let cells = parse_popup_number(value, 1, u64::from(dimension)).map_err(error)?;
    Ok(u16::try_from(cells).unwrap_or(dimension))
}

fn parse_popup_number(value: &str, minimum: u64, maximum: u64) -> Result<u64, &'static str> {
    if value.starts_with('-') {
        return Err("too small");
    }
    match value.parse::<u64>() {
        Ok(value) if value < minimum => Err("too small"),
        Ok(value) if value > maximum => Err("too large"),
        Ok(value) => Ok(value),
        Err(_) if value.chars().all(|character| character.is_ascii_digit()) => Err("too large"),
        Err(_) => Err("invalid"),
    }
}

fn popup_exit_code(terminal: &TerminalSession) -> Option<u8> {
    terminal.completion().map(|completion| {
        completion
            .signal
            .unwrap_or_else(|| u8::try_from(completion.code).unwrap_or(u8::MAX))
    })
}

fn popup_content_size(state: &PopupState) -> Option<(u16, u16)> {
    if state.border_lines == PopupBorderLines::None {
        (state.width > 0 && state.height > 0).then_some((state.width, state.height))
    } else {
        (state.width > 2 && state.height > 2).then_some((state.width - 2, state.height - 2))
    }
}

fn popup_command_shape(default_command: &str, command: &[String]) -> Option<Vec<String>> {
    if command.is_empty() {
        return (!default_command.is_empty()).then(|| vec![default_command.to_owned()]);
    }
    Some(command.to_vec())
}

fn popup_other_overlay_present(inner: &ServerState, client: ClientId) -> bool {
    inner.command_prompts.contains_key(&client)
        || inner.choose_trees.contains_key(&client)
        || inner.choose_buffers.contains_key(&client)
        || inner.display_panes.contains_key(&client)
        || inner.command_outputs.contains_key(&client)
        || inner.menus.contains_key(&client)
        || inner.confirms.contains_key(&client)
}

fn any_overlay_present(inner: &ServerState, client: ClientId) -> bool {
    popup_other_overlay_present(inner, client) || inner.popups.contains_key(&client)
}

fn menu_shortcut(value: &str) -> Option<String> {
    let key = zz_protocol::canonical_key(value);
    let mut base = key.as_str();
    while let Some(rest) = base.strip_prefix("C-").or_else(|| base.strip_prefix("M-")) {
        base = rest;
    }
    let named = matches!(
        base,
        "Enter"
            | "Escape"
            | "Space"
            | "Tab"
            | "BTab"
            | "BSpace"
            | "Up"
            | "Down"
            | "Left"
            | "Right"
            | "Home"
            | "End"
            | "PPage"
            | "NPage"
            | "DC"
            | "IC"
    );
    let function = base
        .strip_prefix('F')
        .and_then(|number| number.parse::<u8>().ok())
        .is_some_and(|number| number > 0);
    let character = {
        let mut characters = base.chars();
        characters
            .next()
            .is_some_and(|character| !character.is_control())
            && characters.next().is_none()
    };
    (named || function || character).then_some(key)
}

enum MenuStartingChoice {
    Default,
    Unselected,
    At(u64),
}

fn menu_starting_number(value: Option<&str>) -> Result<MenuStartingChoice, ServerError> {
    let Some(value) = value else {
        return Ok(MenuStartingChoice::Default);
    };
    if value == "-" {
        return Ok(MenuStartingChoice::Unselected);
    }
    parse_popup_number(value, 0, u64::from(u32::MAX))
        .map(MenuStartingChoice::At)
        .map_err(|cause| ServerError::InvalidCommand(format!("starting choice {cause}")))
}

fn menu_starting_selection(
    starting_choice: &MenuStartingChoice,
    items: &[Option<MenuItem>],
) -> Option<u32> {
    match starting_choice {
        MenuStartingChoice::Default => menu_selectable_from(items, 0, false),
        MenuStartingChoice::Unselected => None,
        MenuStartingChoice::At(start) => {
            let start = usize::try_from(*start).unwrap_or(usize::MAX);
            if start >= items.len() {
                menu_selectable_from(items, items.len().saturating_sub(1), true)
            } else {
                menu_selectable_from(items, start, false)
            }
        }
    }
}

fn menu_selectable_from(items: &[Option<MenuItem>], start: usize, reverse: bool) -> Option<u32> {
    if items.is_empty() {
        return None;
    }
    (0..items.len()).find_map(|offset| {
        let index = if reverse {
            (start + items.len() - offset % items.len()) % items.len()
        } else {
            (start + offset) % items.len()
        };
        items[index]
            .as_ref()
            .is_some_and(|item| item.enabled)
            .then(|| u32::try_from(index).unwrap_or(u32::MAX))
    })
}

fn expand_popup_value(
    inner: &ServerState,
    target: &ExecutionContext,
    active_session: Option<SessionId>,
    value: &str,
) -> String {
    let facts = format_hook_facts(inner);
    let mut hooks =
        DaemonFormatHooks::command_with_optional_variables(&facts, target.format_variables());
    inner
        .engine
        .expand_pane_format_time(value, target, active_session, &mut hooks)
}

fn popup_close_flags(parsed: &ParsedDisplayPopup, modifying: bool) -> Option<(bool, bool, bool)> {
    if modifying
        && !parsed.reset_close_flags
        && parsed.close_on_exit_count == 0
        && !parsed.close_on_any_key
    {
        return None;
    }
    Some((
        parsed.close_on_exit_count == 1,
        parsed.close_on_exit_count > 1,
        parsed.close_on_any_key,
    ))
}

impl ParsedAgentSend {
    fn payload(&self) -> Result<String, ServerError> {
        let text = self.text.join(" ");
        let text = text.trim_end_matches(['\n', '\r']);
        if text.trim().is_empty() {
            return Err(ServerError::InvalidCommand(
                "agent-send needs text on the command line or on standard input".to_owned(),
            ));
        }
        if text.len() > MAX_AGENT_SEND_BYTES {
            return Err(ServerError::InvalidCommand(format!(
                "agent-send payload is {} bytes; the limit is {MAX_AGENT_SEND_BYTES}",
                text.len()
            )));
        }
        if text
            .chars()
            .any(|character| character.is_control() && !matches!(character, '\n' | '\r' | '\t'))
        {
            return Err(ServerError::InvalidCommand(
                "agent-send payload contains control characters; pipe plain text".to_owned(),
            ));
        }
        let payload = match &self.context {
            Some(reference) => fenced_block(&reference.header(), text),
            None => text.to_owned(),
        };
        if payload.len() > MAX_AGENT_SEND_BYTES {
            return Err(ServerError::InvalidCommand(format!(
                "agent-send payload is {} bytes with its context header; the limit is \
                 {MAX_AGENT_SEND_BYTES}",
                payload.len()
            )));
        }
        Ok(payload)
    }
}

fn fenced_block(header: &str, text: &str) -> String {
    let widest = text
        .split('\n')
        .flat_map(|line| line.split(|character| character != '`'))
        .map(str::len)
        .max()
        .unwrap_or(0);
    let fence = "`".repeat(widest.saturating_add(1).max(3));
    format!("{header}\n{fence}\n{text}\n{fence}")
}

fn last_command_block(pane: PaneId, capture: &LastCommandCapture) -> String {
    let mut body = String::new();
    if capture.truncated_rows > 0 {
        let _ = writeln!(
            body,
            "truncated: dropped the first {} lines",
            capture.truncated_rows
        );
    }
    body.push_str(&capture.output);
    fenced_block(&format!("{pane} $ {}", capture.command), &body)
}

/// Whether `zz agent-send` must read its payload from standard input.
///
/// Malformed arguments answer `false` and let the daemon report the real error.
#[must_use]
pub fn agent_send_reads_stdin(args: &[String]) -> bool {
    parse_agent_send_args(args).is_ok_and(|parsed| parsed.text.is_empty())
}

fn parse_agent_send_args(args: &[String]) -> Result<ParsedAgentSend, ServerError> {
    let mut parsed = ParsedAgentSend::default();
    let mut index = 0;
    while let Some(argument) = args.get(index) {
        if argument == "--" {
            parsed
                .text
                .extend(args[index.saturating_add(1)..].iter().cloned());
            break;
        }
        if argument == "--submit" {
            parsed.submit = true;
            index += 1;
            continue;
        }
        if let Some(value) = option_value("agent-send", args, index, &["-t", "--target"])? {
            parsed.target = Some(value.value);
            index += value.consumed;
            continue;
        }
        if let Some(value) = option_value("agent-send", args, index, &["--context"])? {
            parsed.context = Some(ContextReference::parse(&value.value)?);
            index += value.consumed;
            continue;
        }
        if argument.starts_with('-') && argument != "-" {
            return Err(ServerError::UnsupportedCommand(format!(
                "agent-send {argument}"
            )));
        }
        parsed.text.push(argument.clone());
        index += 1;
    }
    Ok(parsed)
}

#[derive(Debug, Default)]
struct ParsedCaptureBrowser {
    target: Option<String>,
    output: Option<String>,
}

fn parse_capture_browser_args(args: &[String]) -> Result<ParsedCaptureBrowser, ServerError> {
    let mut parsed = ParsedCaptureBrowser::default();
    let mut index = 0;
    while let Some(argument) = args.get(index) {
        if argument == "--" {
            if index.saturating_add(1) != args.len() {
                return Err(ServerError::InvalidCommand(
                    "capture-browser does not accept positional arguments".to_owned(),
                ));
            }
            break;
        }
        if let Some(value) = option_value("capture-browser", args, index, &["-t"])? {
            parsed.target = Some(value.value);
            index += value.consumed;
            continue;
        }
        if let Some(value) = option_value("capture-browser", args, index, &["-o"])? {
            parsed.output = Some(value.value);
            index += value.consumed;
            continue;
        }
        return Err(ServerError::InvalidCommand(format!(
            "unexpected capture-browser argument: {argument}"
        )));
    }
    Ok(parsed)
}

fn parse_target_only_args(command: &str, args: &[String]) -> Result<Option<String>, ServerError> {
    let mut target = None;
    let mut index = 0;
    while let Some(argument) = args.get(index) {
        if argument == "--" {
            if index.saturating_add(1) != args.len() {
                return Err(ServerError::InvalidCommand(format!(
                    "{command} does not accept positional arguments"
                )));
            }
            break;
        }
        if let Some(value) = option_value(command, args, index, &["-t"])? {
            target = Some(value.value);
            index += value.consumed;
            continue;
        }
        return Err(ServerError::InvalidCommand(format!(
            "unexpected {command} argument: {argument}"
        )));
    }
    Ok(target)
}

struct OptionValue {
    value: String,
    consumed: usize,
}

fn option_value(
    command: &str,
    args: &[String],
    index: usize,
    names: &[&str],
) -> Result<Option<OptionValue>, ServerError> {
    let argument = &args[index];
    for name in names {
        if argument == name {
            let value = args.get(index.saturating_add(1)).ok_or_else(|| {
                ServerError::InvalidCommand(format!("{command} {name} requires a value"))
            })?;
            return Ok(Some(OptionValue {
                value: value.clone(),
                consumed: 2,
            }));
        }
        let attached = name
            .strip_prefix("--")
            .and_then(|_| argument.strip_prefix(&format!("{name}=")))
            .or_else(|| {
                (!name.starts_with("--"))
                    .then(|| argument.strip_prefix(name))
                    .flatten()
            })
            .filter(|value| !value.is_empty());
        if let Some(value) = attached {
            return Ok(Some(OptionValue {
                value: value.to_owned(),
                consumed: 1,
            }));
        }
    }
    Ok(None)
}

fn debug_marker(client: ClientId, context: &ExecutionContext, args: &[String]) -> Execution {
    log::info!(
        target: "zz_daemon::diagnostics::marker",
        "user_marker client={client} session={:?} window={:?} pane={:?} note={:?}",
        context.session,
        context.window,
        context.pane,
        args.join(" "),
    );
    log::logger().flush();
    Execution::default()
}

fn workspace_tools_catalog() -> Execution {
    Execution {
        output: WORKSPACE_TOOLS.to_owned(),
        effects: Vec::new(),
    }
}

const WORKSPACE_TOOLS: &str = "\
zz workspace verbs: drive the surrounding zz session from inside an agent pane.

Targets are stable IDs: %N a pane, @N a window, $N a session. Your own pane is
$ZZ_PANE, your session is $ZZ_SESSION, and the daemon socket is $ZZ_SOCKET.
Run `zz list-panes -t @N` or `zz list-windows` to discover the rest.

  zz tools
      Print this catalog.

  zz agent-send [-t %N] [--submit] [--context PATH[:START[-END]]] [TEXT]
      Put TEXT in an agent pane's composer for its user to review, or submit
      it outright with --submit (only when that pane is idle). A -t naming a
      non-agent pane, or no -t at all, routes to that window's most recently
      focused agent pane, so a pipe from a terminal needs no addressing at
      all: `git diff | zz agent-send`. Reads standard input when TEXT is
      omitted. --context adds a file/line header and fences the payload.

  zz capture-pane -p -t %N [-S -] [-E -] [-J]
      Print a terminal pane's text. -S -/-E - widen the range to the whole
      scrollback; -J rejoins soft-wrapped lines.

  zz send-last-output -t %N
      Send a terminal pane's last completed command and its output to the most
      recently focused agent pane in the same window. Needs a shell that emits
      OSC 133 prompt marks.

  zz capture-browser -t %N -o /absolute/out.png
      Write a browser pane's latest rendered frame to a PNG.

  zz set-browser-url -t %N URL
      Point a browser pane at URL.

  zz send-keys -t %N 'text' Enter
      Type into a terminal pane. -l sends text literally.

  zz split-window | zz split-browser | zz split-picker [-h|-v] [-t %N]
      Add a pane beside another one.

  zz debug-marker [NOTE]
      Stamp a user_marker line into the daemon log, so the moment something
      looked wrong is easy to find when reading diagnostics later.
";

fn ensure_browser_attached(inner: &ServerState, pane: PaneId) -> Result<(), ServerError> {
    let window = inner
        .engine
        .state
        .window_for_pane(pane)
        .ok_or_else(|| ServerError::MissingTarget(pane.to_string()))?;
    let session = inner.engine.state.windows[&window].session;
    if inner
        .attached
        .get(&session)
        .is_some_and(|clients| !clients.is_empty())
    {
        Ok(())
    } else {
        Err(ServerError::PaneNotAttached(pane))
    }
}

fn handle_connection<S: TransportStream>(
    mut stream: S,
    shared: &Arc<Shared>,
) -> Result<(), DaemonError> {
    let connection_started = diagnostic_timer();
    let mut inbound_frame = Vec::new();
    let first_message = match read_protocol_message_into(&mut stream, &mut inbound_frame) {
        Ok(message) => message,
        Err(error @ ProtocolError::VersionMismatch { received, .. }) => {
            best_effort_protocol_mismatch_reply(&mut stream, received);
            log::info!(
                target: "zz_daemon::diagnostics::connection",
                "rejected client protocol={received} server_protocol={PROTOCOL_VERSION}",
            );
            return Err(error.into());
        }
        Err(error) => return Err(error.into()),
    };
    let ProtocolMessage::ClientHello(hello) = first_message else {
        return Err(ServerError::InvalidCommand(
            "first protocol message must be ClientHello".to_owned(),
        )
        .into());
    };
    if let Err(error) = validate_hello(&hello) {
        best_effort_protocol_mismatch_reply(&mut stream, hello.protocol_version);
        log::info!(
            target: "zz_daemon::diagnostics::connection",
            "rejected client hello protocol={} server_protocol={PROTOCOL_VERSION}",
            hello.protocol_version,
        );
        return Err(error);
    }
    let startup_reentry_capability = format!(
        "{}{}",
        crate::STARTUP_REENTRY_CAPABILITY_PREFIX,
        shared.server_id
    );
    let startup_reentry = hello.kind == ClientKind::Command
        && hello.capabilities.contains(&startup_reentry_capability);
    if !startup_reentry && !shared.wait_for_startup() {
        return Ok(());
    }

    let outbound = OutboundMailbox::new();
    let (client, server_hello) = shared.register(
        hello.kind,
        hello.client_instance_id,
        hello.device_name.clone(),
        hello.color_scheme,
        hello.kind == ClientKind::Interactive
            && hello
                .capabilities
                .iter()
                .any(|capability| capability == ClientHello::CLIENT_TERMINAL_CAPABILITY),
    );
    let mut registration = ClientRegistrationGuard::new(shared, client);
    log::debug!(
        target: "zz_daemon::diagnostics::connection",
        "registered client={client} kind={:?} hello={hello:#?}",
        hello.kind,
    );
    let mut writer = stream.try_clone()?;
    let writer_mailbox = Arc::clone(&outbound);
    let writer_thread = thread::Builder::new()
        .name(format!("zz-client-writer-{}", client.0))
        .spawn(move || write_outbound(&mut writer, &writer_mailbox))
        .map_err(|error| DaemonError::Thread(error.to_string()))?;
    let _ = outbound.enqueue_reliable(&ProtocolMessage::ServerHello(server_hello));
    if matches!(hello.kind, ClientKind::Interactive | ClientKind::Control) {
        shared.subscribe(client, Arc::clone(&outbound));
    }

    let context = {
        let inner = shared.inner.lock();
        hello
            .origin
            .and_then(|pane| ExecutionContext::for_pane(&inner.engine.state, pane))
            .or_else(|| {
                let fallback = if matches!(hello.kind, ClientKind::Command | ClientKind::Control) {
                    inner.engine.state.most_recent_context()
                } else {
                    inner.engine.state.default_context()
                };
                fallback.map(|(session, window, pane)| {
                    ExecutionContext::new(Some(session), Some(window), Some(pane))
                })
            })
            .unwrap_or_default()
    };
    let (command_sender, command_worker, mut context) = if hello.kind == ClientKind::Command {
        let (sender, receiver) = crossbeam_channel::unbounded::<CommandRequest>();
        let worker_shared = Arc::clone(shared);
        let worker_outbound = Arc::clone(&outbound);
        let worker = match thread::Builder::new()
            .name(format!("zz-client-command-{}", client.0))
            .spawn(move || {
                let mut context = context;
                while let Ok(CommandRequest {
                    request_id,
                    command,
                }) = receiver.recv()
                {
                    let response = worker_shared.execute_command_request(
                        client,
                        ClientKind::Command,
                        &mut context,
                        request_id,
                        &command,
                    );
                    let _ = worker_outbound
                        .enqueue_reliable(&ProtocolMessage::CommandResponse(response));
                }
            }) {
            Ok(worker) => worker,
            Err(error) => {
                outbound.close();
                let _ = writer_thread.join();
                return Err(DaemonError::Thread(error.to_string()));
            }
        };
        (Some(sender), Some(worker), None)
    } else {
        (None, None, Some(context))
    };

    let result = loop {
        let message = match read_protocol_message_into(&mut stream, &mut inbound_frame) {
            Ok(message) => message,
            Err(ProtocolError::Io(error))
                if matches!(
                    error.kind(),
                    ErrorKind::UnexpectedEof | ErrorKind::ConnectionReset | ErrorKind::BrokenPipe
                ) =>
            {
                break Ok(());
            }
            Err(error) => break Err(error.into()),
        };
        let message_started = diagnostic_timer();
        log::trace!(
            target: "zz_daemon::diagnostics::connection",
            "message begin client={client} bytes={} frame_capacity={} message={message:#?}",
            inbound_frame.len(),
            inbound_frame.capacity(),
        );
        match message {
            ProtocolMessage::CommandRequest(CommandRequest {
                request_id,
                command,
            }) => {
                if let Some(sender) = &command_sender {
                    if sender
                        .send(CommandRequest {
                            request_id,
                            command,
                        })
                        .is_err()
                    {
                        break Err(DaemonError::Thread(
                            "command client worker stopped".to_owned(),
                        ));
                    }
                } else {
                    let response = shared.execute_command_request(
                        client,
                        hello.kind,
                        context.as_mut().expect("interactive client owns context"),
                        request_id,
                        &command,
                    );
                    let _ = outbound.enqueue_reliable(&ProtocolMessage::CommandResponse(response));
                }
            }
            ProtocolMessage::Attach { session } => {
                let Some(context) = context.as_mut() else {
                    let _ = outbound.enqueue_reliable(&ProtocolMessage::CommandResponse(
                        CommandResponse::Error {
                            request_id: 0,
                            error: ServerError::InvalidCommand(
                                "command client cannot attach".to_owned(),
                            ),
                            output: String::new(),
                        },
                    ));
                    continue;
                };
                match shared.attach_target(client, hello.kind, context, &session) {
                    Ok((session, snapshot)) => {
                        outbound.reset_kitty_images();
                        outbound.reset_pasted_images();
                        let _ = outbound
                            .enqueue_reliable(&ProtocolMessage::Attached { session, snapshot });
                        shared.send_resync(client, &outbound);
                        shared.publish_snapshot();
                    }
                    Err(error) => {
                        let _ = outbound.enqueue_reliable(&ProtocolMessage::CommandResponse(
                            CommandResponse::Error {
                                request_id: 0,
                                error,
                                output: String::new(),
                            },
                        ));
                    }
                }
            }
            ProtocolMessage::Detach => {
                let control_session = (hello.kind == ClientKind::Control)
                    .then(|| {
                        shared
                            .inner
                            .lock()
                            .attached
                            .iter()
                            .find_map(|(session, clients)| {
                                clients.contains(&client).then_some(*session)
                            })
                    })
                    .flatten();
                shared.detach(client);
                if let Some(session) = control_session {
                    shared.publish_to_client(client, EventPayload::Detached { session, by: None });
                }
            }
            ProtocolMessage::SetColorScheme(color_scheme) => {
                if hello.kind == ClientKind::Interactive {
                    shared.set_client_color_scheme(client, color_scheme);
                }
            }
            ProtocolMessage::SetConfigOverrides { entries } => {
                shared.set_config_overrides(client, hello.kind, &entries);
            }
            ProtocolMessage::Input(input) => {
                if hello.kind != ClientKind::Interactive {
                    let _ = outbound.enqueue_reliable(&ProtocolMessage::CommandResponse(
                        CommandResponse::Error {
                            request_id: 0,
                            error: ServerError::InvalidCommand(
                                "command client cannot send input".to_owned(),
                            ),
                            output: String::new(),
                        },
                    ));
                    continue;
                }
                let Some(context) = context.as_mut() else {
                    let _ = outbound.enqueue_reliable(&ProtocolMessage::CommandResponse(
                        CommandResponse::Error {
                            request_id: 0,
                            error: ServerError::InvalidCommand(
                                "command client cannot send input".to_owned(),
                            ),
                            output: String::new(),
                        },
                    ));
                    continue;
                };
                if let Err(error) = shared.input(client, hello.kind, context, input) {
                    let _ = outbound.enqueue_reliable(&ProtocolMessage::CommandResponse(
                        CommandResponse::Error {
                            request_id: 0,
                            error: daemon_server_error(error),
                            output: String::new(),
                        },
                    ));
                }
            }
            ProtocolMessage::GuiResponse(response) => {
                shared.complete_gui_request(client, response);
            }
            ProtocolMessage::Resync => shared.send_resync(client, &outbound),
            ProtocolMessage::RequestFull { pane } => {
                shared.send_full(client, pane, &outbound);
            }
            ProtocolMessage::HistoryRequest { pane, start, count } => {
                shared.send_history(client, pane, start, count, &outbound);
            }
            ProtocolMessage::PasteUploadBegin {
                upload_id,
                pane,
                purpose,
                extension,
                total_bytes,
            } => {
                shared.begin_paste_upload(
                    client,
                    hello.kind,
                    upload_id,
                    pane,
                    purpose,
                    extension,
                    total_bytes,
                );
            }
            ProtocolMessage::PasteUploadChunk { upload_id, bytes } => {
                shared.extend_paste_upload(client, upload_id, &bytes);
            }
            ProtocolMessage::FetchPastedImage { pane, number }
                if hello.kind == ClientKind::Interactive =>
            {
                shared.fetch_pasted_image(client, pane, number);
            }
            message @ (ProtocolMessage::AgentPrompt { .. }
            | ProtocolMessage::AgentCancel { .. }
            | ProtocolMessage::AgentUnqueue { .. }
            | ProtocolMessage::AgentRespondPermission { .. }
            | ProtocolMessage::AgentSetConfigOption { .. }
            | ProtocolMessage::AgentSetMode { .. }
            | ProtocolMessage::AgentAuthenticate { .. }
            | ProtocolMessage::AgentSessionOp { .. }
            | ProtocolMessage::AgentReplay { .. }
            | ProtocolMessage::AgentAcknowledgePromptRestore { .. }) => {
                if let Err(error) = handle_agent_message(shared, client, message) {
                    let _ = outbound.enqueue_reliable(&ProtocolMessage::CommandResponse(
                        CommandResponse::Error {
                            request_id: 0,
                            error,
                            output: String::new(),
                        },
                    ));
                }
            }
            _ => {}
        }
        log::trace!(
            target: "zz_daemon::diagnostics::connection",
            "message end client={client} elapsed_us={} context={context:#?}",
            diagnostic_elapsed_us(message_started),
        );
    };

    shared.detach(client);
    registration.unregister();
    drop(command_sender);
    if command_worker.is_some_and(|worker| worker.join().is_err()) {
        log::error!(
            target: "zz_daemon::diagnostics::connection",
            "command worker panicked for client={client}",
        );
    }
    outbound.close();
    if writer_thread.join().is_err() {
        log::error!(
            target: "zz_daemon::diagnostics::connection",
            "writer thread panicked for client={client}",
        );
    }
    log::debug!(
        target: "zz_daemon::diagnostics::connection",
        "unregistered client={client} success={} connection_elapsed_us={}",
        result.is_ok(),
        diagnostic_elapsed_us(connection_started),
    );
    result
}

#[cfg(feature = "agent")]
fn handle_agent_message(
    shared: &Arc<Shared>,
    client: ClientId,
    message: ProtocolMessage,
) -> Result<(), ServerError> {
    shared.agent_message(client, message)
}

/// A daemon built without the agent feature still speaks the protocol; it just
/// has nothing to run the adapter with.
#[cfg(not(feature = "agent"))]
fn handle_agent_message(
    _shared: &Arc<Shared>,
    _client: ClientId,
    _message: ProtocolMessage,
) -> Result<(), ServerError> {
    Err(ServerError::UnsupportedCommand(
        "this daemon was built without agent support".to_owned(),
    ))
}

fn best_effort_protocol_mismatch_reply(stream: &mut impl Write, client: u16) {
    let message = ProtocolMessage::CommandResponse(CommandResponse::Error {
        request_id: 0,
        error: ServerError::ProtocolMismatch {
            client,
            server: PROTOCOL_VERSION,
        },
        output: String::new(),
    });
    let mut frame = Vec::new();
    if encode_protocol_message_into(&message, &mut frame).is_ok() {
        let _ = stream.write_all(&frame).and_then(|()| stream.flush());
    }
}

fn write_outbound(stream: &mut impl TransportStream, outbound: &OutboundMailbox) {
    while let Some(frame) = outbound.recv() {
        let started = diagnostic_timer();
        let bytes = frame.len();
        let capacity = frame.capacity();
        let write_started = diagnostic_timer();
        let write_result = stream.write_all(&frame);
        let write_us = diagnostic_elapsed_us(write_started);
        let flush_started = diagnostic_timer();
        let result = write_result.and_then(|()| stream.flush());
        let flush_us = diagnostic_elapsed_us(flush_started);
        log::trace!(
            target: "zz_daemon::diagnostics::outbound",
            "write bytes={bytes} frame_capacity={capacity} success={} write_us={} flush_us={} elapsed_us={}",
            result.is_ok(),
            write_us,
            flush_us,
            diagnostic_elapsed_us(started),
        );
        if result.is_err() {
            outbound.close();
            break;
        }
        outbound.recycle_frame(frame);
    }
    let _ = stream.shutdown();
    outbound.mark_writer_finished();
}

fn validate_hello(hello: &ClientHello) -> Result<(), DaemonError> {
    if hello.protocol_version != PROTOCOL_VERSION {
        return Err(ServerError::ProtocolMismatch {
            client: hello.protocol_version,
            server: PROTOCOL_VERSION,
        }
        .into());
    }
    Ok(())
}

fn daemon_server_error(error: DaemonError) -> ServerError {
    match error {
        DaemonError::Server(error) => error,
        DaemonError::CommandFailed { error, .. } => daemon_server_error(*error),
        DaemonError::CommandExit { exit_code, .. } => {
            ServerError::Internal(format!("command exited with status {exit_code}"))
        }
        other => ServerError::Internal(other.to_string()),
    }
}

#[cfg(unix)]
fn prepare_socket(path: &Path) -> Result<(), DaemonError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    // A stopping daemon releases its endpoint within one accept tick; wait
    // that out so a spawn racing a kill-server binds instead of dying to a
    // socket that only looks alive. The deadline is generous because loaded
    // schedulers stretch the tick.
    let deadline = Instant::now() + Duration::from_secs(3);
    while path.exists() {
        match LocalTransport::connect(path) {
            Ok(_) if Instant::now() >= deadline => {
                return Err(DaemonError::AlreadyRunning(path.to_owned()));
            }
            Ok(_) => thread::sleep(Duration::from_millis(20)),
            Err(_) => {
                match fs::remove_file(path) {
                    Ok(()) => {}
                    Err(error) if error.kind() == ErrorKind::NotFound => {}
                    Err(error) => return Err(error.into()),
                }
                break;
            }
        }
    }
    Ok(())
}

#[cfg(windows)]
fn prepare_socket(_: &Path) -> Result<(), DaemonError> {
    Ok(())
}

#[cfg(unix)]
fn restrict_socket_permissions(path: &Path) -> Result<(), std::io::Error> {
    use std::os::unix::fs::PermissionsExt;

    fs::set_permissions(path, fs::Permissions::from_mode(0o600))
}

#[cfg(windows)]
fn restrict_socket_permissions(_: &Path) -> Result<(), std::io::Error> {
    Ok(())
}

fn server_id() -> u64 {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    let folded = u64::try_from(timestamp & u128::from(u64::MAX)).unwrap_or_default();
    folded ^ u64::from(std::process::id())
}

fn mux_set_option_command(option: MuxOptionKey, value: &str) -> CommandInvocation {
    CommandInvocation::new("set-option", ["-g", "--", option.as_str(), value])
}

fn expand_path(path: &str) -> PathBuf {
    if let Some(rest) = path.strip_prefix("~/") {
        return home_directory().map_or_else(|| PathBuf::from(path), |home| home.join(rest));
    }
    PathBuf::from(path)
}

fn prompt_history_path(path: &str) -> Option<PathBuf> {
    if path.is_empty() {
        None
    } else if Path::new(path).is_absolute() {
        Some(PathBuf::from(path))
    } else {
        path.strip_prefix("~/")
            .and_then(|rest| home_directory().map(|home| home.join(rest)))
    }
}

fn load_command_prompt_history(path: &Path, limit: usize) -> Vec<String> {
    let Ok(contents) = fs::read_to_string(path) else {
        return Vec::new();
    };
    let mut history = Vec::new();
    for line in contents.split('\n').filter(|line| !line.is_empty()) {
        if let Some(command) = line.strip_prefix("command:") {
            add_command_prompt_history(&mut history, command, limit);
        } else if !line.starts_with("search:") {
            add_command_prompt_history(&mut history, line, limit);
        }
    }
    history
}

fn add_command_prompt_history(history: &mut Vec<String>, input: &str, limit: usize) -> bool {
    let added = history.last().is_none_or(|entry| entry != input);
    if added {
        history.push(input.to_owned());
    }
    let removed = history.len().saturating_sub(limit);
    if history.len() > limit {
        history.drain(..removed);
    }
    removed != 0 || (added && limit != 0)
}

fn save_command_prompt_history(path: &Path, history: &[String]) {
    let mut contents = String::new();
    for entry in history {
        let _ = writeln!(contents, "command:{entry}");
    }
    if let Err(error) = fs::write(path, contents) {
        log::debug!("failed to save prompt history {}: {error}", path.display());
    }
}

#[derive(Default)]
struct SourceGlobMatches {
    paths: Vec<PathBuf>,
    errors: Vec<String>,
}

fn source_glob_matches(path: &Path) -> SourceGlobMatches {
    match glob::glob(path.to_string_lossy().as_ref()) {
        Ok(paths) => {
            let mut matches = SourceGlobMatches::default();
            for path in paths {
                match path {
                    Ok(path) => matches.paths.push(path),
                    Err(error) => matches.errors.push(error.to_string()),
                }
            }
            matches.paths.sort();
            matches
        }
        Err(error) => SourceGlobMatches {
            paths: Vec::new(),
            errors: vec![error.to_string()],
        },
    }
}

fn expand_relative(source: &Path, nested: &str) -> PathBuf {
    let nested = expand_path(nested);
    if nested.is_absolute() {
        nested
    } else {
        source
            .parent()
            .unwrap_or_else(|| Path::new("."))
            .join(nested)
    }
}

