    #[test]
    fn editor_sniff_matches_the_pin_basename_rule() {
        for editor in ["vi", "vim", "nvim", "gvim", "/usr/bin/evil"] {
            assert_eq!(
                mode_keys_from_environment(None, Some(OsStr::new(editor))),
                "vi",
                "{editor}"
            );
        }
        for editor in ["emacsclient", "VI", "/usr/bin/emacs"] {
            assert_eq!(
                mode_keys_from_environment(None, Some(OsStr::new(editor))),
                "emacs",
                "{editor}"
            );
        }
        assert_eq!(mode_keys_from_environment(None, None), "emacs");
        assert_eq!(
            mode_keys_from_environment(Some(OsStr::new("")), Some(OsStr::new("vim"))),
            "emacs"
        );
    }

    #[test]
    fn editor_option_uses_daemon_boot_environment_precedence() {
        assert_eq!(
            editor_from_environment(Some(OsStr::new("nvim")), Some(OsStr::new("vim"))),
            "nvim"
        );
        assert_eq!(
            editor_from_environment(None, Some(OsStr::new("emacs"))),
            "emacs"
        );
        assert_eq!(
            editor_from_environment(Some(OsStr::new("")), Some(OsStr::new("vim"))),
            ""
        );
        assert_eq!(editor_from_environment(None, None), "/usr/bin/vi");
    }

    #[cfg(unix)]
    #[test]
    fn checkshell_rejects_relative_non_executable_and_own_binary_paths() {
        use std::os::unix::fs::PermissionsExt as _;

        let directory = tempfile::tempdir().expect("temporary directory");
        assert!(!shell_is_valid_for_program(
            Path::new("sh"),
            OsStr::new("zz")
        ));
        assert!(shell_is_valid_for_program(
            directory.path(),
            OsStr::new("zz")
        ));

        let non_executable = directory.path().join("not-executable");
        fs::write(&non_executable, []).expect("write non-executable shell");
        fs::set_permissions(&non_executable, fs::Permissions::from_mode(0o600))
            .expect("set non-executable permissions");
        assert!(!shell_is_valid_for_program(
            &non_executable,
            OsStr::new("zz")
        ));

        let own_binary = directory.path().join("zz-shell-test");
        fs::write(&own_binary, []).expect("write own binary");
        fs::set_permissions(&own_binary, fs::Permissions::from_mode(0o700))
            .expect("set own binary permissions");
        assert!(!shell_is_valid_for_program(
            &own_binary,
            OsStr::new("-zz-shell-test")
        ));

        let valid = directory.path().join("valid-shell");
        fs::write(&valid, []).expect("write valid shell");
        fs::set_permissions(&valid, fs::Permissions::from_mode(0o700))
            .expect("set valid shell permissions");
        assert!(shell_is_valid_for_program(&valid, OsStr::new("zz")));
    }

