    #[cfg(unix)]
    #[test]
    fn command_connection_waits_without_hiding_peer_disconnects() {
        fn connect(
            shared: &Arc<Shared>,
            instance: u64,
        ) -> (
            std::os::unix::net::UnixStream,
            thread::JoinHandle<Result<(), DaemonError>>,
            ClientId,
        ) {
            let (mut client, server) = std::os::unix::net::UnixStream::pair().expect("pair");
            client
                .set_read_timeout(Some(Duration::from_secs(2)))
                .expect("read timeout");
            let server_shared = Arc::clone(shared);
            let connection = thread::spawn(move || handle_connection(server, &server_shared));
            zz_protocol::write_protocol_message(
                &mut client,
                &ProtocolMessage::ClientHello(ClientHello {
                    protocol_version: PROTOCOL_VERSION,
                    client_instance_id: ClientInstanceId(instance),
                    kind: ClientKind::Command,
                    device_name: None,
                    capabilities: Vec::new(),
                    color_scheme: None,
                    origin: None,
                }),
            )
            .expect("hello");
            let ProtocolMessage::ServerHello(hello) =
                zz_protocol::read_protocol_message(&mut client).expect("server hello")
            else {
                panic!("missing server hello");
            };
            (client, connection, hello.client_id)
        }

        let shared = Arc::new(Shared::new(1));
        let (mut waiter, waiter_connection, _) = connect(&shared, 1);
        let (mut signaler, signaler_connection, _) = connect(&shared, 2);
        zz_protocol::write_protocol_message(
            &mut waiter,
            &ProtocolMessage::CommandRequest(CommandRequest {
                request_id: 1,
                command: CommandInvocation::new("wait-for", ["connection"]),
            }),
        )
        .expect("wait request");
        let deadline = Instant::now() + Duration::from_secs(2);
        while shared
            .inner
            .lock()
            .wait_channels
            .get("connection")
            .map_or(0, |channel| channel.waiters.len())
            != 1
        {
            assert!(Instant::now() < deadline, "connection wait did not queue");
            thread::yield_now();
        }
        zz_protocol::write_protocol_message(
            &mut signaler,
            &ProtocolMessage::CommandRequest(CommandRequest {
                request_id: 2,
                command: CommandInvocation::new("wait-for", ["-S", "connection"]),
            }),
        )
        .expect("signal request");
        for (stream, request_id) in [(&mut signaler, 2), (&mut waiter, 1)] {
            assert!(matches!(
                zz_protocol::read_protocol_message(stream).expect("wait response"),
                ProtocolMessage::CommandResponse(CommandResponse::Success {
                    request_id: response_id,
                    ..
                }) if response_id == request_id
            ));
        }
        drop(waiter);
        drop(signaler);
        waiter_connection
            .join()
            .expect("waiter handler")
            .expect("waiter connection");
        signaler_connection
            .join()
            .expect("signaler handler")
            .expect("signaler connection");

        let (mut dropped, dropped_connection, dropped_client) = connect(&shared, 3);
        zz_protocol::write_protocol_message(
            &mut dropped,
            &ProtocolMessage::CommandRequest(CommandRequest {
                request_id: 3,
                command: CommandInvocation::new("wait-for", ["dropped"]),
            }),
        )
        .expect("dropped wait request");
        let deadline = Instant::now() + Duration::from_secs(2);
        while shared
            .inner
            .lock()
            .wait_channels
            .get("dropped")
            .map_or(0, |channel| channel.waiters.len())
            != 1
        {
            assert!(Instant::now() < deadline, "dropped wait did not queue");
            thread::yield_now();
        }
        drop(dropped);
        dropped_connection
            .join()
            .expect("dropped handler")
            .expect("dropped connection");
        assert!(
            !shared
                .inner
                .lock()
                .client_instances
                .contains_key(&dropped_client)
        );
        assert!(
            shared
                .inner
                .lock()
                .wait_channels
                .get("dropped")
                .is_none_or(|channel| channel.waiters.is_empty())
        );
    }

    #[test]
    fn client_registration_guard_cleans_up_automatic_and_explicit_exits() {
        let shared = Arc::new(Shared::new(1));

        let automatic = {
            let (client, _) = shared.register_subscribed(
                ClientKind::Interactive,
                Some("automatic".to_owned()),
                None,
                OutboundMailbox::new(),
            );
            let guard = ClientRegistrationGuard::new(&shared, client);
            assert!(shared.inner.lock().subscribers.contains_key(&client));
            drop(guard);
            client
        };
        {
            let inner = shared.inner.lock();
            assert!(!inner.subscribers.contains_key(&automatic));
            assert!(!inner.client_color_schemes.contains_key(&automatic));
            assert!(!inner.client_names.contains_key(&automatic));
        }

        let (explicit, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("explicit".to_owned()),
            None,
            OutboundMailbox::new(),
        );
        let mut guard = ClientRegistrationGuard::new(&shared, explicit);
        guard.unregister();
        drop(guard);
        let inner = shared.inner.lock();
        assert!(!inner.subscribers.contains_key(&explicit));
        assert!(!inner.client_color_schemes.contains_key(&explicit));
        assert!(!inner.client_names.contains_key(&explicit));
    }

    #[test]
    fn terminal_watcher_does_not_retain_idle_session_after_pane_removal() {
        let shared = Arc::new(Shared::new(1));
        let pane = PaneId(u64::MAX - 1);
        let terminal = Arc::new(TerminalSession::spawn_output_view(
            "idle watcher fixture".to_owned(),
            String::new(),
        ));
        let terminal_weak = Arc::downgrade(&terminal);
        shared
            .inner
            .lock()
            .terminals
            .insert(pane, Arc::clone(&terminal));
        shared
            .watch_terminal(pane, &terminal)
            .expect("start terminal watcher");

        let deadline = Instant::now() + Duration::from_secs(2);
        while terminal.diagnostics().event_queue_len != 0 {
            assert!(Instant::now() < deadline, "watcher did not become idle");
            thread::sleep(Duration::from_millis(5));
        }
        assert_eq!(
            Arc::strong_count(&terminal),
            2,
            "only the test and terminal map should own the session"
        );

        shared.inner.lock().terminals.remove(&pane);
        drop(terminal);
        let deadline = Instant::now() + Duration::from_secs(2);
        while terminal_weak.upgrade().is_some() {
            assert!(
                Instant::now() < deadline,
                "idle terminal remained owned after pane removal"
            );
            thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn terminal_watcher_persists_dynamic_viewport_titles_in_mux_snapshots() {
        let shared = Arc::new(Shared::new(1));
        let pane = shared
            .inner
            .lock()
            .engine
            .state
            .create_session("title-fixture")
            .expect("session")
            .2;
        let terminal = Arc::new(TerminalSession::spawn_output_view(
            "dynamic terminal title".to_owned(),
            String::new(),
        ));
        shared
            .inner
            .lock()
            .terminals
            .insert(pane, Arc::clone(&terminal));
        shared
            .watch_terminal(pane, &terminal)
            .expect("start terminal watcher");
        terminal.attach_view(TerminalViewId(u64::MAX - 1));

        let deadline = Instant::now() + Duration::from_secs(2);
        loop {
            let title = shared
                .inner
                .lock()
                .engine
                .state
                .pane(pane)
                .map(|pane| pane.title.clone());
            if title.as_deref() == Some("dynamic terminal title") {
                break;
            }
            assert!(
                Instant::now() < deadline,
                "terminal title did not reach mux state; last title was {title:?}"
            );
            thread::sleep(Duration::from_millis(5));
        }
        let snapshot = shared.inner.lock().engine.state.snapshot();
        assert_eq!(
            snapshot.sessions[0].windows[0].panes[&pane].title,
            "dynamic terminal title"
        );

        let replacement = Arc::new(TerminalSession::spawn_output_view(
            "replacement terminal".to_owned(),
            String::new(),
        ));
        shared
            .inner
            .lock()
            .terminals
            .insert(pane, Arc::clone(&replacement));
        shared.synchronize_pane_title(pane, &terminal, "stale watcher title");
        assert_eq!(
            shared.inner.lock().engine.state.pane(pane).unwrap().title,
            "dynamic terminal title",
            "a retired watcher must not rename its replacement"
        );

        shared.inner.lock().terminals.remove(&pane);
    }

