    #[test]
    fn confirm_before_parses_first_shapes_prompts_and_uses_one_reply() {
        let (shared, client, _, mut context) = popup_test_workspace("desktop");
        assert!(matches!(
            shared.execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("confirm-before", ["-c", "bad", "{ broken"]),
            ),
            Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                if message != "invalid confirm key"
        ));
        for key in ["", "yy", "é", "\n"] {
            assert!(matches!(
                shared.execute(
                    client,
                    ClientKind::Interactive,
                    &mut context,
                    &CommandInvocation::new(
                        "confirm-before",
                        ["-c", key, "display-message valid"]
                    ),
                ),
                Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                    if message == "invalid confirm key"
            ));
        }
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("confirm-before", ["-c", "Y", "renamew confirmed"]),
            )
            .expect("open default confirm");
        assert_eq!(
            shared.inner.lock().confirms[&client].state.prompt,
            "Confirm 'rename-window'? (Y/n) "
        );
        shared.input_confirm(client, &context, ConfirmAction::Reply(false));
        assert_ne!(
            shared.inner.lock().engine.state.windows[&context.window.unwrap()].name,
            "confirmed"
        );

        context
            .format_variables
            .insert("question".to_owned(), "Proceed?".to_owned());
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new(
                    "confirm-before",
                    ["-p", "#{question} {confirm-key}", "renamew accepted"],
                ),
            )
            .expect("open custom confirm");
        assert_eq!(
            shared.inner.lock().confirms[&client].state.prompt,
            "Proceed? {confirm-key} "
        );
        shared.input_confirm(client, &context, ConfirmAction::Reply(true));
        assert_eq!(
            shared.inner.lock().engine.state.windows[&context.window.unwrap()].name,
            "accepted"
        );
    }

    #[test]
    fn confirm_before_blocking_status_background_state_and_overlay_clearing_match_pin() {
        let (shared, interactive, _, mut context) = popup_test_workspace("desktop");
        shared
            .execute(
                interactive,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-menu", ["Old", "o", "display-message old"]),
            )
            .expect("open old menu");
        shared
            .execute(
                interactive,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("confirm-before", ["display-message replacement"]),
            )
            .expect("replace menu with confirm");
        assert!(!shared.inner.lock().menus.contains_key(&interactive));
        shared.input_confirm(interactive, &context, ConfirmAction::Reply(false));

        let run_blocking = |accepted| {
            let sender = Arc::clone(&shared);
            let command_context = context.clone();
            let (send, receive) = crossbeam_channel::bounded(1);
            let worker = thread::spawn(move || {
                let mut command_context = command_context;
                let result = sender.execute(
                    ClientId(901),
                    ClientKind::Command,
                    &mut command_context,
                    &CommandInvocation::new(
                        "confirm-before",
                        ["-t", "desktop", "renamew blocking"],
                    ),
                );
                send.send(result).expect("return confirm result");
            });
            wait_for_confirm_state(&shared, interactive);
            shared.input_confirm(interactive, &context, ConfirmAction::Reply(accepted));
            let result = receive
                .recv_timeout(Duration::from_secs(5))
                .expect("blocking confirm result");
            worker.join().expect("confirm command worker");
            result
        };
        assert!(matches!(
            run_blocking(false),
            Err(DaemonError::CommandExit { exit_code: 1, .. })
        ));
        run_blocking(true).expect("accepted blocking confirm");
        assert_eq!(
            shared.inner.lock().engine.state.windows[&context.window.unwrap()].name,
            "blocking"
        );

        let original = context.pane.expect("original pane");
        let original_window = context.window.expect("original window");
        shared
            .execute(
                interactive,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-window", ["-n", "fresh"]),
            )
            .expect("fresh target window");
        let fresh_window = context.window.expect("fresh window");
        let mut original_context =
            ExecutionContext::for_pane(&shared.inner.lock().engine.state, original)
                .expect("original context");
        shared
            .execute(
                interactive,
                ClientKind::Interactive,
                &mut original_context,
                &CommandInvocation::new("confirm-before", ["-b", "rename-window background-fresh"]),
            )
            .expect("open background confirm");
        shared.input_confirm(interactive, &context, ConfirmAction::Reply(true));
        let inner = shared.inner.lock();
        assert_eq!(
            inner.engine.state.windows[&fresh_window].name,
            "background-fresh"
        );
        assert_ne!(
            inner.engine.state.windows[&original_window].name,
            "background-fresh"
        );
    }

    #[test]
    fn lock_commands_store_only_and_keep_clientless_error_parity() {
        let shared = Arc::new(Shared::new(1));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                ClientId(99),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("lock-server", [] as [&str; 0]),
            )
            .expect("clientless lock-server");
        assert!(matches!(
            shared.execute(
                ClientId(99),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("lock-client", [] as [&str; 0]),
            ),
            Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                if message == "no current client"
        ));
        assert!(matches!(
            shared.execute(
                ClientId(99),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("lock-session", ["-t", "missing"]),
            ),
            Err(DaemonError::Server(ServerError::SessionNotFound(message))) if message == "missing"
        ));

        shared
            .execute(
                ClientId(99),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "work"]),
            )
            .expect("lock test session");
        shared
            .execute(
                ClientId(99),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "set-hook",
                    ["-g", "after-lock-server", "set-option -g @locked yes"],
                ),
            )
            .expect("lock hook");
        shared
            .execute(
                ClientId(99),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("lock-server", [] as [&str; 0]),
            )
            .expect("lock hook fires");
        assert_eq!(
            shared
                .execute(
                    ClientId(99),
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-options", ["-gv", "@locked"]),
                )
                .expect("lock hook option")
                .output,
            "yes"
        );
        shared
            .execute(
                ClientId(99),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("lock-session", ["-t", "work"]),
            )
            .expect("existing lock session");
    }

    #[cfg(unix)]
    #[test]
    fn display_popup_resolves_styles_from_the_sessions_current_window() {
        let (shared, client, _, mut context) = popup_test_workspace("desktop");
        let first_window = context.window.expect("current popup window");
        let created = shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("new-window", ["-d", "-n", "target"]),
            )
            .expect("create popup target window");
        let target_pane = match created.effects.first() {
            Some(MuxEffect::PaneCreated { pane, .. }) => *pane,
            other => panic!("expected target pane creation: {other:?}"),
        };
        let target_window = shared
            .inner
            .lock()
            .engine
            .state
            .window_for_pane(target_pane)
            .expect("popup target window");
        let first_window = first_window.to_string();
        let target_window = target_window.to_string();
        let target_pane = target_pane.to_string();

        for (window, style, border_style) in [
            (target_window.as_str(), "bg=red", "fg=cyan"),
            (first_window.as_str(), "bg=blue", "fg=magenta"),
        ] {
            shared
                .execute(
                    client,
                    ClientKind::Interactive,
                    &mut context,
                    &CommandInvocation::new(
                        "set-window-option",
                        ["-t", window, "popup-style", style],
                    ),
                )
                .expect("set window popup style");
            shared
                .execute(
                    client,
                    ClientKind::Interactive,
                    &mut context,
                    &CommandInvocation::new(
                        "set-window-option",
                        ["-t", window, "popup-border-style", border_style],
                    ),
                )
                .expect("set window popup border style");
        }

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-popup", ["-t", &target_pane, "exit 0"]),
            )
            .expect("open popup for target pane");
        let state = wait_for_popup_state(&shared, client, |state| state.dead);
        // The pin reads popup styles from the target session's current window
        // (cmd-display-menu.c: `s->curw->window->options`), not from the window
        // that owns the `-t` pane, which `new-window -d` left unfocused.
        assert_eq!(state.style, "bg=blue");
        assert_eq!(state.border_style, "fg=magenta");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-popup", ["-C"]),
            )
            .expect("clear target popup");
    }

    #[cfg(unix)]
    #[test]
    fn display_popup_creates_modifies_and_clears_one_dead_overlay_safely() {
        let (shared, client, mailbox, mut context) = popup_test_workspace("desktop");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new(
                    "display-popup",
                    [
                        "-w20",
                        "-h",
                        "10",
                        "-T",
                        "first",
                        "-s",
                        "bg=red,fg=white",
                        "-S",
                        "fg=cyan",
                        "-b",
                        "rounded",
                        "-EE",
                        "-k",
                        "exit 3",
                    ],
                ),
            )
            .expect("open retained popup");
        let state = wait_for_popup_state(&shared, client, |state| state.dead);
        assert_eq!(
            (state.left, state.top, state.width, state.height),
            (29, 6, 20, 10)
        );
        assert_eq!((state.client_columns, state.client_rows), (80, 24));
        assert_eq!((state.cell_width_px, state.cell_height_px), (8, 18));
        assert_eq!(state.title, "first");
        assert_eq!(state.style, "bg=red,fg=white");
        assert_eq!(state.border_style, "fg=cyan");
        assert_eq!(state.border_lines, PopupBorderLines::Rounded);
        assert!(!state.close_on_exit);
        assert!(state.close_on_exit_zero);
        assert!(state.close_on_any_key);
        let (terminal, viewport) = {
            let inner = shared.inner.lock();
            let terminal = Arc::clone(&inner.popups[&client].terminal);
            let viewport = terminal.latest_viewport();
            (terminal, viewport)
        };
        assert_eq!((viewport.columns, viewport.rows), (18, 8));
        assert!(
            take_reliable_messages(&mailbox)
                .iter()
                .any(|message| matches!(
                    message,
                    ProtocolMessage::Event(Event {
                        payload: EventPayload::Popup { state: Some(state) },
                        ..
                    }) if state.title == "first"
                ))
        );

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new(
                    "popup",
                    ["-T", "second", "-B", "-NE", "-w", "60", "ignored"],
                ),
            )
            .expect("modify dead popup");
        let modified = shared.inner.lock().popups[&client].state.clone();
        assert_eq!(modified.title, "second");
        assert_eq!((modified.width, modified.height), (20, 10));
        assert_eq!(modified.border_lines, PopupBorderLines::None);
        assert!(modified.close_on_exit);
        assert!(!modified.close_on_exit_zero);
        assert!(!modified.close_on_any_key);
        assert!(modified.dead);
        assert_eq!(
            (
                terminal.latest_viewport().columns,
                terminal.latest_viewport().rows
            ),
            (18, 8)
        );

        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-popup", ["-C"]),
            )
            .expect("clear popup");
        assert!(!shared.inner.lock().popups.contains_key(&client));

        shared.inner.lock().command_prompts.insert(
            client,
            CommandPrompt::new("prompt".to_owned(), String::new(), None),
        );
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-popup", ["exit 0"]),
            )
            .expect("other overlay is a silent no-op");
        assert!(!shared.inner.lock().popups.contains_key(&client));
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-popup", ["-C"]),
            )
            .expect("clear other overlay");
        assert!(!shared.inner.lock().command_prompts.contains_key(&client));

        let pane = context.pane.expect("popup test pane");
        shared
            .input(
                client,
                ClientKind::Interactive,
                &mut context,
                InputMessage::ResizeTerminal {
                    pane,
                    columns: 1,
                    rows: 1,
                    cell_width_px: 8,
                    cell_height_px: 18,
                },
            )
            .expect("shrink popup test client");
        shared
            .execute(
                client,
                ClientKind::Interactive,
                &mut context,
                &CommandInvocation::new("display-popup", ["-B"]),
            )
            .expect("zero-sized borderless default is a silent no-op");
        assert!(!shared.inner.lock().popups.contains_key(&client));
    }

