    #[test]
    fn popup_client_resolution_errors_are_exact_and_precede_target_lookup() {
        let shared = Arc::new(Shared::new(1));
        assert!(matches!(
            shared.execute(
                ClientId(99),
                ClientKind::Command,
                &mut ExecutionContext::default(),
                &CommandInvocation::new("display-popup", [] as [&str; 0]),
            ),
            Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                if message == "no current client"
        ));
        for command in [
            CommandInvocation::new("display-menu", ["Item", "i", "display-message item"]),
            CommandInvocation::new("confirm-before", ["display-message confirmed"]),
        ] {
            assert!(matches!(
                shared.execute(
                    ClientId(99),
                    ClientKind::Command,
                    &mut ExecutionContext::default(),
                    &command,
                ),
                Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                    if message == "no current client"
            ));
        }

        let (shared, _, _, context) = popup_test_workspace("desktop");
        assert!(matches!(
            shared.execute(
                ClientId(99),
                ClientKind::Command,
                &mut context.clone(),
                &CommandInvocation::new("display-popup", ["-c", "bogus"]),
            ),
            Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                if message == "can't find client: bogus"
        ));
        for command in [
            CommandInvocation::new(
                "display-menu",
                ["-c", "bogus", "Item", "i", "display-message item"],
            ),
            CommandInvocation::new(
                "confirm-before",
                ["-t", "bogus", "display-message confirmed"],
            ),
        ] {
            assert!(matches!(
                shared.execute(
                    ClientId(99),
                    ClientKind::Command,
                    &mut context.clone(),
                    &command,
                ),
                Err(DaemonError::Server(ServerError::InvalidCommand(message)))
                    if message == "can't find client: bogus"
            ));
        }
    }

    #[test]
    fn list_clients_uses_attached_registry_name_order_and_session_filtering() {
        let shared = Arc::new(Shared::new(1));
        let mut context = ExecutionContext::default();
        shared
            .execute(
                ClientId(90),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "z"]),
            )
            .unwrap();
        let z = context.session.unwrap();
        shared
            .execute(
                ClientId(90),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "A"]),
            )
            .unwrap();
        let a = context.session.unwrap();

        let (zeta, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("zeta".to_owned()),
            Some(TerminalColorScheme::Dark),
            OutboundMailbox::new(),
        );
        let (alpha, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("alpha".to_owned()),
            Some(TerminalColorScheme::Light),
            OutboundMailbox::new(),
        );
        let (_detached, _) = shared.register_subscribed(
            ClientKind::Interactive,
            Some("ghost".to_owned()),
            None,
            OutboundMailbox::new(),
        );
        shared.attach(zeta, z).unwrap();
        shared.attach(alpha, a).unwrap();

        let listed = shared
            .execute(
                ClientId(91),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("list-clients", [] as [&str; 0]),
            )
            .unwrap();
        assert_eq!(listed.output, "alpha: A [0x0 ] \nzeta: z [0x0 ] ");

        let filtered = shared
            .execute(
                ClientId(91),
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "lsc",
                    [
                        "-t",
                        "z",
                        "-F",
                        "#{line}:#{client_name}:#{session_name}:#{client_width}x#{client_height}:#{client_termname}",
                    ],
                ),
            )
            .unwrap();
        assert_eq!(filtered.output, "1:zeta:z:0x0:");
    }

    #[test]
    fn show_messages_logs_commands_newest_first_and_bounds_the_ring() {
        let shared = Arc::new(Shared::new(1));
        let client = ClientId(7);
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "work"]),
            )
            .unwrap();

        let displayed = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut context,
            1,
            &CommandInvocation::new("display-message", ["hello"]),
        );
        assert!(matches!(
            displayed,
            CommandResponse::Success { output, .. } if output.is_empty()
        ));
        let shown = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut context,
            2,
            &CommandInvocation::new("showmsgs", [] as [&str; 0]),
        );
        let CommandResponse::Success { output, .. } = shown else {
            panic!("show-messages should succeed");
        };
        let lines = output.lines().collect::<Vec<_>>();
        assert_eq!(lines.len(), 3);
        assert!(lines[0].ends_with(": device-7 command: show-messages"));
        assert!(lines[1].ends_with(": hello"));
        assert!(lines[2].ends_with(": device-7 command: display-message hello"));
        assert!(lines.iter().all(|line| {
            let bytes = line.as_bytes();
            bytes.get(2) == Some(&b':') && bytes.get(5) == Some(&b':')
        }));

        let mut inner = shared.inner.lock();
        inner.message_log.clear();
        inner.next_message_number = 0;
        drop(inner);
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-option", ["-s", "message-limit", "3"]),
            )
            .unwrap();
        let mut inner = shared.inner.lock();
        for number in 0..5 {
            push_server_message(&mut inner, format!("message-{number}"));
        }
        assert_eq!(
            inner
                .message_log
                .iter()
                .map(|message| message.text.as_str())
                .collect::<Vec<_>>(),
            ["message-2", "message-3", "message-4"]
        );
        assert_eq!(
            inner
                .message_log
                .iter()
                .rev()
                .map(|message| message.text.as_str())
                .collect::<Vec<_>>(),
            ["message-4", "message-3", "message-2"]
        );
        inner.message_log.clear();
        inner.next_message_number = 0;
        drop(inner);

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-option", ["-su", "message-limit"]),
            )
            .unwrap();
        let mut inner = shared.inner.lock();
        for number in 0..5 {
            push_server_message(&mut inner, format!("message-{number}"));
        }
        drop(inner);
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-option", ["-s", "message-limit", "3"]),
            )
            .unwrap();
        let mut inner = shared.inner.lock();
        assert_eq!(inner.message_log.len(), 5);
        push_server_message(&mut inner, "message-5".to_owned());
        assert_eq!(
            inner
                .message_log
                .iter()
                .map(|message| message.text.as_str())
                .collect::<Vec<_>>(),
            ["message-3", "message-4", "message-5"]
        );
    }

    #[test]
    fn command_hooks_fire_at_the_daemon_boundary_with_formats_and_nohooks() {
        let shared = Arc::new(Shared::new(1));
        let (session, first_pane, _) = output_view_session_fixture(&shared, "hooks", "first");
        let (first_window, second_window) = {
            let mut inner = shared.inner.lock();
            let first_window = inner
                .engine
                .state
                .window_for_pane(first_pane)
                .expect("first window");
            let (second_window, second_pane) = inner
                .engine
                .state
                .create_window_at(
                    session,
                    None,
                    Some("second".to_owned()),
                    PaneKind::Terminal,
                    false,
                )
                .expect("second window");
            inner.terminals.insert(
                second_pane,
                Arc::new(TerminalSession::spawn_output_view(
                    "second fixture".to_owned(),
                    "second".to_owned(),
                )),
            );
            (first_window, second_window)
        };
        let mut context = ExecutionContext::for_pane(&shared.inner.lock().engine.state, first_pane)
            .expect("hook context");
        let client = ClientId(7);

        for (name, value) in [
            (
                "after-select-window",
                "display-message '#{hook}|#{hook_arguments}|#{hook_flag_t}|#{window_name}'",
            ),
            (
                "command-error",
                "display-message '#{hook}|#{hook_arguments}'",
            ),
            ("after-list-buffers", "display-message 'daemon=#{hook}'"),
        ] {
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-hook", [name, value]),
                )
                .unwrap();
        }
        shared.inner.lock().message_log.clear();

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "select-window",
                    ["-t", second_window.to_string().as_str()],
                ),
            )
            .unwrap();
        assert_eq!(
            shared
                .inner
                .lock()
                .message_log
                .iter()
                .map(|message| message.text.clone())
                .collect::<Vec<_>>(),
            [format!(
                "after-select-window|-t {second_window}|{second_window}|second"
            )]
        );

        shared.inner.lock().message_log.clear();
        assert!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("select-window", ["-t", "missing"]),
                )
                .is_err()
        );
        assert_eq!(
            shared
                .inner
                .lock()
                .message_log
                .iter()
                .map(|message| message.text.as_str())
                .collect::<Vec<_>>(),
            ["command-error|-t missing"]
        );

        shared.inner.lock().message_log.clear();
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("list-buffers", [] as [&str; 0]),
            )
            .unwrap();
        assert_eq!(
            shared
                .inner
                .lock()
                .message_log
                .back()
                .map(|message| message.text.as_str()),
            Some("daemon=after-list-buffers")
        );

        for (args, value) in [
            (
                vec!["alert-bell"],
                "display-message 'immediate=#{hook}:#{hook_arguments}'",
            ),
            (
                vec!["after-select-window"],
                "set-hook -R alert-bell ignored",
            ),
        ] {
            let mut command_args = args.into_iter().map(str::to_owned).collect::<Vec<_>>();
            command_args.push(value.to_owned());
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-hook", command_args),
                )
                .unwrap();
        }
        shared.inner.lock().message_log.clear();
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("select-window", ["-t", first_window.to_string().as_str()]),
            )
            .unwrap();
        assert_eq!(
            shared
                .inner
                .lock()
                .message_log
                .iter()
                .map(|message| message.text.as_str())
                .collect::<Vec<_>>(),
            ["immediate=alert-bell:"]
        );

        for (args, value) in [
            (
                vec!["after-set-option"],
                "display-message nested-after-set-option",
            ),
            (
                vec!["after-select-window"],
                "set-option @inside yes ; select-window -t missing ; display-message unreachable",
            ),
            (
                vec!["-a", "after-select-window"],
                "display-message next-index",
            ),
        ] {
            let mut command_args = args.into_iter().map(str::to_owned).collect::<Vec<_>>();
            command_args.push(value.to_owned());
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-hook", command_args),
                )
                .unwrap();
        }
        shared.inner.lock().message_log.clear();
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "select-window",
                    ["-t", second_window.to_string().as_str()],
                ),
            )
            .unwrap();
        assert_eq!(
            shared
                .inner
                .lock()
                .message_log
                .iter()
                .map(|message| message.text.as_str())
                .collect::<Vec<_>>(),
            ["can't find window: missing", "next-index"]
        );
        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-options", ["-v", "@inside"]),
                )
                .unwrap()
                .output,
            "yes"
        );
    }

    #[test]
    fn user_hook_run_now_uses_shared_option_storage_and_only_hook_format() {
        let shared = Arc::new(Shared::new(1));
        let (_, pane, _) = output_view_session_fixture(&shared, "user-hook", "first");
        let mut context = ExecutionContext::for_pane(&shared.inner.lock().engine.state, pane)
            .expect("user hook context");
        let client = ClientId(7);

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-option", ["-g", "@myhook", "v"]),
            )
            .unwrap();
        let hook_command = "display-message -p 'AT-HOOK-RAN|#{hook}|#{hook_arguments}'";
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-hook", ["-g", "@myhook", hook_command]),
            )
            .unwrap();
        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-options", ["-g", "-v", "@myhook"]),
                )
                .unwrap()
                .output,
            hook_command
        );
        assert!(
            !shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-hooks", ["-g"]),
                )
                .unwrap()
                .output
                .lines()
                .any(|line| line.starts_with('@'))
        );

        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-hook", ["-R", "@myhook"]),
                )
                .unwrap()
                .output,
            "AT-HOOK-RAN|@myhook|"
        );

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-option", ["-g", "@myhook", "v"]),
            )
            .unwrap();
        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-hook", ["-R", "@myhook"]),
                )
                .unwrap()
                .output,
            ""
        );
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("set-hook", ["-g", "-u", "@myhook"]),
            )
            .unwrap();
        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-options", ["-g", "-q", "-v", "@myhook"]),
                )
                .unwrap()
                .output,
            ""
        );
    }

    #[test]
    fn command_hook_output_joins_the_triggering_client_response_in_pin_order() {
        let shared = Arc::new(Shared::new(1));
        let (session, first_pane, _) = output_view_session_fixture(&shared, "hook-output", "first");
        let second_window = {
            let mut inner = shared.inner.lock();
            let (window, pane) = inner
                .engine
                .state
                .create_window_at(
                    session,
                    None,
                    Some("second".to_owned()),
                    PaneKind::Terminal,
                    false,
                )
                .expect("second window");
            inner.terminals.insert(
                pane,
                Arc::new(TerminalSession::spawn_output_view(
                    "second fixture".to_owned(),
                    "second".to_owned(),
                )),
            );
            window
        };
        let client = ClientId(7);
        let mut setup_context =
            ExecutionContext::for_pane(&shared.inner.lock().engine.state, first_pane)
                .expect("hook setup context");
        for (name, value) in [
            ("after-select-window", "display-message -p FIRED-SW"),
            ("command-error", "display-message -p CMD-ERR"),
        ] {
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut setup_context,
                    &CommandInvocation::new("set-hook", ["-g", name, value]),
                )
                .expect("global hook");
        }

        let success = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut ExecutionContext::default(),
            1,
            &CommandInvocation::new("select-window", ["-t", second_window.to_string().as_str()]),
        );
        assert_eq!(
            success,
            CommandResponse::Success {
                request_id: 1,
                output: "FIRED-SW".to_owned(),
                exit_code: 0,
            }
        );

        let failure = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut ExecutionContext::default(),
            2,
            &CommandInvocation::new("select-window", ["-t", "missing"]),
        );
        assert_eq!(
            failure,
            CommandResponse::Error {
                request_id: 2,
                error: ServerError::WindowNotFound("missing".to_owned()),
                output: "CMD-ERR".to_owned(),
            }
        );

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut setup_context,
                &CommandInvocation::new("set-buffer", ["-b", "buffer0", "payload"]),
            )
            .expect("buffer fixture");
        for (name, value) in [
            ("after-list-buffers[1]", "display-message -p IDX-B"),
            ("after-list-buffers[0]", "display-message -p IDX-A"),
        ] {
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut setup_context,
                    &CommandInvocation::new("set-hook", ["-g", name, value]),
                )
                .expect("indexed hook");
        }
        let ordered = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut ExecutionContext::default(),
            3,
            &CommandInvocation::new("list-buffers", ["-F", "OWN-#{buffer_name}"]),
        );
        assert_eq!(
            ordered,
            CommandResponse::Success {
                request_id: 3,
                output: "OWN-buffer0\nIDX-A\nIDX-B".to_owned(),
                exit_code: 0,
            }
        );

        for (name, value) in [
            ("after-set-option", "display-message -p SETOPT-FIRED"),
            ("after-display-message", "display-message -p DM-NESTED"),
        ] {
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut setup_context,
                    &CommandInvocation::new("set-hook", ["-g", name, value]),
                )
                .expect("no-hooks fixture");
        }
        let no_hooks = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut ExecutionContext::default(),
            4,
            &CommandInvocation::new("set-option", ["-g", "@hook-output", "1"]),
        );
        assert_eq!(
            no_hooks,
            CommandResponse::Success {
                request_id: 4,
                output: "SETOPT-FIRED".to_owned(),
                exit_code: 0,
            }
        );

        shared
            .execute(
                client,
                ClientKind::Command,
                &mut setup_context,
                &CommandInvocation::new(
                    "set-hook",
                    ["-g", "alert-bell", "display-message -p R-FIRED"],
                ),
            )
            .expect("run-now fixture");
        let run_now = shared.execute_command_request(
            client,
            ClientKind::Command,
            &mut ExecutionContext::default(),
            5,
            &CommandInvocation::new("set-hook", ["-gR", "alert-bell"]),
        );
        assert_eq!(
            run_now,
            CommandResponse::Success {
                request_id: 5,
                output: "R-FIRED".to_owned(),
                exit_code: 0,
            }
        );
    }

    #[test]
    fn event_hooks_fire_after_mutation_with_captured_formats() {
        let shared = Arc::new(Shared::new(1));
        let client = ClientId(7);
        let mut context = ExecutionContext::default();
        shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new(
                    "set-hook",
                    [
                        "-g",
                        "session-created",
                        "set-environment -gF ZZ_TEST_SESSION_CREATED '#{hook}|#{hook_session}|#{hook_session_name}|#{hook_arguments}'",
                    ],
                ),
            )
            .expect("session-created hook");
        let created = shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("new-session", ["-d", "-s", "events"]),
            )
            .expect("new session");
        let session = context.session.expect("created session");
        let window = context.window.expect("created window");
        assert!(created.output.is_empty());
        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-environment", ["-g", "ZZ_TEST_SESSION_CREATED"],),
                )
                .unwrap()
                .output,
            format!("ZZ_TEST_SESSION_CREATED=session-created|{session}|events|")
        );

        for (name, value) in [
            (
                "window-renamed",
                "set-environment -gF ZZ_TEST_WINDOW_RENAMED '#{hook}|#{hook_window}|#{hook_window_name}'",
            ),
            (
                "window-layout-changed",
                "set-environment -gF ZZ_TEST_WINDOW_LAYOUT_CHANGED '#{hook}|#{hook_window}'",
            ),
        ] {
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("set-hook", ["-g", name, value]),
                )
                .expect("window event hook");
        }
        let renamed = shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("rename-window", ["-t", &window.to_string(), "named"]),
            )
            .expect("rename window");
        assert!(renamed.output.is_empty());
        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new("show-environment", ["-g", "ZZ_TEST_WINDOW_RENAMED"],),
                )
                .unwrap()
                .output,
            format!("ZZ_TEST_WINDOW_RENAMED=window-renamed|{window}|named")
        );

        let split = shared
            .execute(
                client,
                ClientKind::Command,
                &mut context,
                &CommandInvocation::new("split-window", ["-d"]),
            )
            .expect("split window");
        assert!(split.output.is_empty());
        assert_eq!(
            shared
                .execute(
                    client,
                    ClientKind::Command,
                    &mut context,
                    &CommandInvocation::new(
                        "show-environment",
                        ["-g", "ZZ_TEST_WINDOW_LAYOUT_CHANGED"],
                    ),
                )
                .unwrap()
                .output,
            format!("ZZ_TEST_WINDOW_LAYOUT_CHANGED=window-layout-changed|{window}")
        );
    }

